window.__Q=window.__Q||{};window.__Q["prev/1/A1"]=[{"q":"对胆汁酸的描述，错误的是","o":["胆汁酸是胆固醇的主要转化产物","胆汁酸具有亲水性和疏水性","胆汁酸可分为初级胆汁酸和次级胆汁酸","胆汁酸可分为游离型和结合型","胆囊中的都是初级胆汁酸"],"a":4,"e":"胆囊胆汁中既有初级胆汁酸，也有经肠菌脱羟生成、随肠肝循环返回的次级胆汁酸，故E项错误。胆汁酸由胆固醇在肝转化而来，具亲水与疏水两面，按来源分初级与次级，按是否与甘氨酸、牛磺酸结合分游离型与结合型"},{"q":"己糖激酶以葡萄糖为底物时，Km=1/2[S]，其反应速率v是Vmax的","o":["9%","15%","33%","50%","67%"],"a":4,"e":"按米氏方程，Km=1/2[S]时v=Vmax[S]/（0.5[S]+[S]），即Vmax/1.5，约为67%Vmax。9%与15%对应底物浓度远低于Km的情形，33%为[S]=0.5Km时的速率，50%是[S]=Km时的速率"},{"q":"具有四级结构的蛋白质特征是","o":["分子中必须含有辅基","两条或两条以上具有三级结构多肽链进一步折叠、盘曲形成","以肽键维系四级结构的稳定","每条多肽链都具有独立生物学活性","有两条或两条以上的多肽链组成"],"a":4,"e":"四级结构指两条或两条以上具独立三级结构的亚基，以非共价键缔合形成的空间排布，故其基本特征是含两条以上多肽链。维系四级结构的是氢键、离子键、疏水作用等次级键，肽键维系的是一级结构。辅基并非必需成分，单链蛋白也可带辅基；各亚基单独存在时通常不表现活性"},{"q":"逆转录病毒基因组复制时所用的引物为","o":["RNA","DNA","tRNA","mRNA","不需要引物"],"a":2,"e":"逆转录病毒以宿主细胞的tRNA作为引物，其3'-OH与病毒RNA模板配对后启动负链DNA合成，随后RNA链被RNase H水解，第二链以片段末端为引物合成。逆转录酶自身不能起始聚合，仍需引物提供3'-OH"},{"q":"在酶浓度和其他反应条件不变的情况下，反应速率v对底物浓度[S]作图可得到","o":["直线","S形曲线","矩形双曲线","抛物线","钟罩形曲线"],"a":2,"e":"底物浓度对反应速率的影响遵循米氏方程，v对[S]作图呈矩形双曲线：低浓度时为一级反应，高浓度时酶被饱和呈零级反应。S形曲线见于具协同效应的别构酶，钟罩形曲线见于温度或pH的影响，直线仅出现于双倒数作图，抛物线无对应动力学意义"},{"q":"矩形双曲线反映了受体-配体结合的","o":["高度专一性","高度亲和力","可饱和性","可逆性","特定的作用模式"],"a":2,"e":"受体-配体结合随配体浓度增加而趋于饱和，其结合曲线呈矩形双曲线，反映可饱和性，即细胞表面受体数目有限。高度专一性指只结合特定配体；高度亲和力指低浓度即可结合；可逆性指可解离；特定作用模式指结合后产生效应，均不由该曲线直接体现"},{"q":"以下不属于次级胆汁酸的是","o":["脱氧胆酸","牛磺脱氧胆酸","鹅脱氧胆酸","石胆酸","甘氨脱氧胆酸"],"a":2,"e":"次级胆汁酸由初级胆汁酸经肠菌脱去7α-羟基生成，包括脱氧胆酸、石胆酸及其与甘氨酸、牛磺酸的结合物，牛磺脱氧胆酸、甘氨脱氧胆酸均属之。鹅脱氧胆酸在肝内由胆固醇直接合成，为初级胆汁酸，并非次级"},{"q":"脂肪酸合成酶系存在于细胞的","o":["细胞质","微粒体","线粒体基质","线粒体内膜","溶酶体"],"a":0,"e":"脂肪酸合成酶系存在于细胞质，催化以乙酰CoA为原料、丙二酰CoA为二碳供体的软脂酸合成。微粒体参与脂肪酸延长与去饱和；线粒体基质是脂肪酸β-氧化场所；线粒体内膜进行氧化磷酸化；溶酶体参与降解，均非脂肪酸合成部位"},{"q":"下述序列中，在双链状态下属于完全回文结构的序列是","o":["CTGAGATC","AGTCAGTC","AGTCTGA","GACTCTGA","AGTCGACT"],"a":4,"e":"回文结构指两条链5′→3′方向序列完全一致，AGTCGACT的反向互补链仍读作AGTCGACT，故为完全回文。CTGAGATC、AGTCAGTC与GACTCTGA的反向互补序列均与原序列不同，AGTCTGA为7个核苷酸的单数长度，不可能形成完全回文"},{"q":"基因比对主要包括核酸序列比对和下列哪项比对","o":["脂肪酸","单糖结构","多糖链","氨基酸","空间结构"],"a":3,"e":"基因比对包括核酸序列比对与氨基酸序列比对，前者比较DNA或RNA序列，后者比较蛋白质的氨基酸序列，用于同源基因搜索与功能推测。脂肪酸、单糖结构、多糖链属糖脂代谢物，空间结构比对属结构分析，均不是序列比对的内容"},{"q":"下列组织不能氧化利用脂肪酸的是","o":["脑","心肌","肝脏","肾脏","肌肉"],"a":0,"e":"脑组织缺乏脂肪酸β-氧化所需酶系，不能氧化脂肪酸，但能利用酮体供能，故长期饥饿时酮体成为脑的重要能源。心肌、肝、肾、骨骼肌均可摄取脂肪酸进行β-氧化，肝的β-氧化产物以酮体形式输出，肾皮质也以脂肪酸为主要燃料"},{"q":"重组DNA技术中常用的属于限制性核酸内切酶的哪一类","o":["Ⅰ类酶","Ⅱ类酶","Ⅲ类酶","Ⅳ类酶","Ⅴ类酶"],"a":1,"e":"重组DNA技术中使用的限制性核酸内切酶是Ⅱ型酶，能识别回文序列并在识别位点内或其附近定点切割，产生黏性或平末端，便于片段连接。Ⅰ型、Ⅲ型酶切割位点不固定，不产生可用于克隆的确定片段，Ⅳ型、Ⅴ型酶不是重组技术的常用工具酶"},{"q":"指出下列哪项是酵解过程中可被别构调节的限速酶","o":["磷酸己糖异构酶","6-磷酸果糖激酶-1","醛缩酶","3-磷酸甘油醛脱氢酶","乳酸脱氢酶"],"a":1,"e":"糖酵解三个关键酶为己糖激酶、磷酸果糖激酶-1和丙酮酸激酶，其中磷酸果糖激酶-1活性最低、是最重要的调控点，受ATP与柠檬酸别构抑制，受AMP和果糖-2,6-二磷酸别构激活。磷酸己糖异构酶、醛缩酶、3-磷酸甘油醛脱氢酶和乳酸脱氢酶催化的均为可逆反应，不具限速作用"},{"q":"维生素B6作为酶的辅酶最重要的作用是","o":["参与氨基酸的合成、分解和互变","参与合成神经递质","参与合成δ-氨基-γ-酮基戊酸","参与合成尼克酸","作为糖原磷酸化酶组分，稳定酶分子"],"a":0,"e":"维生素B6的活性形式磷酸吡哆醛是转氨酶、脱羧酶等多种氨基酸代谢酶的辅酶，最重要作用是参与氨基酸的合成、分解与相互转变。合成神经递质、合成δ-氨基-γ-酮基戊酸只是个别具体反应；合成尼克酸不依赖B6；作为糖原磷酸化酶组分稳定酶分子并非其主要功能"},{"q":"原核生物基因表达调控的乳糖操纵子系统属于","o":["复制水平调节","转录水平调节","转录后水平调节","翻译水平调节","翻译后水平调节"],"a":1,"e":"乳糖操纵子由结构基因、调控序列与调节基因组成，阻遏蛋白与CAP均作用于启动子上游的DNA序列，控制RNA聚合酶起始转录的速度，故属转录水平调节。复制水平调节针对DNA复制起始，转录后调节涉及mRNA加工与稳定性，翻译与翻译后调节作用于蛋白合成及修饰，均非操纵子的作用层次"},{"q":"蛋白质生物合成时需要信号肽的过程是","o":["线粒体蛋白质的合成","多核糖体的合成","核糖体与mRNA附着","核糖体与内质网附着","肽从核糖体的释放"],"a":3,"e":"分泌蛋白N端信号肽合成后即被信号识别颗粒识别，使核糖体暂停翻译并结合内质网膜上的SRP受体，核糖体由此附着于内质网，新生肽链边合成边进入内质网腔。信号肽随后被信号肽酶切除。核糖体与内质网的解离发生在转运完成后，与信号肽无关；肽链延长、终止与卸载均不需信号肽"},{"q":"根据色氨酸和酪氨酸含量对蛋白质进行定量测定的方法为","o":["双缩脲反应","凯氏定氮法","茚三酮反应","紫外吸收法","考马斯亮蓝法"],"a":3,"e":"色氨酸与酪氨酸的苯环共轭系统在280nm有特征吸收，蛋白质在280nm的吸光度与其含量成正比，故可用紫外吸收法快速定量，且不破坏样品。凯氏定氮测总氮量，双缩脲法测肽键，酚试剂法依赖芳香族残基但试剂显色，考马斯亮蓝法结合疏水区，均非依据色氨酸、酪氨酸的直接吸收"},{"q":"DNA复制时，序列5'-TpApGpApCpT-3'指导合成的互补序列是","o":["5'-ApTpCpTpTpA-3'","5'-ApGpTpCpTpA-3'","5'-ApGpUpCpUpA-3'","3'-TpGpTpCpTpA-5'","5'-ApGpGpCpGpA-3'"],"a":1,"e":"互补链与模板反向平行，模板为5'-TpApGpApCpT-3'，互补序列按5'至3'写作ApGpTpCpTpA。A项碱基配对错误，C项以U代替T属RNA序列，D项为3'端起始的反向写法，E项碱基不互补"},{"q":"IPTG诱导乳糖操纵子表达的机制是","o":["使乳糖-阻遏蛋白复合物解离","与阻遏蛋白结合，使之丧失DNA结合能力","与乳糖竞争结合阻遏蛋白","与RNA聚合酶结合，使之通过操纵序列","变构修饰RNA聚合酶，提高其活性"],"a":1,"e":"IPTG是乳糖类似物，作为诱导物与乳糖操纵子的阻遏蛋白结合，使其构象改变、丧失与操纵序列结合的能力，从而解除阻遏、启动转录。IPTG不被代谢，不与乳糖竞争结合阻遏蛋白，也不直接作用于RNA聚合酶或对其进行变构修饰"},{"q":"维生素A参与视紫红质的形式是","o":["全反视黄醇","11-顺视黄醇","全反视黄醛","11-顺视黄醛","9-顺视黄醛"],"a":3,"e":"视紫红质由11-顺视黄醛与视蛋白结合而成，弱光下11-顺视黄醛异构为全反式，触发视蛋白构象改变而产生视觉信号。全反式视黄醇与11-顺视黄醇需先氧化为醛，全反视黄醛是光激活后的形式，9-顺视黄醛不参与视紫红质的组成"},{"q":"关于癌基因的叙述中错误的是","o":["是细胞增殖的正调节基因","可诱导细胞凋亡","能在体外引起细胞转化","能在体内诱发肿瘤","包括病毒癌基因和细胞癌基因"],"a":1,"e":"癌基因是细胞增殖的正调节基因，激活后能在体外引起细胞转化、体内诱发肿瘤，包括病毒癌基因与细胞癌基因，故可诱导细胞凋亡的叙述错误。诱导细胞凋亡是抑癌基因或促凋亡基因的功能，与癌基因促进增殖、抑制凋亡的作用相反"},{"q":"下列关于核酸理化性质叙述不正确的是","o":["氯化钠、乙醇可使核酸自溶液中沉淀下来","核酸具有两性解离性质","核酸与双缩脲试剂反应，溶液呈紫红色","核酸的线形分子比环形分子黏度要大得多","高温可以使DNA变性"],"a":2,"e":"双缩脲反应检测肽键，蛋白质与多肽才呈紫红色，核酸不含肽键故不显色。核酸具两性解离，可被乙醇、氯化钠沉淀，线形分子黏度大于环形分子，加热使氢键断裂而发生变性。核酸最大吸收峰在260nm，蛋白质在280nm，据此可判断核酸纯度"},{"q":"真核生物在蛋白质生物合成中的起始tRNA是","o":["亮氨酰-tRNA","丙氨酰-tRNA","赖氨酰-tRNA","甲酰甲硫氨酰-tRNA","甲硫氨酰-tRNA"],"a":4,"e":"真核起始氨酰tRNA为Met-tRNAiMet，携带未甲酰化的甲硫氨酸，在起始密码子AUG处就位装配起始复合物。D项指原核生物的fMet-tRNAfMet，其甲硫氨酸已被甲酰化。起始tRNA与识别可读框内部AUG的Met-tRNA结构不同，二者不能互换"},{"q":"下列激素具有抗脂解作用的是","o":["肾上腺素","胰高血糖素","ACTH","胰岛素","促甲状腺素"],"a":3,"e":"胰岛素可抑制激素敏感性脂肪酶活性，促进脂肪合成并抑制脂肪动员，发挥抗脂解作用，故为答案。肾上腺素、胰高血糖素、ACTH、促甲状腺素均通过激活脂肪酶促进脂肪动员，属脂解激素，与胰岛素作用相反"},{"q":"下述哪两个酶是产生氮的直接供体，进入尿素生成通路","o":["精氨酸酶和精氨基琥珀酸裂解酶","黄嘌呤氧化酶和鸟嘌呤脱氨酶","谷氨酸脱氢酶和谷氨酰胺酶","精氨基琥珀酸合成酶和鸟氨酸转氨甲酰酶","天冬氨酸转氨酶和氨甲酰磷酸合成酶"],"a":4,"e":"尿素的两个氮分别来自氨与天冬氨酸：氨甲酰磷酸合成酶Ⅰ在肝线粒体固定游离氨，天冬氨酸转氨酶在细胞质生成天冬氨酸提供第二个氮。谷氨酸脱氢酶与谷氨酰胺酶只是产氨的酶，精氨酸酶和精氨基琥珀酸裂解酶作用于循环后段"},{"q":"以下哪种物质不是肝脏糖异生原料","o":["甘油","乙酰乙酸","谷氨酸","丙酮酸","乳酸"],"a":1,"e":"糖异生原料为乳酸、甘油、生糖氨基酸及丙酮酸，乙酰乙酸属酮体，其分解生成乙酰CoA，乙酰CoA不能净生成葡萄糖，故不能异生为糖。谷氨酸为生糖氨基酸，可经α-酮戊二酸进入糖异生。甘油经甘油-3-磷酸、磷酸二羟丙酮进入糖异生"},{"q":"糖原的1个葡萄糖基经糖酵解可生成","o":["1个ATP","2个ATP","3个ATP","4个ATP","5或6个ATP"],"a":2,"e":"糖原的葡萄糖基经磷酸化酶磷酸解生成葡萄糖-1-磷酸，再转变为葡萄糖-6-磷酸进入糖酵解，省去己糖激酶消耗的一个ATP，故净生成3个ATP，而游离葡萄糖净得2个。糖原合成时虽消耗UTP，但分解供能时以磷酸解方式节省ATP，这是糖原供能效率高于游离葡萄糖的原因"},{"q":"对乳糖操纵子而言","o":["CAP是正性调节因素，阻遏蛋白是负性调节因素","CAP是负性调节因素，阻遏蛋白是正性调节因素","CAP和阻遏蛋白都是正性调节因素","CAP和阻遏蛋白都是负性调节因素","CAP和阻遏蛋白在不同的反应条件下，均显示是正性和负性双向调节因素"],"a":0,"e":"乳糖操纵子受双重调节：葡萄糖缺乏时cAMP升高，CAP-cAMP复合物结合启动子上游促进转录，为正性调节；有乳糖时别乳糖使阻遏蛋白脱离操纵序列，为负性调节。二者并非均为正性或均为负性，也不呈双向调节"},{"q":"调控自身基因转录激活的DNA序列是","o":["顺式作用因子","顺式作用元件","反式作用因子","反式作用元件","顺/反式作用元件"],"a":1,"e":"顺式作用元件是位于基因旁侧、能调控同一DNA分子上自身基因转录的DNA序列，包括启动子、增强子等。顺式作用因子是对这类DNA结合蛋白的旧称；反式作用因子是识别顺式元件的蛋白质，由其他基因编码并可扩散，本质不是DNA序列；反式作用元件并非常用规范术语"},{"q":"乙酰CoA的代谢去路不包括","o":["进入三羧酸循环，彻底氧化为二氧化碳和水","羧化为丙二酰CoA，进一步合成脂酸","生成生酮氨基酸","生成酮体，作为能源","合成胆固醇"],"a":2,"e":"乙酰CoA可进入三羧酸循环彻底氧化、羧化为丙二酰CoA合成脂肪酸、合成胆固醇与酮体，但不能生成氨基酸。生酮氨基酸指亮氨酸与赖氨酸，只能由氨基酸分解产生乙酰CoA，不能反向生成。酮体、胆固醇与脂肪酸合成均以乙酰CoA为起点，三者在肝内都很活跃"},{"q":"下列对于血脂的叙述正确的是","o":["均不溶于水","主要以脂蛋白形式存在","都来自肝脏","与血细胞结合被运输","脂肪与清蛋白结合被转运"],"a":1,"e":"血脂不溶于水，在血中必须与载脂蛋白结合形成脂蛋白才能运输，故主要以脂蛋白形式存在。血脂来源包括食物与肝合成等，并非都来自肝脏。血脂不与血细胞结合运输。游离脂肪酸才与清蛋白结合转运，脂肪以脂蛋白形式运输。均不溶于水的表述过于绝对且未指出其运输形式"},{"q":"甲硫氨酸循环的需要维生素","o":["维生素PP","生物素","CoA","维生素B12","吡哆醛"],"a":3,"e":"甲硫氨酸循环中，N5-甲基四氢叶酸将甲基转给同型半胱氨酸生成甲硫氨酸，由甲硫氨酸合酶催化，辅酶为维生素B12。B12缺乏使甲基无法转移，叶酸滞留为N5-CH3-FH4，即叶酸陷阱。生物素参与羧化，CoA参与酰基转移，吡哆醛参与转氨，维生素PP为NAD/NADP成分，均非此循环所需"},{"q":"对于成熟的红细胞来说，最重要的一条代谢途径是","o":["磷酸戊糖途径","脂肪酸氧化","三羧酸循环","酮体合成","脂肪酸合成"],"a":0,"e":"成熟红细胞无线粒体，不能进行三羧酸循环、脂肪酸氧化、酮体生成及脂肪酸合成；其最重要的代谢途径之一是磷酸戊糖途径，产生NADPH以维持还原型谷胱甘肽、保护细胞免受氧化损伤。红细胞也依赖糖酵解供能，但糖酵解不在所给选项中"},{"q":"作用于细胞内受体的激素是","o":["甲状旁腺素","胰岛素","肾上腺素","干扰素","雌激素"],"a":4,"e":"雌激素属类固醇激素，脂溶性，可透过细胞膜与胞内受体结合调节基因转录。甲状旁腺素、胰岛素、肾上腺素、干扰素均为亲水激素，经膜受体和第二信使发挥作用。甲状腺素与1,25-(OH)2D3也作用于胞内受体"},{"q":"利用几根毛发进行基因诊断主要体现了基因诊断的哪项特点","o":["特异性高","灵敏度高","稳定性好","应用范围广","早期诊断"],"a":1,"e":"基因诊断可仅用几根毛发等极微量样品完成检测，体现其灵敏度高的特点。特异性高指能精确识别特定基因序列；稳定性好指样本不易降解；应用范围广指可用于多种疾病；早期诊断指症状出现前检出，均与样品用量少无直接对应"},{"q":"转录生成的RNA，通常5'端第一个碱基是","o":["pppG","pppC","pppU","pppA","pppT"],"a":0,"e":"转录起始时RNA聚合酶以GTP或ATP作为第一位核苷酸，多数启动子以GTP起始，新生RNA的5′-端保留三个磷酸基团，故为pppG。pppA亦可见但比例较低，C与U不作为起始核苷酸；pppT中的T为脱氧胸苷，只存在于DNA，不出现在RNA"},{"q":"蛋白质分子中α-螺旋和β-折叠都属于","o":["一级结构","二级结构","三级结构","四级结构","五级结构"],"a":1,"e":"α-螺旋与β-折叠是肽链主链局部空间排布的规律构象，属二级结构，不涉及侧链构象。一级结构指氨基酸序列，三级结构指整条肽链的全部三维折叠，四级结构指亚基间的空间排布，无五级结构之说"},{"q":"合成糖蛋白糖链的酶存在于","o":["细胞核","细胞膜","细胞液","线粒体","内质网"],"a":4,"e":"糖蛋白糖链的合成与加工由内质网和高尔基体的糖基转移酶催化，长萜醇载体上的寡糖前体在内质网组装并转移至肽链，故合酶系存在于内质网，高尔基体只承担后期修剪。细胞核无糖基化功能，细胞质溶胶缺乏相应的膜结合酶与糖核苷酸转运系统，溶酶体只负责降解"},{"q":"全基因组鸟枪法测序的主要步骤，不包括","o":["建立基因组文库","高效大规模双向测序","序列组装","检测微卫星位点","缺口填补"],"a":3,"e":"全基因组鸟枪法直接将基因组打成不同大小片段构建文库，随机双向测序后经生物信息学拼接并补缺口。检测微卫星位点属基因多态性分析或法医学个体识别，与测序流程无关；建库、大规模测序、组装、补缺口为其主要步骤"},{"q":"甘油氧化分解及其异生成糖的共同中间产物是","o":["丙酮酸","2-磷酸甘油酸","3-磷酸甘油酸","磷酸二羟丙酮","磷酸烯醇式丙酮酸"],"a":3,"e":"甘油经甘油激酶生成甘油-3-磷酸，再脱氢生成磷酸二羟丙酮，后者可循糖酵解途径分解，也可经糖异生转变为葡萄糖，故为二者共同中间物。3-磷酸甘油酸、丙酮酸位于其下游。2-磷酸甘油酸与磷酸烯醇式丙酮酸只在糖酵解后半段出现"},{"q":"以下哪种胆汁酸不属于结合型次级胆汁酸","o":["甘氨石胆酸","牛磺鹅脱氧胆酸","牛磺脱氧胆酸","牛磺石胆酸","甘氨脱氧胆酸"],"a":1,"e":"牛磺鹅脱氧胆酸由鹅脱氧胆酸与牛磺酸结合而成，鹅脱氧胆酸属初级胆汁酸，故它属结合型初级胆汁酸。甘氨石胆酸、牛磺石胆酸、牛磺脱氧胆酸与甘氨脱氧胆酸分别由石胆酸、脱氧胆酸结合生成，属结合型次级胆汁酸"},{"q":"关于痛风症的叙述，错误的是","o":["是指患者血中尿酸含量升高","尿酸盐晶体会沉积于关节、软组织、软骨、肾脏等处，导致关节炎、尿路结石及肾疾病等","多见于成年女性","分原发性和继发性","别嘌呤醇是主要的治疗药物"],"a":2,"e":"痛风多见于成年男性而非女性，故该说法错误。其本质是嘌呤终产物尿酸生成过多或排泄减少，血尿酸升高，尿酸盐结晶沉积于关节、软组织、软骨与肾，引起关节炎、尿路结石及肾病，分原发与继发两类，别嘌醇抑制黄嘌呤氧化酶为主要药物"},{"q":"赖氨酸属于","o":["含硫氨基酸","碱性氨基酸","酸性氨基酸","含羟基的氨基酸","含芳香环的氨基酸"],"a":1,"e":"赖氨酸侧链含ε-氨基，属碱性氨基酸。精氨酸含胍基、组氨酸含咪唑基，同属碱性氨基酸。含硫氨基酸为半胱氨酸与甲硫氨酸，酸性氨基酸为天冬氨酸与谷氨酸，含羟基者为丝氨酸、苏氨酸与酪氨酸，含芳香环者为苯丙氨酸、酪氨酸与色氨酸"},{"q":"鸟类和哺乳类维持体温的能量来源都是细胞呼吸。ATP在细胞中易于再生，所以是源源不断的能源。水解时释放出能量较多，是生物体内最直接的能量来源。生物体内ATP最主要的来源是","o":["糖酵解","三羧酸循环","磷酸戊糖途径","氧化磷酸化作用","底物水平磷酸化"],"a":3,"e":"氧化磷酸化是NADH和FADH2经呼吸链氧化释能、驱动ADP磷酸化生成ATP的过程，体内ATP绝大部分由此产生。底物水平磷酸化只在糖酵解和三羧酸循环的少数步骤生成少量ATP，并非主要来源。糖酵解与三羧酸循环是产能物质的分解途径，磷酸戊糖途径不产能，只提供NADPH和核糖"},{"q":"合成一分子尿素需消耗高能磷酸键数目是","o":["1个","2个","3个","4个","5个"],"a":3,"e":"尿素合成中，CPS-Ⅰ生成氨基甲酰磷酸消耗2个高能键，精氨酸代琥珀酸合成酶催化瓜氨酸与天冬氨酸缩合时ATP变为AMP加PPi，又消耗2个高能键，共4个。精氨酸水解生成尿素与鸟氨酸不耗能。1、2、3、5个均少计或错计某一步"},{"q":"人类基因组中，编码蛋白质的基因大多数属于","o":["回文序列","卫星DNA","单拷贝序列","高度重复序列","中度重复序列"],"a":2,"e":"单拷贝序列又称低度重复序列，在基因组中仅出现一次或少数几次，大多数编码蛋白质的基因属于此类。卫星DNA与高度重复序列不编码蛋白质，回文序列是限制酶识别的反向重复结构，中度重复序列主要为rRNA、tRNA基因及散在重复元件"},{"q":"将1个完全被放射性标记的DNA分子放于无放射性标记的环境中复制三代后，所产生的全部DNA分子中，有放射性标记的DNA分子有","o":["1个","2个","4个","6个","8个"],"a":1,"e":"DNA复制为半保留复制，亲代两条放射性标记链分别进入两个子代分子，无论复制多少代，含放射性的DNA分子始终为2个。其余6个分子的两条链均在无标记环境中新合成，不含放射性。该实验是半保留复制的直接证据"},{"q":"维持DNA双螺旋稳定因素是","o":["核糖与碱基之间的糖苷键","碱基堆积力和氢键","碱基之间的磷酸二酯键","磷酸基团的亲水性","脱氧核糖上的羟基"],"a":1,"e":"DNA双螺旋靠互补碱基对间的氢键与疏水性碱基堆积力共同维系，前者保证配对特异性，后者贡献主要稳定能。糖苷键连接碱基与脱氧核糖，磷酸二酯键构成骨架，脱氧核糖无羟基而核糖才有。磷酸二酯键与糖苷键属共价键，不参与双螺旋结构的稳定"},{"q":"RNA在真核细胞DNA复制过程中所起的作用是","o":["DNA合成的模板","协助辨认复制起始位点","作为酶催化复制反应","参与复制终止阶段进程","作为引物"],"a":4,"e":"真核DNA复制需先由引物酶合成短段RNA引物，提供3'-OH端供DNA聚合酶延伸，故RNA的作用是作为引物。DNA模板是DNA自身；辨认复制起始位点靠起始蛋白复合物；催化复制反应的是DNA聚合酶；RNA不参与复制终止阶段"},{"q":"下列关于DNA分子的叙述，错误的是","o":["腺嘌呤的克分子数等于胸腺嘧啶的克分子数","同种生物体不同组织中的DNA碱基组成极为相似","DNA双螺旋中碱基对位于外侧","两股多核甘酸链通过A与T或C与G之间的氢键连接","维持双螺旋稳定的主要因素是氢键和碱基堆积力"],"a":2,"e":"DNA双螺旋中脱氧核糖与磷酸构成的亲水骨架位于外侧，碱基对包埋在双螺旋内侧，故该项错误。Chargaff规则表明A与T、G与C的摩尔数相等，同种生物不同组织DNA碱基组成相似，双链间靠A-T、G-C氢键相连，氢键与碱基堆积力维持双螺旋稳定"},{"q":"法医学个体识别的核心技术是","o":["PCR","DNA测序","Nouthern印迹","Southern印迹","基于STR的DNA指纹技术"],"a":4,"e":"基于PCR-STR的DNA指纹技术选取多个短串联重复位点扩增，产物长度具高度个体特异性，微量血痕、毛发即可认定，是法医学个体识别的核心技术。Southern印迹用于DNA片段分析，DNA测序用于突变检测，均非个体识别体系"},{"q":"将蛋白质溶液的pH值调节到其等电点时","o":["可使蛋白质稳定性增加","可使蛋白质稳定性降低，易于沉出","可使蛋白质表面的净电荷不变","可使蛋白质表面的净电荷增加","对蛋白质表面水化膜无影响"],"a":1,"e":"pH等于等电点时蛋白质净电荷为零，分子间静电斥力消失，电荷与水化膜双重稳定因素被削弱，颗粒易聚集沉淀。pH偏离等电点时分子带同种电荷而互相排斥，稳定性反而增加；此时表面净电荷为零而非增加或不变，水化膜本身未被破坏但保护作用下降"},{"q":"苯丙酮尿症患者是由于缺乏","o":["苯丙氨酸转氨酶","酪氨酸酶","苯丙氨酸羟化酶","苯丙酮酸脱氢酶","酪氨酸羟化酶"],"a":2,"e":"苯丙酮尿症因肝中苯丙氨酸羟化酶缺乏，苯丙氨酸不能转化为酪氨酸，转而经转氨基生成苯丙酮酸等代谢物蓄积，损害神经系统。酪氨酸酶缺乏致白化病；酪氨酸羟化酶缺乏影响儿茶酚胺合成；其余所列酶并非苯丙酮尿症的缺陷酶"},{"q":"氨基酰tRNA的3'末端腺苷酸与氨基酸相连的基团是","o":["1'-OH","2'-OH","3'-OH","2'-磷酸","3'-磷酸"],"a":2,"e":"tRNA氨基酸臂CCA末端的腺苷酸以3'-OH与氨基酸羧基形成酯键，2'-OH虽可参与但产物不稳定。1'-OH参与碱基与核糖的连接，2'-磷酸与3'-磷酸不是tRNA末端结构。氨基酰tRNA合成酶消耗ATP完成氨基酸活化"},{"q":"下列关于酶的别构调节，错误的是","o":["受别构调节的酶称为别构酶","别构酶催化反应动力学符合米-曼氏方程","别构酶多是关键酶（如限速酶），催化的反应常是不可逆反应","别构调节是快速调节","别构酶分子常含有多个亚基"],"a":1,"e":"别构酶不遵守米氏方程，底物饱和曲线呈S形并具协同效应。别构酶多为关键酶、含多个亚基、通过构象改变实现快速调节；动力学不符合米-曼氏方程恰是其基本特点而非例外。别构效应剂可为底物、产物或其他小分子，结合于调节部位而非活性中心"},{"q":"以下关于常见复杂疾病相关基因鉴定技术的正确说法是","o":["GWAS（全基因组的关联研究）技术在单基因遗传病相关基因鉴定过程中具有很大的优势","GWAS（全基因组的关联研究）技术产生庞大数据信息并且假阳性很低","全外显子测序选择性检测蛋白编码序列","GWAS（全基因组的关联研究）与全外显子测序技术相比，在复杂疾病易感基因研究中体现出更高的检测性价比","GWAS（全基因组的关联研究）可以检测出疾病相关罕见突变的发生"],"a":2,"e":"全外显子测序仅选择性捕获并测序基因组中的外显子即蛋白编码序列，故该项正确。GWAS主要用于复杂疾病易感基因关联分析，在单基因遗传病中优势有限，数据量庞大且假阳性较高，难以检出罕见突变。其性价比相对全外显子测序并非更高，故其余选项错误"},{"q":"蛋白质多肽链具有方向性，其正确描述是","o":["3'端→5'端","5'端→3'端","N端→C端","C端→N端","羧基到氨基端"],"a":2,"e":"多肽链有极性，N端为氨基端即起始端，C端为羧基端即末端，书写与序列编号均自N端至C端，蛋白质合成也由N端向C端延伸。C端→N端方向与合成方向相反；“N端→C端→N端”不成序列。肽键平面虽限制旋转，但不改变链的方向性"},{"q":"某种非编码小RNA在生物体参与hnRNA的剪接过程。该种RNA是","o":["mRNA","tRNA","rRNA","sncRNA","snRNA"],"a":4,"e":"snRNA与多种蛋白质组成剪接体，识别hnRNA的外显子-内含子交界序列，催化内含子删除与外显子连接，故参与hnRNA剪接的是snRNA。snoRNA参与rRNA前体的加工与修饰，miRNA与siRNA介导靶mRNA降解或翻译抑制，hnRNA本身是mRNA的前体，均非剪接的催化组分"},{"q":"生物转化反应中参与氧化反应最重要的酶是","o":["单加氧酶（混合功能氧化酶）","加双氧酶","水解酶","胺氧化酶","脱氢酶"],"a":0,"e":"生物转化第一相反应的氧化以肝细胞微粒体细胞色素P450单加氧酶最为重要，该酶以NADPH供氢，使一个氧原子掺入底物、另一个还原成水，故又称混合功能氧化酶。加双氧酶、胺氧化酶与脱氢酶作用范围有限，水解酶属第二相水解反应"},{"q":"可以直接进行未知疾病相关基因鉴定分离的方法是","o":["Northern印迹法","cDNA芯片","RNA酶保护试验","RT-PCR","原位杂交"],"a":1,"e":"cDNA芯片可一次性检测大量基因的表达差异，通过比较疾病与正常组织表达谱直接筛选、鉴定未知疾病相关基因，故为答案。Northern印迹、RNA酶保护试验、RT-PCR、原位杂交均需已知序列设计探针或引物，用于已知基因的检测验证，不适合直接分离未知基因"},{"q":"基因芯片是将哪种成分以何种方式固定于单位面积的支持物上的","o":["许多特定的多肽片段有规律地紧密排列","许多特定的探针有规律地紧密排列","许多特定的DNA片段有规律地紧密排列","许多特定的DNA片段随机地紧密排列","许多特定的 RNA片段有规律地紧密排列"],"a":2,"e":"基因芯片又称DNA微阵列，是将大量已知序列的DNA片段有规律地微量点样或原位合成于硅片等支持物上，再与荧光标记的待测样品杂交，通过各点荧光信号判断序列与表达量。“探针”是这些片段的统称而非本题所指的固定物；多肽与RNA片段均不作芯片固定相；随机排列无法定位信号，失去芯片意义"},{"q":"下列不属于酶促共价修饰调节的是","o":["酶蛋白分子中的丝氨酸、苏氨酸及酪氨酸的磷酸化修饰","酶蛋白分子的乙酰化与去乙酰化修饰","核小体组蛋白分子的甲基化和去甲基化修饰","酶蛋白分子的腺苷化与去腺苷化互变","磷蛋白磷酸酶催化酶分子去磷酸化"],"a":2,"e":"酶的共价修饰限定在酶蛋白自身，磷酸化、乙酰化、腺苷化及其逆向去修饰均由相应酶催化，磷蛋白磷酸酶催化的去磷酸化正是其中一环。核小体组蛋白的甲基化与去甲基化修饰的是染色质结构蛋白，属基因表达调控的表观遗传修饰，改变的是染色质构象，不是酶活性的共价修饰调节"},{"q":"肝糖原分解直接补充血糖的原因是","o":["有糖原磷酸化酶","有强大的糖异生能力","有葡萄糖-6-磷酸酶","有葡萄糖激酶","有葡萄糖氧化酶"],"a":2,"e":"肝含有葡萄糖-6-磷酸酶，可将糖原分解产生的葡萄糖-6-磷酸水解为游离葡萄糖释放入血，直接补充血糖，故为答案。糖原磷酸化酶催化磷酸解生成葡萄糖-1-磷酸，为糖原分解共有酶，但肌糖原因缺乏葡萄糖-6-磷酸酶而不能补充血糖。葡萄糖激酶为磷酸化葡萄糖的酶，糖异生与葡萄糖氧化酶均非直接原因"},{"q":"糖、脂类和蛋白质三大营养物质分解的共同代谢途径是","o":["糖酵解途径","β-氧化过程","柠檬酸循环","鸟氨酸循环","磷酸戊糖通路"],"a":2,"e":"糖、脂与蛋白质分解都生成乙酰CoA，最终经三羧酸循环彻底氧化，故柠檬酸循环是共同通路。糖酵解仅糖可利用，β-氧化仅脂肪酸，鸟氨酸循环合成尿素，磷酸戊糖途径是糖代谢的分支。三羧酸循环在线粒体进行，是三大物质代谢相互联系的枢纽"},{"q":"下述产能过程不在线粒体的是","o":["三羧酸循环","脂肪酸β-氧化","电子传递","糖酵解","氧化磷酸化"],"a":3,"e":"糖酵解在细胞质中进行，1分子葡萄糖净生成2分子ATP和2分子NADH，是唯一不在线粒体的产能途径。三羧酸循环在线粒体基质，脂肪酸β-氧化在线粒体，电子传递与氧化磷酸化在线粒体内膜，均生成大量ATP"},{"q":"原癌基因的特点不包括","o":["广泛存在于各种生物细胞中","进化过程中基因序列具有高度的保守性","不同原癌基因的功能各不相同","不同原癌基因的定位各不相同","所有的原癌基因一旦被激活，都具有致癌活性"],"a":4,"e":"原癌基因广泛存在于各种生物细胞，进化上高度保守，不同成员的功能与定位各异；但并非任一原癌基因激活就必然致癌，肿瘤发生需多基因、多步骤累积，且常需抑癌基因失活协同。故所有原癌基因一旦激活都具有致癌活性这一绝对化表述错误"},{"q":"胰岛素是由胰脏内的胰岛β细胞受内源性或外源性物质等的刺激而分泌的一种蛋白质激素。1922年开始用于临床，使过去称为不治之症的糖尿病患者得到挽救。下列胰岛素对糖代谢影响的论述正确的是","o":["促进糖的异生","促进糖原分解","抑制细胞膜载体转运葡萄糖入细胞","促进糖原合成","合成脂肪的能力降低"],"a":3,"e":"胰岛素使血糖去路增强、来源减弱：激活磷酸二酯酶降低cAMP，糖原合酶去磷酸化被活化、磷酸化酶受抑，糖原合成加速而分解减少。A、B项实为胰高血糖素的作用，它促进糖异生与糖原分解。C项方向相反，胰岛素促进GLUT4转位，加速葡萄糖入细胞；E项亦相反，胰岛素促进脂肪合成"},{"q":"在离体肝线粒体悬液中加入氰化物，则一分子β-羟丁酸氧化的P/O比值为","o":["0","1","2","3","4"],"a":0,"e":"氰化物抑制细胞色素氧化酶，阻断电子由Cyt aa3传给氧，呼吸链中断，氧化磷酸化完全停止，故P/O比值为0。β-羟丁酸经β-氧化及三羧酸循环产生的NADH无法被氧化，也无ATP生成。1至4的数值对应呼吸链部分偶联部位仍在工作，与氰化物作用不符"},{"q":"下列不参与构成核小体核心颗粒的蛋白是","o":["H1","H2A","H2B","H3","H4"],"a":0,"e":"核小体核心颗粒由H2A、H2B、H3、H4各两分子构成组蛋白八聚体，DNA缠绕其上形成核心结构。H1属连接组蛋白，结合于核小体之间的连接DNA并锁住DNA进出核心的位点，不参与核心颗粒构成。H2A、H2B、H3、H4均为核心组蛋白，是八聚体的组成部分，故只有H1不在其核心颗粒之列"},{"q":"下列哪种物质脱下的一对氢经呼吸链传递后P/O比约为2.5","o":["β-羟丁酸","琥珀酸","α-磷酸甘油","维生素C","脂酰CoA"],"a":0,"e":"β-羟丁酸脱氢生成乙酰乙酸时由NAD+接受氢，NADH经NADH呼吸链氧化，P/O比值约2.5。琥珀酸与α-磷酸甘油脱下的氢经FAD从复合体Ⅱ进入呼吸链，P/O为1.5；维生素C在复合体Ⅳ前供电子，脂酰CoA脱氢酶以FAD为辅基，比值同样为1.5"},{"q":"关于别构调节的叙述，哪一项是错误的","o":["别构酶常由两个以上亚基组成","别构调节剂常是些小分子代谢物","别构剂通常与酶活性中心以外的某一特定部位结合","途径的终产物通常是该途径起始反应酶的别构抑制剂","调节具有放大效应"],"a":4,"e":"别构调节通过效应剂与调节部位结合引起酶构象改变，无共价修饰，也不产生级联放大；放大效应是化学修饰调节即磷酸化-去磷酸化的特点，故E项错误。别构酶多为寡聚体，效应剂常为小分子代谢物，终产物反馈抑制途径的起始酶"},{"q":"磺胺类药物抑菌作用的机制是抑制","o":["二氢叶酸还原酶","二氢叶酸合成酶","四氢叶酸合成酶","四氢叶酸还原酶","叶酸合成酶"],"a":1,"e":"磺胺类药物与对氨基苯甲酸结构相似，竞争性抑制二氢蝶酸合酶，阻断二氢叶酸合成，使细菌核酸合成受抑。甲氨蝶呤抑制的是二氢叶酸还原酶，作用点在磺胺之后，对人和细菌的酶均有抑制。二氢乳清酸脱氢酶属嘧啶合成， aspartate转氨甲酰酶催化尿素循环第一步，均非其靶点"},{"q":"乙酰乙酸在体内不能直接转变生成","o":["丙酮","HMG-CoA","乙酰乙酰CoA","L-β羟丁酸","以上都不能"],"a":1,"e":"酮体生成的方向为乙酰乙酰CoA与乙酰CoA缩合成HMG-CoA，再裂解生成乙酰乙酸，故乙酰乙酸不能直接转变为HMG-CoA。乙酰乙酸可还原为β-羟丁酸、脱羧生成丙酮，也可经琥珀酰CoA转硫酶或硫激酶活化生成乙酰乙酰CoA"},{"q":"血浆脂蛋白密度由低到高的正确顺序是","o":["LDL、VLDL、CM、HDL","CM、VLDL、LDL、HDL","VLDL、LDL、CM、HDL","CM、VLDL、HDL、LDL","HDL、VLDL、CM、LDL"],"a":1,"e":"脂蛋白密度由脂质与蛋白质比例决定，脂质愈多密度愈低：CM含甘油三酯约90%，密度最低，VLDL次之，LDL以胆固醇为主，HDL蛋白质约占50%，密度最高，故顺序为CM、VLDL、LDL、HDL。HDL、VLDL、LDL、CM为倒序，其余排列均把LDL与VLDL的位置颠倒"},{"q":"关于DNA复制中化学反应的表述，错误的是","o":["新链走向与模板链走向相反","模板链的走向是3'→5'","新链走向与模板链走向相同","新链的延伸方向是5'→3'","形成3',5'-磷酸二酯键"],"a":2,"e":"DNA复制中两条链反向平行，新链走向与模板链相反，故新链走向与模板链走向相同的说法错误。模板链方向为3'→5'，新链沿5'→3'延伸，核苷酸间以3',5'-磷酸二酯键连接，这些表述均正确"},{"q":"下列哪项癌基因的表达产物是生长因子","o":["RAS","SIS","MYC","SRC","RAF"],"a":1,"e":"SIS编码血小板源生长因子β链，属细胞外生长因子类原癌基因产物。RAS与RAF编码细胞内信号转导分子，SRC编码非受体型酪氨酸激酶，MYC编码核内转录因子，均不分泌至细胞外。细胞外生长因子类原癌基因还包括INT-2"},{"q":"参与非线粒体氧化体系的酶类有","o":["加单氧酶","过氧化氢酶","过氧化物酶","琥珀酸脱氢酶","苹果酸脱氢酶"],"a":1,"e":"过氧化氢酶定位于过氧化物酶体，可分解H2O2，属非线粒体氧化体系，参与其中的过氧化氢代谢。琥珀酸脱氢酶为线粒体呼吸链复合体Ⅱ组分，苹果酸脱氢酶参与线粒体内三羧酸循环，二者均为线粒体酶，不属非线粒体氧化体系，构成最主要的易混点"},{"q":"下列有关酮体的描述错误的是","o":["酮体是肝脏输出能源的一种形式","酮体可作为脑和肌肉组织的重要能源","脂肪动员减少时肝内酮体生成增多","酮体是水溶性物质","丙酮可由呼吸道呼出"],"a":2,"e":"酮体在脂肪动员增强、肝内脂肪酸β氧化旺盛时生成增多；脂肪动员减少时酮体生成减少，故该项错误。酮体是肝输出能源的形式，包括乙酰乙酸、β-羟丁酸和丙酮，为水溶性物质，可作为脑和肌肉的重要能源，丙酮可经呼吸道呼出，其余各项描述正确"},{"q":"血红素合成的关键酶是","o":["己糖激酶","转氨酶","CPS-Ⅰ","ALA合酶","HMG-CoA合酶"],"a":3,"e":"ALA合酶在线粒体内以甘氨酸与琥珀酰CoA缩合生成ALA，是血红素合成的限速酶，辅酶为磷酸吡哆醛，受血红素反馈抑制。HMG-CoA合酶参与胆固醇与酮体生成，CPS-Ⅰ催化尿素合成的首步反应"},{"q":"结合胆红素是指","o":["胆红素-清蛋白","胆红素-Y蛋白","胆红素-葡糖醛酸","胆红素-Z蛋白","胆红素-珠蛋白"],"a":2,"e":"胆红素在肝细胞内经胆红素-葡萄糖醛酸基转移酶催化，由UDPGA提供葡萄糖醛酸基，生成葡萄糖醛酸胆红素即结合胆红素，水溶性大增而便于随胆汁排泄。胆红素-清蛋白是血中运输形式，属未结合胆红素；胆红素-Y蛋白、Z蛋白是肝内转运载体，仍属未结合型；胆红素-珠蛋白不存在"},{"q":"能使蛋白质沉淀而不变性的试剂是","o":["浓盐酸","浓氢氧化钠溶液","硫酸铵溶液","生理盐水","蒸馏水"],"a":2,"e":"高浓度硫酸铵等中性盐可使蛋白质脱水、屏蔽电荷而析出沉淀，但不破坏空间结构，沉淀可再溶解且活性保留，称盐析，故为答案。浓盐酸、浓氢氧化钠为强酸强碱，使蛋白质变性。生理盐水、蒸馏水不能使蛋白质发生这种不変性的盐析沉淀"},{"q":"赖氨酸的脱羧产物是","o":["腐胺","精脒","精胺","尸胺","乙醇胺"],"a":3,"e":"赖氨酸经细菌脱羧酶催化脱去羧基生成尸胺，与组胺、酪胺、色胺、苯乙胺同属肠道细菌对未消化蛋白质的腐败产物。鸟氨酸脱羧生成腐胺，腐胺再经丙胺转移生成精脒与精胺，丝氨酸脱羧生成乙醇胺，故其余各项分别对应其他氨基酸"},{"q":"与蛋白激酶G（PKG）信息传递途径有关的物质是","o":["环化鸟苷酸（cGMP）","热休克蛋白","1,4,5-三磷酸肌醇（IP3）","Ca2+","环腺苷酸（cAMP）"],"a":0,"e":"PKG即蛋白激酶G，其别构激活物为cGMP，由鸟苷酸环化酶催化GTP生成，故cGMP与该途径直接相关。cAMP是PKA的激活物，属另一通路。IP3为磷脂酶C水解PIP2的产物，主要促内质网释放Ca2+。Ca2+多通过钙调蛋白起作用，热休克蛋白为分子伴侣，均非PKG途径的第二信使"},{"q":"糖、脂肪酸与蛋白质三者之间代谢的交叉点是","o":["琥珀酸","丙酮酸","延胡索酸","乙酰辅酶A","磷酸烯醇式丙酮酸"],"a":3,"e":"乙酰CoA是糖、脂、蛋白质分解代谢的共同中间产物：糖酵解生成的丙酮酸氧化脱羧为乙酰CoA，脂肪酸β-氧化生成乙酰CoA，氨基酸碳骨架也汇入。丙酮酸是糖与氨基酸的交叉点，琥珀酸、延胡索酸属三羧酸循环中间物，磷酸烯醇式丙酮酸是糖异生中间物"},{"q":"糖酵解时哪一对代谢物提供P使ADP生成ATP","o":["3-磷酸甘油醛及磷酸烯醇式丙酮酸","1，3-二磷酸甘油酸及磷酸烯醇式丙酮酸","1-磷酸葡萄糖及1，6-双磷酸果糖","6-磷酸葡萄糖及2-磷酸甘油酸","1，3-二磷酸甘油酸及2-磷酸甘油酸"],"a":1,"e":"糖酵解中两次底物水平磷酸化分别由1,3-二磷酸甘油酸和磷酸烯醇式丙酮酸提供高能磷酸基给ADP。3-磷酸甘油醛、2-磷酸甘油酸、1-磷酸葡萄糖均非磷酸供体，1,6-双磷酸果糖是磷酸果糖激酶-1的产物，属耗能步骤产物"},{"q":"琥珀酸氧化呼吸链和NADH氧化呼吸链的共同组成部分是","o":["NADH","琥珀酸","CoQ","细胞色素类","FADH2"],"a":2,"e":"NADH呼吸链为复合体Ⅰ→Q→复合体Ⅲ→Cyt c→复合体Ⅳ→O2，琥珀酸呼吸链为复合体Ⅱ→Q→复合体Ⅲ→Cyt c→复合体Ⅳ→O2，两条链共用泛醌及其后组分。NADH、琥珀酸与FADH2分别是两条链的底物，不共用"},{"q":"下列蛋白质混合液通过凝胶过滤层析时，最先被洗脱下来的是","o":["马肝过氧化氢酶（相对分子量247 500）","肌红蛋白（相对分子量16 900）","人血清蛋白（相对分子量68 500）","牛G-乳球蛋白（相对分子量35 000）","牛胰岛素（相对分子量5 733）"],"a":0,"e":"凝胶过滤层析中分子量大者不能进入凝胶颗粒内部孔隙，随流动相最先被洗脱，分子量小者进入孔隙、路径长而最后洗脱。马肝过氧化氢酶分子量247500最大，故最先洗脱。牛胰岛素与肌红蛋白分子最小，最后洗脱，人血清蛋白与牛β-乳球蛋白居中"},{"q":"关于磷酸戊糖途径说法正确的是","o":["是体内产生CO2的主要来源","可生成NADPH供合成代谢需要","是体内生成糖醛酸的途径","饥饿时葡萄糖经此途径代谢增加","可生成NADPH，后者经电子传递链可生成ATP"],"a":1,"e":"戊糖磷酸途径生成NADPH与核糖-5-磷酸，NADPH为脂肪酸、胆固醇等合成代谢供氢。体内CO2主要来自丙酮酸脱氢酶复合体与三羧酸循环，糖醛酸由糖醛酸途径生成，饥饿时该途径减弱，NADPH不进入呼吸链产能"},{"q":"关于抑癌基因的说法错误的是","o":["可促进细胞的分化","可诱发细胞程序性死亡","突变时可能导致肿瘤发生","可抑制细胞过度生长","最早发现的是p53基因"],"a":4,"e":"最早发现的抑癌基因是RB基因，其缺失导致视网膜母细胞瘤；p53最初被当作癌基因，1989年后才证实野生型p53为抑癌基因。抑癌基因可抑制细胞过度生长、促进分化、诱发凋亡，突变失活则易致肿瘤发生"},{"q":"原核细胞中，识别基因转录起始点的是","o":["阻遏蛋白","转录激活蛋白","基础转录因子","特异转录因子","σ因子"],"a":4,"e":"原核RNA聚合酶全酶由核心酶与σ因子组成，σ因子辨认启动子并协助全酶结合模板，识别转录起始点后即脱落，核心酶继续延长。阻遏蛋白与激活蛋白属操纵子调控蛋白，基础转录因子和特异转录因子是真核转录因子，均不负责原核起始点识别"},{"q":"三羧酸循环的限速酶是","o":["丙酮酸脱氢酶","顺乌头酸酶","琥珀酸脱氢酶","延胡索酸酶","异柠檬酸脱氢酶"],"a":4,"e":"三羧酸循环的关键酶为异柠檬酸脱氢酶，催化异柠檬酸氧化脱羧生成α-酮戊二酸，受ATP、NADH抑制及ADP、Ca2+激活。丙酮酸脱氢酶为糖氧化脱羧的关键酶，不属循环本身。顺乌头酸酶、琥珀酸脱氢酶、延胡索酸酶催化循环中其他步骤，但均非限速酶"},{"q":"维生素B2是下列哪种辅酶或辅基的组成成分","o":["NAD+","NADP+","CoASH","TPP","FAD"],"a":4,"e":"维生素B2即核黄素，其活性形式为FMN和FAD，作为黄素酶的辅基传递氢原子。NAD+与NADP+含维生素PP即烟酰胺，CoASH含泛酸，TPP含维生素B1，四者与维生素B2无关"},{"q":"三羧酸循环中催化琥珀酸形成延胡索酸的酶是琥珀酸脱氢酶，此酶的辅因子是","o":["NAD+","CoASH","FAD","TPP","NADP+"],"a":2,"e":"琥珀酸脱氢酶是循环中唯一结合于线粒体内膜的酶，辅因子为FAD，脱下的氢经复合体Ⅱ交给泛醌，生成1.5分子ATP。NAD+为异柠檬酸脱氢酶、α-酮戊二酸脱氢酶及苹果酸脱氢酶的辅因子，TPP为α-酮戊二酸脱氢酶的辅酶之一，CoASH为硫解所需"},{"q":"下列哪一种酶经磷酸化修饰后被激活","o":["丙酮酸脱氢酶","磷酸果糖激酶-1","糖原磷酸化酶","糖原合酶","乙酰CoA羧化酶"],"a":2,"e":"糖原磷酸化酶经磷酸化由b型转为a型而激活，促进糖原分解。糖原合酶、丙酮酸脱氢酶、乙酰CoA羧化酶磷酸化后均失活；磷酸果糖激酶-1受AMP与果糖-2,6-二磷酸别构激活，并非磷酸化激活"},{"q":"不是以胆固醇为原料合成的化合物是","o":["胆汁酸","胆红素","雌二醇","1,25-(OH)2-D3","醛固酮"],"a":1,"e":"胆红素是铁卟啉化合物的降解产物，由血红素经血红素加氧酶及胆绿素还原酶催化生成，与胆固醇无关。胆汁酸、雌二醇、醛固酮及1,25-(OH)2-D3均以胆固醇为原料合成，分别经7α-羟化、芳香化及肾上腺皮质羟化等途径生成"},{"q":"关于钙的生理功能，错误的是","o":["血钙能降低神经肌肉的兴奋性","钙可降低毛细血管通透性","钙是代谢调节的第二信使","钙可降低心肌的兴奋性","钙参与血液凝固的作用"],"a":3,"e":"钙离子是心肌兴奋-收缩偶联的触发物，细胞外钙升高可增强心肌收缩力与兴奋性，故D项错误。血钙升高降低神经肌肉兴奋性，钙可降低毛细血管通透性、作为第二信使参与信号转导，并作为凝血因子Ⅳ参与血液凝固"},{"q":"乳糖操纵子的直接诱导剂是指","o":["β-半乳糖苷酶","β-半乳糖苷透性酶","葡萄糖","乳糖","半乳糖"],"a":4,"e":"乳糖本身不能直接结合阻遏蛋白，须先经通透酶进入细胞，再由β-半乳糖苷酶转变为别乳糖，别乳糖以半乳糖基与阻遏蛋白结合使其构象改变、从操纵序列脱落。β-半乳糖苷酶与透性酶是结构基因产物，属被诱导的酶而非诱导剂；葡萄糖引起分解代谢阻遏，降低cAMP使转录下降"},{"q":"合成胆固醇的酶系分布于","o":["线粒体+光面内质网","线粒体+高尔基体","细胞质+光面内质网","线粒体+溶酶体","细胞质+高尔基体"],"a":2,"e":"胆固醇合成酶系存在于胞质溶胶和光面内质网膜，乙酰CoA经柠檬酸转运至胞质，HMG-CoA还原酶位于内质网。线粒体是酮体生成与氧化磷酸化的场所，高尔基体参与糖蛋白加工，溶酶体负责蛋白水解"},{"q":"核酸具有紫外吸收特征的原因，是由于嘌呤和嘧啶环中有","o":["共轭双键","氮原子","硫原子","连接了核糖","连接了磷酸基团"],"a":0,"e":"嘌呤和嘧啶是含共轭双键的杂环分子，在260nm有特征性紫外吸收，可用于核酸定量及判断变性。氮原子、核糖与磷酸基团不产生该吸收峰；蛋白质的280nm吸收来自酪氨酸与色氨酸残基的共轭双键，两者常被互相设错"},{"q":"下列关于tRNA叙述，错误的是","o":["通常由几百个核苷酸组成，分子量较大","含有假尿嘧啶","磷酸与核糖的比值为1","含有胸腺嘧啶","含有二氢尿嘧啶"],"a":0,"e":"tRNA由74～95个核苷酸组成，分子量较小，是RNA中最小的一类。其含假尿嘧啶、二氢尿嘧啶及胸腺嘧啶等稀有碱基，磷与核糖比为1，呈三叶草形二级结构和倒L形三级结构，3'端为CCA，氨基酸即连接于此"},{"q":"下列有关胆汁酸的说法中，哪项是错误的","o":["又称为胆汁","通常以钠盐形式存在","为小肠吸收脂肪所必需","它的缺乏可导致脂溶性维生素的吸收障碍","在肝内以胆固醇为合成原料"],"a":0,"e":"胆汁酸是胆汁中的主要固体成分，以钠盐或钾盐形式存在，作为乳化剂促进脂肪及脂溶性维生素吸收，在肝内以胆固醇为原料合成。胆汁酸不等于胆汁，胆汁尚含胆红素、胆固醇、磷脂；其缺乏将影响脂肪消化与脂溶性维生素吸收"},{"q":"下列对磷生理功能的叙述，错误的是","o":["构成骨盐成分","是核酸的组成成分","不参与细胞膜的组成","参与体内能量代谢","参与维持体内酸碱平衡"],"a":2,"e":"磷是骨盐羟基磷灰石的组成成分，也是核酸与磷脂的组成成分，磷脂为细胞膜的基本骨架，故“不参与细胞膜的组成”错误。磷还以磷酸酯形式参与能量代谢与酶的磷酸化修饰，并作为磷酸盐缓冲对参与维持酸碱平衡"},{"q":"顺式作用元件是指","o":["基因的5'-端序列","基因的3'-端序列","基因5'-端序列以外的序列","基因3'-端序列以外的序列","具有转录调节功能的特异DNA序列"],"a":4,"e":"顺式作用元件是可影响自身基因转录活性的特异DNA序列，包括启动子、增强子与沉默子，多位于基因附近但不必在5'或3'端。增强子可远距离发挥作用，沉默子抑制转录。反式作用因子才是蛋白质，与顺式元件结合发挥调节作用"},{"q":"关于未结合胆红素，下列说法正确的是","o":["称为肝胆红素","凡登白试验间接阳性","是血浆中不与任何物质结合的胆红素","水溶性较大，易在尿中出现","不易进入脑组织产生毒性"],"a":1,"e":"未结合胆红素与清蛋白结合运输，不能直接与重氮试剂反应，需加乙醇等加速剂后才显色，故凡登白试验呈间接阳性。它并非不与任何物质结合，且为脂溶性、不能经尿排出，易透过血脑屏障产生神经毒性；肝胆红素指结合胆红素"},{"q":"有关LDL的叙述，不正确的是","o":["富含apo AⅠ和apo B100","可经受体途径降解","胆固醇和胆固醇酯含量丰富","主要在肝脏降解","由VLDL转变生成"],"a":0,"e":"LDL主要含apo B100，不含apo AⅠ；apo AⅠ是HDL的主要载脂蛋白，故富含apo AⅠ和apo B100的说法错误。LDL由VLDL经IDL转变生成，富含胆固醇及胆固醇酯，可经LDL受体途径被细胞摄取降解，主要在肝脏清除，其余各项均为LDL的正确特征"},{"q":"定位于线粒体内膜上的酶系统是","o":["糖酵解酶系","磷酸戊糖途径酶系","呼吸链","三羧酸循环酶系","脂肪酸合酶"],"a":2,"e":"呼吸链的四个蛋白质复合体及泛醌、细胞色素c均嵌于或附着于线粒体内膜，催化NADH和FADH2的氧化。糖酵解酶系、磷酸戊糖途径酶系位于胞质溶胶，脂肪酸合酶亦在胞质。三羧酸循环酶系位于线粒体基质，仅琥珀酸脱氢酶结合于内膜"},{"q":"下列具有受体酪氨酸蛋白激酶活性的是","o":["甲状腺素受体","雌激素受体","乙酰胆碱受体","表皮生长因子受体","肾上腺素受体"],"a":3,"e":"表皮生长因子受体属受体酪氨酸激酶，配体结合后二聚化并发生自身磷酸化。甲状腺素与雌激素受体位于核内，属核受体；乙酰胆碱受体为离子通道型，肾上腺素受体为G蛋白偶联受体。胰岛素受体亦属受体酪氨酸激酶，类固醇激素受体则位于核内"},{"q":"参与合成人体蛋白质的氨基酸，不是L-α氨基酸的是","o":["甘氨酸","丙氨酸","丝氨酸","亮氨酸","异亮氨酸"],"a":0,"e":"组成蛋白质的20种氨基酸除甘氨酸外均为L-α-氨基酸，甘氨酸的α-碳连接两个氢原子，无不对称碳原子、不具旋光性，故无L与D之分。丙氨酸、丝氨酸、亮氨酸和异亮氨酸均有手性α-碳，属L-α-氨基酸"},{"q":"酶的磷酸化修饰常发生在","o":["赖氨酸的ε-氨基","含羧基的氨基酸残基","组氨酸的咪唑基","含羟基的氨基酸残基","半胱氨酸的巯基"],"a":3,"e":"蛋白激酶将ATP的γ-磷酸基转移至底物蛋白丝氨酸、苏氨酸、酪氨酸残基侧链的羟基，故磷酸化修饰发生在含羟基的氨基酸残基。赖氨酸的ε-氨基、组氨酸的咪唑基、半胱氨酸的巯基不带羟基，分别参与酰化、质子传递与二硫键形成。含羧基的残基带负电荷，不是磷酸化位点"},{"q":"克隆的真核基因组DNA可在多种系统表达，但例外的是","o":["E、coli表达体系","哺乳类细胞","酵母表达体系","昆虫表达体系","CHO细胞表达体系"],"a":0,"e":"E.coli缺乏转录后加工与翻译后修饰机制，不能剪接内含子、不能糖基化，基因组DNA克隆在其内难以表达有活性的真核蛋白，只能表达cDNA编码产物。哺乳类细胞、酵母、昆虫细胞与CHO细胞均具加工能力，可表达基因组DNA"},{"q":"通常G蛋白偶联的受体存在于","o":["线粒体","微粒体","细胞核","细胞膜","细胞质"],"a":3,"e":"G蛋白偶联受体是七次跨膜的单体蛋白，氨基端在膜外、羧基端在膜内，胞内环与三聚体G蛋白结合，故存在于细胞膜。类固醇激素受体位于细胞质或细胞核，不属GPCR。线粒体、微粒体上无此类受体分布"},{"q":"关于tRNA分子，下面描述正确的是","o":["tRNA分子多数由80个左右的氨基酸组成","tRNA的功能是结合蛋白质合成所需要的各种辅助因子","tRNA的3'末端有氨基酸臂","反密码环中的反密码子，可以结合DNA中相互补的碱基","tRNA的5'末端有多聚腺苷酸结构"],"a":2,"e":"tRNA的3'端为CCA序列，其腺苷酸核糖羟基与氨基酸形成酯键，称氨基酸臂；反密码环的反密码子与mRNA密码子互补而非与DNA配对。tRNA由70～90个核苷酸组成，5'端无多聚腺苷酸，功能是搬运氨基酸而非结合辅助因子"},{"q":"体内合成长链脂酸的主要原料是","o":["乙酰辅酶A","丙酰辅酶A","乙酰乙酰辅酶A","草酰乙酸","葡萄糖"],"a":0,"e":"长链脂肪酸以乙酰CoA为基本原料，在胞质溶胶经脂肪酸合酶复合体反复缩合、还原、脱水、再还原，每次延长2个碳，先合成16碳软脂酸再延长。丙酰CoA是奇数碳脂肪酸及支链氨基酸的代谢产物，只能作为起始单位生成少量奇数碳脂酸；乙酰乙酰CoA、草酰乙酸、葡萄糖均非直接原料"},{"q":"有关不对称转录，叙述正确的是","o":["模板链并非永远在同一DNA单链","没有规律的转录","双向复制后的转录","同一单链DNA转录时，可以从5′→3′或者3′→5′延长","转录产物翻译生成的多肽中的氨基酸含有不对称碳原子"],"a":0,"e":"不对称转录指双链DNA中只有一条链作为模板，且模板链并非固定在某一单链上，同一DNA分子中不同基因的模板可位于不同链，故该说正确。转录方向恒为5′→3′，与模板链反向平行；模板链也称反义链，编码链又称有意义链；RNA聚合酶沿模板3′→5′方向移动"},{"q":"抗霉素A是呼吸链特异抑制剂，它作用于","o":["NADH-辅酶Q还原酶","琥珀酸-辅酶Q还原酶","还原辅酶Q与细胞色素c还原酶","细胞色素b到QN的电子传递","ATP合酶"],"a":3,"e":"抗霉素A阻断复合体Ⅲ中Cyt b到QN的电子传递，使Q循环中断，QH2不能将电子交给Cyt c1。NADH-辅酶Q还原酶为复合体Ⅰ，琥珀酸-辅酶Q还原酶为复合体Ⅱ，ATP合酶为复合体Ⅴ，均非其作用部位"},{"q":"下列代谢物经相应特异脱氢酶催化脱下的2H，不能经过NADH呼吸链氧化的是","o":["异柠檬酸","苹果酸","α-酮戊二酸","琥珀酸","丙酮酸"],"a":3,"e":"琥珀酸脱氢酶以FAD为辅基，脱下的氢经复合体Ⅱ即琥珀酸-泛醌还原酶交给泛醌，走FADH2呼吸链，不经复合体Ⅰ。异柠檬酸、苹果酸、α-酮戊二酸及丙酮酸脱氢均生成NADH，经NADH呼吸链氧化"},{"q":"下列不参与甘油三酯合成的化合物是","o":["3-磷酸甘油","脂酰辅酶A","CDP-甘油二酯","磷脂酸","甘油二酯"],"a":2,"e":"甘油三酯合成经甘油-3-磷酸与脂酰CoA酰化生成磷脂酸，脱磷酸成甘油二酯，再与脂酰CoA缩合。CDP-甘油二酯是磷脂酰肌醇、心磷脂等甘油磷脂合成的活化中间物，不参与甘油三酯合成。磷脂酸与甘油二酯均为甘油三酯合成的中间物"},{"q":"有关同工酶的正确叙述是","o":["同工酶具有相同的理化性质","同工酶对同种底物亲和力相同","同工酶的空间结构一定相同","组成同工酶的亚基一定相同","不同组织中同工酶谱不同"],"a":4,"e":"同工酶催化相同反应但分子形式不同，不同组织表达的同工酶谱各异，如乳酸脱氢酶在心肌与骨骼肌的亚基组成不同。同工酶的理化性质、对底物亲和力及空间结构各异，组成亚基也可不同，故相同、一定相同等表述错误"},{"q":"关于肿瘤抑制基因的叙述，错误的是","o":["突变时可导致肿瘤发生","p16基因是最早发现的抑癌基因","促进细胞的分化","抑制细胞过度生长","诱发细胞程序性死亡"],"a":1,"e":"最早发现的抑癌基因是Rb，经视网膜母细胞瘤家系定位克隆获得；p16发现较晚，属细胞周期负调控因子。抑癌基因抑制细胞过度生长、促进分化并诱发凋亡，其突变或缺失使负性调控丧失而致肿瘤"},{"q":"有关脂肪酸活化的描述，错误的是","o":["增加水溶性","增加代谢活性","消耗ATP","在线粒体内进行","由脂酰CoA合成酶催化"],"a":3,"e":"脂肪酸活化在胞质溶胶中由脂酰CoA合成酶催化，消耗ATP生成脂酰CoA，增加水溶性并为β-氧化提供活性形式。生成的脂酰CoA需经肉碱穿梭才能进入线粒体，故活化并非在线粒体内进行"},{"q":"酶原之所以没有酶活性是因为","o":["缺乏辅助因子","活性中心未形成或未暴露","已经变性","酶原分子被其他物质包裹","肽链合成不完全"],"a":1,"e":"酶原无活性是因为其活性中心尚未形成或被遮蔽，需经有限水解切除部分肽段、构象改变后活性中心暴露才有活性。缺乏辅助因子指结合酶的全酶形成问题；酶原并未变性，肽链合成完整，也未被其他物质包裹，这些均非酶原无活性的原因"},{"q":"目前的基因治疗中，应用最多的载体是","o":["腺病毒载体","腺相关病毒载体","逆转录病毒载体","单纯疱疹病毒载体","慢病毒载体"],"a":2,"e":"逆转录病毒载体感染细胞后经逆转录并整合，可将目的基因稳定整合于宿主染色体而长期表达，转移效率高、宿主范围广，是基因治疗中应用最多的载体。腺病毒、腺相关病毒、单纯疱疹病毒与慢病毒载体各有适用场合但非最多用"},{"q":"关于关键酶的叙述哪一项是错误的","o":["关键酶常位于代谢途径的第一步反应","关键酶在代谢途径中活性最高，所以对整个代谢途径的流量起决定作用","关键酶常是变构酶","受激素调节的酶常是关键酶","关键酶常催化单向反应或非平衡反应"],"a":1,"e":"关键酶催化途径首步或分支点反应，速度最慢、活性最低，其活性决定整条途径的流量与方向，而非活性最高。关键酶常为别构酶，多催化单向非平衡反应，并受激素经共价修饰调节。关键酶活性最低而非最高，其催化反应速度最慢，故限制整条途径的速率"},{"q":"1mol软脂酸彻底氧化时可净生成的ATP摩尔数是","o":["30","32","38","106","108"],"a":3,"e":"软脂酸经7次β-氧化生成7分子FADH2、7分子NADH和8分子乙酰CoA，按1.5、2.5、10计算共得106分子ATP。30与32为短链脂肪酸的产能数值，38为旧版按整数计算的软脂酸产能，108无依据"},{"q":"免疫球蛋白多样性产生的机制，是由于发生了基因","o":["整合","转染","转化","转位","转导"],"a":3,"e":"免疫球蛋白重链与轻链基因由V、D、J片段经基因转位重排拼接，产生大量可变区组合，是多样性产生的主要机制。整合指病毒DNA插入宿主基因组，转化是细胞摄取外源DNA，转导是经噬菌体转移基因"},{"q":"运输外源性甘油三酯的血浆脂蛋白是","o":["CM","VLDL","LDL","HDL","IDL"],"a":0,"e":"乳糜微粒由小肠黏膜细胞组装，经淋巴入血，运输食物来源的外源性甘油三酯与胆固醇。VLDL运输肝合成的内源性甘油三酯，LDL将内源性胆固醇运至肝外组织，HDL逆向转运胆固醇，IDL是VLDL向LDL转化的中间物，均不承担外源性甘油三酯的运输"},{"q":"脂肪动员增加时，脂酸在肝内分解产生的乙酰CoA最易转变为","o":["非必需氨基酸","二氧化碳、水和能量","肝糖原","酮体","胆固醇"],"a":3,"e":"脂肪动员增加时肝内脂肪酸β氧化产生大量乙酰CoA，而草酰乙酸因用于糖异生而相对不足，乙酰CoA不能充分进入三羧酸循环，转而在肝内缩合生成酮体，故最易转变为酮体。非必需氨基酸与肝糖原需其他前体。二氧化碳、水和能量为彻底氧化产物，但此处因草酰乙酸不足而受限。胆固醇合成需特定条件且量较少"},{"q":"体内核苷酸从头合成过程中的底物可由以下哪条代谢通路直接提供","o":["葡萄糖的无氧酵解过程","氨基酸的脱氨基作用","磷酸戊糖通路","甘油三酯的脂肪动员过程","尿素的合成过程"],"a":2,"e":"核苷酸从头合成以核糖-5-磷酸为骨架，后者由磷酸戊糖通路生成，嘌呤环即在其上逐步构建。糖酵解提供丙酮酸与ATP，氨基酸脱氨基产生氨与α-酮酸，脂肪动员供脂肪酸，尿素合成消耗氨，均不直接提供核糖磷酸"},{"q":"具有Ⅱ类启动子的基因是","o":["tRNA编码基因","5S rRNA编码基因","snRNA编码基因","蛋白质编码基因","microRNA编码基因"],"a":3,"e":"Ⅱ类启动子由TATA盒、转录起始点及上游元件组成，位于蛋白质编码基因转录起始点上游，由RNA聚合酶Ⅱ识别。Ⅰ类启动子用于rRNA基因，Ⅲ类启动子用于tRNA、5S rRNA与snRNA等小分子RNA基因，故其余各项对应其他类型启动子"},{"q":"哪种氨基酸脱氨基产生草酰乙酸","o":["谷氨酰胺","天冬氨酸","丝氨酸","谷氨酸","天冬酰胺"],"a":1,"e":"天冬氨酸经转氨基脱去氨基后生成草酰乙酸，二者在谷草转氨酶催化下可相互转变。谷氨酸与谷氨酰胺脱氨生成α-酮戊二酸，丝氨酸脱氨生成丙酮酸，天冬酰胺脱氨先生成天冬氨酸。草酰乙酸也可由丙酮酸经丙酮酸羧化酶直接生成，是糖异生的起始步骤"},{"q":"脂肪酸和胆固醇合成过程中的供氢体NADPH主要来自","o":["糖酵解","磷酸戊糖通路","糖的有氧氧化","脂类代谢","氨基酸分解代谢"],"a":1,"e":"磷酸戊糖途径的6-磷酸葡萄糖脱氢酶以NADP+为受氢体生成NADPH，为脂肪酸与胆固醇合成提供还原当量。糖酵解与有氧氧化产生的是NADH，脂类与氨基酸分解代谢主要生成NADH和FADH2，均不能大量提供合成所需的NADPH"},{"q":"下列哪种物质属于维生素D原","o":["胆钙化醇","谷固醇","7-脱氢胆固醇","25-羟胆钙化醇","24,25-羟胆钙化醇"],"a":2,"e":"7-脱氢胆固醇是维生素D3原，存在于皮肤，经紫外线照射转变为胆钙化醇（维生素D3）。胆钙化醇及其羟化物25-羟胆钙化醇、24,25-羟胆钙化醇已是维生素D的活性形式或代谢物；谷固醇是植物甾醇，不是人体的维生素D原"},{"q":"tRNA分子不仅有稳定的二级结构，还有稳定的三级结构。tRNA分子的三级结构","o":["是三叶草型结构进一步折叠形成倒“L”型","是根据Chargaff规则研究出的","对于不同的tRNA典型结构并不相同","是三叶草结构进一步折叠成双螺旋","是典型的锌指结构"],"a":0,"e":"tRNA的三级结构是在三叶草形二级结构基础上进一步折叠形成的倒“L”型，靠碱基堆积和氢键维持，使反密码子环与氨基酸接受臂分处两端。Chargaff规则是DNA碱基组成规律，与tRNA折叠无关；不同tRNA的三级结构总体相似；锌指是DNA结合蛋白的模体，不是tRNA结构"},{"q":"下列维生素中，具有抗氧化作用的是","o":["硫胺素","核黄素","维生素E","维生素K","维生素D"],"a":2,"e":"维生素E是体内最重要的脂溶性抗氧化剂，位于细胞膜及脂蛋白中，捕获自由基，保护膜中不饱和脂肪酸免遭氧化。硫胺素为TPP前体，参与α-酮酸氧化脱羧与转酮醇；核黄素构成FMN、FAD，作递氢体。维生素K参与γ-羧化，维生素D调节钙磷代谢"},{"q":"酵母双杂交实验可用来检测","o":["蛋白质-蛋白质相互作用","蛋白质-DNA相互作用","蛋白质-RNA相互作用","DNA-DNA相互作用","DNA-RNA相互作用"],"a":0,"e":"酵母双杂交把诱饵蛋白与靶蛋白分别融合到转录因子的DNA结合域与激活域，两者相互作用使报告基因表达，专用于检测蛋白质-蛋白质相互作用。蛋白质-DNA作用常用EMSA与ChIP，蛋白质-RNA用RNA pull-down，DNA-DNA与DNA-RNA作用不用该体系"},{"q":"体内活性硫酸根是指","o":["PAPS","GABA","GSH","GSSG","SAM"],"a":0,"e":"体内活性硫酸根为3'-磷酸腺苷-5'-磷酸硫酸（PAPS），由ATP与硫酸根活化生成，是硫酸化反应的硫酸基供体，故为答案。SAM为活性甲硫氨酸，是甲基供体。GABA为抑制性神经递质。GSH为还原型谷胱甘肽，GSSG为氧化型谷胱甘肽，均参与氧化还原"},{"q":"噬菌体T4连接酶能催化连接的DNA末端是","o":["5'-P和3'-P","5'-OH和3'-P","5'-P和3'-OH","5'-OH和3'-OH","任意两种"],"a":2,"e":"DNA连接酶催化一个片段的3'-OH与另一片段的5'-磷酸基形成磷酸二酯键，需ATP供能。5'-OH与3'-OH均缺磷酸基，3'-磷酸不能作为受体，故只有5'-P与3'-OH末端可被连接"},{"q":"作用于膜受体的激素是","o":["肾上腺素","雌激素","甲状腺素","孕激素","醛固酮"],"a":0,"e":"肾上腺素、胰高血糖素、促肾上腺皮质激素等为水溶性激素，不能进入细胞，须与膜上特异性受体结合，经第二信使传递信号。甲状腺激素、雌激素、雄激素、糖皮质激素均属脂溶性激素，可透过细胞膜与胞内受体结合，调节基因转录"},{"q":"有氧氧化时，1mol葡萄糖在三羧酸循环中产生多少GTP","o":["2mol","6mol","18mol","24mol","36mol"],"a":0,"e":"1mol葡萄糖经三羧酸循环，琥珀酰CoA合成酶催化琥珀酰CoA转为琥珀酸时经底物水平磷酸化生成2mol GTP。18mol是呼吸链氧化磷酸化产生的ATP量，24mol与36mol均非循环内GTP生成量"},{"q":"不是操纵子组成部分的是","o":["结构基因","启动序列","阻遏物","CAP结合位点","操纵序列"],"a":2,"e":"操纵子由结构基因、启动序列、操纵序列及CAP结合位点等DNA元件组成；阻遏物是由调节基因编码的蛋白质，可作用于操纵序列，但本身不属于操纵子的结构组成，故不是操纵子的组成部分"},{"q":"霍乱毒素的作用机制是","o":["Go的ADP核糖化","Gq的ADP核糖化","Gsα的ADP核糖化","Gβγ的ADP核糖化","Giα的ADP核糖化"],"a":3,"e":"官方答案为【Gβγ的ADP核糖化】，但依据教材，正确答案为【Gsα的ADP核糖化】。霍乱毒素A亚基进入细胞后，以NAD+为供体使Gsα的Arg201发生ADP核糖化，GTP酶活性丧失，Gsα持续激活，腺苷酸环化酶大量生成cAMP，氯离子和水分泌亢进致水样泻。修饰位点在α亚基而非βγ复合体，Gβγ不具GTP酶活性，无法解释持续激活"},{"q":"甲基的直接供体是","o":["胆碱","N10-甲基四氢叶酸","甲硫氨酸","S-腺苷甲硫氨酸","肾上腺素"],"a":3,"e":"SAM即活性甲硫氨酸，其中的甲基为活性甲基，是体内最主要的甲基直接供体，参与50余种物质的甲基化。甲硫氨酸须先与ATP反应生成SAM才能供甲基；N5-甲基四氢叶酸、胆碱为甲基的间接来源或甲基化产物，肾上腺素是接受甲基的产物而非供体"},{"q":"酮体生成过多主要见于","o":["脂肪酸摄入过多","肝内脂肪代谢紊乱","糖供应不足或利用障碍","肝脏功能低下","脂肪运输障碍"],"a":2,"e":"糖供应不足或利用障碍时草酰乙酸生成减少，乙酰CoA不能充分进入三羧酸循环而转向酮体生成，见于饥饿与糖尿病。脂肪摄食过多而糖充足时酮体不增多，肝功能低下与脂肪运输障碍也不是主因。胰岛素缺乏时脂解加强、糖利用障碍，酮体生成进一步增多，可致酮症酸中毒"},{"q":"调节氧化磷酸化作用的重要激素是","o":["肾上腺素","甲状腺素","肾上腺皮质激素","胰岛素","生长素"],"a":1,"e":"甲状腺素能诱导Na+-K+-ATP酶生成，增加耗氧与产热，使基础代谢率升高，是调节氧化磷酸化的重要激素。肾上腺素作用短暂，主要经受体快速调节代谢；胰岛素、生长素及肾上腺皮质激素对氧化磷酸化无直接调节作用"},{"q":"构成赖氨酰氧化酶组分的元素是","o":["碘","硅","锰","钼","铜"],"a":4,"e":"赖氨酰氧化酶以铜为辅基，催化胶原分子中赖氨酸残基的ε-氨基氧化脱氨形成共价交联，铜缺乏则胶原交联障碍、血管脆性增加。碘参与甲状腺激素合成，硅与结缔组织有关，锰为多种酶的激活剂，钼参与黄嘌呤氧化酶等"},{"q":"关于DNA复制的表述，错误的是","o":["具有高保真性","需要RNA依赖的DNA聚合酶参加","是半保留复制","是半不连续复制","需要DNA依赖的DNA聚合酶参加"],"a":1,"e":"DNA复制以DNA为模板，需依赖DNA的DNA聚合酶，半保留、半不连续合成并具高保真性。依赖RNA的DNA聚合酶即逆转录酶，催化以RNA为模板合成DNA，属逆转录过程，不参与DNA复制"},{"q":"ALA合酶的辅酶是","o":["烟酰胺腺膘呤二核苷酸（NAD+）","黄素腺膘呤二核苷酸（FAD）","黄素单核苷酸（FMN）","磷酸吡哆醛","硫胺素焦磷酸酯（TPP）"],"a":3,"e":"ALA合酶催化甘氨酸与琥珀酰CoA缩合生成δ-氨基-γ-酮戊酸，辅酶为磷酸吡哆醛（维生素B6的活性形式），是血红素合成的限速酶。NAD+、FAD、FMN为氧化还原辅酶，TPP为α-酮酸氧化脱羧的辅酶，均非ALA合酶所需"},{"q":"DNA复制与转录过程有许多异同点，下列描述中不正确的是","o":["两过程均需DNA链作为模板","在复制和转录中合成方向均为5'→3'","复制的产物通常大于转录产物","两过程均需聚合酶和多种蛋白因子","两过程均需RNA引物"],"a":4,"e":"DNA复制需要RNA引物提供3'-OH起始延伸，而转录由RNA聚合酶直接从起始位点合成，不需引物，故两过程均需RNA引物的说法不正确。两者都以DNA为模板、合成方向均为5'→3'、均需聚合酶及多种蛋白因子；复制产物是整个基因组，通常大于转录产物"},{"q":"生物素作为辅酶，在酶促反应中","o":["传递CO2","转移酰基","转移甲基","传递氢原子","转移氨基"],"a":0,"e":"生物素作为羧化酶辅基，与酶蛋白赖氨酸残基共价结合，起固定并转移CO2的作用，参与丙酮酸羧化酶、乙酰CoA羧化酶催化的羧化反应。转移酰基由辅酶A与硫辛酸承担，转移甲基由SAM承担，传递氢由NAD+、FAD承担，转移氨基由磷酸吡哆醛承担"},{"q":"不参与脂肪酸氧化过程的化合物是","o":["肉碱","NAD+","NADP+","FAD","CoASH"],"a":2,"e":"脂肪酸β氧化中，脂酰CoA脱氢酶以FAD为辅基，β-羟脂酰CoA脱氢酶以NAD+为辅酶，CoASH参与硫解，肉碱负责将脂酰基转运入线粒体，均参与氧化过程。NADP+主要为脂肪酸合成等还原性合成供氢，不参与β氧化，故为答案"},{"q":"长链脂酰CoA通过线粒体内膜的载体是","o":["载体蛋白","3-磷酸甘油","柠檬酸","苹果酸","肉碱"],"a":4,"e":"长链脂酰CoA不能直接透过线粒体内膜，需经肉碱脂酰转移酶Ⅰ催化与肉碱生成脂酰肉碱，再由转位酶运入基质，由酶Ⅱ重新生成脂酰CoA并释出肉碱。载体蛋白、3-磷酸甘油、柠檬酸、苹果酸参与的是其他转运或穿梭系统"},{"q":"阿糖胞苷作为抗肿瘤药物的机制，是抑制了","o":["二氢叶酸还原酶的活性","核糖核苷酸还原酶的活性","二氢乳清酸脱氢酶胸苷酸合成酶的活性","胸苷酸合酶的活性","氨基甲酰基转移酶的活性"],"a":1,"e":"阿糖胞苷在体内转化为阿糖胞苷三磷酸，主要抑制核糖核苷酸还原酶，阻断核糖核苷酸还原为脱氧核糖核苷酸，从而抑制DNA合成。二氢叶酸还原酶受甲氨蝶呤抑制；胸苷酸合酶受氟尿嘧啶抑制；二氢乳清酸脱氢酶受来氟米特抑制，均非阿糖胞苷靶点"},{"q":"不参加DNA切除修复过程的酶是","o":["DNA聚合酶Ⅰ","DNA聚合酶Ⅲ","AP内切核酸酶","DNA连接酶","蛋白质UvrA、UvrB等"],"a":1,"e":"切除修复由核酸酶切除损伤片段，DNA聚合酶Ⅰ以其5'→3'外切及聚合活性填补缺口，再由DNA连接酶封口；UvrA、UvrB、UvrC参与核苷酸切除修复的识别与切割，AP内切酶参与碱基切除修复。DNA聚合酶Ⅲ是复制中的主要催化酶，不参与切除修复的填补"},{"q":"强烈抑制ALA合酶的物质是","o":["高铁血红素","促红细胞生成素","谷胱甘肽","睾酮","细胞色素P"],"a":0,"e":"血红素合成速度超过珠蛋白合成时，过多的血红素氧化为高铁血红素，后者对ALA合酶产生强烈反馈抑制，防止血红素堆积。促红细胞生成素促进红系增殖并诱导ALA合酶合成，属正向调节。睾酮可促进血红素合成，谷胱甘肽与细胞色素P均不作用于该酶"},{"q":"酶原激活的生理意义是","o":["避免细胞自身损伤","恢复酶活性","促进生长","加速代谢","保护酶的活性"],"a":0,"e":"消化道蛋白酶以酶原形式分泌，激活后仅在肠腔特定部位发挥作用，可避免胰腺自身消化及细胞外基质蛋白被水解，属保护性机制。酶原激活是肽键断裂暴露活性中心、由无活性变为有活性，并非恢复已失活的酶，也不直接促进生长或加速代谢"},{"q":"细胞内传递信息的第二信使是","o":["受体","载体","蛋白质","甘油三酯","小分子物质"],"a":4,"e":"第二信使是细胞内可扩散的小分子或离子，如cAMP、cGMP、IP3、DAG、Ca2+，在细胞内传递信号并调节信号转导蛋白活性。受体是接受配体的蛋白质，载体是膜转运蛋白，甘油三酯为储能脂质，蛋白质多为效应分子，均不承担胞内小分子信使功能"},{"q":"长期饥饿时大脑主要的能源物质是","o":["氨基酸","脂肪","葡萄糖","类脂","酮体"],"a":4,"e":"长期饥饿时肝内脂肪酸β氧化产生的乙酰CoA大量生成酮体，酮体透过血脑屏障后被脑组织氧化利用，成为大脑主要能源，故为答案。葡萄糖在短期饥饿时为主要能源，长期则供应受限。脂肪不能通过血脑屏障，脑不能直接氧化脂酸。氨基酸与类脂均非长期饥饿时脑的主要供能物质"},{"q":"端粒酶是一种","o":["依赖于DNA的DNA聚合酶","依赖于DNA的RNA聚合酶","依赖于RNA的DNA聚合酶","依赖于RNA的RNA聚合酶","特殊的核酶"],"a":2,"e":"端粒酶以自身RNA为模板，逆转录合成端粒DNA重复序列，本质是依赖RNA的DNA聚合酶，兼具逆转录酶活性。依赖DNA的DNA聚合酶为复制酶，依赖DNA的RNA聚合酶为转录酶，依赖RNA的RNA聚合酶为RNA复制酶"},{"q":"反竞争性抑制剂是与","o":["游离酶结合","[S]结合","[ES]结合","酶的活性中心相结合","酶的非必需基团相结合"],"a":2,"e":"反竞争性抑制剂只能与酶-底物复合物结合，其结合位点由底物诱导产生，形成IES后不能释放产物，使Vmax降低、表观Km减小。竞争性抑制剂与游离酶活性中心结合，非竞争性抑制剂则可与游离酶及复合物结合"},{"q":"原核生物蛋白质生物合成需要多种酶和蛋白质因子的参与。可以促进氨酰-tRNA进入A位，结合并分解GTP的延长因子是","o":["EF-Tu","EF-Ts","EF-G","eRF","RF-1"],"a":0,"e":"EF-Tu与GTP结合后携带氨酰-tRNA进入核糖体A位，GTP水解为GDP，EF-Tu-GDP释出后由EF-Ts置换GDP使之再生。EF-G具转位酶活性，推动肽酰-tRNA由A位移至P位。RF-1与eRF为释放因子，识别终止密码子，不参与进位"},{"q":"可直接激活蛋白激酶C的是","o":["环腺苷酸（cAMP）","环化鸟苷酸（cGMP）","1,4,5-三磷酸肌醇（IP3）","磷脂酰肌醇-4,5-二磷酸（PIP2）","二酯酰甘油（DAG）"],"a":4,"e":"DAG与钙离子共同激活PKC，促使其转位至细胞膜。cAMP激活PKA，cGMP激活PKG，IP3促使内质网释放钙，PIP2是磷脂酶C的底物、生成DAG和IP3的前体，本身不激活PKC"},{"q":"N5-甲基四氢叶酸中的甲基只能用于合成","o":["甲硫氨酸","嘧啶碱基","N5,N10-甲烯四氢叶酸","N5,N10-甲炔四氢叶酸","嘌呤碱基"],"a":0,"e":"N5-CH3-FH4是体内甲基的间接供体，其甲基经甲硫氨酸合成酶转移给同型半胱氨酸生成甲硫氨酸，再由SAM参与广泛甲基化反应。该甲基不能用于嘌呤环或嘧啶环的合成，嘌呤合成利用的是甲酰基、亚氨甲基等一碳单位。N5-CH3-FH4也不能转变为甲烯、甲炔四氢叶酸，此方向不可逆"},{"q":"关于嘌呤和嘧啶核苷酸从头和补救合成途径的比较，描述错误的是","o":["从头合成是以磷酸核糖、氨基酸等简单物质为原料，补救合成是利用体内游离的嘌呤或嘌呤核苷为原料","两者在不同组织中重要性各不相同","肝组织进行从头合成，而脑、骨髓等以补救合成为主","一般情况下，从头合成是合成的主要途径","一般情况下，补救合成是合成的主要途径"],"a":4,"e":"一般情况下从头合成是核苷酸合成的主要途径，补救合成为次要或辅助途径，故补救合成为主要途径的说法错误。从头合成以磷酸核糖、氨基酸、CO2等简单物质为原料，补救合成利用游离嘌呤或嘌呤核苷。肝以从头合成为主，脑、骨髓等缺乏从头合成能力而以补救合成为主，各组织重要性不同"},{"q":"关于管家基因的描述，下列最确切的是","o":["在生物个体全生命过程的几乎所有细胞中持续表达","在生物个体全生命过程的部分细胞中持续表达","在生物个体部分生命过程的部分细胞中持续表达","在特定环境下的生物个体全生命过程的所有细胞中持续表达","在特定环境下的生物个体全生命过程的部分细胞中持续表达"],"a":0,"e":"管家基因产物为生命全过程所必需，在生物个体几乎所有细胞、各发育阶段持续表达，受环境因素影响小。只在部分细胞、部分生命过程或特定环境下表达的基因属奢侈基因或诱导、阻遏表达基因，均不符管家基因定义"},{"q":"大多数处于活化状态的真核基因对DNaseⅠ","o":["低度敏感","中度敏感","高度敏感","不敏感","不一定"],"a":2,"e":"转录活化的染色质结构疏松、组蛋白修饰改变，对DNaseⅠ出现超敏位点，呈高度敏感。沉默基因对DNaseⅠ不敏感，低度或中度敏感不能反映基因的转录活性状态。超敏位点常位于启动子、增强子等调控序列，是染色质活化的标志"},{"q":"一个家族中有几代中的几位罹患了癌症，这有可能涉及癌基因的突变。下列选项中不是癌基因表达产物的是","o":["转录因子","蛋白酪氨酸激酶","生长因子","蛋白磷酸酶","生长因子受体"],"a":3,"e":"癌基因产物按功能分为生长因子、生长因子受体、蛋白酪氨酸激酶、G蛋白、核内转录因子等，分别作用于信号通路的各个环节。蛋白磷酸酶多为抑癌基因产物，如PTEN可水解PIP3而去除生长信号，方向与癌基因相反。蛋白酪氨酸激酶、生长因子及其受体、转录因子均可由原癌基因编码"},{"q":"关于体细胞杂交叙述不正确的是","o":["杂交细胞保留一方染色体，而另一方染色体逐渐丢失","利用碱基互补配对原则","可以利用该方法进行基因定位","杂交细胞含有双亲不同的染色体","胸苷激酶通过该方法定位于17号染色体"],"a":1,"e":"体细胞杂交通过灭活病毒或PEG介导使不同物种细胞融合，杂交细胞初期含双亲染色体，随后一方染色体逐渐丢失，据此可将基因定位到特定染色体，如胸苷激酶基因定位于17号染色体，故其余各项正确。该过程不依赖碱基互补配对原则，故该叙述不正确"},{"q":"合成甘油三酯能力最强的组织是","o":["肝脏","脂肪组织","小肠","肾脏","肌肉组织"],"a":0,"e":"肝脏合成甘油三酯能力最强，可将糖、脂酸等转化为甘油三酯并以VLDL形式输出，是内源性甘油三酯合成的主要场所，故为答案。脂肪组织主要为储存甘油三酯，也合成但能力不及肝。小肠合成外源性甘油三酯形成乳糜微粒。肾与肌肉合成能力弱"},{"q":"蛋白质在酶的作用下可完全水解成","o":["多肽","脂蛋白","氨基酸","脂蛋白与氨基酸","氨基酸与多肽"],"a":2,"e":"蛋白质在酶或酸、碱作用下完全水解，最终产物为组成它的氨基酸。多肽是部分水解产物；脂蛋白是脂类与蛋白质的复合物；脂蛋白与氨基酸、氨基酸与多肽均非完全水解的终产物"},{"q":"干扰素抑制病毒作用使elF2失活的修饰方式是","o":["磷酸化","羧基化","ADP核糖基化","甲基化","乙酰化"],"a":0,"e":"干扰素诱导的蛋白激酶R被双链RNA激活后，使eIF-2α磷酸化，eIF-2与GTP结合受阻，翻译起始被抑制。ADP核糖基化是白喉毒素修饰eEF-2的方式，甲基化、乙酰化、羧基化多发生于组蛋白或代谢酶，均不导致eIF-2失活"},{"q":"蛋白质的体外表达系统大体上可分为","o":["细菌表达系统与病毒表达系统","昆虫表达系统与酵母表达系统","酵母表达系统与病毒表达系统","原核表达系统与真核表达系统","哺乳动物表达系统与细菌表达系统"],"a":3,"e":"蛋白质体外表达系统按宿主分为原核表达系统与真核表达系统两类，前者以大肠埃希菌为代表，成本低、产量高但缺乏糖基化等翻译后修饰；后者包括酵母、昆虫细胞与哺乳动物细胞，可完成折叠与修饰。体内表达系统、无细胞翻译体系与化学合成均不属此分类，转基因与转染是导入手段"},{"q":"下列激素中，可抑制激素敏感性甘油三酯脂肪酶的是","o":["肾上腺素","胰高血糖素","胰岛素","TSH","ACTH"],"a":2,"e":"胰岛素降低血糖的同时抑制脂肪动员，通过激活磷酸二酯酶降低cAMP，使cAMP依赖蛋白激酶活性下降，激素敏感性甘油三酯脂肪酶不被磷酸化而保持低活性。肾上腺素、去甲肾上腺素、胰高血糖素、促肾上腺皮质激素均通过升高cAMP激活该酶，促进脂肪分解"},{"q":"第二信使二酯酰甘油（DAG）的来源是由","o":["甘油三酯水解而成","磷脂酰肌醇-4,5-二磷酸（PIP2）水解生成","卵磷脂水解产生","在体内合成","由胆固醇转化而来的"],"a":1,"e":"PIP2在磷脂酶C催化下水解生成DAG和IP3，DAG留在膜上激活PKC，IP3促使钙库释放钙。甘油三酯水解生成脂肪酸与甘油，卵磷脂水解生成溶血磷脂与脂肪酸，DAG并非由胆固醇转化而来"},{"q":"在细胞内，葡萄糖无氧氧化生成","o":["乳酸","脂肪酸","酮体","乙酰乙酸","核糖"],"a":0,"e":"葡萄糖无氧氧化在细胞质中经糖酵解生成丙酮酸，丙酮酸还原为乳酸，净生成2分子ATP。脂肪酸在细胞质合成但需乙酰CoA为原料，酮体在肝线粒体生成，乙酰乙酸属酮体，核糖由磷酸戊糖途径产生"},{"q":"合成血红素的基本原料是","o":["乙酸、CO、Fe2+","珠蛋白、Fe2+","琥珀酰CoA、Fe3+","乙酰CoA、甘氨酸、Fe2+","琥珀酰CoA、甘氨酸、Fe2+"],"a":4,"e":"血红素由琥珀酰CoA与甘氨酸缩合成δ-氨基-γ-酮戊酸起始，经系列反应生成原卟啉Ⅸ，最后在亚铁螯合酶催化下与Fe2+结合成血红素，故三种基本原料为琥珀酰CoA、甘氨酸和Fe2+。乙酰CoA不参与起始缩合；球蛋白是血红素的结合蛋白而非合成原料；镁用于合成叶绿素"},{"q":"丙酮酸脱氢酶复合体为直径约30nm的多角形，含有3种酶和5种辅酶。在糖的有氧氧化过程中，丙酮酸经丙酮酸脱氢酶复合体催化后的产物不包括","o":["乙酰CoA","FADH2","NADH＋H＋","CO2","丙酮"],"a":4,"e":"丙酮酸脱氢酶复合体催化氧化脱羧，产物为乙酰CoA、NADH+H+和CO2，脱下的氢经二氢硫辛酰胺脱氢酶传给NAD+，反应中可检出FADH2。丙酮由乙酰乙酸脱羧生成，属酮体成分，与该复合体无关"},{"q":"可用于基因表达谱分析的是","o":["Western blotting","原位杂交","PCR","DNA芯片","Southern blotting"],"a":3,"e":"DNA芯片将大量探针固定于固相载体，与标记核酸杂交，可同时检测成千上万个基因的表达水平，用于基因表达谱分析。Western印迹检测蛋白质，原位杂交定位单个核酸，PCR扩增特定片段，Southern印迹分析DNA"},{"q":"载体构建是基因工程常用的基本技术。要将外源的基因片段插入某个载体的多克隆位点，首先需要","o":["核酸外切酶","核酸内切酶","限制性的核酸内切酶","DNase","RNase"],"a":2,"e":"限制性核酸内切酶识别DNA回文序列并在特定位点切开磷酸二酯键，产生黏性或平端，是目的基因与载体连接的前提。核酸外切酶从链端逐个水解，DNase与RNase无序列特异性，普通核酸内切酶无特异识别位点"},{"q":"体内非必需氨基酸合成的主要途径是","o":["转氨基作用","联合脱氨基作用","嘌呤核苷酸循环","氧化脱氨基作用","还原脱氨基作用"],"a":1,"e":"官方答案为【联合脱氨基作用】，但依据教材，正确答案为【转氨基作用】。非必需氨基酸由α-酮酸接受氨基生成，催化此反应的是氨基转移酶，故合成途径为转氨基作用；联合脱氨基作用是转氨基与谷氨酸氧化脱氨偶联的分解途径，方向相反。嘌呤核苷酸循环是肌肉脱氨基的补充形式，氧化脱氨基主要针对L-谷氨酸"},{"q":"重组DNA技术领域常用的质粒DNA来自于","o":["原核细胞染色体DNA","原核细胞染色体外独立遗传单位","真核细胞染色体的DNA","真核细胞染色体外独立遗传单位","病毒DNA"],"a":1,"e":"质粒是细菌染色体外能自主复制、稳定遗传的双链环状DNA，不依赖染色体而独立存在，是重组DNA技术最常用的载体。真核细胞染色体外DNA如线粒体DNA不作常规载体，病毒DNA属另一类载体，染色体DNA片段缺乏复制起点，不能自主复制"},{"q":"下列关于tRNA分子的叙述，正确的是","o":["5'端是羟基化的","不具茎环结构","含有乙酰化的碱基","3'端的碱基顺序为-CCA","含有dTMP"],"a":3,"e":"绝大多数tRNA的3'端序列为CCA，是氨基酸结合位点。tRNA的5'端为磷酸基而非羟基；具典型茎环（三叶草）结构；以含稀有碱基为特征而非乙酰化碱基；含核糖核苷酸，不含dTMP，后者为DNA成分"},{"q":"肿瘤的发生除了与癌基因的异常活化以及肿瘤抑制基因的异常失活密切相关外，也与生长因子及其受体的高度活化密切相关，下列哪种生长因子的活化不能导致肿瘤的发生","o":["EGF","VEGF","TNF","IGF","EPO"],"a":4,"e":"促红细胞生成素主要促进红细胞生成，其活化一般不直接导致肿瘤发生；而EGF、IGF通过促细胞增殖，VEGF通过促血管生成，TNF参与炎症反应与肿瘤微环境，均与肿瘤发生发展密切相关。故活化不能导致肿瘤者为促红细胞生成素"},{"q":"克隆某一目的DNA的基本过程，不包括以下哪一项","o":["基因载体的选择与构建","外源基因与载体的拼接","重组DNA分子导入受体细胞","重组体的筛选","表达目的基因编码的蛋白质"],"a":4,"e":"DNA克隆的基本步骤为分、选、连、转、筛，即分离目的DNA与载体、拼接成重组体、导入受体细胞、筛选重组体。表达目的基因编码的蛋白质属克隆基因的表达，是基因工程的最终目标，不是克隆本身必需环节。载体构建与外源基因拼接分别是选与连的内容"},{"q":"原核生物非依赖Rho因子的转录终止方式是","o":["形成终止复合物","形成终止空泡","形成发夹结构","形成poly(A)的尾巴","形成三叶草的结构"],"a":2,"e":"非依赖Rho的终止依靠转录产物3′端形成富含GC的发夹结构，其后接一串寡聚U，发夹使RNA聚合酶停顿，rU-dA配对较弱使转录复合物解离。依赖Rho的终止则由Rho蛋白沿RNA移动并解旋RNA-DNA杂交体。σ因子参与起始识别，ρ因子即Rho，均不参与发夹式终止"},{"q":"使细胞内环化腺苷酸（cAMP）水平降低的因素有","o":["蛋白激酶C","蛋白激酶A","磷酸二酯酶","腺苷酸环化酶","磷脂酶C"],"a":2,"e":"磷酸二酯酶催化cAMP水解为5′-AMP，使cAMP水平下降、信号终止，胰岛素即通过增加该酶活性降低cAMP。腺苷酸环化酶催化ATP生成cAMP，使其升高；蛋白激酶A是cAMP的下游靶分子，蛋白激酶C由DAG与Ca2+激活，磷脂酶C水解PIP2生成IP3和DAG"},{"q":"反竞争性抑制作用的描述正确的是","o":["抑制剂既与酶相结合又与酶-底物复合物相结合","抑制剂只与酶-底物复合物相结合","抑制剂使酶促反应的Km值降低，Vmax增高","抑制剂使酶促反应的Km值升高，Vmax降低","抑制剂不改变酶促反应的Km值，只降低Vmax"],"a":1,"e":"反竞争性抑制剂只能与酶-底物复合物结合，使Km降低、Vmax降低，抑制剂结合后酶不能释放产物。与游离酶和复合物均结合者为混合性抑制，非竞争性抑制Km不变、Vmax降低，竞争性抑制Km升高、Vmax不变"},{"q":"在正常呼吸的线粒体中，不包含在复合体中的细胞色素是","o":["细胞色素a","细胞色素b","细胞色素c","细胞色素c1","细胞色素P450"],"a":2,"e":"细胞色素c是位于线粒体内膜外侧的可溶性载体，独立存在于膜间隙，不属于任何呼吸链复合体，负责在复合体Ⅲ与Ⅳ之间传递电子。细胞色素a、a3构成复合体Ⅳ，细胞色素b、c1属于复合体Ⅲ；细胞色素P450主要参与滑面内质网的生物转化，不参与线粒体呼吸链"},{"q":"氰化物中毒引起缺氧是由于","o":["微循环障碍","干扰氧的运输","中枢性肺换气不良","抑制细胞呼吸","氧耗增加"],"a":3,"e":"氰化物与细胞色素氧化酶即复合体Ⅳ的Fe3+结合，阻断电子由Cyt aa3传给氧，呼吸链中断，细胞不能利用氧，故缺氧的本质是抑制细胞呼吸。此时动脉血氧分压与氧饱和度正常，并非干扰氧的运输。微循环障碍、中枢性肺换气不良、氧耗增加分别见于休克、中枢抑制与高热甲亢"},{"q":"原核DNA复制中，①DNA聚合酶Ⅲ，②解旋酶，③DNA聚合酶Ⅰ，④引物酶，⑤DNA连接酶，⑥SSB的作用顺序是","o":["④③①②⑤⑥","②③⑥④①⑤","④②①⑤⑥③","④②⑥①③⑤","②⑥④①③⑤"],"a":4,"e":"复制起始时解旋酶先打开双链，SSB结合单链防止复性，引物酶合成RNA引物，DNA聚合酶Ⅲ延伸子链，DNA聚合酶Ⅰ切除引物并填补，DNA连接酶连接缺口，故顺序为②⑥④①③⑤。DNA聚合酶Ⅰ在聚合酶Ⅲ之后发挥作用，连接酶最后封口，其余选项顺序均与此不符"},{"q":"反竞争性抑制剂对酶促反应速率的影响是","o":["Km升高，Vmax不变","Km下降，Vmax下降","Km不变，Vmax下降","Km下降，Vmax升高","Km下降，Vmax不变"],"a":1,"e":"反竞争性抑制剂只与ES结合生成IES，使有效酶量减少，Vmax降低，同时表观Km减小。竞争性抑制Km增大、Vmax不变，非竞争性抑制Km不变、Vmax降低，三者靠双倒数作图的截距与斜率区分；Km下降而Vmax升高的组合不存在"},{"q":"在色氨酸操纵子中，衰减子存在于","o":["启动序列","操纵序列","调节序列","结构基因","前导序列"],"a":4,"e":"色氨酸操纵子的衰减子位于结构基因上游的前导序列内，通过前导肽翻译与mRNA二级结构形成调控转录是否提前终止，故为前导序列。启动序列为RNA聚合酶结合部位，操纵序列为阻遏蛋白结合部位，调节序列编码调节蛋白，结构基因编码色氨酸合成酶系，均非衰减子所在"},{"q":"白喉毒素可共价修饰下列哪种因子","o":["eIF-5","eEF-2","eIF-2","EF-1","eIF-4F"],"a":1,"e":"白喉毒素催化真核生物延长因子eEF-2发生二磷酸腺苷核糖基化修饰，使其失活，阻断蛋白质合成的延长阶段，故为答案。eIF-5、eIF-2、eIF-4F为真核起始因子，EF-1为原核延长因子，均非白喉毒素的作用靶点"},{"q":"下列哪种物质对巯基酶有直接的保护作用","o":["NADH","GSSG","GSH","FAD","泛酸"],"a":2,"e":"GSH的巯基可自身氧化为GSSG，从而保护酶分子中的巯基不被氧化，使含巯基的酶保持活性。GSSG为氧化型，无保护作用。NADH、FAD为递氢体，泛酸是CoA的组成成分，均不直接保护巯基"},{"q":"利用恰当的方法，把正在进行DNA复制的细胞里的冈崎片段分离出来，这些短链DNA应具有的特性是","o":["它们是双链的DNA","它们是一组短的单链DNA片段","它们是DNA/RNA杂化双链","它们的碱基序列具有一致性","它们是环状双链DNA"],"a":1,"e":"冈崎片段是随从链不连续合成的产物，为一组短的、与模板互补的单链DNA片段，原核生物长约1000～2000个核苷酸，随后由连接酶连接成完整链。其5′-端带RNA引物但主体为单链DNA，故非双链也非环状，各片段序列互不相同"},{"q":"蛋白质的含氮量是","o":["0、12","0、14","0、16","0、18","0、20"],"a":2,"e":"各种蛋白质含氮量接近，平均为16%，即每克氮相当于6.25克蛋白质，这是凯氏定氮法推算蛋白质含量的依据。0.12、0.14、0.18、0.20均非平均含氮比例；蛋白质含碳约50%～55%、含氧20%～23%，含氮量远低于这些元素"},{"q":"有关呼吸链叙述正确的是","o":["两条呼吸链由四种酶复合体组成","递电子体同时也是递氢体","递氢体同时也是递电子体","抑制Cyt a3，则呼吸链中各组分都呈氧化态","呼吸链的组分通常按E0由大到小的顺序排列"],"a":2,"e":"递氢体传递氢即同时传递H+与电子，故递氢体同时也是递电子体，如NAD+、FMN、CoQ；单纯的递电子体如细胞色素只传电子不传氢。呼吸链有两条及四个复合体；抑制Cyt a3使其上游组分呈还原态；组分按E0由小到大排列"},{"q":"胆固醇合成的限速酶是","o":["HMG-CoA裂解酶","HMG-CoA还原酶","HMG-CoA合成酶","甲羟戊酸激酶","鲨烯环氧合酶"],"a":1,"e":"HMG-CoA还原酶催化HMG-CoA还原为甲羟戊酸，是胆固醇合成的限速酶，受胆固醇别构抑制、受胰岛素诱导。HMG-CoA合成酶催化乙酰CoA缩合生成HMG-CoA，HMG-CoA裂解酶参与酮体生成，甲羟戊酸激酶与鲨烯环氧合酶属后续步骤的酶"},{"q":"脂肪酸合成酶催化合成的脂肪酸只能是","o":["硬脂酸","20碳脂酸","15碳脂酸","软脂酸","不饱和脂肪酸"],"a":3,"e":"脂肪酸合酶复合体经缩合、还原、脱水、再还原的循环，每轮延长2个碳，经7轮后由硫酯酶水解释放16碳的软脂酸，故产物只能是软脂酸。硬脂酸等更长碳链需在内质网或线粒体内经延长酶系加工，不饱和脂肪酸由去饱和酶催化生成"},{"q":"精氨酸酶主要存在于哪种组织","o":["脾脏","小肠","肝脏","肌肉","脑组织"],"a":2,"e":"精氨酸酶主要存在于肝脏，催化精氨酸水解为鸟氨酸和尿素，是鸟氨酸循环即尿素合成的最后一步，故为答案。脾、小肠、肌肉、脑组织精氨酸酶活性很低或缺乏，不承担尿素合成的功能"},{"q":"氨基酸脱羧基的辅酶是","o":["FAD","生物素","TPP","磷酸吡哆胺","磷酸吡哆醛"],"a":4,"e":"氨基酸脱羧酶的辅酶是磷酸吡哆醛，为维生素B6的活性形式，可稳定脱羧产生的碳负离子中间体。磷酸吡哆胺主要参与转氨基作用；TPP是α-酮酸氧化脱羧的辅酶；FAD、生物素分别参与氧化还原和羧化反应，均非脱羧酶的辅酶"},{"q":"Southern blotting的基本过程是","o":["将DNA转移到膜上，用DNA探针杂交","将蛋白质转移到膜上，用抗体做探针杂交","将RNA转移到膜上，用DNA探针杂交","将DNA转移到膜上，用RNA探针杂交","将RNA转移到膜上，用RNA探针杂交"],"a":0,"e":"Southern印迹法将电泳分离的DNA变性后转移至硝酸纤维素膜或尼龙膜，再用标记DNA探针杂交，用于基因组DNA的定性定量。蛋白质转膜后用抗体探测是Western印迹，RNA转膜后用探针杂交是Northern印迹"},{"q":"以下不是维生素A的生理功能是","o":["作为视紫红质的成分参与视觉","维持上皮组织的结构和功能","抗氧化作用","调节血钙浓度促进生长、发育","增强机体抵抗力，有一定抗癌作用"],"a":3,"e":"调节血钙、促进骨骼生长发育的是维生素D，其活性形式1,25-(OH)2-D3促进肠钙吸收，故D项不属维生素A的功能。维生素A构成视紫红质参与视觉，维持上皮组织完整性，具有抗氧化作用，并增强抵抗力、有一定的防癌作用"},{"q":"乳糖操纵子中，能够和阻遏蛋白结合的部位是","o":["P序列","-35区","O序列","-10区","CAP位点"],"a":2,"e":"乳糖操纵子中阻遏蛋白结合于操纵序列，阻止RNA聚合酶转录结构基因；诱导物与阻遏蛋白结合使其构象改变而脱离O序列，故为O序列。P序列为启动子是RNA聚合酶结合部位。-35区、-10区为启动子的保守序列。CAP位点为分解代谢物激活蛋白结合部位"},{"q":"下列哪类氨基酸都是必需氨基酸","o":["碱性氨基酸","含硫氨基酸","分支氨基酸","芳香族氨基酸","脂肪族氨基酸"],"a":2,"e":"分支氨基酸包括亮氨酸、异亮氨酸、缬氨酸，均为人体不能合成的必需氨基酸，故为答案。碱性氨基酸中赖氨酸必需而精氨酸、组氨酸为条件必需。含硫氨基酸中蛋氨酸必需而半胱氨酸为条件必需。芳香族氨基酸中苯丙氨酸、色氨酸必需而酪氨酸为条件必需。脂肪族氨基酸含多种非必需氨基酸"},{"q":"用于检测体内蛋白质-DNA相互作用的技术是","o":["酵母双杂交实验","电泳迁移率变动测定（EMSA）","GST pull-down实验","染色质免疫沉淀（ChIP）","免疫共沉淀（CoIP）"],"a":3,"e":"染色质免疫沉淀（ChIP）用抗体富集与特定蛋白结合的DNA片段，可检测细胞内蛋白质与DNA的相互作用，故为答案。酵母双杂交、GST pull-down与免疫共沉淀检测蛋白质-蛋白质相互作用。EMSA为体外检测蛋白质与DNA结合的技术，并非体内方法，故ChIP为体内检测的首选"},{"q":"与下列α-氨基酸相应的α-酮酸，是三羧酸循环的中间产物的是","o":["丙氨酸","谷氨酸","精氨酸","胱氨酸","苏氨酸"],"a":1,"e":"谷氨酸经转氨基或氧化脱氨基生成α-酮戊二酸，后者是三羧酸循环的中间产物。丙氨酸对应丙酮酸，为糖酵解终产物；天冬氨酸对应草酰乙酸；胱氨酸与苏氨酸的相应酮酸不属循环中间物，精氨酸须先转变为谷氨酸再脱氨"},{"q":"下列血浆脂蛋白中甘油三酯含量最高、最低的分别是","o":["CM，VLDL","LDL，HDL","VLDL，HDL","HDL，CM","CM，HDL"],"a":4,"e":"CM以转运外源性甘油三酯为主，甘油三酯约占其重量90%，为最高；HDL颗粒最小，蛋白质与磷脂比例高，甘油三酯仅约5%，为最低。VLDL富含内源性甘油三酯但低于CM，LDL以胆固醇为主，HDL参与胆固醇逆向转运"},{"q":"关于环腺苷酸（cAMP）的描述，错误的是","o":["在腺苷酸环化酶催化下由ATP生成","由磷酸二酯酶水解成5'-AMP","合成与分解反应都在细胞膜上进行","它是多数含氮激素的第二信使","胰岛素能够降低细胞内cAMP的浓度"],"a":2,"e":"cAMP由腺苷酸环化酶在细胞膜内侧催化ATP生成，但水解它的磷酸二酯酶分布于细胞质，故“合成与分解都在细胞膜上进行”错误。cAMP是多数含氮激素的第二信使，胰岛素通过激活磷酸二酯酶降低其浓度，水解产物为5′-AMP"},{"q":"下列关于tRNA的叙述，错误的是","o":["含有密码子环","通常由70～80个核苷酸组成","参与蛋白质生物合成","三级结构呈倒L型","含有大量的稀有碱基"],"a":0,"e":"tRNA含反密码子环，其中的反密码子与mRNA密码子互补配对，本身不含密码子环，A项错误。tRNA约70～80个核苷酸，含大量稀有碱基，三级结构呈倒L型，是蛋白质合成中的氨基酸搬运工具"},{"q":"原核生物RNA聚合酶的全酶组成是","o":["α2βσ","αββ'σ","α2ββ'ωσ","αββ'","ααβ'"],"a":2,"e":"原核RNA聚合酶全酶由α2ββ'ωσ组成，σ因子辨认启动子，核心酶α2ββ'ω负责催化。α2βσ缺β'与ω，αββ'缺σ，ααβ'亚基组成不全，均非全酶形式。σ因子在转录起始后脱落，核心酶继续沿模板延长RNA链"},{"q":"有些疾病是由于基因的过度表达引起的，因此可通过向患者体内导入有抑制基因表达作用的核酸，阻断致病基因的异常表达，从而达到治疗疾病的目的，这种基因治疗策略是","o":["基因矫正","基因置换","基因增补","基因失活","基因敲除"],"a":3,"e":"向患者体内导入反义RNA、核酶、siRNA或miRNA，与靶基因的mRNA互补结合或将其降解，阻断过度表达的致病基因，属基因失活策略中的基因干扰。基因矫正与基因置换针对缺陷基因原位修复，基因增补是导入正常基因补偿功能，基因敲除针对生殖细胞或胚胎干细胞，与体细胞导入抑制性核酸不同"},{"q":"当肝细胞内ATP供应充分时，下列叙述中哪项是错误的","o":["丙酮酸激酶被抑制","6-磷酸果糖激酶-1被抑制","异柠檬酸脱氢酶被抑制","果糖双磷酸酶-1被抑制","进入三羧酸循环的乙酰辅酶A减少"],"a":3,"e":"ATP供应充分时，糖酵解和三羧酸循环受抑，丙酮酸激酶、6-磷酸果糖激酶-1及异柠檬酸脱氢酶均被ATP抑制，进入三羧酸循环的乙酰辅酶A减少。果糖双磷酸酶-1是糖异生关键酶，高ATP时糖异生应加强，该酶不被ATP抑制（其抑制剂是AMP和2,6-双磷酸果糖），故此项错误"},{"q":"有关蛋白质亚基的描述，正确的是","o":["一条多肽链卷曲成螺旋结构","两条以上多肽链卷曲形成的二级结构","两条以上多肽链与辅基结合成蛋白质","每个亚基都有各自的三级结构","一条多肽链就是一个亚基"],"a":3,"e":"亚基指具有完整三级结构的多肽链，是四级结构的组成单位，各亚基有各自的三级结构并以非共价键聚集。一条多肽链卷曲成螺旋描述的是二级结构，两条以上多肽链形成二级结构的说法概念错误，与辅基结合成蛋白质也不是亚基的定义"},{"q":"以NAD+为辅酶的脱氢酶有","o":["葡萄糖-6-磷酸脱氢酶","6-磷酸葡糖酸脱氢酶","脂酰CoA脱氢酶","苹果酸脱氢酶","琥珀酸脱氢酶"],"a":3,"e":"苹果酸脱氢酶以NAD+为辅酶，催化苹果酸氧化为草酰乙酸。葡萄糖-6-磷酸脱氢酶和6-磷酸葡糖酸脱氢酶以NADP+为辅酶；脂酰CoA脱氢酶和琥珀酸脱氢酶以FAD为辅基，均不以NAD+为辅酶"},{"q":"环化腺苷酸（cAMP）能别构激活","o":["磷脂酶A","蛋白激酶A","蛋白激酶C","蛋白激酶G","酪氨酸蛋白激酶"],"a":1,"e":"cAMP与蛋白激酶A的调节亚基结合，使其构象改变而与催化亚基解离，酶被别构激活，进而磷酸化多种底物蛋白，这是cAMP信号的主要通路。蛋白激酶C由DAG与Ca2+激活，蛋白激酶G由cGMP激活，酪氨酸蛋白激酶由受体或配体调控，三者均非cAMP的靶酶"},{"q":"苯妥英钠降低血清未结合胆红素的机制是","o":["刺激肝细胞合成更多的Z蛋白","诱导肝细胞线粒体内UDP-葡萄糖醛酸基转移酶的生成","诱导肝细胞滑面内质网UDP-葡萄糖醛酸基转移酶的生成","使UDP-葡萄糖醛酸供应增加","改变未结合胆红素的分子构型"],"a":2,"e":"苯巴比妥类可诱导肝细胞滑面内质网UDP-葡萄糖醛酸基转移酶的生成，加速未结合胆红素转变为结合胆红素，从而降低血清未结合胆红素，用于新生儿黄疸。该酶位于内质网而非线粒体，Y、Z蛋白参与摄取，UDPGA是葡萄糖醛酸供体而非诱导对象"},{"q":"泛酸是下列哪种辅酶或辅基的组成成分","o":["FMN","NAD+","CoASH","TPP","NADP+"],"a":2,"e":"泛酸即维生素B5，是辅酶A的组成成分，CoASH通过其巯基携带酰基参与酰基转移反应。FMN含维生素B2，NAD+与NADP+含维生素PP，TPP含维生素B1。泛酸缺乏可致四肢神经痛"},{"q":"原核生物的核糖体上有3个重要的功能部位，该功能部位可以释放已经卸载的氨酰-tRNA，将tRNA排出。该重要的功能部位称为","o":["A位","P位","E位","氨基酰位","肽酰位"],"a":2,"e":"E位即排出位，转位后接纳P位卸下氨基酸的tRNA，使其从核糖体脱落。A位结合氨酰tRNA，P位结合肽酰tRNA，分别称氨酰位与肽酰位。起始时fMet-tRNA直接进入P位，A位空留待下一个氨酰tRNA进位"},{"q":"决定氧化磷酸化速率的最主要的生理因素是","o":["ADP浓度","呼吸链抑制剂","解偶联剂","激素","线粒体突变"],"a":0,"e":"氧化磷酸化速率主要受ADP浓度调节，ADP升高时ATP合酶转运质子加快，呼吸链氧化随之加速，此即呼吸控制。ATP、AMP均为腺苷酸的组成成分，ATP升高反而抑制氧化磷酸化。氧与底物在生理条件下供应相对稳定，不是最主要的限速因素"},{"q":"真核细胞转染的常用方法有","o":["氯化钙转染","DEAE纤维素介导转染","超声波穿孔","脂质体转染","噬菌体载体介导"],"a":3,"e":"脂质体转染以人工脂质膜包裹DNA形成囊泡，穿透细胞膜进入真核细胞，操作简单、重复性好、对细胞无毒。氯化钙法与DEAE纤维素法主要用于细菌转化，超声波不能形成可控膜孔，噬菌体载体介导属转导"},{"q":"中心法则阐明的遗传信息表达方式是","o":["蛋白质→RNA→DNA","RNA→DNA→蛋白质","RNA→蛋白质→DNA","DNA→RNA→蛋白质","DNA→蛋白质→RNA"],"a":3,"e":"中心法则指遗传信息由DNA转录给RNA，再由mRNA翻译成蛋白质，即DNA→RNA→蛋白质，mRNA在其中衔接两种大分子。逆转录即RNA→DNA是对中心法则的补充，仅见于逆转录病毒。蛋白质不能反向决定核酸序列，故RNA→蛋白质→DNA、DNA→蛋白质→RNA等流向均不存在"},{"q":"由插入序列和转座子介导的基因移位或重排称","o":["转座","转导","转染","转化","接合"],"a":0,"e":"由插入序列和转座子介导的基因移位或重排称为转座，依赖转座酶实现。转导由噬菌体介导；转染是体外DNA导入真核细胞；转化是细菌摄取游离DNA；接合通过细胞直接接触传递质粒，均非转座子介导"},{"q":"内皮型NO合酶的编码区G894T位点的SNP，可能与原发性高血压有关。下列哪种策略可以研究这一机制","o":["蛋白质结构分析","条件性基因敲除","GWAS关联分析","紫外交联免疫共沉淀测序","基因捕获"],"a":0,"e":"该SNP位于编码区，G894T可改变eNOS蛋白的氨基酸序列并影响酶活性，用蛋白质结构分析可推测突变对蛋白结构与功能的影响。GWAS用于群体水平关联定位，条件性基因敲除与基因捕获属动物模型和基因分离技术"},{"q":"发生在同源序列间的重组是","o":["位点特异的重组","随机重组","非位点特异的重组","基本重组","人工重组"],"a":3,"e":"同源重组发生在两条相似或相同DNA分子的同源序列之间，互换对等片段，又称基本重组，减数分裂时的交换即属此类。位点特异性重组只发生在特定序列间，如λ噬菌体整合、免疫球蛋白基因重排。随机重组并无固定的序列对应关系，人工重组属体外操作而非体内过程"},{"q":"绝大多数血浆蛋白质的合成场所是","o":["肾","骨髓","肝","肌肉","脾"],"a":2,"e":"绝大多数血浆蛋白由肝细胞合成并分泌入血，包括清蛋白、凝血因子、补体等，故肝为主要场所。肾可分泌肾素、促红细胞生成素等少量蛋白，骨髓合成免疫球蛋白，脾参与抗体生成，肌肉主要合成胞内蛋白，均非血浆蛋白的主要来源。清蛋白由肝合成是肝功能的经典指标"},{"q":"关于酶的化学修饰调节的叙述，错误的是","o":["酶以有活性（高活性）和无活性（低活性）两种形式存在","属于快速调节","两种形式的转变由不同酶催化","别构酶不存在化学修饰调节","具有级联放大效应"],"a":3,"e":"别构酶同样可受磷酸化等共价修饰调节，糖原磷酸化酶既是别构酶又受化学修饰调节，故D项错误。化学修饰使酶在高活性与低活性两种形式间转变，由不同酶催化且不可逆，属快速调节，并通过级联反应产生放大效应"},{"q":"原核生物DNA复制中的引物是","o":["以DNA为模板合成的DNA片段","以RNA为模板合成的RNA片段","以DNA为模板合成的RNA片段","以RNA为模板合成的DNA片段","引物仍存在于复制完成的DNA链中"],"a":2,"e":"引物酶以DNA为模板合成短的RNA片段作为引物，提供3'-OH供DNA聚合酶延伸，故为以DNA为模板合成的RNA片段。以DNA为模板合成的DNA片段为子链而非引物。以RNA为模板涉及逆转录，见于端粒酶或逆转录病毒。引物最终被DNA聚合酶Ⅰ切除，并不保留于成熟DNA链"},{"q":"下列哪种辅酶中不含维生素","o":["CoASH","FAD","NAD+","FMN","CoQ"],"a":4,"e":"CoQ为脂溶性苯醌类化合物，由酪氨酸衍生的醌环与异戊二烯侧链构成，不含维生素成分。CoASH含泛酸，FAD与FMN含维生素B2，NAD+含烟酰胺，均为维生素衍生的辅酶。泛醌在复合体Ⅰ、Ⅱ与Ⅲ之间传递电子，是脂溶性递氢体"},{"q":"参与维持DNA单链模版状态，避免形成超螺旋结构的酶是","o":["引发前体","拓扑异构酶Ⅰ","单链DNA结合蛋白","解链酶","拓扑异构酶Ⅱ"],"a":2,"e":"单链DNA结合蛋白结合解链后的单链DNA，防止其重新配对形成双链或二级结构，维持单链模板状态，故为答案。拓扑异构酶Ⅰ、Ⅱ通过切断和重接DNA链消除复制叉前方的超螺旋张力，作用对象为双链DNA而非维持单链。引发前体与引物酶参与引物合成，解链酶负责打开双链，均不直接维持单链模板状态"},{"q":"抑癌基因是一类抑制细胞过度生长、增殖从而遏制肿瘤形成的基因。对于正常细胞，调控生长的基因（如原癌基因）和调控抑制生长的基因（如抑癌基因）的协调表达是调节控制细胞生长的重要分子机制之一。这两类基因相互制约，维持正负调节信号的相对稳定。抑癌基因的丢失或失活也可能导致肿瘤发生。癌症是原癌基因激活和抑癌基因失活双重事件导致的。第一个被克隆的抑癌基因是","o":["p16","Rb","p53","DCC","APC"],"a":1,"e":"Rb是第一个被克隆的抑癌基因，其失活与视网膜母细胞瘤及骨肉瘤相关，遵循二次打击与杂合性丢失机制。p53、p16、DCC、APC均为其后鉴定的抑癌基因。Rb蛋白通过调控G1/S检查点发挥抑癌作用"},{"q":"下列物质，可作为磷脂酰胆碱和磷脂酰乙醇胺合成中的共同原料是","o":["Gly","SAM","Ser","Thr","Met"],"a":2,"e":"丝氨酸脱羧生成乙醇胺，乙醇胺经甲基化生成胆碱，二者分别活化为CDP-乙醇胺和CDP-胆碱，再与甘油二酯缩合生成磷脂酰乙醇胺和磷脂酰胆碱，故丝氨酸是共同原料。SAM提供甲基，Met是SAM的前体，Gly与Thr不参与"},{"q":"有关肝脏在维生素代谢作用的描述中，哪项有错误","o":["肝脏是贮存维生素的重要器官","肝脏分泌胆汁酸为吸收脂溶性维生素所必须","脂肪吸收不良时肝脏脂溶性维生素贮存量下降","肝病的出血倾向与维生素K作用延长有关","肝病的出血倾向与维生素K吸收减少有关"],"a":4,"e":"官方答案为【肝病的出血倾向与维生素K吸收减少有关】，但依据教材，正确答案为【肝病的出血倾向与维生素K作用延长有关】。肝病时胆汁酸合成与分泌减少，脂溶性维生素K吸收下降，凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化受阻而致出血，吸收减少恰是真实机制。D项称维生素K作用延长，概念不成立，维生素K并不存在作用时间延长这一情形"},{"q":"嘌呤核苷酸从头合成的直接原料，不包括","o":["甘氨酸","天冬氨酸","谷氨酸","CO2","一碳单位"],"a":2,"e":"嘌呤从头合成以磷酸核糖、甘氨酸、天冬氨酸、谷氨酰胺、一碳单位及CO2为原料。谷氨酸不直接参与，提供氨基的是谷氨酰胺；甘氨酸提供C4、C5与N7，天冬氨酸提供N1，一碳单位提供C2与C8"},{"q":"真核生物mRNA的3'-末端尾巴结构是","o":["约200个核苷酸的poly(C)","约200个核苷酸的poly(A)","约100个核苷酸的poly(G)","约200个核苷酸的poly(U)","约300个核苷酸的poly(U)"],"a":1,"e":"真核mRNA转录后由poly(A)聚合酶在3'端加上约200个腺苷酸的poly(A)尾，保护mRNA并促进翻译起始。poly(C)、poly(G)与poly(U)均非其尾巴结构；组蛋白mRNA例外，无poly(A)尾而以3'端发夹结构代之"},{"q":"肝脏中合成的酮体不能氧化的器官是","o":["心肌","肾脏","脑","骨骼肌","肝脏"],"a":4,"e":"肝缺乏琥珀酰CoA转硫酶，不能将乙酰乙酸活化为乙酰乙酰CoA，故能生成酮体却不能氧化酮体。心肌、肾、脑与骨骼肌均含该酶，可利用酮体供能，脑在饥饿时尤为依赖。酮体包括乙酰乙酸、β-羟丁酸与丙酮，分子小、水溶性好，易透过血脑屏障"},{"q":"丙酮酸羧化酶的描述正确的是","o":["活性可被柠檬酸激活","活性可被乙酰辅酶A激活","是糖酵解的关键酶","存在于细胞质中","催化所有的糖异生原料的异生过程"],"a":1,"e":"丙酮酸羧化酶以生物素为辅基，仅存在于线粒体，催化丙酮酸羧化生成草酰乙酸，其活性受乙酰CoA别构激活，是糖异生的第一步。柠檬酸是乙酰CoA羧化酶的激活剂，二者常被互换设错；该酶属糖异生关键酶而非糖酵解酶，且只能以丙酮酸、乳酸等生糖物质为底物，不能催化所有原料异生"},{"q":"可识别分泌蛋白新生肽链N端的物质是","o":["转肽酶","信号肽识别颗粒","GTP酶","RNA酶","mRNA的聚A尾部"],"a":1,"e":"信号肽识别颗粒由SRP-RNA与六种蛋白质组成，识别并结合新生肽链N端的信号肽，同时结合核糖体使其暂停翻译，再引导复合体结合内质网膜上的SRP受体。转肽酶催化肽键形成，GTP酶水解GTP供能，RNA酶水解RNA，均不识别信号肽；polyA尾位于mRNA 3′端，与肽链分拣无关"},{"q":"组氨酸生成组胺是通过","o":["脱氨基作用","氧化作用","还原作用","脱羧基作用","转氨基作用"],"a":3,"e":"组氨酸在组氨酸脱羧酶催化下脱去羧基生成组胺，组胺是强烈的血管舒张剂和胃酸分泌刺激剂。脱氨基、转氨基、氧化、还原均不生成组胺，这些反应分别对应其他氨基酸代谢途径"},{"q":"未结合胆红素的特点是","o":["胆红素丙酸侧链的羧基可参与分子内氢键的形成","比结合胆红素更难通过生物膜","易在尿中出现","不加尿素或乙醇就能与重氮试剂呈阳性反应","水溶性强"],"a":0,"e":"未结合胆红素的丙酸侧链羧基可与分子内其他基团形成氢键，使极性基团内藏，故难溶于水、不能透过肾小球滤过膜而不出现于尿中。它须与清蛋白结合运输，因氢键遮蔽而需加尿素或乙醇破坏氢键后才与重氮试剂呈阳性（间接反应）。水溶性强、易在尿中出现、易透过生物膜均为结合胆红素的特点"},{"q":"关于细胞色素特点正确的是","o":["细胞色素也可分布在线粒体外","血红素A是Cyt c的辅基","呼吸链中有许多种细胞色素可被CN-抑制","细胞色素C氧化酶其本质不是细胞色素","所有的细胞色素与线粒体内膜紧密结合，不易分离"],"a":0,"e":"细胞色素是以铁卟啉为辅基的色素蛋白，除线粒体内膜的a、b、c外，微粒体的细胞色素b5与P450也存在于线粒体外，故该说成立。Cyt c的辅基是血红素c，血红素a属Cyt aa3。细胞色素氧化酶即复合体Ⅳ，本质是细胞色素。CN-只抑制Cyt aa3，并非抑制多种细胞色素"},{"q":"糖组学研究的主要技术，不包括","o":["色谱","质谱","糖微阵列技术","限制性片段长度多态性分析","生物信息学"],"a":3,"e":"糖组学分析聚糖的组成与功能，依赖色谱分离、质谱鉴定、糖微阵列和生物信息学处理。限制性片段长度多态性分析检测DNA酶切片段长度差异，属基因诊断技术，与聚糖无关；色谱、质谱用于糖链结构解析，微阵列用于糖与蛋白结合谱筛查"},{"q":"下述属于基因沉默技术的是","o":["PCR","体外转录","逆转录","RNAi","原位杂交"],"a":3,"e":"RNAi由与靶基因同源的双链RNA诱导，经Dicer生成siRNA后降解同源mRNA，属转录后基因沉默技术。PCR是体外扩增DNA，体外转录与逆转录分别由RNA聚合酶和逆转录酶催化核酸合成，原位杂交用于核酸定位，均不引起基因沉默"},{"q":"胆固醇生物合成的限速步骤是","o":["二甲丙烯焦磷酸生成焦磷酸法尼酯","鲨烯生成羊毛固醇","羊毛固醇生成胆固醇","HMG-CoA生成甲羟戊酸","乙酰乙酰CoA生成HMG-CoA"],"a":3,"e":"HMG-CoA还原酶催化HMG-CoA还原为甲羟戊酸，是胆固醇合成的限速步骤与调节关键环节。二甲丙烯焦磷酸生成焦磷酸法尼酯、鲨烯生成羊毛固醇、羊毛固醇生成胆固醇均为其后步骤，乙酰乙酰CoA生成HMG-CoA位于限速反应之前"},{"q":"不参与DNA复制的酶是","o":["解螺旋酶","连接酶","引物酶","拓扑酶","核酶"],"a":4,"e":"解螺旋酶解开双链，引物酶合成RNA引物，拓扑酶消除复制超螺旋，连接酶连接冈崎片段，均为DNA复制所需。核酶是具催化活性的RNA，参与RNA剪接等反应，不参与DNA复制。引物酶本质是依赖DNA的RNA聚合酶，与核酶不同"},{"q":"控制长链脂酰辅酶A进入线粒体氧化速度的因素是","o":["脂酯CoA合成酶的活性","肉碱-脂酰基转移酶活性","脂酰CoA脱氢酶的活性","脂酰CoA的含量","细胞内ATP的水平"],"a":1,"e":"长链脂酰CoA不能直接透过线粒体内膜，需经肉碱脂酰转移酶Ⅰ催化生成脂酰肉碱进入线粒体，该酶是脂肪酸β-氧化的限速酶，其活性决定进入线粒体氧化的速度。脂酰CoA合成酶负责活化，脂酰CoA脱氢酶催化β-氧化第一步，ATP水平只间接影响"},{"q":"磷酸二羟丙酮是哪两种物质代谢之间的交叉点","o":["糖-氨基酸","糖-脂酸","糖-甘油","糖-胆固醇","糖-核酸"],"a":2,"e":"磷酸二羟丙酮是糖酵解中间产物，在细胞质经3-磷酸甘油脱氢酶还原为3-磷酸甘油，再与脂酰CoA合成甘油三酯，故为糖与甘油代谢的交叉点。糖与脂肪酸的交叉点是乙酰CoA，糖与氨基酸的交叉点是丙酮酸等α-酮酸，胆固醇与核酸不与磷酸二羟丙酮直接相通"},{"q":"有关蛋白质β-折叠的描述，错误的是","o":["主链骨架呈锯齿状","氨基酸侧链交替位于扇面上下方","β-折叠的肽链之间不存在化学键","肽链充分伸展","β-折叠有反平行式和平行式结构"],"a":2,"e":"β-折叠中相邻肽段借主链羰基氧与亚氨基氢形成氢键而稳固，肽链之间存在化学键，故C项表述错误。主链呈锯齿状伸展，侧链交替伸向片层上下方，并有平行与反平行两种走向。该氢键属维持二级结构的非共价键，与α-螺旋的维系方式相同"},{"q":"1mol乙酰乙酸生成过程中参与反应的乙酰CoA有多少","o":["1mol","2mol","3mol","4mol","5mol"],"a":1,"e":"乙酰乙酸由2分子乙酰CoA缩合成乙酰乙酰CoA，再与1分子乙酰CoA缩合成HMG-CoA，后者裂解又释出1分子乙酰CoA，净消耗2分子乙酰CoA。3mol与4mol混淆了HMG-CoA的生成与裂解，5mol与该途径的化学计量不符"},{"q":"Ca2+-依赖的蛋白激酶是","o":["受体型酪氨酸蛋白激酶","非受体型酪氨酸蛋白激酶","蛋白激酶C","蛋白激酶A","蛋白激酶G"],"a":2,"e":"PKC属丝/苏氨酸蛋白激酶，其活化需钙离子、DAG和磷脂酰丝氨酸共同参与，故为Ca2+依赖的蛋白激酶。PKA由cAMP激活，PKG由cGMP激活，受体型与非受体型酪氨酸蛋白激酶均不依赖钙离子"},{"q":"基因重组过程中，对于载体DNA，内切酶的切点应在","o":["复制起点","遗传标志的上游","遗传标志的下游","多克隆位点","启动子结构中"],"a":3,"e":"多克隆位点是载体上多种限制性内切酶单一切点的集中区，外源DNA由此插入而不破坏载体功能。复制起点负责载体自主复制，选择标志用于筛选重组体，启动子驱动外源基因表达，三者被切开即丧失相应功能；遗传标志上下游的序列一般不含酶切位点"},{"q":"在已知序列的情况下，最方便的获取目的DNA的方法是","o":["化学合成法","聚合酶链式反应","直接从组织中提取","从基因组文库中筛选","基因芯片"],"a":1,"e":"已知序列时可依据两端序列设计一对引物，用聚合酶链反应在体外快速扩增目的DNA，操作简便、产量高。化学合成法成本高且长度受限，直接从组织提取难以获得单一目的片段，文库筛选与基因芯片费时，均非最方便的方法"},{"q":"病毒癌基因来自","o":["自身基因突变","细胞原癌基因的转导","细胞抑癌基因的突变","与其他病毒基因重组","自身基因重排"],"a":1,"e":"病毒癌基因由逆转录病毒在感染过程中从宿主细胞基因组捕获原癌基因转导而来，捕获后常发生缺失或点突变而失去正常调控，成为持续活化的致癌序列。化学致癌物诱发的点突变使原癌基因激活属另一途径；染色体易位见于淋巴瘤；基因扩增使原癌基因过量表达，均不产生病毒癌基因"},{"q":"在线粒体中，氧化磷酸化解偶联意味着","o":["线粒体代谢停止","线粒体膜ATP酶被抑制","线粒体三羧酸循环被终止","ATP持续形成并且氧被利用","ATP生成停止，但氧被利用"],"a":4,"e":"解偶联剂破坏内膜质子电化学梯度，电子仍沿呼吸链传给氧，耗氧继续，但ADP不能被磷酸化，ATP生成停止，能量以热能释放。呼吸链与三羧酸循环并不停止，ATP合酶本身未被抑制，只是失去质子驱动力，故与“代谢停止”“酶被抑制”不同"},{"q":"β地中海贫血是我国华南地区最常见的常染色体隐性遗传性血液病之一。患者由于血红蛋白的β珠蛋白基因突变，导致β珠蛋白缺失（β0）或合成不足（β+），从而引发遗传性溶血性贫血。国际上已报道约170种β珠蛋白基因的突变体，我国也已发现20多种突变体。在临床上，如果要对β地中海贫血患者进行β珠蛋白基因多个突变位点的检测，选择下述哪种方法较为合适","o":["Southern印迹","Northern印迹","变性高效液相色谱（DHPLC）","等位基因特异寡核苷酸（ASO）分子杂交","聚合酶链式反应-限制性片段长度多态性（PCR-RFLP）"],"a":2,"e":"PCR-DHPLC利用异源双链与同源双链在色谱柱上保留行为的差异，逐段扫描目的基因，一次可筛查多个位点并发现未知突变，适合β珠蛋白基因多种突变型的检测。PCR-ASO杂交与PCR-RFLP每次只针对已知位点，通量低。Southern印迹检测DNA大片段改变，Northern印迹检测RNA，均不适用点突变筛查"},{"q":"红细胞内主要的抗氧化物是","o":["NADH","COQH","GSH","FADH2","FMNH2"],"a":2,"e":"红细胞内主要的抗氧化物是还原型谷胱甘肽，可清除过氧化氢和自由基、保护血红蛋白与膜蛋白免受氧化，由磷酸戊糖途径提供的NADPH维持其还原态。NADH、FADH2、FMNH2主要是还原当量载体；辅酶Q还原型在红细胞中并非主要抗氧化物质"},{"q":"谷胱甘肽的功能主要是","o":["参与氧化还原反应","脱羧基反应","脱氨基反应","甲基化反应","磷酸化反应"],"a":0,"e":"GSH的巯基具还原性，可清除过氧化物与自由基，保护酶和蛋白质的巯基，维持红细胞膜完整性，是体内重要的还原剂，故主要参与氧化还原反应。谷胱甘肽不催化脱羧、脱氨或甲基化，磷酸化亦非其功能"},{"q":"脂肪酸合成的限速酶是","o":["甘油三酯脂肪酶","甘油二酯脂肪酶","甘油一酯脂肪酶","乙酰辅酶A羧化酶","脂蛋白脂肪酶"],"a":3,"e":"乙酰辅酶A羧化酶是脂肪酸合成的限速酶，催化乙酰CoA羧化为丙二酰CoA，受柠檬酸激活、棕榈酰CoA抑制并经磷酸化调节。甘油三酯、甘油二酯、甘油一酯脂肪酶参与脂肪动员；脂蛋白脂肪酶水解脂蛋白中的甘油三酯，均非脂肪酸合成限速酶"},{"q":"印迹技术中所使用的支持物为","o":["滤纸","醋酸纤维薄膜","硝酸纤维素膜","琼脂糖","聚丙烯酰胺凝胶"],"a":2,"e":"印迹技术将电泳分离的核酸或蛋白质转移至硝酸纤维素膜、尼龙膜等固相支持物上，再与探针杂交或进行免疫检测。滤纸与醋酸纤维薄膜吸附能力及机械强度不足，琼脂糖与聚丙烯酰胺凝胶是电泳分离介质，不是转移后的固相载体"},{"q":"Lac阻遏蛋白是由","o":["Z基因编码","Y基因编码","A基因编码","I基因编码","P序列编码"],"a":3,"e":"乳糖操纵子的I基因有独立启动子，编码阻遏蛋白，阻遏蛋白结合操纵序列O使操纵子关闭。Z、Y、A分别编码β-半乳糖苷酶、通透酶和转乙酰酶，P序列是RNA聚合酶结合位点，不编码蛋白质"},{"q":"最常用的两大双序列比对工具是FASTA和","o":["ASCL","BLAST","PERL","MatLab","SPSS"],"a":1,"e":"FASTA与BLAST是最常用的双序列比对工具，BLAST通过局部比对在数据库中快速搜索同源序列，是基因功能注释与同源检索的基础工具。PERL为编程语言，MatLab与SPSS为统计与数值计算软件，ASCL并非序列比对工具"},{"q":"催化mRNA 3'端poly(A)尾生成的酶是","o":["RNA聚合酶","核苷酸转移酶","RNase P","RNase D","多聚A聚合酶"],"a":4,"e":"真核mRNA前体在3'端切断后，由多聚腺苷酸聚合酶以ATP为底物、不依赖模板地加上数十至数百个腺苷酸，形成poly(A)尾。RNA聚合酶催化的是转录，RNase P参与tRNA前体5'端加工，RNase D参与tRNA 3'端修剪"},{"q":"磷酸化作用可使下列哪种酶受到抑制","o":["糖原合酶","已糖激酶","糖原磷酸化酶","磷酸化酶b激酶","甘油三酯脂肪酶"],"a":0,"e":"糖原合酶磷酸化后由活性a型变为无活性b型，故磷酸化抑制该酶。糖原磷酸化酶与磷酸化酶b激酶磷酸化后被激活，己糖激酶不受此种抑制，甘油三酯脂肪酶即激素敏感性脂肪酶磷酸化后活性升高。胰岛素经激活磷酸酶使糖原合酶去磷酸而恢复活性"},{"q":"下列关于酮体代谢的叙述，不正确的是","o":["肝不能氧化利用酮体","生成酮体是肝特有的功能","饥饿时酮体生成减少","糖尿病患者酮体生成可增多","脑不能氧化脂酸，但能利用酮体"],"a":2,"e":"饥饿时脂肪动员加强、胰岛素降低，酮体生成显著增多而非减少。肝缺乏琥珀酰CoA转硫酶，只生成不氧化酮体；糖尿病酮症时酮体明显升高，脑不能氧化脂肪酸但可利用酮体。酮体在肝内生成后经血运至肝外组织，由琥珀酰CoA转硫酶活化后氧化"},{"q":"关于同工酶的叙述，正确的是","o":["它们催化相同的化学反应","它们的分子结构相同","它们的理化性质相同","它们分子量相同","它们有相同的免疫学性质"],"a":0,"e":"同工酶催化相同的化学反应，但酶蛋白分子结构、理化性质与免疫学特性不同，其活性中心三维结构相似。各同工酶的分子量与氨基酸序列并不相同，免疫学性质也各异，故不能据此认为结构相同。乳酸脱氢酶的五种同工酶即为典型实例"},{"q":"糖酵解的脱氢反应步骤是","o":["1，6-双磷酸果糖→3-磷酸甘油醛+磷酸二羟丙酮","3-磷酸甘油醛→磷酸二羟丙酮","3-磷酸甘油醛→1，3-二磷酸甘油酸","1，3-二磷酸甘油酸→3-磷酸甘油酸","3-磷酸甘油酸→2-磷酸甘油酸"],"a":2,"e":"该步由甘油醛-3-磷酸脱氢酶催化，以NAD+为受氢体，醛基氧化为羧基并与磷酸形成混合酸酐，是糖酵解唯一的脱氢反应。1,6-双磷酸果糖裂解为磷酸二羟丙酮和甘油醛-3-磷酸属醛缩酶催化的裂解，不脱氢。1,3-二磷酸甘油酸变为3-磷酸甘油酸是底物水平磷酸化，3-磷酸甘油酸变为2-磷酸甘油酸是变位反应"},{"q":"运输内源性胆固醇的血浆脂蛋白主要是","o":["CM","LDL","VLDL","HDL","IDL"],"a":1,"e":"LDL是运输内源性胆固醇的主要形式，其胆固醇来自VLDL经IDL的代谢转化，经LDL受体被肝及肝外组织摄取。CM转运外源性甘油三酯，VLDL转运内源性甘油三酯，HDL参与胆固醇逆向转运，IDL只是VLDL向LDL转变的中间产物"},{"q":"可合成甲状腺素、儿茶酚胺及黑色素的氨基酸是","o":["甲硫氨酸","色氨酸","组氨酸","谷氨酸","酪氨酸"],"a":4,"e":"酪氨酸是合成甲状腺激素、儿茶酚胺（多巴胺、去甲肾上腺素、肾上腺素）及黑色素的前体，故为答案。甲硫氨酸提供甲基并参与转硫。色氨酸合成5-羟色胺、褪黑素等。组氨酸生成组胺。谷氨酸为兴奋性递质及氨基供体，均非上述三类物质的共同前体"},{"q":"关于蛋白质二级结构的描述，错误的是","o":["蛋白质局部或某一段肽链有规则的重复构象","蛋白质部分主链的空间构象","主链构象由每个肽键的两个二面角所确定","整条多肽链中全部氨基酸的位置","无规卷曲也属于二级结构范畴"],"a":3,"e":"二级结构指主链局部有规则的重复构象，由肽键的两个二面角决定，包括α-螺旋、β-折叠、β-转角和无规卷曲。D项所述整条肽链全部氨基酸残基的相对空间位置是三级结构的定义，概念被错置。二级结构只涉及主链，不描述侧链的整体排布"},{"q":"下列各组中终止密码子是","o":["UAG UAA UGA","AAA CCG GCC","UGA AUG GAU","UAA GAA CAA","GUU CUU AUU"],"a":0,"e":"终止密码子为UAA、UAG、UGA，不编码任何氨基酸，故该组正确。AAA编码赖氨酸、CCG编码脯氨酸、GCC编码丙氨酸，均为有义密码子。AUG为起始密码子并编码甲硫氨酸，GAU编码天冬氨酸。GAA编码谷氨酸、CAA编码谷氨酰胺。GUU、CUU、AUU分别编码缬氨酸、亮氨酸、异亮氨酸，均非终止密码子"},{"q":"原核生物的切除修复过程需要：①DNA连接酶；②DNA polⅠ；③Uvr蛋白类。其作用先后次序是","o":["①，②，③","②，③，①","②，①，③","③，②，①","③，①，②"],"a":3,"e":"核苷酸切除修复先由UvrA、UvrB识别损伤并定位，UvrC于损伤两侧切开，UvrD解旋去除寡核苷酸片段，再由DNA polⅠ以对侧链为模板填补缺口，最后DNA连接酶封口，故顺序为③②①。DNA连接酶只封闭切口不能填补，polⅠ不具损伤识别功能"},{"q":"关于β-折叠结构的叙述，正确的是","o":["只存在于α-角蛋白中","只有反平行式结构，没有平行式结构","α-螺旋是右手螺旋，β-折叠是左手螺旋","肽平面的二面角与α-螺旋的相同","主链骨架呈锯齿状形成折叠的片层"],"a":4,"e":"β-折叠中多肽链充分伸展，以Cα为旋转点折叠成锯齿状，侧链交替位于片层上下，形成折纸状片层。β-折叠既有平行式也有反平行式，本身不是左手螺旋，其二面角与α-螺旋不同；α-角蛋白主要含α-螺旋，并非只含β-折叠"},{"q":"脂肪酸在肝脏进行β-氧化不生成的化合物是","o":["H2O","乙酰CoA","脂酰CoA","NADH+H+","FADH2"],"a":0,"e":"β-氧化每轮包括脱氢、加水、再脱氢、硫解，产物为FADH2、NADH+H+、乙酰CoA和少两个碳的脂酰CoA，加水反应消耗水，故不生成水。NADH与FADH2只有经呼吸链传递、电子最终交给氧才生成水，属氧化磷酸化而非β-氧化本身"},{"q":"下列哪种因素与脂肪肝的病因相关","o":["摄入高蛋白饮食","高糖饮食","肝内磷脂缺乏，合成VLDL能力下降","摄入高脂饮食","肝脏有转化脂肪的能力"],"a":2,"e":"肝内磷脂合成障碍使载脂蛋白与磷脂不足，VLDL组装和分泌受阻，甘油三酯不能运出而堆积于肝，是脂肪肝的重要机制。高糖、高脂饮食只提供过多合成原料，属诱因；高蛋白饮食利于载脂蛋白合成，肝转化脂肪的能力本身不是病因"},{"q":"关于TFⅡD的叙述下列不正确的是","o":["是一种由多亚基组成的复合物","TFⅡD通过TBP识别、结合TATA盒","为PolⅠ、Ⅱ和Ⅲ三种转录过程所必需","由TATA组成的最简单的启动子只需TFⅡD","与原核基因转录无关"],"a":3,"e":"TFⅡD由TBP与TAFs组成多亚基复合物，TBP识别并结合TATA盒；但最简单的含TATA启动子仍需RNA聚合酶Ⅱ及TFⅡB、E、F、H等组装起始复合物，绝非仅需TFⅡD。TFⅡD只参与RNA聚合酶Ⅱ的转录，与原核基因转录无关"},{"q":"肝脏在脂肪代谢中产生过多酮体的主要原因是由于","o":["肝功能不好","肝中脂肪代谢紊乱","脂肪运转障碍","脂肪摄食过多","糖供给不足或利用障碍"],"a":4,"e":"糖供给不足或利用障碍时草酰乙酸减少，乙酰CoA进入三羧酸循环受阻而大量转向酮体生成，见于饥饿与糖尿病。肝功能不好、脂肪运输障碍不是酮体增多的直接原因，单纯脂肪摄食过多而糖充足时酮体不升高"},{"q":"最普遍进行的生物转化第二相反应是代谢物与","o":["谷胱甘肽结合","葡糖醛酸结合","硫酸结合","乙酰基结合","甲基结合"],"a":1,"e":"葡萄糖醛酸结合是生物转化第二相反应中最普遍的一种，UDPGA提供葡糖醛酸基，与含羟基、羧基或氨基的化合物结合后水溶性增强易于排出。硫酸结合需PAPS且容量有限，乙酰基与甲基结合见于胺类，谷胱甘肽结合多用于解毒活性代谢物"},{"q":"关于生物氧化能量的释放，正确的是","o":["生物氧化过程中总能量变化与反应途径无关","生物氧化过程中总能量变化与反应途径有关","细胞质是生物氧化和产能的主要部位","只能通过氧化磷酸化生成ATP","生物氧化释放的能量只能用来产热供能"],"a":0,"e":"生物氧化中能量释放的总量只取决于反应物与产物的自由能差，与反应途径无关，故该项正确。生物氧化主要在线粒体而非细胞质。能量既可通过氧化磷酸化生成ATP，也可经底物水平磷酸化生成ATP。释放的能量除合成ATP外部分以热散发，并非只能产热"},{"q":"原核生物和真核生物翻译起始不同之处在于","o":["真核生物先靠Shine Dalgarno序列使mRNA结合核糖体","真核生物帽子结合蛋白是翻译起始因子之一","IF比eIF种类多","原核生物和真核生物使用不同起始密码","原核生物有TATAAT作为翻译起始序列，真核生物则是TATA"],"a":1,"e":"真核mRNA的5′-帽由帽子结合蛋白eIF4E识别，该蛋白是eIF4F复合体的组分，属翻译起始因子，原核生物无此机制。Shine-Dalgarno序列是原核mRNA与16S rRNA互补的核糖体结合位点，真核不存在。真核起始因子种类远多于原核IF，两者均以AUG为起始密码；TATAAT与TATA是转录启动子元件，与翻译起始无关"},{"q":"糖酵解的最重要的关键酶是","o":["葡萄糖激酶","己糖激酶","丙酮酸激酶","6-磷酸果糖激酶-1","磷酸甘油酸激酶"],"a":3,"e":"6-磷酸果糖激酶-1催化果糖-6-磷酸生成果糖-1,6-二磷酸，是糖酵解中活性最低、变构调节最灵敏的步骤，其活性决定整条通路的流量，故为最重要的关键酶。己糖激酶与丙酮酸激酶同为关键酶但调节幅度较小；葡萄糖激酶仅存在于肝和胰岛；磷酸果糖激酶-2催化果糖-2,6-二磷酸生成，与糖异生调节有关"},{"q":"关于蛋白质合成的终止阶段，正确的叙述是","o":["终止密码子有两种","终止密码子都由U、G、A三种脱氧核苷酸构成","一种特异的tRNA可识别终止密码子","某种蛋白质因子可识别终止密码子","肽酰-tRNA在核蛋白体“受位”上脱落"],"a":3,"e":"终止密码有UAA、UAG、UGA三个，不被任何tRNA识别，由释放因子RF识别并结合A位，触发肽酰转移酶转为酯酶，水解肽酰-tRNA的酯键释放肽链。终止密码由U、G、A核糖核苷酸构成；肽链在P位肽酰-tRNA上脱落"},{"q":"已知某酶Km值为0、05mol/L，欲使其所催化的反应速率达Vmax的80%时，底物浓度应是","o":["0、04mol/L","0、05mol/L","0、1mol/L","0、2mol/L","0、8mol/L"],"a":3,"e":"按米氏方程v=Vmax[S]/（Km+[S]），v达80%Vmax时[S]=4Km，即0.2mol/L。0.05mol/L即Km本身，此时速率仅为50%Vmax；0.1mol/L为2Km，速率为67%；0.8mol/L远大于Km，速率接近而非等于80%Vmax"},{"q":"重组DNA技术中实现目的基因与载体DNA拼接的是","o":["DNA聚合酶","RNA聚合酶","DNA连接酶","RNA连接酶","限制性核酸内切酶"],"a":2,"e":"DNA连接酶催化目的基因与载体DNA片段之间形成磷酸二酯键，将两者拼接为完整重组DNA分子，故为答案。DNA聚合酶用于合成新链，RNA聚合酶用于转录。RNA连接酶连接RNA。限制性核酸内切酶用于切割产生片段，不负责拼接"},{"q":"同源重组是指","o":["同一种属来源的DNA间重组","同一细胞来源的DNA间重组","同一DNA分子中两链间的重组","DNA双链的同源区间重组","DNA的专一重组"],"a":3,"e":"同源重组发生在两段序列相同或高度相似的DNA双链之间，通过链侵入与交换实现片段互换，常见于减数分裂和双链断裂修复。A、B项以种属或细胞来源界定，与重组机制无关。位点特异性重组依赖特定序列，转座重组依赖转座子，均属另外类型"},{"q":"丙二酸对琥珀酸脱氢酶的抑制作用是","o":["反馈抑制","竞争性抑制","非竞争抑制","不可逆抑制","反竞争性抑制"],"a":1,"e":"丙二酸与琥珀酸结构相似，可竞争性结合琥珀酸脱氢酶的活性中心，阻碍琥珀酸结合，属竞争性抑制，增大琥珀酸浓度可解除。反馈抑制是代谢终产物抑制途径起始酶；非竞争与反竞争抑制不与底物竞争活性中心；不可逆抑制为共价结合，均不符合丙二酸的作用方式"},{"q":"蛋白质分子中β-转角属于蛋白质的","o":["四级结构","三级结构","二级结构","一级结构","侧链结构"],"a":2,"e":"β-转角是肽链主链局部回折形成的空间构象，含3～4个氨基酸残基，第一个残基的羰基与第四个残基的氨基形成氢键，属二级结构，不涉及侧链构象。一级结构指氨基酸排列顺序；三级结构指整条肽链的全部空间构象；四级结构指亚基缔合；侧链结构不属结构层次划分"},{"q":"大肠杆菌合成的所有未修饰的多肽链，其-N末端的氨基酸残基应是","o":["甲硫氨酸","丝氨酸","甲酰甲硫氨酸","甲酰丝氨酸","谷氨酸"],"a":2,"e":"原核生物起始密码AUG代表甲酰甲硫氨酸，由fMet-tRNAfMet进入P位起始翻译，故新合成多肽的N端为甲酰甲硫氨酸，约半数成熟蛋白随后由脱甲酰基酶切除甲酰基。真核生物起始残基为甲硫氨酸，丝氨酸与谷氨酸不参与起始，故其余选项不成立"},{"q":"健康人饥饿3天时，血浆代谢物浓度变化最大的可能是","o":["脂酸","葡萄糖","乙酰乙酸","亮氨酸","丙酮酸"],"a":2,"e":"饥饿3天时脂肪动员加强，肝生成大量酮体，乙酰乙酸与β-羟丁酸浓度较正常升高数十倍，变化幅度最大。血糖在饥饿初期下降后趋于稳定，脂肪酸与亮氨酸变化相对平缓，丙酮酸维持低水平。酮体为脂溶性小分子，由肝外组织氧化利用"},{"q":"以下属于直接针对目的DNA进行筛选的方法是","o":["青霉素抗药性","四环素抗药性","分子杂交","蓝白斑筛选","电泳"],"a":2,"e":"分子杂交用标记探针与目的DNA序列互补配对，直接针对目的DNA本身进行筛选鉴定。青霉素、四环素抗药性筛选的是载体上的选择标志，蓝白斑筛选依据lacZ是否被插入失活，电泳只按分子大小分离，均不直接识别目的序列"},{"q":"依赖Ca2＋的蛋白激酶是","o":["蛋白激酶A（PKA）","蛋白激酶C（PKC）","蛋白激酶G（PKG）","受体型酪氨酸蛋白激酶（RTK）","非受体型酪氨酸蛋白激酶"],"a":1,"e":"PKC的激活依赖Ca2+和磷脂（DAG），属Ca2+/磷脂依赖性蛋白激酶，故为答案。PKA依赖cAMP，PKG依赖cGMP，两者均不依赖Ca2+。受体型与非受体型酪氨酸蛋白激酶依赖配体诱导的二聚化与自身磷酸化，与Ca2+无关"},{"q":"下列哪个不是一碳单位","o":["甲基","甲烯基","甲炔基","甲酰基","一氧化碳"],"a":4,"e":"一碳单位包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基，均由四氢叶酸携带。一氧化碳虽含一个碳，但不属一碳单位范畴，故为答案"},{"q":"存在于肝脏，但不存在于肌肉的酶是","o":["己糖激酶","葡萄糖-6-磷酸酶","乳酸脱氢酶","丙酮酸脱氢酶","糖原磷酸化酶"],"a":1,"e":"葡萄糖-6-磷酸酶存在于肝细胞内质网，可水解葡萄糖-6-磷酸释放游离葡萄糖入血，是肝糖原补充血糖的关键，肌组织缺乏此酶。己糖激酶、乳酸脱氢酶、丙酮酸脱氢酶、糖原磷酸化酶在肝与肌中均存在，其中肌的己糖激酶活性更高，糖原磷酸化酶在肌中尤为丰富"},{"q":"下列哪一种物质不能作为基因载体","o":["pBR322质粒","λ噬菌体","噬菌体","病毒RNA","逆转录病毒DNA"],"a":3,"e":"基因载体须为能独立复制并携带外源DNA进入受体细胞的DNA分子，质粒、噬菌体、柯斯质粒、人工染色体及改造后的病毒DNA均可用。病毒RNA不能作为载体，因其不能被DNA连接酶直接连接，也无法在宿主内稳定复制传代，需先逆转录为cDNA方可克隆"},{"q":"地球上有极少数人可能永远不会被艾滋病毒感染，即便他们接触艾滋病毒的机会比其他人高。你认为这些为数不多的幸运儿是因为","o":["他们的趋化因子受体的基因发生了突变，导致HIV无法进入宿主细胞","他们体内含有特殊的核酸酶，能将进入细胞内的HIV基因组RNA迅速水解","他们体内含有特殊的抑制剂，能强烈抑制HIV编码的蛋白酶","他们体内含有特殊的抑制剂，能强烈抑制HIV编码的逆转录酶","他们的基因组DNA上缺乏原病毒DNA整合的特异性位点"],"a":0,"e":"少数天然抵抗HIV感染者携带趋化因子受体（如CCR5）基因突变，HIV无法利用该辅助受体进入宿主细胞，从而阻断感染。体内并无能迅速水解HIV基因组RNA的特殊核酸酶；针对蛋白酶或逆转录酶的特异抑制剂是药物作用而非人体固有；HIV整合位点并非缺乏，而是进入受阻"},{"q":"关于糖蛋白O-连接型聚糖的叙述，错误的是","o":["合成部位是内质网和高尔基体","聚糖与多肽链丝氨酸/苏氨酸残基连接","O-连接型聚糖的合成发生在多肽链合成后","需要由N-乙酰葡糖胺和半乳糖构成的核心二糖","糖基化位点由多肽链的二、三级结构决定"],"a":3,"e":"O-连接型聚糖的核心二糖由N-乙酰半乳糖胺与半乳糖构成，而非N-乙酰葡糖胺。其合成在内质网和高尔基体完成，于多肽链合成后逐个加上糖基，连接于丝氨酸或苏氨酸羟基，糖基化位点由多肽链二、三级结构决定"},{"q":"当ATP/ADP比值降低时，可产生的效应是","o":["抑制丙酮酸羧化酶","抑制丙酮酸激酶","激活6-磷酸果糖激酶-1","抑制丙酮酸脱氢酶","激活果糖双磷酸酶-1"],"a":2,"e":"ATP/ADP比值降低提示能量不足，AMP、ADP增多，变构激活糖酵解关键酶6-磷酸果糖激酶-1，加速糖酵解供能。此时丙酮酸激酶也被激活而非被抑制；丙酮酸羧化酶、丙酮酸脱氢酶受抑，而果糖双磷酸酶-1因AMP升高而受抑制而非被激活，故其余选项不符"},{"q":"醛缩酶的产物包括","o":["G-6-P","F-6-P","F-2，6-BP","1,3-二磷酸甘油酸","3-磷酸甘油醛"],"a":4,"e":"醛缩酶催化果糖-1,6-二磷酸裂解为磷酸二羟丙酮和3-磷酸甘油醛，二者经丙糖磷酸异构酶互变。G-6-P与F-6-P是己糖激酶和磷酸己糖异构酶的底物或产物，F-2,6-BP是磷酸果糖激酶的强别构激活剂，1,3-二磷酸甘油酸是3-磷酸甘油醛脱氢酶的产物"},{"q":"合成尿素首步反应的产物是","o":["鸟氨酸","氨基甲酰磷酸","瓜氨酸","精氨酸","天冬氨酸"],"a":1,"e":"尿素合成第一步在肝细胞线粒体内，由氨基甲酰磷酸合成酶Ⅰ催化NH3、CO2和ATP合成氨基甲酰磷酸，故为首步产物。鸟氨酸为循环起始物，与氨基甲酰磷酸结合生成瓜氨酸。瓜氨酸、精氨酸为后续中间产物。天冬氨酸提供第二个氨基，非首步产物"},{"q":"磺胺类药物可抑制细菌体内哪种物质的合成","o":["维生素B12","吡哆醛","辅酶A","四氢叶酸","生物素"],"a":3,"e":"磺胺类药物与对氨基苯甲酸结构相似，竞争性抑制二氢蝶酸合酶，阻碍细菌合成四氢叶酸，使核酸合成受阻。人体可直接利用食物中的叶酸，故该药只抑制细菌。维生素B12、吡哆醛、辅酶A、生物素分别由其他维生素构成，合成不受影响"},{"q":"多数氨基酸都具有两个以上密码子，但以下哪项除外","o":["苏氨酸、甘氨酸","脯氨酸、精氨酸","丝氨酸、亮氨酸","色氨酸、甲硫氨酸","天冬氨酸和天冬酰胺"],"a":3,"e":"遗传密码中色氨酸与甲硫氨酸各只有一个密码子（UGG、AUG），其余氨基酸均有2个以上密码子，体现密码子的简并性。苏氨酸、甘氨酸、脯氨酸、精氨酸、丝氨酸、亮氨酸、天冬氨酸与天冬酰胺均有多个密码子；AUG同时兼作起始密码子"},{"q":"血浆脂蛋白琼脂糖凝胶电泳，从负极到正极的电泳图谱顺序是","o":["CM→前β-脂蛋白→β-脂蛋白→α-脂蛋白","CM→α-脂蛋白→前β-脂蛋白→β-脂蛋白","α-脂蛋白→前β-脂蛋白→β-脂蛋白→CM","CM→β-脂蛋白→前β-脂蛋白→α-脂蛋白","α-脂蛋白→β-脂蛋白→前β-脂蛋白→CM"],"a":3,"e":"琼脂糖电泳中CM不泳动而留于原点，其后依次为β-脂蛋白即LDL、前β-脂蛋白即VLDL、α-脂蛋白即HDL，故从负极到正极为CM→β→前β→α。α-脂蛋白泳动最快，前β位于β之前"},{"q":"由泛酸组成的辅酶参与","o":["脱羧反应","羧化反应","脱氢反应","转酰基作用","转氨基作用"],"a":3,"e":"泛酸是辅酶A与酰基载体蛋白的组成成分，CoA携带酰基参与转酰基反应，是酰基转移酶的辅因子。脱羧反应多需焦磷酸硫胺素，羧化反应需生物素，脱氢反应需烟酰胺或核黄素类辅酶，转氨基反应需磷酸吡哆醛"},{"q":"蛋白质的等电点是","o":["蛋白质溶液pH值为7、0时溶液的pH值","蛋白质溶液pH值为7、4时溶液的pH值","蛋白质分子呈正离子状态时溶液的pH值","蛋白质分子呈负离子状态时溶液的pH值","蛋白质的正电荷与负电荷相等时溶液的pH值"],"a":4,"e":"蛋白质分子正、负电荷相等、净电荷为零时的溶液pH即等电点，此时蛋白质呈兼性离子，在电场中不移动。溶液pH大于pI时蛋白质带负电荷，小于pI时带正电荷。A、B项把等电点误解为固定pH数值，与蛋白质种类无关，属概念错误"},{"q":"同一质粒DNA分子沉降系数最大的状态是","o":["超螺旋","环状","线性","有一个或几缺口的双链环状分子","变性后"],"a":0,"e":"超螺旋是双链环状DNA进一步盘绕形成的致密三级结构，分子最紧凑，沉降系数最大。有缺口的开环分子应力释放、结构松弛，沉降最慢；线性分子较超螺旋松散。变性后双链解离为单链，构象伸展，沉降行为改变，同样小于超螺旋"},{"q":"关于蛋白聚糖和糖蛋白的叙述，正确的是","o":["蛋白聚糖分子中聚糖比例小于蛋白","糖蛋白中糖所占的比例较蛋白多","糖蛋白和蛋白聚糖中糖链的结构相同","糖蛋白和蛋白聚糖在体内的分布相同","二者的糖链延长都需要特异性糖基转移酶催化"],"a":4,"e":"蛋白聚糖与糖蛋白的糖链合成与延长均由特异性糖基转移酶催化，将糖基逐一加到受体分子上，故该项正确。蛋白聚糖中糖的比例大于蛋白，糖蛋白中蛋白比例大于糖。二者糖链结构不同，蛋白聚糖为长链糖胺聚糖，糖蛋白为短分支寡糖。二者体内分布也不同"},{"q":"亚硝酸盐造成的DNA的损伤是","o":["形成TT二聚体","使A甲基化","转换T为C","取代A并异构成G","使C脱氨成U"],"a":4,"e":"亚硝酸使碱基脱去氨基，胞嘧啶脱氨生成尿嘧啶，导致C-G转换为T-A；腺嘌呤脱氨则生成次黄嘌呤。TT二聚体由紫外线照射形成，碱基甲基化由烷化剂引起，碱基类似物取代碱基后可引起错配，均属其他类型的损伤"},{"q":"下列哪项不是构成呼吸链的成员","o":["细胞色素","铁硫蛋白","辅酶Q","FAD","血红素"],"a":4,"e":"呼吸链的成员包括尼克酰胺腺嘌呤二核苷酸、黄素蛋白（FAD）、铁硫蛋白、辅酶Q和细胞色素等。血红素是细胞色素的辅基，游离血红素本身并非呼吸链的组成成员，故不属于构成呼吸链的独立成员"},{"q":"能识别DNA特异序列并在识别位点或其周围切割双链DNA的一类酶是","o":["限制性外切核酸酶","非限制性核酸外切酶","限制性核酸内切酶","DNase","DNA内切酶"],"a":2,"e":"限制性核酸内切酶识别双链DNA特定的回文序列，并在识别位点内部或附近切割磷酸二酯键，是重组DNA技术的核心工具酶。DNA连接酶只封闭切口，不切割；DNA聚合酶催化核苷酸聚合；解旋酶解开双链；核酸外切酶从末端逐个水解，均无序列特异性切割功能"},{"q":"在肝细胞内尿素合成的部位是","o":["线粒体","溶酶体","粗面内质网","滑面内质网","细胞质及线粒体"],"a":4,"e":"鸟氨酸循环中氨甲酰磷酸合成与鸟氨酸转氨甲酰发生在线粒体，精氨酸代琥珀酸合成及以后步骤在细胞质，故尿素合成的酶系跨线粒体与细胞质分布。溶酶体负责蛋白水解，粗面内质网合成蛋白质，滑面内质网参与脂质合成与生物转化"},{"q":"下列属于脂肪动员产物的是","o":["甘油","3-磷酸甘油","3-磷酸甘油醛","1,3-二磷酸甘油酸","2,3-二磷酸甘油酸"],"a":0,"e":"脂肪动员时甘油三酯在脂肪酶作用下逐步水解，释放游离脂肪酸与甘油入血，甘油主要由肝经甘油激酶磷酸化后进入糖代谢。3-磷酸甘油、3-磷酸甘油醛、1,3-二磷酸甘油酸、2,3-二磷酸甘油酸均为糖酵解或磷酸甘油穿梭的中间产物"},{"q":"PCR技术不可用于","o":["目的基因的克隆","微量目的基因的检测","某些遗传病的检测","蛋白质结构分析","体外突变目的基因"],"a":3,"e":"PCR扩增的是核酸，用于目的基因克隆、微量DNA检测、遗传病基因诊断及体外定点突变，不能直接分析蛋白质结构；蛋白质结构需经电泳、层析、质谱或晶体衍射等方法测定。故D项不属于PCR用途"},{"q":"有机磷化合物可结合于胆碱酯酶活性中心的","o":["丝氨酸残基的羟基","半胱氨酸残基的巯基","色氨酸残基的吲哚基","组氨酸残基的咪唑基","精氨酸残基的胍基"],"a":0,"e":"有机磷与胆碱酯酶活性中心丝氨酸残基的羟基共价结合，使酶磷酰化而失活。半胱氨酸巯基、组氨酸咪唑基、精氨酸胍基与色氨酸吲哚基虽可为必需基团，但不是有机磷的作用位点。解磷定可使磷酰化的胆碱酯酶复活，透析则不能去除已共价结合的抑制剂"},{"q":"氮杂丝氨酸抗肿瘤作用的原理是","o":["其结构与谷胺酰胺相似，可抑制嘌呤核苷酸的合成","叶酸类似物，抑制嘌呤核苷酸的合成","结构与次黄嘌呤相似，从而抑制嘌呤核苷酸的合成","抑制一碳单位的转运","丝氨酸类似物，可抑制一碳单位的生成"],"a":0,"e":"氮杂丝氨酸是谷氨酰胺的结构类似物，取代酰胺氮后使酰胺转移反应受阻，抑制PRPP酰胺转移酶及甲酰甘氨酰胺核苷酸合成，从而阻断嘌呤核苷酸生成，也干扰CTP合成。甲氨蝶呤抑制二氢叶酸还原酶，6-巯基嘌呤抑制次黄嘌呤-鸟嘌呤磷酸核糖转移酶，5-氟尿嘧啶抑制胸苷酸合酶，机制均不同"},{"q":"在原核生物翻译起始时，所形成的70S起始复合物中不包括的物质是","o":["核糖体的大亚基","核糖体的小亚基","mRNA","fMet-tRNA","起始因子"],"a":4,"e":"原核翻译起始时，起始因子（IF-1、IF-2、IF-3）辅助30S小亚基、mRNA和甲酰甲硫氨酰-tRNA结合，在50S大亚基加入形成70S起始复合物之前即解离，故起始因子不属于起始复合物组分。该复合物含核糖体大小亚基、mRNA和甲酰甲硫氨酰-tRNA"},{"q":"合成初级游离型胆汁酸的直接原料是","o":["乙酰CoA","胆固醇","7α-羟胆固醇","胆固醇酯","结合胆红素"],"a":1,"e":"肝细胞以胆固醇为原料，经7α-羟化酶催化生成初级游离胆汁酸，包括胆酸与鹅脱氧胆酸，故直接原料是胆固醇。乙酰CoA是合成胆固醇的原料，7α-羟胆固醇是中间产物，胆固醇酯须先水解，结合胆红素与胆汁酸合成无关"},{"q":"组成蛋白质的氨基酸有","o":["10种","15种","20种","25种","30种"],"a":2,"e":"天然蛋白质中常见的编码氨基酸共20种，由标准遗传密码直接编码。10种、15种过少，25种、30种过多，均超出遗传密码所编码的氨基酸种类"},{"q":"真核基因表达调控具有典型的多级调控特点，已知诱导剂A能诱导B基因的表达，关于诱导剂A调控B基因表达层次研究的实验体系中描述正确的是","o":["如果加入DNA甲基转移酶抑制剂，B基因的表达没有改变，说明诱导剂A对B基因表达的调控不发生在染色质水平","如果加入放线菌酮，B基因的表达没有改变，说明诱导剂A对B基因表达的调控不发生在蛋白质水平","如果加入鹅膏蕈碱，B基因的mRNA表达没有改变，说明诱导剂A对B基因表达的调控不发生在转录水平","如果加入蛋白酶体抑制剂，B基因的表达没有改变，说明诱导剂A对B基因表达的调控不发生在翻译后水平","如果诱导剂A能诱导特异mRNA生成并导致B基因的表达改变，说明诱导剂A对B基因表达的调控发生在转录后或翻译水平"],"a":4,"e":"多级调控含染色质、转录、转录后、翻译及翻译后各层次，判定调控点须比较特异mRNA与蛋白量的变化。诱导剂A诱导特异mRNA生成后才出现B基因表达改变，说明调控落在转录后加工与翻译环节，而非B基因结构或拷贝数改变。加甲基转移酶抑制剂无效不能排除染色质水平，组蛋白修饰同样影响染色质状态；鹅膏蕈碱只抑制RNA聚合酶Ⅱ"},{"q":"关于化学渗透假说，错误的叙述是","o":["由Peter Mitchell首先提出","需要在线粒体内膜两侧形成电位差","必须将内膜外侧的H＋泵到膜内来","质子泵的作用在于存储能量","H＋顺浓度由膜外回流时驱动ATP的生成"],"a":2,"e":"化学渗透假说认为呼吸链将质子从线粒体基质泵到内膜外侧（膜间隙），形成外高内低的质子电化学梯度，H+顺梯度经ATP合酶回流时驱动ATP合成。故将内膜外侧的H+泵到膜内的方向相反，错误；该假说由Peter Mitchell提出，需内膜两侧电位差，质子泵的作用是储能"},{"q":"酶不可逆抑制的机制是","o":["抑制剂与酶的活性中心以共价键结合","抑制剂使酶蛋白变性","抑制剂与酶的辅助因子结合","抑制剂以次级键结合在酶活性中心外","抑制剂与酶表面的极性基团结合"],"a":0,"e":"不可逆性抑制剂与酶活性中心必需基团以共价键结合，不能经透析、超滤去除，酶活性无法恢复，有机磷与胆碱酯酶丝氨酸羟基结合即属此类。使酶蛋白变性是变性剂的作用，与抑制剂结合无关；以次级键结合于活性中心外属非竞争性抑制，为可逆抑制"},{"q":"酶促反应动力学是研究","o":["酶分子的空间构象","酶的电泳行为","酶的活性中心","影响酶促反应速率的因素","酶的合成"],"a":3,"e":"酶促反应动力学研究各种因素（底物浓度、酶浓度、温度、pH、抑制剂、激活剂等）对酶促反应速率的影响及规律。酶的空间构象、活性中心属结构研究范畴；电泳行为是酶的理化性质；酶的合成属基因表达调控，均非动力学研究内容"},{"q":"三羧酸循环中哪1个化合物前后各放出1个分子CO2","o":["柠檬酸","乙酰CoA","琥珀酸","α-酮戊二酸","异柠檬酸"],"a":3,"e":"异柠檬酸脱氢酶催化异柠檬酸氧化脱羧生成α-酮戊二酸并放出CO2，α-酮戊二酸脱氢酶复合体再脱羧生成琥珀酰CoA又放出CO2，故前后各放1分子CO2的是α-酮戊二酸。柠檬酸与琥珀酸不直接脱羧，乙酰CoA进入循环时不放CO2"},{"q":"不发生在心肌细胞的代谢途径是","o":["糖酵解","糖异生","脂肪酸氧化","TCA循环","氧化磷酸化"],"a":1,"e":"心肌缺乏葡萄糖-6-磷酸酶及果糖二磷酸酶等糖异生关键酶，不能进行糖异生，其糖原仅供自身氧化。糖酵解、脂肪酸β-氧化、三羧酸循环与氧化磷酸化在心肌均活跃，心肌以有氧氧化供能为主。心肌糖原分解生成的葡萄糖-6-磷酸只能进入糖酵解，不能水解释放葡萄糖"},{"q":"RNA组学研究的RNA分子，不包括","o":["snRNA","mRNA","siRNA","miRNA","scRNA"],"a":1,"e":"RNA组学研究snmRNA，即非编码小RNA，包括snRNA、snoRNA、siRNA、miRNA、scRNA等，不含编码蛋白质的mRNA。mRNA属转录物组学研究的对象，是蛋白质合成的模板"},{"q":"含B族维生素的辅酶在酶促反应中的作用是","o":["传递电子，原子和化学基团的作用","稳定酶蛋白的构象","决定酶促反应的催化机制","决定酶的专一性","提高酶的催化活性"],"a":0,"e":"B族维生素衍生的辅酶作为辅因子，在反应中传递电子、质子或功能基团，本身无催化作用。酶的专一性由酶蛋白决定，催化机制依赖活性中心整体结构，辅酶不决定专一性，也不主要通过稳定构象发挥作用"},{"q":"人类游离型胆汁酸不包括","o":["胆酸","鹅脱氧胆酸","甘氨石胆酸","石胆酸","脱氧胆酸"],"a":2,"e":"游离型胆汁酸包括胆酸、鹅脱氧胆酸、脱氧胆酸与石胆酸，其羧基未与甘氨酸或牛磺酸结合。甘氨石胆酸是石胆酸与甘氨酸的结合型胆汁酸，属结合型，故不属于游离型。胆酸与鹅脱氧胆酸为初级胆汁酸，脱氧胆酸与石胆酸为次级胆汁酸"},{"q":"食物淀粉的消化起始部位是","o":["小肠","大肠","胃","口腔","肾"],"a":3,"e":"唾液含α-淀粉酶，食物在口腔咀嚼时即开始水解淀粉的α-1,4-糖苷键，但口腔停留时间短，小肠才是淀粉消化的主要场所。胃内酸性强、无淀粉酶，大肠主要吸收水分与电解质，肾不参与消化"},{"q":"钙调蛋白中钙离子的结合位点数为","o":["3个","4个","5个","6个","7个"],"a":1,"e":"钙调蛋白分子中有4个EF手型结构域，每个结构域结合1个Ca2+，共结合4个钙离子，结合后构象改变而激活靶酶。3个、5个、6个与7个均与EF手型结构域的数目不符。该结构域呈螺旋-环-螺旋构象，是钙结合蛋白的典型特征"},{"q":"参加肠道次级结合胆汁酸生成的氨基酸是","o":["鸟氨酸","精氨酸","甘氨酸","甲硫氨酸","瓜氨酸"],"a":2,"e":"次级胆汁酸由初级胆汁酸经肠菌脱羟后再与甘氨酸或牛磺酸结合生成，故结合所用氨基酸为甘氨酸。鸟氨酸与瓜氨酸是尿素循环中间物，精氨酸为尿素循环产物，甲硫氨酸提供活性甲基。初级胆汁酸在肝内合成，次级胆汁酸在肠道由肠菌作用生成后部分被重吸收"},{"q":"果糖双磷酸酶-1的抑制剂是","o":["磷酸果糖","2,6-双磷酸果糖","ATP","GTP","柠檬酸"],"a":1,"e":"2,6-双磷酸果糖是果糖双磷酸酶-1的强变构抑制剂，同时激活6-磷酸果糖激酶-1，协调糖异生与糖酵解。磷酸果糖是其底物类似物；ATP、GTP、柠檬酸主要抑制糖酵解酶或作为能量信号，并非果糖双磷酸酶-1的主要抑制剂"},{"q":"有关转录延长阶段，叙述不正确的是","o":["RNA聚合酶全酶催化此过程","RNA聚合酶与模板结合松弛","转录过程未终止时，即开始翻译","σ因子从转录起始复合物上脱落","RNA聚合酶与模板的结合无特异性"],"a":0,"e":"转录延长阶段由核心酶催化，σ亚基在第一个磷酸二酯键生成后即从起始复合物上脱落，故“全酶催化延长”不正确。核心酶与模板结合松弛且无序列特异性，可沿模板滑动；原核生物转录尚未终止时核糖体即可结合mRNA开始翻译，形成转录与翻译偶联"},{"q":"关于pH对酶促反应速率影响的叙述，错误的是","o":["pH影响酶、底物或辅助因子的解离程度，从而影响酶促反应速率","溶液pH过高或过低会使酶活性降低，但不会引起酶蛋白变性","动物体内多数酶的最适pH接近中性","pH可影响酶活性中心的空间构象","酶的最适pH受底物浓度、缓冲液种类及浓度的影响"],"a":1,"e":"过酸或过碱会破坏酶的空间结构，使酶蛋白变性失活，故该说法错误。pH通过影响酶活性中心必需基团、底物与辅因子的解离状态改变反应速率，也影响活性中心构象；动物体内多数酶最适pH接近中性，最适pH受底物浓度、缓冲液种类与浓度影响"},{"q":"受体的特异性取决于","o":["受体与G蛋白分子构象","受体与细胞膜的分子构象","受体与配体的分子构象","细胞膜的选择通透性","受体的类型"],"a":2,"e":"受体与配体的结合特异性由二者分子空间构象的互补决定，构象匹配才能形成高亲和力结合。G蛋白决定信号转导途径而非识别特异性，膜脂组成与通透性、受体类型均不决定配体识别的专一性。同一配体作用于不同受体亚型可产生不同效应"},{"q":"某种RNA在生物体内总量最多，约占RNA的80%以上。其与核糖体蛋白结合形成核糖体，为蛋白质的生物合成提供空间环境，其类似于一个移动的多肽链“装配厂”。该种RNA是","o":["mRNA","rRNA","tRNA","ncRNA","sncRNA"],"a":1,"e":"rRNA占RNA总量的80%以上，与核糖体蛋白共同构成核糖体，为mRNA、tRNA及多种蛋白质因子提供结合位点，是蛋白质合成的场所。mRNA携带密码子作为模板，含量最少；tRNA约占15%，负责搬运氨基酸；ncRNA与sncRNA为非编码RNA的总称及亚类，不构成核糖体"},{"q":"关于真核生物蛋白质合成描述正确的是","o":["边转录，边翻译","先转录，后直接进行翻译","经转录后加工再进行翻译","核糖体大亚基先与小亚基结合","mRNA先与tRNA结合"],"a":2,"e":"真核细胞转录在核内、翻译在胞质，时空分开，初级转录产物须经加帽、加尾与剪接等加工成熟后才出核翻译。原核才边转录边翻译；翻译起始时mRNA先与小亚基及起始tRNA结合，大亚基随后加入"},{"q":"长期不食用植物油，会缺乏下列哪种物质","o":["亚麻酸","油酸","棕榈酸","硬脂酸","软脂酸"],"a":0,"e":"α-亚麻酸与亚油酸属必需脂肪酸，人体不能合成，须由植物油供给，长期不食植物油即缺乏。油酸、软脂酸、硬脂酸均可由糖代谢产生的乙酰CoA经脂肪酸合酶系合成，棕榈酸即软脂酸，均属非必需脂肪酸，不因忌植物油而缺乏"},{"q":"缺乏时会引起坏血病的维生素是","o":["维生素B1","维生素B2","维生素C","维生素PP","硫辛酸"],"a":2,"e":"维生素C是脯氨酸羟化酶与赖氨酸羟化酶的辅因子，缺乏使胶原合成障碍、毛细血管脆性增加，引起坏血病，表现为牙龈出血与伤口愈合不良。维生素B1缺乏致脚气病，B2缺乏致口角炎，PP缺乏致病，硫辛酸为α-酮酸氧化脱羧的辅酶"},{"q":"关于RB基因的叙述，错误的是","o":["RB蛋白是p105","最初在视网膜母细胞瘤中发现","磷酸化形式是活性型","RB蛋白的磷酸化程度与细胞周期有关","低磷酸化RB蛋白是活性型"],"a":2,"e":"RB蛋白为105kDa，去磷酸化或低磷酸化形式为活性型，能结合E2F、抑制细胞增殖并促进分化；磷酸化使其失活，磷酸化程度随细胞周期变化，故C项错误。RB基因最初在视网膜母细胞瘤中被发现"},{"q":"增加双向电泳蛋白样品的溶解性的试剂，不包括","o":["变性剂","表面活性剂","氧化剂","还原剂","起载体作用的两性电解质"],"a":2,"e":"双向电泳样品缓冲液含变性剂如尿素、表面活性剂如CHAPS、还原剂如DTT和载体两性电解质，分别用于变性、增溶、断裂二硫键与维持pH梯度。氧化剂促使蛋白质氧化交联、破坏巯基，不利于溶解，故不包括在内"},{"q":"磷脂酶C水解甘油磷脂后的产物是","o":["甘油","甘油二酯","溶血磷脂1","溶血磷脂2","脂酸"],"a":1,"e":"磷脂酶C水解甘油磷脂（如磷脂酰肌醇二磷酸）的磷酸二酯键，生成甘油二酯和三磷酸肌醇两个第二信使，故水解产物为甘油二酯。磷脂酶A1/A2水解生成溶血磷脂，磷脂酶D生成磷脂酸，均非磷脂酶C的产物；甘油、脂酸不是其直接产物"},{"q":"肝脏输出肝内合成的甘油三酯的形式是","o":["直接释放","参与合成CM形式","参与合成HDL形式","参与合成VLDL形式","参与合成LDL"],"a":3,"e":"肝合成的甘油三酯与apoB100、磷脂、胆固醇组装成VLDL分泌入血，经脂蛋白脂肪酶水解释放脂肪酸供肝外组织利用。CM由小肠黏膜细胞合成，HDL主要参与胆固醇逆转运，LDL是VLDL的代谢产物，肝不直接释放游离甘油三酯"},{"q":"经脱羧基作用后生成γ-氨基丁酸的是","o":["半胱氨酸","谷氨酸","甘氨酸","谷氨酰胺","天冬氨酸"],"a":1,"e":"谷氨酸经L-谷氨酸脱羧酶催化脱去α-羧基生成γ-氨基丁酸，该酶以磷酸吡哆醛为辅酶，GABA是脑内抑制性神经递质。半胱氨酸脱羧生成牛磺酸，甘氨酸本身即为抑制性递质而非其前体，天冬氨酸与谷氨酰胺不生成GABA，故其余选项归属错误"},{"q":"脂肪酸进行β-氧化的部位是","o":["线粒体内膜上","线粒体基质内","微粒体","细胞质","细胞核"],"a":1,"e":"脂肪酸β-氧化酶系位于线粒体基质，活化的脂酰CoA经肉碱穿梭进入基质，完成脱氢、加水、再脱氢、硫解。线粒体内膜是呼吸链与ATP合酶所在部位，微粒体参与脂肪酸延长与ω-氧化，细胞质是脂肪酸合成的场所"},{"q":"影响酶促反应速率的因素不包括","o":["底物浓度","酶的浓度","反应环境的酸碱度","反应温度","变性剂"],"a":4,"e":"底物浓度、酶浓度、pH和温度均为酶促反应的常规影响因素，酶浓度与速率成正比，温度具双重性。变性剂使酶蛋白空间构象破坏、活性丧失，属酶的变性而非动力学影响因素，故不列入。抑制剂与激活剂才是动力学研究的另一类因素"},{"q":"丙酮酸氧化时在哪个环节上进入呼吸链","o":["CoQ","NADH-CoQ还原酶","CoQH2-Cyt b","Cyt氧化酶","琥珀酸脱氢酶"],"a":1,"e":"丙酮酸氧化脱羧生成的NADH经复合体Ⅰ即NADH-泛醌还原酶进入呼吸链，将电子传给泛醌。琥珀酸脱氢酶是复合体Ⅱ，只接受琥珀酸脱下的FADH2；CoQ与细胞色素氧化酶位于其下游，不是NADH的入口"},{"q":"高脂血症患者进行血清代谢组学分析，降低的成分有","o":["LDL","Apo E","CM","胆固醇","HDL"],"a":4,"e":"高脂血症患者血清中升高的多为LDL、乳糜微粒、胆固醇及ApoE等致动脉粥样硬化脂蛋白，而具有抗动脉粥样硬化作用的HDL常降低，故降低的成分为HDL。HDL介导胆固醇逆向转运，其水平与血脂异常呈负相关"},{"q":"关于解偶联剂，错误的是","o":["可抑制氧化反应","使氧化反应和磷酸化反应脱节","使ATP生成减少","使呼吸加快，耗氧增加","常见的解偶联剂是二硝基苯酚"],"a":0,"e":"解偶联剂使质子电化学梯度被破坏，氧化与磷酸化脱节，ATP生成减少，而电子传递反而加快、耗氧增加，产热增多，故“抑制氧化反应”错误。2,4-二硝基苯酚是典型解偶联剂。抑制电子传递的是呼吸链抑制剂如氰化物，二者机制不同"},{"q":"DNA双螺旋结构每旋转一周，沿轴上升高度是","o":["0、15nm","0、34nm","3、54nm","5、40nm","6、80nm"],"a":2,"e":"B型DNA双螺旋每旋转一周含约10个碱基对，螺距即沿轴上升高度为3.54nm。0.34nm是每个碱基对之间的上升距离；0.15nm并非标准参数；5.40nm和6.80nm均不符合B-DNA的螺旋参数"},{"q":"生物转化作用中属于第二相反应的是","o":["氧化","还原","水解","氧化+还原+水解","结合"],"a":4,"e":"生物转化第二相为结合反应，与葡萄糖醛酸、硫酸、乙酰基、谷胱甘肽等结合，进一步增加水溶性与极性便于排出。第一相包括氧化、还原和水解，其中氧化最常见，由细胞色素P450单加氧酶系催化；部分物质可不经第一相直接进入第二相"},{"q":"鉴定疾病相关基因的关键是","o":["通过疾病家系的连锁分析对染色体进行定位","确定疾病表型和基因之间的实质联系","借助生物信息数据库对比待定基因的信息","利用生物化学和细胞生物学等方法确定基因功能","使用疾病动物模型确定导致异常表型的基因"],"a":1,"e":"确定疾病表型与基因之间的实质联系是关键，只有明确基因序列改变与异常表型的关系，才能判定基因的致病作用。连锁分析、生物信息学比对、动物模型及功能学方法均是鉴定手段，服务于这一核心。以动物模型确定基因只是验证途径之一，不能替代表型与基因关系的确认"},{"q":"血红素合成的限速酶是","o":["血红素合酶","ALA脱水酶","ALA合酶","尿卟啉原Ⅰ同合酶","亚铁螯合酶"],"a":2,"e":"ALA合酶催化甘氨酸与琥珀酰CoA缩合生成ALA，是血红素合成的限速酶，辅酶为磷酸吡哆醛。ALA脱水酶催化胆色素原生成，亚铁螯合酶催化铁插入原卟啉，均非限速步骤。血红素合成的起始与终末阶段在线粒体，中间阶段在胞质，ALA合酶位于线粒体"},{"q":"磷脂酰肌醇二磷酸（PIP2）经磷脂酰肌醇激酶（PI-K）作用后的产物是","o":["PI","PI3","PIP","IP3","PIP3"],"a":4,"e":"磷脂酰肌醇3-激酶在PIP2肌醇环的3位磷酸化，生成磷脂酰肌醇-3,4,5-三磷酸即PIP3，后者募集含PH结构域的信号分子。PI与PIP是磷酸化程度更低的中间物，IP3由磷脂酶C水解PIP2生成，属另一分支"},{"q":"限制性内切核酸酶以GGG▼CGCCC方式切割产生的末端突出部分含","o":["1个核苷酸","2个核苷酸","3个核苷酸","4个核苷酸","5个核苷酸"],"a":1,"e":"回文序列GGGCGCCC共8个碱基，两条链的切割点对称错开2个碱基，切开后每条链各留下由胞嘧啶和鸟嘌呤组成的2个核苷酸单链突出端，形成5′黏端，可与同尾酶产物互补连接。1个核苷酸与平末端均不符此序列对称切割的结果，3个、4个核苷酸是识别6碱基序列的常见突出长度"},{"q":"关于阻塞性黄疸，下列说法错误的是","o":["常见于肠道阻塞","胆道阻塞，胆道压力增大破裂，结合胆红素反流入血","也称肝后性黄疸","尿胆红素阳性","粪便颜色可以变浅"],"a":0,"e":"阻塞性黄疸由胆道阻塞（如胆总管结石、胰头癌压迫）引起，属肝后性黄疸，并非肠道阻塞所致，故该项错误。胆道阻塞致胆道压力升高、胆管破裂，结合胆红素反流入血，尿胆红素阳性，粪便因缺乏胆色素而颜色变浅"},{"q":"下述有关胆固醇合成的叙述，错误的是","o":["几乎全身组织均可合成，脑组织除外","需要NADPH供氢","主要在细胞质及内质网进行","关键酶是HMG-CoA还原酶","肝脏是合成的主要场所"],"a":0,"e":"胆固醇合成场所几乎是全身各组织，肝脏为主，脑组织也能自身合成胆固醇以支持髓鞘形成，故脑组织除外的说法错误。合成需NADPH供氢、在细胞质和内质网进行、关键酶为HMG-CoA还原酶、肝脏是主要场所，这些表述均正确"},{"q":"下列哪种方法用于筛选与特定蛋白结合的未知RNA","o":["酵母单杂交系统","酵母双杂交系统","酵母三杂交系统","组织芯片","原位杂交"],"a":2,"e":"酵母三杂交在双杂交基础上引入第三个融合分子如RNA，借RNA与蛋白结合使BD与AD靠近，用于筛选与特定RNA结合的蛋白。酵母单杂交筛选与DNA元件结合的蛋白，双杂交检测蛋白-蛋白相互作用，原位杂交只作定位而不用于筛选"},{"q":"关于病毒癌基因的叙述中，错误的是","o":["能使培养细胞转化为癌细胞","存在于逆转录病毒","又称病毒原癌基因","感染宿主能引起肿瘤","感染宿主细胞后可整合于宿主细胞"],"a":2,"e":"病毒癌基因是逆转录病毒从宿主细胞基因组中捕获的原癌基因，经转导后发生突变或受病毒启动子控制而持续表达，故称病毒癌基因而非“病毒原癌基因”，细胞内的对应序列才称原癌基因。它们可刺激细胞增殖、诱发肿瘤，编码生长因子、受体或激酶。正常细胞中存在同源序列，故非病毒所特有"},{"q":"关于疾病相关基因的鉴定和功能研究，以下说法中错误的是","o":["疾病相关基因的克隆可采取非染色体定位克隆和染色体定位克隆两大策略","GWAS可以覆盖外显子绝大部分疾病相关基因变异","人类新基因的克隆大都是从同源EST分析开始的","基因的功能即基因编码的蛋白质功能和非编码基因RNA的功能","基因功能可从生物化学、细胞和整体三个水平描述"],"a":1,"e":"GWAS以连锁不平衡标记筛查常见变异，主要覆盖调控区等非编码变异；覆盖外显子绝大部分变异的是全外显子组测序。定位克隆分染色体定位与非定位两策略，基因功能含编码蛋白与非编码RNA功能，可从生化、细胞、整体三水平描述"},{"q":"与蛋白质在电场中泳动的方向和速度无关的是","o":["蛋白质分子的大小","蛋白质分子所带的电荷","蛋白质的等电点","蛋白质溶液的pH","蛋白质溶液的温度"],"a":4,"e":"蛋白质电泳的方向和速度主要取决于分子大小、所带电荷量及颗粒形状，而电荷又由等电点与溶液pH决定。温度不直接决定泳动方向和速度的本质，属无关项。分子大小、电荷、等电点与溶液pH均为决定泳动的关键因素"},{"q":"有关竞争性抑制作用的叙述，错误的是","o":["抑制剂与底物结构相似","与酶的结合是可逆的","与酶的活性中心结合","与酶非共价结合","抑制程度只与抑制剂的浓度有关"],"a":4,"e":"竞争性抑制的程度取决于抑制剂与酶的相对亲和力以及抑制剂与底物浓度的相对比例，增大底物浓度可减轻抑制，故“只与抑制剂浓度有关”错误。竞争性抑制剂与底物结构相似，与酶活性中心非共价可逆结合，表观Km增大而Vmax不变"},{"q":"仅在肝中合成的化合物是","o":["糖原","尿素","脂肪酸","胆固醇","血浆蛋白"],"a":1,"e":"尿素只能在肝细胞通过鸟氨酸循环合成，是氨的主要解毒产物，肝外组织不能合成尿素。糖原、脂肪酸与胆固醇在肝外多种组织均可合成，血浆蛋白虽以肝合成最多，但γ-球蛋白由浆细胞产生。故严重肝病时血氨升高，可诱发肝性脑病"},{"q":"关于线粒体DNA（mtDNA）的特点，错误的是","o":["编码tRNA数目少于核基因是影响氧化磷酸化的主要因素","人mtDNA编码13条多肽链","mtDNA突变常可影响氧化磷酸化","mtDNA缺乏保护而容易受到损伤","遗传性mtDNA疾病以母系遗传居多"],"a":0,"e":"mtDNA为裸露环状双链，缺乏蛋白质保护与损伤修复系统，突变率高，编码13条多肽、22种tRNA和2种rRNA，均参与氧化磷酸化。调节氧化磷酸化速率的主要因素是ADP的供应量，而非编码tRNA的数目，A项所述无依据"},{"q":"下列局部比对搜索工具BLAST序列数据库，哪一个是通过查询DNA序列比对蛋白质数据库的","o":["BLASTN","BLASTP","BLASTX","TBLASTN","TBLASTX"],"a":2,"e":"BLASTX以核酸序列为查询序列，按六种读框翻译后检索蛋白质数据库，适用于未知基因产物的功能推测。BLASTN为核酸对核酸库，BLASTP为蛋白质对蛋白质库。TBLASTN以蛋白质序列检索翻译后的核酸库，TBLASTX则是核酸对核酸的翻译比对"},{"q":"在8AcetylCoA+nATP+14 NADPH→palmitic acid+8CoASH+nADP+nPi+14NADP中，以下哪个是最强的激动剂","o":["Acetyl-CoA","Malonyl-CoA","Malate","Citrate","Oxaloacetate"],"a":3,"e":"柠檬酸是乙酰CoA羧化酶最强的别构激活剂，使无活性原聚体聚合成有活性多聚体，加速丙二酸单酰CoA生成与脂肪酸合成。乙酰CoA为该酶底物，丙二酸单酰CoA是产物并反馈抑制脂肪酸合成，苹果酸与草酰乙酸不激活该酶"},{"q":"能使蛋白质溶液稳定的因素是","o":["蛋白质不带电荷","蛋白质溶液的黏度大","蛋白质分子表面带有水化膜和电荷层","蛋白质分子表面的疏水基因相互排斥","蛋白质分子中的肽键"],"a":2,"e":"蛋白质胶体的稳定依赖颗粒表面的水化膜与电荷层，二者使颗粒相互排斥。去除电荷与水化膜即发生沉淀，盐析即利用此原理；黏度大、肽键及疏水基团排斥均非稳定因素。盐析用高浓度中性盐破坏水化膜并中和电荷，沉淀的蛋白质不变性"},{"q":"以下选项中，建议通过功能克隆进行分离鉴定疾病相关基因的是","o":["镰状细胞贫血相关基因","类风湿性关节炎相关基因","2型糖尿病相关基因","哮喘相关基因","胰腺癌相关基因"],"a":0,"e":"功能克隆从蛋白质入手，先测出异常蛋白的氨基酸序列，据此设计简并探针钓取cDNA，镰状细胞贫血的珠蛋白基因正是循此路线克隆成功的。类风湿性关节炎、2型糖尿病、哮喘、胰腺癌均为多基因复杂疾病，无单一异常蛋白可依，需靠连锁分析、GWAS或外显子组测序鉴定易感基因"},{"q":"以下有关端粒酶的描述，除了哪一项，其他都是正确的","o":["其RNA组分是合成DNA片段的模板","向端粒的3'端添加DNA链","它协助线性染色体的合成","是低等原核生物特有的酶","是一种逆转录酶"],"a":3,"e":"端粒酶由RNA与逆转录酶组成，其RNA组分作为合成端粒DNA的模板，向染色体3'端添加重复序列，属逆转录酶，作用是维持线性染色体末端。端粒酶存在于真核生物，原核生物染色体环状、无端粒，故该项错误"},{"q":"下列有关酮体的叙述错误的是","o":["酮体是脂酸在肝分解氧化时特有的中间产物","肝有活性较强的合成酮体的酶系","肝存在利用酮体的酶系","酮体是肝输出能源的一种方式","酮体是脑组织的重要能源"],"a":2,"e":"肝有活性很强的酮体合成酶系但缺乏利用酮体的酶，故“肝存在利用酮体的酶系”错误。酮体是脂肪酸在肝内β-氧化的特有中间产物，包括乙酰乙酸、β-羟丁酸和丙酮，分子小、溶于水，易透过血脑屏障，是肝向肝外输出能源的形式，长期饥饿时脑主要靠其供能"},{"q":"氰化物是剧毒物，使人中毒致死的原因是","o":["与肌红蛋白中Fe3+结合使之不能储氧气","与Cyt b中Fe3+结合使之不能传递电子","与Cyt c中Fe3+结合使之不能传递电子","与Cyt a3中Fe3+结合使之不能激活1/2 O2","与血红蛋白中Fe3+结合使之不能运输氧气"],"a":3,"e":"氰化物与细胞色素aa3即Cyt a3的Fe3+结合，阻断电子传给氧，氧化磷酸化中止而迅速致死。肌红蛋白与血红蛋白结合Fe3+不影响电子传递链；Cyt b、Cyt c位于Cyt a3上游，抑制后仍有部分电子可传递"},{"q":"从IMP合成GMP需要","o":["谷氨酸","谷氨酰胺","天冬氨酸","天冬酰胺","甘氨酸"],"a":1,"e":"IMP先经NAD+氧化为黄嘌呤核苷酸，再由谷氨酰胺提供氨基生成GMP，该反应由ATP供能。IMP转变为AMP才需天冬氨酸提供氨基，谷氨酸、天冬酰胺与甘氨酸均不参与IMP向GMP的转变"},{"q":"使乳糖操纵子实现高表达的条件是","o":["乳糖存在，葡萄糖缺乏","乳糖缺乏，葡萄糖存在","乳糖和葡萄糖均存在","乳糖和葡萄糖均不存在","只要乳糖存在"],"a":0,"e":"乳糖操纵子高表达需乳糖存在，以诱导物别构解除阻遏蛋白的抑制，同时葡萄糖缺乏使cAMP升高、CAP-cAMP复合物结合DNA激活转录。乳糖缺乏时阻遏蛋白结合操纵序列；葡萄糖存在时cAMP低、CAP不能激活；仅有乳糖而葡萄糖充足时表达受分解代谢物阻遏，达不到高水平"},{"q":"肝内脂肪大量动员时，生成的乙酰辅酶A主要转变为","o":["胆固醇","葡萄糖","脂酸","酮体","胆固醇酯"],"a":3,"e":"肝内脂肪酸β-氧化生成的大量乙酰CoA，在饥饿或糖供给不足、草酰乙酸减少时不能顺利进入三羧酸循环，转而经HMG-CoA途径在肝线粒体缩合成酮体。B项不成立，乙酰CoA不能净生成葡萄糖。C项方向相反，脂酸合成需乙酰CoA羧化酶催化并消耗NADPH，此时被抑制"},{"q":"下列关于逆转录酶的叙述，正确的是","o":["是以mRNA为模板催化合成RNA的酶","其催化合成反应方向是3'→5'","催化合成时需先合成冈崎片段","此酶具有RNase活性","不需要引物"],"a":3,"e":"逆转录酶具三种活性：RNA依赖的DNA聚合酶、DNA依赖的DNA聚合酶及RNase H活性，能水解RNA/DNA杂化链中的RNA。合成方向为5'→3'，需tRNA等引物提供3'-OH，产物为前病毒双链DNA，不经冈崎片段"},{"q":"脂肪细胞合成脂肪所需的甘油主要来自","o":["糖异生","葡萄糖分解","磷脂水解","脂肪水解","经甘油激酶作用生成的甘油磷酸提供"],"a":1,"e":"脂肪细胞缺乏甘油激酶，不能利用游离甘油，合成脂肪所需的甘油主要来自葡萄糖分解（糖酵解）中间产物磷酸二羟丙酮还原生成的3-磷酸甘油。糖异生是生成葡萄糖的途径；磷脂水解、脂肪水解产生的甘油不能被脂肪细胞直接再利用；经甘油激酶生成甘油磷酸在脂肪细胞不成立"},{"q":"基因芯片检测的原理是基于","o":["抗原-抗体标记系统的应用","双色荧光探针系统的应用","化学发光信号标记系统的应用","放射性核素标记系统的应用","地高辛-配基标记系统的应用"],"a":1,"e":"基因芯片将大量已知序列的寡核苷酸探针有序固定于固相支持物，样品以不同荧光标记后杂交，据信号强弱与比值判断基因表达差异，其原理基于双色或多色荧光标记样品杂交。抗原-抗体系统属蛋白质检测，放射核素与地高辛标记为单标记体系，均非芯片差异分析的基础"},{"q":"与DNA修复过程缺陷有关的疾病是","o":["着色性干皮病","黄嘌呤尿症","卟啉症","痛风","黄疸"],"a":0,"e":"着色性干皮病由核苷酸切除修复系统基因缺陷所致，紫外线造成的嘧啶二聚体不能切除修复，患者皮肤对光敏感并易发皮肤癌。黄嘌呤尿症为黄嘌呤氧化酶缺陷，痛风与尿酸生成过多有关，卟啉症为血红素合成障碍，黄疸为胆红素代谢异常"},{"q":"多核苷酸链由于链的5'-端和3'-端所含的基团不同，从而使得链具有了5'→3'的方向性。下面关于多核苷酸链叙述正确的是","o":["5'末端是指链的一末端核苷酸上C-5'上的羟基是自由的，对此核苷酸称为链的5'-羟基末端","5'末端是指链的一末端核苷酸上C-5'连接的磷酸只形成一个酯键，对此核苷酸称为链的5'-磷酸末端","3'末端是指链的另一末端核苷酸上C-3'连接的磷酸只形成一个酯键，对此核苷酸称为链的3'-磷酸末端","3'末端是指链的另一末端核苷酸上C-3'上没有氧原子，对此核苷酸称为链的3'-末端","3'末端是指链的另一末端核苷酸上C-3'连接的磷酸形成不止一个酯键，对此核苷酸称为链的3'-磷酸末端"],"a":1,"e":"多核苷酸链5'末端核苷酸C-5'连接的磷酸仅形成一个酯键、另一端为游离磷酸基，称5'-磷酸末端，故该项正确。5'末端游离的是磷酸而非羟基。3'末端为游离的3'-羟基，称3'-羟基末端，而非磷酸末端。C-3'连接磷酸仅形成一个酯键、含氧原子或形成多个酯键的描述均错误"},{"q":"1,4,5-三磷酸肌醇（IP3）受体位于","o":["核膜","线粒体内膜","细胞膜","内质网","溶酶体"],"a":3,"e":"IP3受体是内质网（肌质网）膜上的钙释放通道，IP3与之结合后通道开放，使内质网内Ca2+释放入胞质，参与磷脂酶C信号通路。细胞膜上分布的是G蛋白偶联受体等，并非IP3受体；线粒体内膜主要是呼吸链与ATP合酶；溶酶体膜上无此受体"},{"q":"tRNA分子3'末端的碱基序列是","o":["CCC-3'","AAC-3'","AAA-3'","CCA-3'","ACA-3'"],"a":3,"e":"所有tRNA的3'末端均为CCA序列，是氨基酸结合的部位，氨基酸通过酯键连接在A的3'-OH上，故为CCA-3'。CCC、AAC、AAA、ACA均非tRNA3'端的保守序列。该CCA序列部分由基因编码、部分在转录后由CCA添加酶加上，是tRNA的普遍特征"},{"q":"关于高能磷酸键，叙述正确的是","o":["有高能磷酸键变化的反应都是不可逆反应","高能磷酸键只能通过氧化磷酸化生成","体内参与反应最多的高能磷酸键存在于ATP中","体内高能化合物都含有高能磷酸键","高能磷酸键是高能磷酸化合物中键能最高的化学键"],"a":2,"e":"ATP是体内能量代谢的通用货币，参与的反应最多，其末端两个磷酸酯键为高能键。并非所有涉及高能键的反应都不可逆，底物水平磷酸化也可生成高能键，高能化合物还包括含高能硫酯键者，高能键指水解自由能大而非键能最高"},{"q":"下列关于DNA双螺旋模型的叙述，错误的是","o":["是DNA的二级结构","双股链相互平行、走向相反","碱基位于双螺旋外侧","碱基间以非共价键相连","磷酸与脱氧核糖组成了双螺旋的骨架"],"a":2,"e":"B型DNA双螺旋中脱氧核糖与磷酸构成的亲水性骨架位于外侧，碱基对包埋在内侧并以氢键相连，故C项错误。双螺旋属二级结构，两条链反向平行、右手螺旋，碱基间靠非共价的氢键与碱基堆积力维系"},{"q":"质子泵抑制剂在强酸环境下，能与壁细胞膜表面的H+/K+-ATP酶的巯基共价结合，抑制H+/K+-ATP酶活性，用于十二指肠溃疡治疗。下列可以评价抑制效果的策略是","o":["RT-qPCR","Western Blotting","Northern Blotting","免疫组化","酶活性检测"],"a":4,"e":"H+/K+-ATP酶被不可逆抑制剂共价修饰后催化活性下降，直接测定酶活性可反映抑制程度。RT-qPCR检测mRNA、Western Blotting检测蛋白表达量、免疫组化定位蛋白，均反映含量而非催化功能。Northern Blotting针对RNA，同样不能评价酶活性"},{"q":"关于病毒癌基因的叙述，正确的是","o":["主要存在于RNA病毒基因组中","无法与宿主细胞基因整合","不能使培养细胞癌变","又称癌基因","由病毒自身基因突变而来"],"a":0,"e":"病毒癌基因主要存在于RNA肿瘤病毒（逆转录病毒）基因组中，是病毒携带的、可使细胞癌变的基因，源于宿主原癌基因的捕获与变异。它可整合入宿主基因组、能使培养细胞恶性转化，也不同于细胞本身的癌基因；并非由病毒自身基因突变新产生"},{"q":"下列哪种条件不符合DNA载体的要求","o":["分子量小","一种内切酶只有1个切口","有基因标志便于筛选","易于引入细胞","不能复制"],"a":4,"e":"载体须能自主复制，才能脱离宿主染色体独立扩增并稳定传代，故不能复制者不符合载体要求。分子量小、单一酶切位点、选择标志、易导入细胞均为载体必备特征；不能复制的DNA只能随宿主基因组复制，无法独立存在"},{"q":"关于质粒的叙述，下列哪项是错误的","o":["大小约为数千个碱基对","易从一个细菌转移入另一个细菌","双链的线性分子","存在于大多数细菌的胞质中","常带抗药基因"],"a":2,"e":"质粒是染色体外能独立复制的闭合双链环状DNA，故“双链的线性分子”描述错误。它可自主复制，赋予宿主耐药或产毒素等表型，可通过接合、转化在细菌间转移，亦可整合入染色体；其复制与染色体不同步，可丢失。线状双链DNA是部分噬菌体与真核病毒的基因组形式"},{"q":"基因芯片事实上就是高通量的","o":["核酸分子杂交","ChIP","蛋白质印迹","EMSA","实时PCR"],"a":0,"e":"基因芯片将大量探针固定于芯片，与标记的核酸样品按碱基互补原则杂交，本质是高通量核酸分子杂交。ChIP研究DNA与蛋白质结合，EMSA亦然，Western Blotting检测蛋白质，实时PCR为扩增定量，均不属杂交原理的高通量检测"},{"q":"结合胆红素理化性质不包括","o":["水溶性大，脂溶性小","与血浆白蛋白结合力大","对细胞的通透性与毒性小","能透过肾小球从尿中排出","与重氮试剂直接反应"],"a":1,"e":"结合胆红素为胆红素双葡萄糖醛酸酯，极性大、水溶性大而脂溶性小，与清蛋白结合疏松，可经肾小球滤过随尿排出，并与重氮试剂直接反应。与清蛋白结合力大的是未结合胆红素，其脂溶性大、易透膜、毒性大，尿中不出现"},{"q":"机体缺乏维生素B6引起的贫血，其原因是","o":["维生素B6（磷酸吡哆醛）是ALA合酶的辅酶","维生素B6（磷酸吡哆醛）是ALA脱水酶的辅酶","维生素B6（磷酸吡哆醛）是亚铁螯合酶的辅酶","维生素B6（磷酸吡哆醛）是尿卟啉原Ⅲ同合酶的辅酶","维生素B6（磷酸吡哆醛）是尿卟啉原Ⅰ同合酶的辅酶"],"a":0,"e":"磷酸吡哆醛是ALA合酶的辅酶，该酶为血红素合成的限速酶，维生素B6缺乏使其活性下降，血红素生成减少而致贫血。ALA脱水酶需锌，亚铁螯合酶需还原剂，尿卟啉原同合酶不含磷酸吡哆醛，故其余各项的辅酶归属均错误"},{"q":"下列情况不属于酶含量调节的是","o":["鸟氨酸循环底物增加，诱导参与鸟氨酸循环的酶合成增加","HMG-CoA还原酶在肝内的合成被胆固醇阻遏","溶酶体蛋白水解酶非特异降解酶蛋白质","酶蛋白分子的泛素化降解途径","胰蛋白酶原在十二指肠中形成胰蛋白酶"],"a":4,"e":"胰蛋白酶原在十二指肠被肠激酶水解激活为胰蛋白酶，属于酶原激活，改变的是酶的活性而非含量，故不属于酶含量调节。底物诱导酶合成、胆固醇阻遏HMG-CoA还原酶合成分别属酶合成的诱导与阻遏；溶酶体降解和泛素化降解属酶蛋白降解，均改变酶含量"},{"q":"关于溶血性黄疸，下列说法正确的是","o":["患者尿胆红素阳性","由破坏红细胞释放出的珠蛋白可以抑制肝细胞处理胆红素的能力","患者血清总胆红素不变","患者肝细胞处理胆红素的能力下降","过多的胆红素超过了肝细胞的处理能力"],"a":4,"e":"大量红细胞破坏使胆红素生成过多，超过肝细胞摄取、转化和排泄能力，血中未结合胆红素升高，故E项正确。此时结合胆红素变化不大，尿胆红素阴性，A项错误。肝细胞处理能力本身正常，B、D项归因不当，总胆红素升高而非不变"},{"q":"对增强子特点的描述，正确的是","o":["增强子距离转录起始点不能太远","仅存在于启动子的上游","增强子作用的发挥不依赖启动子","在结构基因5'-端的DNA序列","是较短的能增强转录的DNA序列"],"a":4,"e":"增强子是较短的DNA序列，与特异调节蛋白结合后增强启动子的转录活性，其作用与方向、距离无关，可位于基因上游、下游或内含子中。增强子发挥作用仍依赖启动子，并非仅存在于上游，也不等同于结构基因5′-端的特定序列"},{"q":"线粒体中丙酮酸彻底氧化发生","o":["3次脱羧，7次脱氢","3次脱羧，5次脱氢","4次脱羧，6次脱氢","4次脱羧，7次脱氢","2次脱羧，5次脱氢"],"a":1,"e":"丙酮酸经脱氢酶复合体氧化脱羧生成乙酰CoA，为1次脱羧、1次脱氢；乙酰CoA进入三羧酸循环一轮为2次脱羧、4次脱氢，合计3次脱羧、5次脱氢，生成4分子NADH、1分子FADH2，并发生1次底物水平磷酸化"},{"q":"原核生物转录起始前-10区的核苷酸序列被称为","o":["TATA盒","CAAT盒","增强子","Pribnow盒","沉默子"],"a":3,"e":"原核生物-10区的一致序列为TATAAT，因由Pribnow首先发现而称Pribnow盒，是RNA聚合酶全酶辨认并形成开放启动子复合物的部位。-35区为TTGACA，供σ因子初步识别。TATA盒是真核Ⅱ类启动子的核心元件，GC盒与CAAT盒属真核上游元件"},{"q":"基因的功能包括编码基因的蛋白质功能和哪项功能","o":["代谢产物","非编码RNA","启动子","增强子","内含子"],"a":1,"e":"基因的功能包括编码蛋白质和编码非编码RNA，后者参与基因表达调控、RNA加工与蛋白质转运。启动子与增强子是调控序列而非基因产物，内含子属基因内非编码序列，代谢产物不是基因编码功能的类别"},{"q":"当溶液的pH值与某种氨基酸的pI一致时，该氨基酸在此溶液中的存在形式是","o":["兼性离子","非兼性离子","带单价正电荷","带单价负电荷","疏水分子"],"a":0,"e":"pH等于pI时，氨基酸的α-氨基与α-羧基解离程度相等，净电荷为零，主要以兼性离子形式存在，在电场中不移动。阳离子在pH低于pI时占优势，阴离子在pH高于pI时占优势。疏水胶粒与极性分子描述的是胶体性质与分子极性，与解离状态无关"},{"q":"DNA损伤后，机体可通过①核酸内切酶；②DNA连接酶；③DNA聚合酶Ⅰ；④DNA聚合酶Ⅰ5'→3'外切酶活性这四种酶的协同作用将损伤加以修复，四种酶的工作顺序是","o":["①，②，③，④","①，④，③，②","②，③，④，①","③，②，①，④","④，③，②，①"],"a":1,"e":"切除修复时，先由核酸内切酶在损伤处切开磷酸二酯键，再由DNA聚合酶Ⅰ的5'→3'外切酶活性切除损伤寡核苷酸，继而以其聚合酶活性填补缺口，最后由DNA连接酶封口。顺序为①→④→③→②，其余排列打乱了切、切、补、连的基本流程"},{"q":"下列哪条途径需要单次跨膜受体","o":["cGMP-蛋白激酶通路","cAMP-蛋白激酶途径","酪氨酸蛋白激酶体系","细胞膜上Ca2+通道开放","Ca2+-依赖性蛋白激酶途径"],"a":2,"e":"酪氨酸蛋白激酶体系的受体为单次跨膜蛋白，配体结合后受体二聚化并激活胞内激酶结构域，故需单次跨膜受体。cAMP-PKA、cGMP-PKG以及Ca2+依赖途径均通过G蛋白偶联的七次跨膜受体传递信号，属GPCR途径，胞内无酶活性，与酶联受体的单次跨膜特征不同"},{"q":"核糖体、甲酰甲硫氨酰tRNA和mRNA共同结合于蛋白质合成的","o":["氨基酸活化阶段","氨基酸搬运阶段","启动阶段","肽链延长阶段","终止阶段"],"a":2,"e":"蛋白质合成启动阶段，核糖体小亚基先结合mRNA，再与甲酰甲硫氨酰-tRNA及大亚基组装成起始复合物，三者共同结合于此时。氨基酸活化由氨酰-tRNA合成酶在胞质完成；搬运是tRNA转运氨基酸；延长阶段涉及进位、成肽与转位；终止由释放因子识别终止密码"},{"q":"原核生物转录终止需要的因子是","o":["释放因子","ρ因子","信号肽","σ因子","Dna B"],"a":1,"e":"ρ因子具依赖RNA的解旋酶活性，结合新生RNA后使RNA聚合酶停顿并拆离DNA-RNA杂化双链，终止转录。σ因子识别启动子，释放因子作用于翻译终止，DnaB为复制解旋酶。依赖ρ因子的终止需RNA上存在ρ结合位点，非依赖者靠RNA发夹结构与寡聚U"},{"q":"β-羟丁酸脱下的氢经呼吸链传递，最终将电子传递给","o":["细胞色素a3","水","氢离子","氧原子","氧分子"],"a":3,"e":"β-羟丁酸脱氢生成乙酰乙酸，NADH经复合体Ⅰ传递电子，最终由细胞色素aa3将电子交给氧原子，与H+结合成水。电子不直接传给氢离子或水；氧分子接受4个电子，并非单个电子的直接受体"},{"q":"有机汞化合物能抑制","o":["巯基酶","羟基酶","胆碱酯酶","含-S-S-的酶","碱性酶"],"a":0,"e":"有机汞与酶分子中半胱氨酸残基的巯基结合，使巯基酶失活，重金属中毒即由此引起。有机磷抑制的是胆碱酯酶活性中心的丝氨酸羟基，羟基酶与含二硫键的酶并非有机汞的靶点。有机磷中毒则用解磷定复活胆碱酯酶"},{"q":"生成酮体的主要原料来源于","o":["葡萄糖氧化分解所产生的乙酰CoA","甘油转变的乙酰CoA","脂酸β-氧化所形成的乙酰CoA","丙氨酸转变而成的乙酰CoA","甘氨酸转变而成的乙酰CoA"],"a":2,"e":"酮体生成以脂肪酸β-氧化产生的乙酰CoA为原料，在肝线粒体由HMG-CoA合酶及裂解酶催化完成。葡萄糖氧化、甘油转变、丙氨酸与甘氨酸代谢产生的乙酰CoA量少，不是主要来源。肝内HMG-CoA合酶是酮体生成的限速酶，饥饿时其活性显著升高"},{"q":"由整合酶催化、在两个DNA序列的特异位点间发生的整合是","o":["人工重组","基本重组","随机重组","同源重组","位点特异的重组"],"a":4,"e":"位点特异性重组发生在具有特定序列的同源位点之间，由整合酶催化，如λ噬菌体DNA整合入宿主染色体。同源重组依赖广泛的序列同源性并由RecA介导；随机重组与人工重组均不依赖特异位点的识别"},{"q":"关于基因组的描述，错误的是","o":["一个细胞DNA分子中全部的编码序列","一个细胞所载的全部遗传信息","在真核生物，基因组还包括线粒体或叶绿体DNA","细菌基因组包括质粒中的DNA序列","病毒基因组可以为DNA，也可以为RNA"],"a":0,"e":"基因组是生物体或细胞一套完整单倍体遗传信息的总和，包括编码序列与非编码序列，真核生物还包括线粒体或叶绿体DNA，细菌质粒DNA亦计入其中。病毒基因组可为DNA或RNA，A项将基因组等同于全部编码序列，范围过窄"},{"q":"蛋白质生物合成时转肽酶活性存于","o":["EFTu","EFG","IR","核糖体大亚基","核糖体小亚基"],"a":3,"e":"肽键形成由大亚基中的转肽酶催化，其活性中心由23S rRNA构成，属核酶，故转肽酶活性存于核糖体大亚基。EFTu负责携带氨酰tRNA进入A位，EFG为转位酶。小亚基承担mRNA结合与密码子识别，不具转肽功能"},{"q":"可以使非糖物质转化为活性葡萄糖的是","o":["糖的有氧氧化","磷酸戊糖途径","糖酵解","三羧酸循环","糖异生"],"a":4,"e":"糖异生将乳酸、甘油、生糖氨基酸等非糖物质转变为葡萄糖，是空腹或饥饿时补充血糖的主要途径。糖酵解方向相反，分解葡萄糖生成乳酸。磷酸戊糖途径生成5-磷酸核糖与NADPH，三羧酸循环氧化乙酰CoA，均不净生成葡萄糖"},{"q":"真核基因转录中起正性调节作用的是","o":["启动子","操纵子","增强子","衰减子","沉默子"],"a":2,"e":"增强子是远距离调控序列，与特异转录因子结合后增强启动子活性，作用与方向和距离无关，属正性调节。沉默子为负调节元件，结合阻遏蛋白抑制转录。启动子只决定转录起始位点，本身不体现正负调节；操纵子为原核调控单位，衰减子亦起负调节作用"},{"q":"下列不属于基因定位的方法是","o":["荧光原位杂交","体细胞杂交","全基因组关联研究","连锁分析","免印印迹"],"a":4,"e":"免疫印迹用于检测特定蛋白质，不属于基因定位方法，故为答案。荧光原位杂交通过荧光探针将基因定位到染色体，体细胞杂交依据染色体丢失进行基因定位，全基因组关联研究与连锁分析通过遗传标记定位疾病基因，均属基因定位相关技术"},{"q":"糖组学研究的主要对象是","o":["糖原","聚糖","血糖","乳糖","葡萄糖"],"a":1,"e":"糖组学以生物体内所有聚糖（糖链）的结构与功能为研究对象，包括糖蛋白、糖脂上的寡糖链。糖原、乳糖、葡萄糖是具体的糖，血糖是血液中葡萄糖的浓度，均为单一或小分子糖，不是糖组学整体研究的对象"},{"q":"由葡萄糖合成糖原时，每增加1个葡萄糖单位消耗高能磷酸键数为","o":["1","2","3","4","5"],"a":1,"e":"葡萄糖磷酸化为葡萄糖-6-磷酸消耗1个ATP，经变位生成葡萄糖-1-磷酸后与UTP生成UDPG，焦磷酸水解又损失1个高能键，故每增加1个葡萄糖单位消耗2个高能磷酸键。UTP可由ATP再生，不另计消耗。1、3、4、5个均与计量不符"},{"q":"下列对酶原的描述错误的是","o":["酶原是细胞内合成及初分泌的没有活性的酶","酶原激活可使酶在特定的部位和环境中发挥作用","酶原分子无活性是因为活性中心未形成或未暴露","绝大多数酶都以酶原形式存在","酶原可在细胞内或外经激活而成为有活性的酶"],"a":3,"e":"只有部分蛋白酶与凝血因子以酶原形式分泌，绝大多数酶并不以酶原存在，此说以偏概全。酶原因活性中心未形成或未暴露而无活性，激活后保证酶在特定部位与环境中发挥作用，激活可发生于细胞内或细胞外"},{"q":"LPL的作用是水解","o":["脂肪细胞内甘油三酯","肝细胞内甘油三酯","CM和VLDL中的甘油三酯","LDL中的甘油三酯","HDL中的甘油三酯"],"a":2,"e":"脂蛋白脂肪酶位于毛细血管内皮细胞表面，由apoCⅡ激活，水解CM与VLDL中的甘油三酯，释出脂肪酸供组织利用。脂肪细胞与肝细胞内的甘油三酯由激素敏感脂肪酶等水解，LDL与HDL中甘油三酯含量很低"},{"q":"O-连接型聚糖的二糖核心为","o":["N-乙酰半乳糖胺-半乳糖","N-乙酰葡糖胺-葡萄糖","N-乙酰葡糖胺-半乳糖","N-乙酰半乳糖胺-葡萄糖","N-乙酰半乳糖胺-甘露糖"],"a":0,"e":"O-连接型聚糖以N-乙酰半乳糖胺与丝/苏氨酸的羟基相连，其核心二糖为N-乙酰半乳糖胺-半乳糖，由GalNAc转移酶和半乳糖转移酶依次加上。N-连接型聚糖与天冬酰胺的酰胺氮相连，核心为五糖，含甘露糖与N-乙酰葡萄糖胺，两者起始糖基与连接氨基酸均不同"},{"q":"含修饰核苷酸最多的RNA是","o":["rRNA","tRNA","mRNA","5SrRNA","hnRNA"],"a":1,"e":"tRNA含大量稀有碱基，如二氢尿嘧啶、假尿苷和次黄嘌呤，是含修饰核苷酸最多的RNA。tRNA约70～80个核苷酸，三级结构呈倒L型，参与蛋白质合成；rRNA、mRNA与hnRNA的修饰核苷酸均明显少于tRNA"},{"q":"根据中心法则，遗传信息的传递方式是","o":["DNA-RNA-蛋白质","蛋白质-RNA-DNA","RNA-DNA-蛋白质","RNA-RNA-DNA","DNA-DNA-蛋白质"],"a":0,"e":"中心法则揭示遗传信息按DNA复制、DNA转录为RNA、RNA翻译为蛋白质的方向传递，即DNA-RNA-蛋白质。蛋白质不能反向指导核酸合成，故蛋白质-RNA-DNA不成立；RNA-DNA-蛋白质所述逆转录仅为对中心法则的补充，并非常规传递主线；RNA-RNA复制只见于部分病毒，不是普遍方式"},{"q":"下列能使血浆胆固醇升高的激素是","o":["氢化可的松","胰岛素","胰高血糖素","肾上腺素","甲状腺素"],"a":1,"e":"胰岛素促进糖利用，同时增强HMG-CoA还原酶活性、增加胆固醇合成，并使LDL受体活性下降，血浆胆固醇升高。胰高血糖素、肾上腺素促进脂肪动员与脂肪酸氧化，甲状腺素加速胆固醇转化与排泄，均使其下降。氢化可的松以升高血糖、促进脂肪重新分布为主，非本题所指激素"},{"q":"原核生物的核糖体上有3个重要的功能部位，其中某功能部位在肽链合成中可以结合氨酰-tRNA，作为氨酰-tRNA进入的位置。该重要的功能部位称为","o":["A位","P位","E位","肽酰位","出口位"],"a":0,"e":"核糖体A位即氨酰位，结合新进入的氨酰-tRNA；P位为肽酰位，结合肽酰-tRNA；E位为排出位，释放卸载后的tRNA。起始时fMet-tRNA直接进入P位，此后每个氨酰-tRNA均先进入A位"},{"q":"下列哪种物质不用作探针","o":["RNA片段","DNA片段","蛋白质","氨基酸","人工合成的寡核苷酸片段"],"a":3,"e":"核酸探针可为DNA片段、RNA片段或人工合成的寡核苷酸，标记后与靶序列互补结合；蛋白质亦可作探针检测蛋白相互作用。氨基酸分子小且无互补配对能力，不能用作探针。探针须带放射性核素或生物素等可检测标记，并与靶序列有足够同源性"},{"q":"维生素D被列为激素的依据是","o":["维生素D与类固醇激素同由胆固醇转变而来","维生素D与类固醇结构上类似","维生素D能在体内合成","维生素D能溶于脂肪和有机溶剂","维生素D能在体内羟化转变成有生物活性的物质"],"a":4,"e":"维生素D本身无活性，须在肝羟化为25-OH-D3、再在肾羟化为1,25-(OH)2-D3才具生物活性，经血液运输作用于靶器官，符合激素微量高效、经体液运送的特征。能在体内合成或由胆固醇转变并非激素专属，脂溶性仅为理化性质，与类固醇结构类似也不构成列为激素的依据"},{"q":"S-腺苷甲硫氨酸最重要的生理功能是","o":["补充甲硫氨酸","生成嘌呤核苷酸","提供甲基","生成嘧啶核苷酸","合成四氢叶酸"],"a":2,"e":"S-腺苷甲硫氨酸是体内最重要的甲基供体，参与DNA、RNA、蛋白质、磷脂及肌酸等分子的甲基化反应。它并非主要用于补充甲硫氨酸；嘌呤、嘧啶环的从头合成不以其为甲基来源；四氢叶酸由叶酸还原而成，均非其主要功能"},{"q":"可使激动型G蛋白中的α亚基发生ADP核糖基化从而丧失GTP酶活性的是","o":["霍乱毒素","百日咳毒素","白喉毒素","铜绿假单胞菌外毒素","肉毒毒素"],"a":0,"e":"霍乱毒素催化激动型Gs的α亚基发生ADP核糖基化，抑制其GTP酶活性，使α亚基持续结合GTP并激活腺苷酸环化酶，胞内cAMP大量生成。百日咳毒素作用于抑制型Gi的α亚基，使其不能被受体激活，与激动型G蛋白恰相对；白喉毒素使延长因子EF-2核糖基化而阻断蛋白质合成；肉毒毒素抑制神经递质释放"},{"q":"柠檬酸循环被认为是一个需氧代谢途径，是因为","o":["循环的某些反应是以氧作为底物的","产生了H2O","CO2是该循环的1个产物","还原型辅酶需通过电子传递链被氧化","以上都不对"],"a":3,"e":"三羧酸循环本身不直接消耗氧，其脱氢生成的NADH、FADH2必须经呼吸链传递电子、由氧最终接受生成水，循环才能持续运转，故表现为需氧。循环中没有以氧为底物的反应，CO2来自脱羧，H2O的生成在呼吸链末端而不在循环内"},{"q":"患者，男，乳房发育，皮肤出现蜘蛛痣，是由于","o":["雌激素分泌过多","雌激素灭活不足","雄激素分泌过少","雄激素失去活性","雌激素受体表达增多"],"a":1,"e":"男性乳房发育、蜘蛛痣与肝掌是肝硬化雌激素增多的表现，肝细胞受损使雌激素灭活减少，血中雌二醇升高，刺激乳腺与皮肤小动脉扩张。雄激素在肝内亦降解减慢但并非本症主因；孕激素、促性腺激素与泌乳素的改变不能解释蜘蛛痣的形成机制"},{"q":"下列机体状态下，脑组织可利用酮体氧化供能的是","o":["饥饿1～3天","轻型糖尿病","空腹","长期饥饿","剧烈运动"],"a":3,"e":"长期饥饿时脂肪动员进一步加强，肝内生成大量酮体，脑利用酮体供能超过葡萄糖，可占总耗氧量约60%。饥饿1～3天与空腹时脑以葡萄糖为主，仅少量利用酮体；轻型糖尿病虽酮体生成增多，但脑供能仍以葡萄糖为主"},{"q":"最常用于原核表达的体系","o":["酵母","昆虫细胞","噬菌体","真菌","大肠杆菌"],"a":4,"e":"大肠埃希菌是应用最多的原核表达体系，培养简单迅速、经济且适合大规模生产，但缺乏对产物的糖基化等加工修饰。酵母、昆虫细胞和真菌属真核表达体系，噬菌体常用作克隆载体而非表达宿主。表达产物常形成包涵体，需复性处理"},{"q":"治疗尿路感染的环丙沙星（ciprofloxacin）和萘啶酸（nalidixicacid）能够特异性抑制细菌体内的","o":["DNA连接酶","RNA聚合酶","DNA拓扑异构酶Ⅰ","DNA解旋酶","DNA解链酶"],"a":2,"e":"官方答案为【DNA拓扑异构酶Ⅰ】，但依据教材，正确答案为【DNA拓扑异构酶Ⅱ】。喹诺酮类特异性抑制细菌DNA促旋酶，即拓扑异构酶Ⅱ，阻碍负超螺旋引入与复制叉前进；拓扑异构酶Ⅰ只切开一条链且不需ATP，不是其靶点。备选项把Ⅱ型误写为Ⅰ型，原答案无法成立"},{"q":"1,4,5-三磷酸肌醇（IP3）与相应受体结合后，细胞质内浓度升高的离子是","o":["K＋","Na＋","HCO3-","Ca2＋","Mg2＋"],"a":3,"e":"IP3为水溶性第二信使，扩散至内质网与IP3受体结合，该受体即Ca2+通道，开放后使钙库释放Ca2+，细胞质Ca2+浓度迅速升高，与DAG共同激活蛋白激酶C。K+、Na+、HCO3-、Mg2+不因IP3受体激活而升高，故其余选项不成立"},{"q":"下列哪种物质是肝细胞特异合成的","o":["脂肪","蛋白质","糖原","尿素","ATP"],"a":3,"e":"尿素合成酶系仅存在于肝脏，尿素为肝细胞特异合成的终产物。脂肪、蛋白质、糖原在多种组织均可合成；ATP几乎在所有活细胞都能生成，并非肝细胞特异"},{"q":"有关游离胆红素的叙述，错误的是","o":["又称为间接胆红素","属于脂溶性物质，易通过细胞膜对脑产生毒性作用","又称肝胆红素","不易经肾随尿排出","与重氮试剂反应间接阳性"],"a":2,"e":"游离胆红素即未结合胆红素，在血浆中与清蛋白结合运输，脂溶性、不能经肾滤过，凡登白试验间接阳性；结合胆红素才称肝胆红素，水溶性、可随尿排出。故C项张冠李戴，A、B、D、E项均为游离胆红素的真实特点"},{"q":"关于基因诊断的描述，正确的是","o":["羊水不适合作为样本用于基因诊断","唾液和尿液可以作为样本用于基因诊断","精液和毛发不适合作为样本用于基因诊断","与常规诊断方法相比，基因诊断的主要劣势是价格显著高于常规诊断方法","恶性肿瘤、心脑血管等复杂性疾病不适合进行基因诊断"],"a":1,"e":"基因诊断样本来源广泛，血液、组织、精液、唾液、尿液、羊水、绒毛与毛发均可，唾液和尿液适用。故羊水、精液、毛发不适合之说错误；其优势是特异性强、灵敏度高，价格并非主要劣势，复杂性疾病亦可作易感基因检测"},{"q":"核酸变性后，可发生哪种效应","o":["Tm值升高","增色效应","失去对紫外线的吸收能力","最大吸收波长发生转移","溶液黏度增加"],"a":1,"e":"DNA变性后双链解离，碱基由堆积状态暴露，260nm吸光度升高，称增色效应。Tm是解链50%时的温度，变性不改变最大吸收波长，也不丧失紫外吸收能力；单链松散使溶液黏度下降。增色效应的大小与变性程度相关，可用于监测DNA复性与杂交过程"},{"q":"关于哺乳动物嘧啶核苷酸从头合成的调节，描述正确的是","o":["天冬氨酸氨基甲酰转移酶是主要调节酶","嘧啶磷酸核糖转移酶是嘧啶核苷酸主要调节酶","氨基甲酰磷酸合成酶Ⅱ是主要调节酶","二清乳清酸酶是主要调节酶","乳清酸核苷酸脱羧酶是主要调节酶"],"a":2,"e":"哺乳动物嘧啶核苷酸从头合成的主要调节酶是氨基甲酰磷酸合成酶Ⅱ，受UMP、UTP等终产物反馈抑制，受PRPP激活。细菌中才以天冬氨酸氨基甲酰转移酶为主要调节酶；嘧啶磷酸核糖转移酶属补救途径，二氢乳清酸酶与乳清酸核苷酸脱羧酶不承担主要调节作用"},{"q":"蛋白质的一级结构是空间构象的基础，蛋白质的功能依赖特定的空间结构，如果蛋白质的折叠发生错误，尽管一级结构不变，但空间构象发生改变仍可影响其功能，严重时可导致疾病——蛋白质构象病，例如","o":["疯牛病","糖尿病","冠心病","脑卒中","痛风症"],"a":0,"e":"疯牛病由朊蛋白错误折叠并聚集成抗蛋白酶的淀粉样纤维所致，一级结构不变而构象改变，属蛋白质构象病。糖尿病源于胰岛素分泌不足或受体缺陷，冠心病与脑卒中是血管病变，痛风为尿酸代谢异常，均非蛋白质折叠异常所致"},{"q":"关于酶原及其激活的叙述，错误的是","o":["酶原是酶的贮存形式","酶原激活时需要水解肽键","体内所有的酶均有酶原形式","酶原激活能形成酶的活性中心","酶原激活是酶原向酶的转化过程"],"a":2,"e":"酶原只是部分酶尤其消化蛋白酶、凝血因子的贮存与分泌形式，多数酶并不以酶原存在，故C项错误。酶原激活需水解一个或几个肽段，使肽链折叠改变而暴露活性中心，本质是酶原向酶的转化，可视为酶的贮存形式"},{"q":"尿素生成的限速酶是","o":["精氨酸酶","CPS-Ⅰ","CPS-Ⅱ","精氨酸代琥珀酸合成酶","鸟氨酸氨基甲酰转移酶"],"a":3,"e":"尿素合成的关键酶中，精氨酸代琥珀酸合成酶活性最低，是鸟氨酸循环启动后的限速酶，催化瓜氨酸与天冬氨酸缩合，消耗ATP生成AMP及PPi。CPS-Ⅰ催化氨与CO2生成氨基甲酰磷酸，是另一调节点，但非活性最低者。CPS-Ⅱ参与嘧啶合成，不参与尿素生成"},{"q":"下列对嘧啶核苷酸从头合成途径的描述，正确的是","o":["先合成嘧啶环，再与PRPP中的磷酸核糖相连","在PRPP的基础上，与氨基酸及CO2作用逐步合成","UMP的合成需要有一碳单位的参加","主要是在线粒体内合成","需要有氨基甲酰磷酸合成酶Ⅰ参加"],"a":0,"e":"嘧啶核苷酸从头合成的特点是先合成嘧啶环（乳清酸），再与PRPP提供的磷酸核糖结合生成UMP，与嘌呤核苷酸先形成PRPP衍生物再逐步成环相反。在PRPP基础上逐步合成是嘌呤合成方式。UMP合成不需一碳单位，该途径在胞液进行，参与的是氨基甲酰磷酸合成酶Ⅱ而非Ⅰ，酶Ⅰ参与尿素合成"},{"q":"关于糖蛋白N-连接型聚糖的叙述，错误的是","o":["合成需要长萜醇载体","合成场所是粗面内质网和高尔基体","N-连接型聚糖合成是在蛋白肽链合成后进行","N-连接型聚糖有五糖核心","聚糖中的N-乙酰葡糖胺与多肽链中天冬酰胺残基的酰胺氮共价连接"],"a":2,"e":"N-连接型聚糖的合成是在肽链合成同时（共翻译）开始的，即边翻译边将预装配的寡糖转移到新生肽链的天冬酰胺残基上，故肽链合成后进行的说法错误。其合成需长萜醇载体、在粗面内质网和高尔基体进行、具五糖核心、由N-乙酰葡糖胺与Asn酰胺氮连接，均正确"},{"q":"以下关于多基因病说法错误的是","o":["一般有家族性遗传倾向","表现为2个以上基因的“微效作用”的相加，或者多基因间相互作用","单一基因的变异一般仅增加对疾病的易感性","包含肿瘤、代谢性疾病等","环境因素往往影响较弱"],"a":4,"e":"多基因病由多个微效基因累加并与环境因素共同作用，环境因素影响显著，遗传度多在中等水平，故“环境因素往往影响较弱”错误。此类疾病有家族聚集倾向但不符孟德尔比例，近亲婚配可提高发病风险，种族与地理差异明显，均反映遗传与环境的双重作用"},{"q":"真核细胞染色质的基本结构单位是","o":["组蛋白","核心颗粒","核小体","超螺旋筒","α-螺旋"],"a":2,"e":"核小体是真核染色质的基本结构单位，由组蛋白H2A、H2B、H3、H4各两分子构成核心八聚体，DNA缠绕其上约1.65圈，再由H1连接。核心颗粒只是核小体的核心部分，不含连接DNA与H1；组蛋白仅为蛋白质组分；超螺旋筒、α-螺旋均非染色质基本单位"},{"q":"构成细菌的限制修饰体系的酶有","o":["限制性核酸内切酶和DNA聚合酶","限制性核酸内切酶和RNA聚合酶","限制性核酸内切酶和甲基化酶","限制性核酸外切酶和甲基化酶","限制性核酸外切酶和DNA聚合酶"],"a":2,"e":"细菌的限制修饰体系由限制性核酸内切酶与相伴的甲基化酶组成：甲基化酶修饰自身DNA使其免遭切割，内切酶识别并切割外源DNA，从而稳定细菌遗传性状。DNA聚合酶、RNA聚合酶参与复制与转录，核酸外切酶从链端逐个水解，均不属该体系"},{"q":"在三羧酸循环和尿素循环中存在的共同中间产物为","o":["草酰乙酸","丙酮酸","延胡索酸","柠檬酸","苹果酸"],"a":2,"e":"尿素循环中精氨酸琥珀酸经裂解酶生成精氨酸与延胡索酸，延胡索酸再经三羧酸循环转变为苹果酸、草酰乙酸，故延胡索酸为两循环共有的中间产物。草酰乙酸与苹果酸只属三羧酸循环，柠檬酸亦为该循环专有；丙酮酸不参与尿素循环。这一联系使尿素循环与三羧酸循环相互衔接"},{"q":"组成核蛋白体的成分为","o":["蛋白质和RNA","RNA和DNA","DNA和蛋白质","tRNA和蛋白质","蛋白质和多糖"],"a":0,"e":"核糖体由rRNA与多种蛋白质组装而成，原核为70S，由30S与50S亚基组成，真核为80S。DNA不参与其组成，故B、C项错误。tRNA只是携带氨基酸的接头分子，并非核糖体结构成分，多糖亦不参与组装"},{"q":"下列关于线粒体DNA（mtDNA）的描述有误的是","o":["mtDNA是线状分子","mtDNA共编码37个基因","mtDNA是细胞核外遗传物质","mtDNA结构特点与原核生物相似","mtDNA独立编码线粒体中的一些蛋白质"],"a":0,"e":"mtDNA为裸露的闭合双链环状分子，全长16569bp，共编码37个基因，即13种多肽、22种tRNA和2种rRNA，结构与原核DNA相似，故“线状分子”之说错误。mtDNA可独立编码部分线粒体蛋白质，遗传密码与核DNA不完全相同，但多数线粒体蛋白仍由核基因编码、在胞质合成后输入"},{"q":"原核生物嘧啶二聚体的主要修复方式为","o":["SOS修复","碱基切除修复","核苷酸切除修复","跨越损伤修复","光复活修复"],"a":4,"e":"光复活酶特异识别并直接逆转嘧啶二聚体，是原核生物修复紫外线损伤的主要方式。核苷酸切除修复虽也能去除二聚体，但需UvrA、UvrB、UvrC切断并删除片段；碱基切除修复针对单个受损碱基。SOS修复与跨越损伤修复属易错修复，哺乳动物缺乏光复活酶而以切除修复为主"},{"q":"生物体内ATP最主要的来源是","o":["糖酵解","三羧酸循环","磷酸戊糖途径","氧化磷酸化作用","底物水平磷酸化作用"],"a":3,"e":"线粒体氧化磷酸化将呼吸链电子传递与ADP磷酸化偶联，生成机体所需ATP的绝大部分。糖酵解与三羧酸循环中的底物水平磷酸化产能有限，磷酸戊糖途径主要生成NADPH与戊糖，均非ATP的主要来源"},{"q":"转录与DNA复制的不同点是","o":["遗传信息储存于碱基序列中","新生链的合成遵守碱基配对原则","RNA聚合酶缺乏校正功能","合成方向为5'→3'","需要消耗能量"],"a":2,"e":"RNA聚合酶缺乏3'→5'外切酶活性，无校对功能，转录错误率高于复制。两者均以碱基配对合成新生链、方向为5'→3'、消耗能量，遗传信息都储于碱基序列，故这些是共同点而非区别。转录只以一条链为模板且仅局部解链，复制则两条链均作模板"},{"q":"对原核和真核蛋白质生物合成均有抑制作用的抗生素是","o":["放线菌酮（环己酰亚胺）","四环素","链霉素","氯霉素","嘌呤霉素"],"a":4,"e":"嘌呤霉素结构与酪氨酰-tRNA相似，可进入原核与真核核糖体A位，使肽酰基转移至其氨基上、肽链提前脱落，故对两类细胞均有抑制作用。放线菌酮作用于真核60S大亚基，四环素、链霉素和氯霉素均只作用于原核核糖体"},{"q":"在乳糖操纵子中，cAMP能对转录进行调控，但先与","o":["CAP结合","RNA聚合酶结合","G蛋白结合","操纵序列结合","阻遏蛋白结合"],"a":0,"e":"cAMP先与CAP结合形成复合物，再结合于启动子上游的CAP位点，促进RNA聚合酶与启动子结合，使lac操纵子转录提高数十倍。cAMP不与RNA聚合酶、操纵序列或阻遏蛋白结合；G蛋白存在于真核信号转导，与原核操纵子的调控无关"},{"q":"合成磷脂酰胆碱及磷脂酰肌醇时均需要下列哪种物质","o":["丝氨酸","甲硫氨酸","CTP","H2O","甘油二酯"],"a":2,"e":"磷脂酰胆碱经CDP-胆碱途径合成，磷脂酰肌醇经CDP-甘油二酯途径合成，均需CTP参与活化。丝氨酸是磷脂酰丝氨酸的骨架，甲硫氨酸提供甲基，甘油二酯是二者共有的骨架成分而非需活化的特异供体"},{"q":"用亮氨酸喂养实验性糖尿病犬时，下列哪种物质从尿中排出增加","o":["酮体","脂肪","乳酸","葡萄糖","非必需氨基酸"],"a":0,"e":"亮氨酸为生酮氨基酸，糖尿病犬给予亮氨酸后其分解生成乙酰CoA与乙酰乙酰CoA，转向酮体生成，尿中酮体排出增多。多数氨基酸使尿糖增加，脂肪不随尿排出，乳酸与非必需氨基酸并非其分解产物"},{"q":"限制性核酸内切酶切割双链DNA后产生的是","o":["5'磷酸基和3'羟基基团的末端","5'羟基和3'羟基基团的末端","3'磷酸基和5'羟基基团的末端","5'磷酸基和3'磷酸基团的末端","两个断裂点都是腺嘌呤核苷酸的末端"],"a":0,"e":"限制性核酸内切酶水解DNA骨架的磷酸二酯键，断裂后每段DNA的5'端为磷酸基、3'端为羟基，这一末端结构便于后续与载体连接。5'-羟基与3'-磷酸的组合不符合其水解方式；黏性末端或平末端都具此基本化学末端；末端碱基种类因酶而异，不固定为腺嘌呤"},{"q":"关于DNA pol Ⅲ亚基功能的表述，错误的是","o":["θ亚基有5'→3'外切酶活性","ε亚基有3'→5'外切酶活性","α亚基有5'→3'聚合活性","β亚基使酶沿模板滑动","ε亚基有碱基选择功能"],"a":0,"e":"DNA聚合酶Ⅲ中α亚基具5'→3'聚合活性，ε亚基具3'→5'外切酶校对活性并参与碱基选择，β亚基为滑动钳使酶沿模板滑动。θ亚基为稳定ε亚基的辅助亚基，并无5'→3'外切酶活性，具5'→3'外切酶活性的是DNA聚合酶Ⅰ，故该项错误"},{"q":"下列化合物对嘌呤核苷酸的生物合成不产生直接反馈抑制作用的是","o":["TMP","IMP","AMP","GMP","ADP"],"a":0,"e":"嘌呤核苷酸从头合成的产物IMP、AMP、GMP以及ADP、GDP均可反馈抑制PRPP合成或相关关键酶。TMP是嘧啶核苷酸，只反馈抑制嘧啶合成途径，对嘌呤核苷酸的合成无直接反馈抑制作用"},{"q":"在体内可转变生成胆色素的原料是","o":["胆汁","胆固醇","胆绿素","血红素","胆素"],"a":3,"e":"胆色素是铁卟啉化合物的分解产物，衰老红细胞释放的血红素经血红素加氧酶氧化为胆绿素，再由胆绿素还原酶生成胆红素，故血红素是生成胆色素的原料。胆固醇是胆汁酸的前体，不能生成胆色素；胆绿素是中间产物，胆汁与胆素是排泄形式或终产物，均非原料"},{"q":"类脂在体内的主要功能是","o":["氧化供能","保护内脏器官","保持体温防止散热","维持正常生物膜的结构和功能","空腹或禁食时体内能量的主要来源"],"a":3,"e":"类脂包括磷脂、糖脂和胆固醇，是构成生物膜脂双层的基本骨架，维持膜的结构与功能。氧化供能主要由甘油三酯承担，保护内脏、保温防散热为脂肪组织的功能，空腹时能量主要来自脂肪动员而非类脂"},{"q":"磷脂酰胆碱的合成需要下列哪种物质的参与","o":["FAD","维生素C","GTP","SAM","NADPH"],"a":3,"e":"胆碱可由磷脂酰乙醇胺经SAM提供甲基生成，再活化为CDP-胆碱与甘油二酯缩合生成磷脂酰胆碱，故需SAM参与。CDP-胆碱生成需CTP而非GTP；FAD、维生素C、NADPH分别参与氧化还原与羟化反应，与胆碱基团的甲基化无关"},{"q":"用于检测体外蛋白质-蛋白质相互作用的技术是","o":["基因芯片","免疫共沉淀（CoIP）","GST pull-down实验","Western Blotting","EMSA"],"a":2,"e":"GST pull-down将GST融合蛋白固定于谷胱甘肽琼脂糖珠，捕获与之直接结合的靶蛋白，用于体外验证蛋白质间相互作用。免疫共沉淀需特异性抗体且多在细胞内进行；Western Blotting检测蛋白表达，EMSA检测DNA与蛋白质结合，基因芯片分析核酸"},{"q":"O-连接型聚糖的合成需要","o":["长萜醇载体","糖基化位点Asn-X-Ser/Thr","N-乙酰半乳糖胺与半乳糖构成的核心二糖","2个N-GlcNAc和3个Man形成的五糖核心","单糖活化为CDP的衍生物"],"a":2,"e":"O-连接型聚糖以N-乙酰半乳糖胺与半乳糖构成的核心二糖为起始，逐步糖基化，连接于丝氨酸或苏氨酸残基的羟基。长萜醇载体、Asn-X-Ser/Thr位点、五糖核心是N-连接型的特征；单糖活化为UDP/GDP衍生物而非CDP，CDP衍生物主要用于磷脂合成"},{"q":"稳定蛋白质分子中α-螺旋和β-折叠的化学键是","o":["肽键","氢键","盐键","二硫键","磷酸二酯键"],"a":1,"e":"α-螺旋靠肽链内第n个残基的羰基氧与第n+4个残基的氨基氢形成氢键维持，β-折叠靠相邻肽段间的氢键维持，二者均属二级结构。肽键是连接氨基酸的一级结构共价键，盐键与二硫键维持三级结构，磷酸二酯键存在于核酸而非蛋白质"},{"q":"基因重组技术中，载体选择的最重要条件是","o":["环状DNA","至少有一个选择标志","具有适宜的RE单一切点","能够自主复制","分子量小"],"a":3,"e":"载体是能自主复制的DNA分子，可在宿主染色体外独立扩增，故自主复制为最关键条件。选择标志、单一酶切位点、分子量小虽重要但属辅助特征；环状并非必需，线性噬菌体载体同样可作载体。表达载体还需具备启动子、核糖体结合位点等表达元件"},{"q":"长期饥饿时脑组织的能量主要来源于","o":["糖的氧化","乳酸氧化","脂酸氧化","酮体的氧化","氨基酸的氧化"],"a":3,"e":"长期饥饿时血糖下降，脑组织逐步适应利用肝生成的酮体供能，酮体可透过血脑屏障，成为脑的主要能源。糖的氧化在短期饥饿时为主，长期则不敷需要。乳酸来自外周糖酵解。脂酸不能透过血脑屏障，脑不能直接利用脂酸。氨基酸为次要补充，非主要来源"},{"q":"由于血型不匹配输血引起的溶血性黄疸，其特点是","o":["尿胆红素阴性","尿胆素原下降","粪胆素原下降","血清结合胆红素明显升高","血清未结合胆红素下降"],"a":0,"e":"溶血性黄疸时未结合胆红素生成过多，超过肝的摄取转化能力，而未结合胆红素为脂溶性、不能经尿排出，故尿胆红素阴性。因肝转化增多，尿胆素原与粪胆素原均升高，血清结合胆红素正常或微增，未结合胆红素明显升高"},{"q":"相同分子量的DNA电泳时，迁移率最大的是","o":["具有单切口的DNA链","线性DNA","环状DNA","完整的超螺旋DNA","具有多切口的DNA链"],"a":3,"e":"凝胶电泳中，相同分子量的DNA迁移率取决于构象紧凑程度：完整超螺旋DNA体积最小、阻力最小，迁移最快。开环即单切口DNA呈松弛环状，迁移最慢；线性DNA居中。多切口DNA与线性分子接近，均慢于超螺旋"},{"q":"镰状细胞贫血病是异常血红蛋白纯合子基因的临床表现，β链变异的类型是","o":["交换","插入","缺失","染色体不分离","点突变"],"a":4,"e":"镰状细胞贫血由β-珠蛋白基因第6密码子A→T单点突变，使谷氨酸变为缬氨酸。交换、插入、缺失与染色体不分离属其他类型的基因或染色体异常，不会产生这种单个氨基酸的替换。镰状红细胞易溶血，临床表现为贫血与黄疸"},{"q":"下列物质仅在肝脏中进行合成的是","o":["糖原","尿素","酮体","脂蛋白","糖酵解"],"a":2,"e":"酮体在肝线粒体以乙酰CoA为原料经HMG-CoA途径生成，肝缺乏利用酮体的酶，须运至肝外氧化，是肝内生成、肝外利用的物质。糖原在肝与肌均可合成，脂蛋白由肝和小肠合成，糖酵解遍布各组织。尿素在肝经鸟氨酸循环生成后入血由肾排出"},{"q":"基因组DNA文库是","o":["一个转化子细胞包含所有染色体片段","一个转化子细胞包含所有cDNA片段","携带各种基因组DNA片段的所有转化子细胞的集合","携带各种cDNA片段的所有转化子细胞的集合","一个转化子细胞包含所有基因组DNA"],"a":2,"e":"基因组文库是把某种生物基因组全部DNA片段克隆入载体后，所获得的携带各种基因组DNA片段的所有转化子细胞的集合，兼含编码与非编码序列。cDNA文库只含表达的基因，单个转化子只携带一个片段，不能代表全部基因组"},{"q":"三羧酸循环主要是在哪一亚细胞部位进行的","o":["细胞核","细胞质","微粒体","线粒体","内质网"],"a":3,"e":"三羧酸循环的酶系除琥珀酸脱氢酶结合于线粒体内膜外，其余均存在于线粒体基质，故该循环在线粒体进行，并与氧化磷酸化共用线粒体内膜。糖酵解在细胞质，磷酸戊糖途径在细胞质，脂肪酸合成在细胞质，内质网承担磷脂与胆固醇合成"},{"q":"鸟氨酸循环中，合成尿素的第二分子氨来自","o":["半胱氨酸","谷氨酸","天冬酰胺","天冬氨酸","氨基甲酰磷酸"],"a":3,"e":"鸟氨酸循环中第一分子氨来自氨基甲酰磷酸，第二分子氨由天冬氨酸提供，经精氨酸代琥珀酸合成酶催化与瓜氨酸缩合，再裂解生成精氨酸和延胡索酸。谷氨酸、半胱氨酸、天冬酰胺须先经转氨基把氨基转给α-酮戊二酸或草酰乙酸，不能直接供氨"},{"q":"将肌肉中的氨以无毒形式运送至肝脏的是","o":["枸橼酸-丙酮酸循环","丙氨酸-葡萄糖循环","鸟氨酸循环","乳酸循环","三羧酸循环"],"a":1,"e":"骨骼肌以丙酮酸为氨基受体生成丙氨酸，经血液运至肝，在肝内脱氨释出氨合成尿素，丙酮酸异生为葡萄糖再运回肌肉，构成丙氨酸-葡萄糖循环。鸟氨酸循环在肝内合成尿素，乳酸循环转运乳酸，枸橼酸-丙酮酸循环转运乙酰CoA"},{"q":"dTMP的嘧啶环中第五位碳原子上的甲基来源于","o":["S-腺苷甲硫氨酸","N5，N10-CH2-FH4","N5-CH3-FH4","N10-CHO-FH4","N5，N10=CH-FH4"],"a":1,"e":"dTMP由dUMP甲基化生成，甲基由N5,N10-亚甲基四氢叶酸提供，由胸苷酸合成酶催化，故为答案。SAM为通用甲基供体但不参与dTMP合成。N5-CH3-FH4参与甲硫氨酸循环。N10-CHO-FH4与N5,N10=CH-FH4分别提供甲酰基与甲炔基，参与嘌呤合成，均非dTMP甲基来源"},{"q":"关于原核生物蛋白质生物合成的描述，错误的是","o":["启动阶段核糖体小亚基先与mRNA的启动信号AUG部位结合","肽链延长阶段分为进位、转肽、脱落、移位四个步骤","每合成一个肽键须消耗2分子GTP","在“受位”上出现UAA以后转入终止阶段","释放因子只有一种可识别3种终止密码子"],"a":4,"e":"原核生物有三种释放因子，RF-1识别UAA与UAG，RF-2识别UAA与UGA，RF-3促进前两者与核糖体结合，故“只有一种释放因子识别三种终止密码子”是错误描述。原核起始密码为AUG，起始甲硫氨酸需甲酰化，核糖体有30S与50S亚基，mRNA有SD序列，这些均正确"},{"q":"巴斯德效应是指","o":["有氧氧化抑制糖酵解","糖酵解抑制糖异生","糖酵解抑制有氧氧化","有氧氧化抑制磷酸戊糖途径","有氧氧化抑制糖醛酸途径"],"a":0,"e":"巴斯德效应指糖有氧氧化抑制无氧氧化的现象，机制是氧充足时NADH经呼吸链氧化，丙酮酸不再还原为乳酸。糖酵解抑制糖异生不属此效应，糖酵解抑制有氧氧化方向相反，磷酸戊糖途径与糖醛酸途径均不参与该调节"},{"q":"重组噬菌体DNA转入宿主细胞的过程属于","o":["感染","转导","转化","转染","转位"],"a":0,"e":"以噬菌体、逆转录病毒等病毒颗粒为载体，将重组DNA包装后导入宿主细胞的过程称感染。转化指细菌直接摄取裸露DNA；转染指用理化方法将噬菌体DNA或外源DNA直接导入细胞。转导是噬菌体介导的细菌间基因转移，转位指转座子移位"},{"q":"胰高血糖素诱导环腺苷酸（cAMP）生成的过程是","o":["激素受体复合物使G蛋白活化，再激活腺苷酸环化酶","激素直接激活腺苷酸环化酶","激素受体复合物活化腺苷酸环化酶","激素激活受体，受体再激活腺苷酸环化酶","激素直接抑制磷酸二酯酶"],"a":0,"e":"胰高血糖素与膜受体结合成激素-受体复合物，使Gs蛋白活化，进而激活腺苷酸环化酶，催化ATP生成cAMP。激素不直接作用于环化酶，也不抑制磷酸二酯酶；受体必须经G蛋白偶联才能传递信号"},{"q":"饥饿可以使肝内哪种代谢途径增强","o":["脂肪合成","糖原合成","糖酵解","糖异生","磷酸戊糖途径"],"a":3,"e":"饥饿时血糖下降、胰岛素降低而胰高血糖素升高，肝糖原耗尽后糖异生显著增强，以氨基酸、乳酸、甘油为原料维持血糖。脂肪合成、糖原合成与糖酵解均被抑制；磷酸戊糖途径主要提供NADPH与核糖，不参与升糖"},{"q":"脂肪酸β-氧化，酮体生成及胆固醇合成的共同中间产物是","o":["MVA","乙酰乙酰辅酶A","HMG CoA","甲基二羟戊酸","乙酰乙酸"],"a":1,"e":"脂肪酸β-氧化末轮生成乙酰乙酰CoA；酮体生成中两分子乙酰CoA先缩合成乙酰乙酰CoA，再与乙酰CoA缩合为HMG-CoA；胆固醇合成中乙酰乙酰CoA亦为HMG-CoA的前体，故为三者共同中间物。HMG-CoA只见于酮体与胆固醇合成，MVA仅属胆固醇途径，乙酰乙酸仅属酮体"},{"q":"氨酰-tRNA中，tRNA与氨基酸的结合键是","o":["盐键","磷酸二酯键","肽键","糖苷键","酯键"],"a":4,"e":"氨酰-tRNA合成酶催化氨基酸的α-羧基与tRNA 3′-CCA末端腺苷酸核糖的2′-或3′-羟基脱水缩合，形成酯键，故氨基酸与tRNA以酯键相连。肽键连接的是肽链中的氨基酸残基，磷酸二酯键连接核苷酸，糖苷键连接碱基与核糖，盐键只是静电作用，均不承担此连接"},{"q":"限制性核酸内切酶切割双链DNA后产生","o":["3'磷酸基末端和5'羟基末端","5'磷酸基末端和3'羟基末端","5'羟基末端和3'羟基末端","3'磷酸基末端和5'磷酸基末端","3'羟基末端、5'羟基末端和磷酸"],"a":1,"e":"限制酶水解磷酸二酯键时，切口两侧分别留下5′-磷酸基末端与3′-羟基末端，此为DNA连接酶封口的化学基础，连接酶正是催化5′-磷酸与3′-羟基形成磷酸二酯键。3′-磷酸与5′-羟基的组合与天然切口结构不符，两端同为磷酸或羟基则无法再连接，含游离磷酸的选项混淆了水解产物"},{"q":"下列关于tRNA的叙述正确的是","o":["具有PolyA尾结构","分子量较小","三级结构形似三叶草","可携带不同的氨基酸","不含稀有碱基"],"a":1,"e":"tRNA由70～90个核苷酸组成，分子量较小，是分子量最小的核酸，故该项正确。tRNA无PolyA尾，PolyA尾为mRNA的修饰。tRNA二级结构呈三叶草形，三级结构为倒L形，选项混淆了二级与三级结构。tRNA只能携带一种特定氨基酸，且含较多稀有碱基，故其余各项错误"},{"q":"5-羟色胺的前体是","o":["胆碱","胆胺","色氨酸","酪氨酸","丝氨酸"],"a":2,"e":"5-羟色胺由色氨酸经色氨酸羟化酶羟化、再脱羧生成。胆碱是乙酰胆碱和磷脂的前体；胆胺（乙醇胺）参与磷脂合成；酪氨酸是儿茶酚胺和甲状腺激素的前体；丝氨酸参与一碳单位与磷脂合成，均非5-羟色胺的前体"},{"q":"下列关于结合胆红素的叙述，错误的是","o":["胆红素与葡糖醛酸结合","水溶性较大","易透过生物膜","可通过肾脏随尿排出","与重氮试剂呈直接反应"],"a":2,"e":"结合胆红素是胆红素与葡萄糖醛酸结合的产物，水溶性大、极性增强，不易透过细胞膜，可随胆汁入肠或经肾随尿排出，与重氮试剂呈直接反应。未结合胆红素为脂溶性，才易透过生物膜并对神经细胞产生毒性，故该项错误"},{"q":"体内产生游离NH3的主要方式","o":["转氨基作用","脱水脱氨基作用","联合脱氨基作用","腐败作用","氧化脱氨基作用"],"a":2,"e":"体内多数氨基酸通过联合脱氨基作用脱氨，即转氨基作用与L-谷氨酸氧化脱氨偶联进行，是产生游离氨的主要方式。单纯转氨基不产生游离氨，氧化脱氨基仅作用于谷氨酸，脱水脱氨基见于丝氨酸与苏氨酸，腐败作用为肠菌分解蛋白质的产物"},{"q":"目前在PCR中催化PCR反应的常用酶是","o":["反转录酶","DNA聚合酶Ⅰ","klenow片段","DNA聚合酶Ⅱ","TaqDNA聚合酶"],"a":4,"e":"PCR使用耐热的Taq DNA聚合酶，最适温度约72℃，95℃时半衰期长达40分钟，可承受变性高温。反转录酶用于cDNA合成，Klenow片段与DNA聚合酶Ⅰ不耐热，DNA聚合酶Ⅱ也不是PCR的常用酶"},{"q":"酪氨酸蛋白激酶可使蛋白质中","o":["酪氨酸残基磷酸化","丝氨酸/苏氨酸残基磷酸化","氨基酸残基去磷酸化","天冬氨酸残基酰胺化","谷氨酸残基酰胺化"],"a":0,"e":"蛋白质酪氨酸激酶催化蛋白质中酪氨酸残基的酚羟基磷酸化，是生长因子受体及非受体型酪氨酸激酶的作用方式。丝氨酸/苏氨酸残基磷酸化由PKA、PKC等催化，酰胺化修饰与磷酸化无关。受体型PTK如胰岛素受体、EGFR，非受体型如Src、JAK，催化同一类残基磷酸化"},{"q":"肝性脑病前后机体各器官有出血倾向，主要是由于","o":["维生素C少","维生素K少","维生素A少","凝血酶原少","纤维蛋白原多"],"a":1,"e":"肝细胞受损时胆汁酸合成与分泌减少，脂溶性维生素K吸收障碍，凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化不足，故有出血倾向。维生素C缺乏引起坏血病，与凝血因子羧化无关。凝血酶原减少是维生素K缺乏的结果而非原因，纤维蛋白原在肝病时多减少"},{"q":"通过蛋白激酶G（PKG）通路发挥作用的是","o":["肾上腺素","维A酸","胰高血糖素","心房钠尿肽","胰岛素"],"a":3,"e":"心房钠尿肽与膜受体结合后激活鸟苷酸环化酶，使cGMP升高并激活蛋白激酶G，引起血管舒张与钠排泄增加。肾上腺素与胰高血糖素经cAMP-蛋白激酶A通路，维A酸经核内受体，胰岛素经酪氨酸激酶受体，均不通过蛋白激酶G"},{"q":"下列有关DNA变性描述正确的是指DNA分子","o":["磷酸二酯键的断裂","糖苷键的断裂","碱基的水解","碱基间氢键的断裂","与蛋白质间的疏水键断裂"],"a":3,"e":"DNA变性是双链间碱基对氢键断裂、双螺旋解开为单链的过程，不涉及磷酸二酯键、糖苷键断裂或碱基水解。与蛋白质间的疏水键断裂不是DNA变性的本质，故正确项为碱基间氢键的断裂"},{"q":"下列有关代表性差异分析（RDA）技术的描述错误的是","o":["RDA技术是RT-PCR技术和聚丙烯胺凝胶电泳技术的结合","RDA技术是建立在核酸差异杂交基础上的PCR技术","RDA技术可检测正常和疾病组织间DNA或cDNA中的表达差异","是克隆未知疾病相关基因的常用技术方法之一","RDA技术对正常和异常DNA片段区分能力强，富集效率高，对起始材料要求低"],"a":0,"e":"代表性差异分析建立在核酸差异杂交基础上，经PCR富集差异片段，可比较正常与疾病组织间DNA或cDNA差异，用于克隆未知疾病相关基因。把RT-PCR与聚丙烯酰胺凝胶电泳结合的是mRNA差异显示技术，故A项归属错误"},{"q":"胆色素是下列哪种物质的代谢产物","o":["血红素","胆固醇","脂蛋白","胆汁酸","脂肪酸"],"a":0,"e":"胆色素是铁卟啉类化合物的分解代谢产物，主要来自衰老红细胞中血红蛋白释放的血红素，经血红素加氧酶与胆绿素还原酶催化生成胆红素。胆固醇可转变为胆汁酸与类固醇激素，胆汁酸、脂蛋白、脂肪酸均不分解生成胆色素"},{"q":"美国国家生物技术信息中心（NCBI）提供的GEO数据库，可检索到何种信息","o":["mRNA的表达水平","SNP位点","蛋白质序列","限制性片段长度多态性","STS序列"],"a":0,"e":"GEO是基因表达综合数据库，收录芯片与测序获得的基因表达谱，可检索mRNA表达水平。SNP位点见于dbSNP，蛋白质序列见于PIR和SwissProt，限制性片段长度多态性与STS序列另有专门数据库"},{"q":"下列关于酮体的叙述错误的是","o":["肝脏可以生成酮体，但不能氧化酮体","酮体是脂肪酸部分氧化分解的中间产物","合成酮体的起始物质是乙酰CoA","酮体包括β-羟丁酸","机体仅在病理情况下才产生酮体"],"a":4,"e":"酮体是脂肪酸在肝内正常代谢的中间产物，饥饿、糖供给不足时生成增多，并非只在病理状态出现，故E项错误。肝有合成酮体的酶系而无利用酮体的酶，酮体须运至肝外氧化。合成原料为乙酰CoA，产物包括乙酰乙酸、β-羟丁酸和丙酮"},{"q":"血浆中运输胆红素的载体是","o":["清蛋白","Y蛋白","Z蛋白","α-球蛋白","γ-球蛋白"],"a":0,"e":"胆红素为亲脂疏水分子，在血浆中与清蛋白结合成复合体运输，此种未结合胆红素不能经肾小球滤过。Y蛋白与Z蛋白是肝细胞内的胆红素载体，α-球蛋白与γ-球蛋白不承担此转运功能。结合后的胆红素不能自由透过细胞膜"},{"q":"容易发生磷酸化与去磷酸化的氨基酸是","o":["G1y、Ser、Val","Thr、Ser、Tyr","Ala、Ile、Leu","Phe、Thr、Val","Tyr、Val、G1y"],"a":1,"e":"蛋白激酶催化的磷酸化发生在含羟基氨基酸残基上，主要是苏氨酸、丝氨酸和酪氨酸的羟基，故为答案。甘氨酸、缬氨酸、丙氨酸、异亮氨酸、亮氨酸、苯丙氨酸侧链无可磷酸化羟基，不能作为磷酸化位点，含这些氨基酸的选项均错误"},{"q":"关于ATP合成酶正确的是","o":["它是呼吸链复合体Ⅳ的一个亚基","F0和F1都是亲水的","在F0中含有OSCP（寡霉素敏感蛋白）组分","F0中仅含有α、β和γ三种亚基","F0是H+通道"],"a":4,"e":"ATP合酶由F0与F1组成，F0疏水嵌于内膜构成H+通道，F1亲水，含α3β3γ等亚基催化ATP生成，OSCP属F1组分。ATP合酶不是呼吸链复合体Ⅳ的亚基，复合体Ⅳ为细胞色素氧化酶；α、β亚基位于F1而非F0，故其余描述不成立"},{"q":"在DNA复制中，对于引物描述正确的是","o":["提供起始模板","激活引物酶","提供复制所需的5'-磷酸","提供复制所需的3'-羟基","激活DNA pol Ⅲ"],"a":3,"e":"引物是引物酶合成的短链RNA，其3'-OH供DNA聚合酶Ⅲ添加dNTP，是子链延长的起点。引物不提供模板，模板是解开的DNA母链；引物酶负责合成引物，并非被引物激活。引物随后由DNA聚合酶Ⅰ的5'→3'外切酶活性切除，缺口由DNA片段填补"},{"q":"关于核苷酸在体内的生物学功能，描述错误的是","o":["作为核酸合成的原料","体内能量的利用形式","参与代谢和生理调节","催化生物化学反应","作为辅酶"],"a":3,"e":"核苷酸是核酸合成的原料，ATP、GTP是体内能量的利用形式，cAMP、cGMP参与代谢与生理调节，腺苷酸衍生物还构成NAD+、FAD、CoA等辅酶。催化生物化学反应是酶的功能，核苷酸本身不具催化活性，具有催化活性的是核酶"},{"q":"当培养液内色氨酸浓度较大时，色氨酸操纵子将处于","o":["诱导表达","阻遏表达","基本表达","组成表达","协调表达"],"a":1,"e":"色氨酸操纵子属可阻遏型，色氨酸作为辅阻遏物与阻遏蛋白结合后结合操纵序列，关闭结构基因表达。胞内无色氨酸时阻遏蛋白不能结合操纵序列，操纵子开放；衰减子只在翻译水平微调，不改变高浓度时的阻遏状态"},{"q":"龋齿发病率增高主要是因为缺乏","o":["铁","硒","氟","锌","钴"],"a":2,"e":"氟与羟基磷灰石结合形成氟磷灰石，增强牙釉质抗酸能力并抑制致龋菌的糖酵解，缺氟使龋齿发病率明显升高。铁缺乏致贫血，硒为谷胱甘肽过氧化物酶的组成成分，锌缺乏影响味觉与生长，钴是维生素B12的组成元素"},{"q":"通过鸟氨酸循环生成尿素时，其分子中的两个氮原子，一个直接来自游离的氮，另一个直接来源于","o":["瓜氨酸","鸟氨酸","精氨酸","甘氨酸","天冬氨酸"],"a":4,"e":"尿素分子的两个氮原子，一个来自氨甲酰磷酸中的游离氨，另一个由天冬氨酸提供，经精氨酸代琥珀酸合成酶催化进入循环。鸟氨酸与瓜氨酸是循环中的载体，精氨酸是裂解产物，甘氨酸不参与供氮"},{"q":"下列用于基因定位（DNA）和特定基因表达定位（RNA）的方法是","o":["Northern Blotting","Southern Blotting","Dot Blotting","FISH","ChIP"],"a":3,"e":"FISH以荧光标记的核酸探针与变性后的染色体或细胞核杂交，可在原位显示基因在染色体上的位置，也可检出细胞内的特异RNA，兼作DNA定位与基因表达定位。Southern印迹检测DNA、Northern印迹检测RNA，均需先提取核酸而失去原位信息；Dot印迹只做斑点杂交，ChIP分析蛋白与DNA的结合"},{"q":"酶的Km值大小与下列哪项无关","o":["酶浓度","酶结构","作用温度","底物结构","反应环境pH值"],"a":0,"e":"Km是酶的特征性常数，取决于酶的结构、底物结构以及温度、pH、离子强度等反应条件，与酶浓度无关。酶浓度只改变Vmax而不改变Km；同一酶对不同结构底物的Km可相差数十倍，故底物结构、温度、pH均与Km有关"},{"q":"蛋白质变性不包括","o":["氢键断裂","肽键断裂","盐键断裂","疏水键断裂","二硫键断裂"],"a":1,"e":"蛋白质变性只破坏空间构象，涉及氢键、盐键、疏水键及二硫键的断裂，不涉及肽键断裂，肽键断裂属于一级结构的水解。变性后理化性质改变、生物活性丧失，但一级结构保持不变，这是变性与水解的本质区别"},{"q":"联系糖、脂代谢的重要枢纽物质是","o":["丙酮酸","磷酸二羟丙酮","草酰乙酸","葡萄糖-6-磷酸","α-酮戊二酸"],"a":1,"e":"磷酸二羟丙酮是糖酵解中间产物，可还原为甘油-3-磷酸进入脂肪合成，故为联系葡萄糖代谢与脂肪代谢的枢纽。丙酮酸是三大物质代谢的交叉点，但主要通过乙酰CoA联系；草酰乙酸与α-酮戊二酸属三羧酸循环中间产物，葡萄糖-6-磷酸是糖代谢的起始磷酸酯"},{"q":"下列酶促反应，需要消耗ATP的是","o":["乙酰CoA与草酰乙酸缩合成柠檬酸","脂酰CoA转变成反Δ2烯酰CoA","丙酮酸转变成磷酸烯醇式丙酮酸","谷氨酸脱氨生成α-酮戊二酸","6-磷酸葡萄糖转变为6-磷酸葡萄糖酸"],"a":2,"e":"丙酮酸羧化生成草酰乙酸由丙酮酸羧化酶催化，以生物素为辅基并消耗1分子ATP，是糖异生的第一步。柠檬酸合酶催化的缩合反应释放硫酯键能量、不耗ATP，脂酰CoA脱氢以FAD为受氢体，谷氨酸脱氢酶辅酶为NAD+，6-磷酸葡萄糖脱氢酶以NADP+为受氢体"},{"q":"线粒体的研究是从1857年开始的，瑞士解剖学家及生理学家阿尔伯特·冯·科立克在肌肉细胞中发现了颗粒状结构。美国化学家莱昂诺尔·米歇利斯推断线粒体参与某些氧化反应。德国生物化学家奥托·海因里希·沃伯格成功完成线粒体的粗提取且分离得到一些催化与氧有关的反应的呼吸酶被授予诺贝尔生理学或医学奖。下列完全发生在线粒体中的反应是","o":["糖酵解","糖异生","磷酸戊糖途径","糖的有氧氧化","三羧酸循环"],"a":4,"e":"三羧酸循环的酶全部位于线粒体基质或内膜，从乙酰CoA与草酰乙酸缩合到草酰乙酸再生，全程在线粒体内完成。糖的有氧氧化包含细胞质中的糖酵解阶段，糖异生兼用细胞质与线粒体，糖酵解与磷酸戊糖途径均在细胞质，故完全在线粒体进行的是三羧酸循环"},{"q":"脂肪酸β-氧化中，以FAD为辅基的酶催化的反应是","o":["脂酸活化","β-羟脂酰辅酶A脱氢酶","还原不饱和脂酸","脂酰辅酶A脱氢酶","以上都不是"],"a":3,"e":"脂肪酸β氧化第一步由脂酰CoA脱氢酶催化，以FAD为辅基，生成反式烯脂酰CoA和FADH2，故为答案。脂酸活化由脂酰CoA合成酶催化并消耗ATP。β-羟脂酰CoA脱氢酶以NAD+为辅酶。还原不饱和脂酸需烯脂酰CoA还原酶并消耗NADPH"},{"q":"乳糖操纵子上Z、Y、A基因产物分别是","o":["脱氢酶、黄素酶、辅酶Q","β-半乳糖苷酶、β-半乳糖苷透性酶、乙酰转移酶","乳糖还原酶、乳糖合成酶、别构酶","葡萄糖-6-磷酸酶、变位酶、醛缩酶","乳糖酶、乳糖磷酸化酶、激酶"],"a":1,"e":"乳糖操纵子结构基因Z、Y、A分别编码β-半乳糖苷酶（水解乳糖）、β-半乳糖苷透性酶（转运乳糖）和半乳糖苷乙酰转移酶。其余选项所列的脱氢酶、黄素酶、葡萄糖-6-磷酸酶、变位酶、醛缩酶等均非乳糖操纵子的产物"},{"q":"人类基因组计划是指","o":["对所有生物基因进行定位并测序","对真核生物基因进行定位并测序","对原核生物基因进行定位并测序","对人类活性基因进行定位并测序","对人类全部基因进行定位并测序"],"a":4,"e":"人类基因组计划测绘人类基因组的遗传图、物理图并测定全部DNA序列，覆盖常染色体99%的序列。其对象为人类而非所有生物，也不限原核或真核生物；非编码区同样在测序之列，故并非只针对有活性的基因"},{"q":"线粒体DNA是","o":["环状DNA，其遗传密码与核DNA的遗传密码完全相同","环状DNA，其遗传密码与核DNA的遗传密码不完全相同","环状DNA，其遗传密码与核DNA的遗传密码完全不同","线状DNA，其遗传密码与核DNA的遗传密码完全相同","线状DNA，其遗传密码与核DNA的遗传密码不完全相同"],"a":1,"e":"线粒体DNA为闭合双链环状分子，共16569bp，编码13种多肽及22种tRNA、2种rRNA，遗传密码与核DNA不完全相同，如UGA编码色氨酸而非终止信号。其基因排列紧凑、无内含子，突变率高，呈母系遗传。线状双链与完全相同的密码系统均不符，多拷贝与母系遗传虽正确但非本题选项组合"},{"q":"人体的营养非必需氨基酸是","o":["赖氨酸","甲硫氨酸","谷氨酸","亮氨酸","缬氨酸"],"a":2,"e":"谷氨酸可由α-酮戊二酸经还原性氨基化生成，也可由其他氨基酸转氨基生成，属营养非必需氨基酸。赖氨酸、甲硫氨酸、亮氨酸、缬氨酸均为必需氨基酸，体内不能合成，须由食物供给，苏氨酸与色氨酸亦属必需"},{"q":"血红蛋白与肌红蛋白的结构，不同之处在于","o":["血红素辅基不同","α-螺旋结构不同","结合的配体不同","蛋白的空间结构不同","血红蛋白为球形，肌红蛋白为棒状结构"],"a":3,"e":"血红蛋白与肌红蛋白的血红素辅基相同、均以α-螺旋为主并可逆结合氧；关键区别在于血红蛋白是由四个亚基组成的四聚体，具四级结构和别构效应，肌红蛋白为单链单体，只有三级结构。二者均为球形蛋白，并非一球一棒"},{"q":"蛋白质多肽链合成终止的机制是","o":["已达到mRNA分子的尽头","特异的tRNA识别终止密码子","终止密码子本身具酯酶作用，可水解肽酰基与tRNA之间的酯键","释放因子能识别终止密码子并进入“受位”","终止密码子部位有较强阻力，核糖体无法沿mRNA移动"],"a":3,"e":"终止密码子不被任何氨酰tRNA识别，只有释放因子能识别并进入A位，此过程需水解GTP，触发肽酰转移酶转变为酯酶，水解肽酰-tRNA的酯键释放肽链。tRNA不识别终止密码子，终止密码子本身无酯酶活性，核糖体也并非因阻力而停止移动"},{"q":"DNA中的共价键不包括","o":["3'，5'-磷酸二酯键","β-糖苷键","磷酸-脱氧核糖的5'-OH的酯键","磷酸-脱氧核糖的2'-OH的酯键","磷酸-脱氧核糖的3'-OH的酯键"],"a":3,"e":"脱氧核糖的C2'位无羟基，不能与磷酸形成酯键，故D项不存在。DNA中核苷酸之间以3',5'-磷酸二酯键相连，碱基与脱氧核糖以β-糖苷键相连，磷酸可与脱氧核糖的3'-OH、5'-OH成酯。核糖的2'-OH成酯只见于RNA"},{"q":"下列化合物中琥珀酸脱氢酶的辅酶是","o":["生物素","FAD","NADP+","NAD+","CoASH"],"a":1,"e":"琥珀酸脱氢酶即复合体Ⅱ，以FAD为辅基，将琥珀酸脱下的氢经铁硫蛋白传给泛醌。NAD+是复合体Ⅰ的辅酶，NADP+用于还原性合成，生物素为羧化酶辅酶，CoASH参与酰基转移反应。复合体Ⅱ不泵出质子，故其电子传递产生的ATP少于复合体Ⅰ"},{"q":"糖有氧氧化，甘油氧化及磷酸戊糖途径的共同中间产物是","o":["3-磷酸甘油","3-磷酸甘油酸","磷酸二羟丙酮","3-磷酸甘油醛","丙酮酸"],"a":3,"e":"3-磷酸甘油醛是糖有氧氧化、甘油氧化（甘油→3-磷酸甘油→磷酸二羟丙酮→3-磷酸甘油醛）及磷酸戊糖途径（非氧化阶段生成）的共同中间产物。3-磷酸甘油酸、磷酸二羟丙酮、丙酮酸并非三途径共有；3-磷酸甘油只见于甘油代谢起始"},{"q":"各种蛋白质的含氮量很接近，平均为","o":["15%","16%","17%","18%","19%"],"a":1,"e":"蛋白质含氮量平均为16%，即每克氮相当于6.25克蛋白质，故测定样品含氮量可推算蛋白质含量。15%、17%、18%、19%等数值与凯氏定氮法的换算系数6.25均不对应，属常见干扰数值"},{"q":"盐析法沉淀蛋白质的原理是","o":["降低蛋白质溶液的介电常数","无机盐与蛋白质结合成不溶性的沉淀复合物","破坏蛋白质的一级结构","调节蛋白质溶液的等电点","破坏蛋白质的水化膜并中和其电荷"],"a":4,"e":"高浓度中性盐夺取蛋白质胶粒表面的水分子并中和其表面电荷，去除两个稳定因素，使蛋白质聚集沉淀，此即盐析原理。A项是加有机溶剂沉淀的机制，降低介电常数使分子间静电引力增强，与盐析不同。C项属变性，盐析不破坏一级结构，沉淀可复溶"},{"q":"蛋白质在胃内的消化主要依靠","o":["寡肽酶","二肽酶","肠激酶","胰蛋白酶","胃蛋白酶"],"a":4,"e":"胃蛋白酶原经胃酸激活为胃蛋白酶，在胃内酸性环境将蛋白质水解为多肽和少量氨基酸，是胃内消化的主力。胰蛋白酶原由肠激酶在小肠激活，作用于小肠；寡肽酶、二肽酶位于小肠刷状缘，完成寡肽的终末水解"},{"q":"下列关于双链DNA的Watson-Crick结构模型叙述正确的是","o":["碱基平面与螺旋长轴垂直","核糖平面螺旋长轴垂直","核糖位于内侧","碱基位于外侧","磷酸位于内侧"],"a":0,"e":"Watson-Crick双螺旋模型中，碱基对平面与螺旋长轴近似垂直，碱基位于内侧，脱氧核糖和磷酸骨架位于外侧。故核糖位于内侧、碱基位于外侧、磷酸位于内侧均错误；核糖平面与长轴垂直的表述也不符合，实际是碱基平面垂直"},{"q":"甲亢病人的甲状腺激素分泌增高，不出现","o":["ATP合成增多","ATP分解增快","耗氧量增多","产热增加","氧化磷酸化反应受抑制"],"a":4,"e":"甲状腺激素促进物质氧化，使耗氧量、产热增加，ATP分解与合成均增快，氧化磷酸化总体增强而非受抑制，故该现象不出现。甲状腺激素虽可使部分能量以热形式散发，但耗氧与产热增加恰说明氧化代谢活跃，氧化磷酸化受抑制不符合甲亢的代谢特点"},{"q":"大肠杆菌DNA的复制是","o":["单起始点单向复制","双起始点单向复制","单起始点双向复制","多起始点双向复制","双起始点双向复制"],"a":2,"e":"大肠杆菌染色体DNA为环状，只有一个复制起点，从该点向两个方向同时进行双向复制，故为单起始点双向复制。单起始点单向复制、双起始点均不符合原核环状DNA复制特征。多起始点双向复制为真核生物线性DNA的特点"},{"q":"生物转化第一相反应中最主要的反应是","o":["水解","还原","加成","氧化","裂合"],"a":3,"e":"第一相反应包括氧化、还原、水解，其中氧化最多见，主要由肝细胞滑面内质网的细胞色素P450单加氧酶系催化，需NADPH与O2。还原由硝基还原酶、偶氮还原酶催化，水解由酯酶、酰胺酶催化，加成与裂合不属该分类"},{"q":"蛋白质在电场中移动的方向取决于","o":["二级结构","三级结构","空间结构","等电点","电荷"],"a":4,"e":"蛋白质在电场中泳动的方向取决于其所带净电荷的性质：偏离等电点时，带负电荷者向正极移动，带正电荷者向负极移动，故由电荷决定。二级、三级等空间结构不直接决定泳动方向。等电点通过影响净电荷间接起作用，但直接决定方向的是电荷本身"},{"q":"在相同条件下，基因组突变率最低的病毒是","o":["HIV","禽流感病毒","SARS病毒","丙肝病毒","SV40"],"a":4,"e":"SV40为双链DNA病毒，复制时利用宿主高保真DNA聚合酶并具校读能力，突变率最低。HIV、丙肝病毒、SARS病毒及禽流感病毒均为RNA病毒，其RNA复制酶缺乏校读功能，突变率显著高于DNA病毒"},{"q":"下述辅助因子用于脂酸的合成的是","o":["FAD","FADH2","辅酶Ⅰ","NADPH","NADH"],"a":3,"e":"脂肪酸合成的还原步骤以NADPH为供氢体，乙酰CoA羧化为丙二酸单酰CoA亦需其参与。FAD、FADH2参与氧化脱氢，辅酶Ⅰ即NAD+主要在分解代谢中递氢，NADH供氢方向相反，均不能替代NADPH"},{"q":"乙酰辅酶A羧化酶和丙酮酸羧化酶的共同点是","o":["受柠檬酸的调节","受乙酰辅酶A的调节","辅酶都是FAD","辅酶都是CoASH","以生物素为辅基"],"a":4,"e":"两种羧化酶均以生物素为辅基，通过生物素-羧基载体形式固定并转移CO2。柠檬酸激活乙酰CoA羧化酶，乙酰CoA激活丙酮酸羧化酶，二者激活剂不同；辅基均非FAD或CoASH，不能作为共同点"},{"q":"以下有关DNA拓扑异构酶的叙述错误的是","o":["Ⅰ型DNA拓扑异构酶切开一条链，让另一条链通过切口","Ⅰ型DNA拓扑异构酶使用ATP水解释放的能量松弛负超螺旋DNA","Ⅱ型DNA拓扑异构酶一次改变连环数的值是2","Ⅰ型和Ⅱ型DNA拓扑异构酶在催化中都与DNA形成共价中间物","所有的DNA拓扑异构酶都能够催化DNA链的断裂和结合"],"a":1,"e":"Ⅰ型拓扑异构酶切开一条链、让另一条链通过切口后再连接，每次改变连环数1，全过程不需ATP；Ⅱ型即促旋酶切开双链、每次改变连环数2，需ATP供能。两类酶催化中均与DNA形成共价中间物，都能催化链的断裂与重新连接，故“使用ATP”一说不成立"},{"q":"有关疾病相关基因的克隆，下列说法错误的是","o":["人类基因组计划的完成可以促进疾病相关基因的克隆","可从疾病的表型差异出发发现疾病相关基因","在了解异常蛋白的功能以前无法克隆相关基因","可以先纯化功能异常的蛋白分子，再克隆相关基因","全基因组关联分析和全外显子测序极大地提高疾病相关基因克隆效率"],"a":2,"e":"疾病相关基因的克隆不依赖已知蛋白功能，定位克隆仅凭染色体位置即可鉴定基因，表型克隆从表型差异出发，故C项错误。人类基因组计划、全基因组关联分析和全外显子测序均提高了克隆效率，功能克隆则先纯化异常蛋白再克隆基因"},{"q":"下列叙述，不属于蛋白质组学研究的是","o":["研究蛋白的动态表达过程","研究蛋白质的共价修饰","研究蛋白质的功能","利用二维电泳/质谱技术进行蛋白质鉴定","利用磁共振技术分析蛋白质代谢产物"],"a":4,"e":"蛋白质组学研究蛋白质的表达、修饰、定位、结构与相互作用，二维电泳结合质谱是经典鉴定手段。磁共振波谱分析代谢产物属代谢组学范畴，检测的是小分子代谢物而非蛋白质；动态表达、共价修饰与功能研究均在蛋白质组学范围内"},{"q":"糖的有氧氧化的最终产物是","o":["CO2+H2O+ATP","乳酸","丙酮酸","乙酰CoA","NADH"],"a":0,"e":"糖有氧氧化经糖酵解、丙酮酸氧化脱羧和三羧酸循环，将葡萄糖彻底氧化为CO2和H2O，同时释放能量生成ATP。乳酸是糖无氧氧化的终产物，丙酮酸、乙酰CoA与NADH均为中间产物，不是最终产物"},{"q":"乙酰CoA在肝脏中的直接代谢去路，不包括","o":["还原缩合生成脂肪酸","在线粒体内彻底氧化分解生成CO2和H2O","合成胆固醇","转化为生酮氨基酸","缩合生成酮体"],"a":3,"e":"乙酰CoA在肝内可彻底氧化、羧化为丙二酰CoA合成脂肪酸、合成胆固醇和酮体，但不能转变为氨基酸。生酮氨基酸指亮氨酸与赖氨酸，只能由氨基酸分解生成乙酰CoA或乙酰乙酰CoA，该方向不可逆"},{"q":"缺铁容易引起贫血，这是由于","o":["铁离子可以促进珠蛋白的合成","铁离子可以促进亚铁螯合酶的活性","血红素合成的原料之一是Fe2+","血红素合成的原料之一是Fe3+","铁离子是ALA合酶的辅助因子"],"a":2,"e":"血红素由琥珀酰CoA、甘氨酸与Fe2+合成，缺铁使原卟啉Ⅸ不能与之结合成血红素，珠蛋白因缺乏辅基而降解，导致小细胞低色素性贫血。铁并非ALA合酶的辅因子，该酶以磷酸吡哆醛为辅酶；铁也不促进珠蛋白合成，Fe3+不能替代Fe2+"},{"q":"二酯酰甘油+NDP-胆碱→NMP+磷脂酰胆碱，此反应中，NMP代表的是","o":["AMP","CMP","TMP","GMP","UMP"],"a":1,"e":"该反应为CDP-胆碱与甘油二酯缩合生成磷脂酰胆碱，同时释出胞苷一磷酸，故NMP为CMP。胆碱活化为CDP-胆碱时消耗CTP并释出焦磷酸，AMP、GMP、UMP与TMP均不参与磷脂酰胆碱的合成"},{"q":"原核生物蛋白质生物合成需要多种酶和蛋白质因子的参与。可以占据核糖体A位，防止A位结合其他tRNA的起始因子是","o":["IF-1","IF-2","IF-3","eIF-1","eIF-2"],"a":0,"e":"IF-1占据核糖体A位，防止起始tRNA过早进入A位，保证fMet-tRNA结合于P位。IF-2促进fMet-tRNA与小亚基结合，IF-3防止大小亚基过早结合；eIF-1与eIF-2为真核起始因子"},{"q":"Ⅱ型启动子中最典型的核心元件是","o":["TATA盒","CAAT盒","GC盒","八联体元件","Pribnow盒"],"a":0,"e":"Ⅱ类启动子即RNA聚合酶Ⅱ识别的启动子，其核心元件是TATA盒，一致序列为TATA(A/T)A(A/T)，决定转录起始位点，并由TBP识别。CAAT盒与GC盒属上游启动子元件，起调节作用而非核心；八联体元件见于免疫球蛋白基因的增强子；Pribnow盒是原核-10区序列"},{"q":"下述哪步反应通过底物水平磷酸化方式生成一分子高能磷酸化合物","o":["柠檬酸→α-酮戊二酸","α-酮戊二酸→琥珀酸","琥珀酸→延胡索酸","延胡索酸→苹果酸","苹果酸→草酰乙酸"],"a":1,"e":"α-酮戊二酸氧化脱羧生成含高能硫酯键的琥珀酰CoA，后者在琥珀酰CoA合成酶催化下生成琥珀酸，同时使GDP磷酸化为GTP，属底物水平磷酸化。柠檬酸生成α-酮戊二酸、琥珀酸生成延胡索酸、延胡索酸生成苹果酸、苹果酸生成草酰乙酸均只脱氢或加水，不直接产生高能磷酸化合物"},{"q":"在嘌呤核苷酸的合成中，第4位及5位的碳原子和第7位氮原子主要来源于","o":["天冬氨酸","谷氨酸","谷氨酰胺","丙氨酸","甘氨酸"],"a":4,"e":"嘌呤环合成中甘氨酸整体掺入，提供第4、5位碳和第7位氮，故为答案。天冬氨酸提供N1，谷氨酰胺提供N3、N9，一碳单位提供C2、C8，CO2提供C6。丙氨酸不参与嘌呤环的构建"},{"q":"对致病基因的突变碱基进行纠正，这种基因治疗策略是","o":["基因矫正","基因置换","基因增补","基因失活","基因敲除"],"a":0,"e":"基因矫正指对致病基因的突变碱基进行原位纠正，不改变基因组其余结构。基因置换是以正常基因原位替换整个致病基因，基因增补为导入外源正常基因而不处理原基因，基因失活与基因敲除为抑制或破坏基因功能"},{"q":"在有氧条件下，线粒体内下述反应中能产生FADH2步骤是","o":["琥珀酸→延胡索酸","异柠檬酸→α-酮戊二酸","α-酮戊二酸→琥珀酰CoA","苹果酸→草酰乙酸","柠檬酸→α-酮戊二酸"],"a":0,"e":"琥珀酸脱氢酶以FAD为辅基，脱氢生成FADH2，是循环中唯一产生FADH2的步骤。异柠檬酸、α-酮戊二酸、苹果酸脱氢均生成NADH；柠檬酸变为α-酮戊二酸包含异柠檬酸脱氢与α-酮戊二酸脱氢两步，产物亦为NADH"},{"q":"在肿瘤的发生发展过程中，正常组织可以从增生，异型变，良性肿瘤，原位癌发展到浸润癌和转移癌。每个阶段都涉及数种基因的变化。下列哪种基因在结肠癌的晚期腺瘤阶段丢失","o":["FAP","MCC","K-RAS","DCC","NM23"],"a":4,"e":"官方答案为【NM23】，但依据教材，正确答案为【DCC】。结肠癌演进中，晚期腺瘤阶段丢失的是结肠癌缺失基因DCC，腺癌阶段为TP53缺失，转移癌阶段才涉及NM23突变。FAP与MCC的突变或缺失见于上皮过度增生阶段，K-RAS突变见于中期腺瘤，均不对应晚期腺瘤"},{"q":"针对大肠杆菌Ⅱ型拓扑异构酶的抗生素可以抑制其催化活性。这些化合物被用于治疗感染和化疗的原理是","o":["直接导致DNA片段的丢失","总是涉及同源重组","直接抑制核糖体组装","可干扰DNA复制的进行","引起DNA突变"],"a":3,"e":"Ⅱ型拓扑异构酶切开双链、改变超螺旋后再连接，复制叉前进必须依赖其解除正超螺旋与解连环，酶被抑制即使复制叉停滞、DNA断裂，故可干扰DNA复制。此类药物并不直接抑制核糖体组装，也不涉及同源重组或诱发点突变"},{"q":"关于三羧酸循环哪个是错误的","o":["是糖、脂肪及蛋白质分解的最终途径","受ATP/ADP比值的调节","NADH可激活柠檬酸合酶","NADH氧化需要线粒体穿梭系统","受ATP/AMP比值的调节"],"a":2,"e":"NADH是柠檬酸合酶的别构抑制剂而非激活剂，线粒体内NADH升高时同时抑制丙酮酸脱氢酶复合体、柠檬酸合酶和α-酮戊二酸脱氢酶复合体，使循环减慢。三羧酸循环是三大物质分解的共同途径，受ATP/ADP与ATP/AMP比值调节，胞质NADH需经穿梭系统进入线粒体氧化"},{"q":"血氨的主要来源","o":["氨基酸脱氨基作用","氨基酸在肠道细菌作用下产生","尿素在肠道细菌尿素酶水解产生","肾小管谷氨酰胺的水解","胺类的分解"],"a":0,"e":"血氨主要来自氨基酸的脱氨基作用，肝、肾、脑等组织中氨基酸经转氨基与氧化脱羧脱下氨基，是内源性氨的主要来源。肠道吸收的氨由细菌分解蛋白质及尿素产生，属外源性来源，量次之；肾小管上皮细胞分泌的氨主要来自谷氨酰胺水解，用于中和尿液中的酸；血液中游离氨本身并非来源"},{"q":"dTMP合成的直接前体是","o":["dUMP","TMP","TDP","dUDP","DCMP"],"a":0,"e":"dTMP由dUMP经胸苷酸合酶催化甲基化生成，甲基供体为N5,N10-亚甲四氢叶酸。dUDP需先脱磷酸生成dUMP，TMP是产物，dCMP经脱氨可生成dUMP但不是直接前体。胸苷酸合酶是氟尿嘧啶类抗肿瘤药物作用的靶点"},{"q":"DNA双螺旋结构中，氢键形成的因素不包括","o":["碱基中的共轭双键","碱基中的酮基或氨基","介质中的pH","酮式-烯醇式互变","氨基-亚氨基互变"],"a":0,"e":"碱基间氢键的形成依赖酮式与烯醇式、氨基与亚氨基互变所提供的供氢与受氢基团，并受介质pH影响其解离状态。碱基共轭双键决定260nm紫外吸收，与氢键的形成无关。A与T间形成两对氢键，G与C间形成三对，故GC含量高者双链更稳定"},{"q":"可定量比较正常脑组织与脑胶质瘤组织的基因表达差异的方法是","o":["LC/MS","2D-DIGE/MS","SAGE","NMR","高通量测序技术"],"a":2,"e":"SAGE（基因表达系列分析）通过计数cDNA标签定量比较不同组织或状态的基因表达差异，可用于比较正常与肿瘤组织的表达谱，故为答案。LC/MS、2D-DIGE/MS、NMR为蛋白质组学或代谢组学技术，研究蛋白或代谢物而非基因表达"},{"q":"核糖核苷酸还原酶催化的反应是","o":["ATP→dAT","GTP→dGTP","ADP→dADP","AMP→dAMP","GMP→dGMP"],"a":2,"e":"核糖核苷酸还原酶催化核糖核苷二磷酸的2′-羟基还原脱氧，生成相应的脱氧核糖核苷二磷酸，ADP→dADP即其一例，产物再磷酸化供DNA合成。ATP→dATP、GDP→dGDP、CDP→dCDP、UDP→dUDP均为其催化反应，AMP不属该酶的底物形式，需先磷酸化为ADP"},{"q":"下列关于胆红素与血浆蛋白质结合的叙述，正确的是","o":["增加其溶解度便于随尿液排出","使它易于进入细胞内储存","限制它自由地进入细胞内，避免对细胞造成毒性作用","胆红素主要与血浆中的球蛋白结合","胆红素与血浆蛋白质后即称为结合胆红素"],"a":2,"e":"游离胆红素与清蛋白结合后水溶性增加、便于运输，同时被限制自由透过细胞膜，避免对富含脂质的神经细胞造成毒性。它主要与清蛋白结合而非球蛋白；结合后仍为未结合胆红素，只有与葡萄糖醛酸结合才称结合胆红素，且不能经尿排出"},{"q":"EcoRⅠ切割DNA双链后产生","o":["平端","5'突出黏端","3'突出黏端","钝性末端","配伍末端"],"a":1,"e":"EcoRⅠ识别GAATTC，在G与A之间交错切割双链，产生5′-端突出的黏性末端。平端（钝性末端）由SmaⅠ等切割产生，3′突出黏端见于PstⅠ，配伍末端指不同酶切出相同黏端的现象，并非EcoRⅠ的产物形式"},{"q":"关于单加氧酶系在生物转化中作用的叙述，哪项有错误","o":["单加氧酶系是一个复合物","又称羟化酶","它所催化反应中一个氧分子发挥两种功能，故又称为混合功能氧化酶","此酶系特异性较差，可催化多种底物","该酶的羟化作用可降低非营养物质的水溶性"],"a":4,"e":"单加氧酶系（羟化酶、混合功能氧化酶）催化羟化反应，向非营养物质引入羟基，通常提高其水溶性以利排泄，故降低水溶性的说法错误。该酶系为复合物，一个氧分子的一个原子掺入底物、另一个还原成水，故称混合功能氧化酶；其特异性差，可催化多种底物"},{"q":"恶性肿瘤可以破坏组织、器官的结构和功能，引起坏死出血合并感染，患者最终可能由于器官功能衰竭而死亡。肿瘤发生的分子基础中，下列哪项不正确","o":["肿瘤发生的本质系细胞生长/增殖失去了控制","多因素所致（物理、化学、病毒等）","多步骤、长期演化的结果","多基因累积突变","原癌基因不是维持机体正常生命活动所必需的"],"a":4,"e":"原癌基因是正常细胞维持生长、增殖与分化所必需的基因，产物参与信号转导与细胞周期调控，只有突变、扩增或过表达后才具致癌性，故该说法错误。肿瘤本质是细胞增殖失去控制，由物理、化学、病毒等多因素、多步骤、多基因突变长期累积而成"},{"q":"下列哪一个氨基酸为必需氨基酸","o":["苯丙氨酸","半胱氨酸","胱氨酸","谷氨酸","精氨酸"],"a":0,"e":"人体不能合成、必须由食物提供的氨基酸为必需氨基酸，共9种，包括苯丙氨酸、亮氨酸、异亮氨酸、苏氨酸、缬氨酸、赖氨酸、甲硫氨酸、色氨酸和组氨酸。谷氨酸可由α-酮戊二酸氨基化生成，属非必需。半胱氨酸由甲硫氨酸转变，精氨酸体内可合成但量少，两者均非必需"},{"q":"DNA变性时会导致","o":["溶液黏度升高","浮力密度降低","260nm处的吸光度增加","易被蛋白酶降解","分子量降低"],"a":2,"e":"DNA变性时双链解开为单链，碱基暴露使260nm紫外吸光度增高，称增色效应，故为答案。变性后黏度下降而非升高，浮力密度升高而非降低。变性只改变空间构象、不涉及共价键断裂，分子量不变，也不更易被蛋白酶降解"},{"q":"线粒体DNA的复制","o":["采用滚环式复制","采用D环复制模式","两条亲代双链同时复制","两条亲代双链在同一起点复制","前导链与后随链同时合成"],"a":1,"e":"线粒体DNA为环状双链，其复制采用D环（置换环）模式：两条链不同时复制，先以一条链为模板合成新链形成D环，再合成另一条链，故为答案。滚环复制见于某些噬菌体与质粒。两条亲代链同时复制、同一起点复制、前导链后随链同时合成均为其他复制方式的特征"},{"q":"合成软脂酸时需要的原料是","o":["8分子乙酰辅酶A","8分子乙酰辅酶A和1分子丙二酰辅酶A","7分子乙酰辅酶A和1分子丙二酰辅酶A","7分子丙二酰辅酶A和1分子乙酰辅酶A","8分子丙二酰辅酶A"],"a":3,"e":"软脂酸含16碳，合成时以1分子乙酰CoA为起始引物，再经7次循环每次加1个丙二酰CoA（各提供2碳），共需7分子丙二酰CoA和1分子乙酰CoA，故为答案。其余选项未按乙酰CoA引物与丙二酰CoA延长的实际计数，均不正确"},{"q":"下列属于多不饱和脂肪酸的是","o":["油酸、软脂酸","软脂酸、亚油酸","亚油酸、亚麻酸","油酸、亚油酸","硬脂酸、花生四烯酸"],"a":2,"e":"亚油酸与α-亚麻酸含两个以上双键，属多不饱和脂肪酸，且为人体必需脂肪酸。油酸是单不饱和脂肪酸，软脂酸与硬脂酸为饱和脂肪酸；花生四烯酸虽为多不饱和，但与硬脂酸并列的选项不成立。必需脂肪酸为亚油酸与α-亚麻酸，花生四烯酸可由亚油酸合成"},{"q":"当脂肪酸β氧化在肝脏中为主时，线粒体中的丙酮酸很可能","o":["氧化脱羧成为乙酰辅酶A进而生成酮体","氧化脱羧成为乙酰辅酶A进入三羧酸循环","还原为乳酸进而异生成糖","羧化为磷酸烯醇丙酮酸进而异生成糖","羧化为草酰乙酸进而异生成糖"],"a":4,"e":"脂肪酸β-氧化为主时乙酰CoA增多，别构激活丙酮酸羧化酶，丙酮酸羧化为草酰乙酸，经苹果酸运出线粒体后异生为糖。乙酰CoA增多反抑制丙酮酸脱氢酶，故不走氧化脱羧生成酮体；还原为乳酸需缺氧条件"},{"q":"变性蛋白质的特性，描述错误的是","o":["生物活性丧失","一级结构未改变","空间结构被破坏","260nm的吸光值显著增加","加热、酸碱、有机溶剂是常见的变性因素"],"a":3,"e":"蛋白质变性时空间构象破坏，埋藏在分子内部的芳香族氨基酸残基暴露，280nm紫外吸收增强并出现增色效应，黏度增加、溶解度降低、结晶能力丧失，生物学活性丧失而一级结构不变。260nm是核酸的紫外吸收峰，蛋白质在此波长吸收很弱，故“260nm吸光值显著增加”属张冠李戴"},{"q":"在细胞质中合成脂肪酸的限速酶是","o":["β-酮脂酰合成酶","水化酶","乙酰CoA羧化酶","脂酰转移酶","β-酮脂酰还原酶"],"a":2,"e":"乙酰CoA羧化酶催化乙酰CoA羧化为丙二酰CoA，是脂肪酸合成的限速酶，受柠檬酸别构激活、长链脂酰CoA抑制，并受磷酸化修饰调节。β-酮脂酰合成酶、水化酶、β-酮脂酰还原酶均为脂肪酸合酶复合体的催化组分，脂酰转移酶负责脂酰基转移"},{"q":"δ-氨基-γ-酮基戊酸（ALA）合成酶的辅基中含","o":["维生素B1","维生素B2","维生素B6","维生素B12","维生素PP"],"a":2,"e":"ALA合酶以磷酸吡哆醛为辅基，即维生素B6的活性形式，催化琥珀酰CoA与甘氨酸缩合生成ALA，是血红素合成的限速步骤。维生素B1为TPP，参与α-酮酸脱羧；维生素B2构成FMN、FAD；维生素B12为钴胺素，参与甲基转移"},{"q":"研究蛋白质相互作用的方法包括","o":["SDS-聚丙烯酰胺凝胶电泳","免疫共沉淀","琼脂糖凝胶电泳","蛋白质的紫外分光光度技术","免疫组化"],"a":1,"e":"免疫共沉淀用抗体沉淀靶蛋白，同时捕获与之结合的蛋白，是研究体内蛋白质相互作用的经典方法。SDS-PAGE与琼脂糖电泳仅按分子大小分离，紫外分光光度法用于定量，免疫组化用于组织定位"},{"q":"胆固醇在体内代谢的主要去路是","o":["构成脂蛋白","构成生物膜","转变为胆汁酸","从肠道排出","转变为类固醇激素"],"a":2,"e":"胆固醇主要在肝经7α-羟化酶催化转变为胆汁酸，这是其在体内代谢排泄的主要去路，胆汁酸随胆汁排入肠道后大部分被重吸收。构成生物膜与构成脂蛋白只是胆固醇的结构或运输形式，并非代谢去路；转变为类固醇激素仅占少量；从肠道排出的主要是胆汁酸及其代谢产物，而非胆固醇本身"},{"q":"体内氨基酸代谢库中，游离的氨基酸的主要去路是","o":["合成胺类","合成蛋白质","分解产生能量","参与许多含氮物质的合成","脱去氨基生成相应的α-酮酸"],"a":1,"e":"氨基酸最主要的去路是合成蛋白质或多肽，用于组织蛋白更新、修复及细胞增殖，占摄取氨基酸的大部分。合成胺类与参与含氮化合物合成量少，脱氨基生成α-酮酸后主要进入三羧酸循环氧化供能，属分解去路而非主要去路"},{"q":"酶促反应中决定酶特异性的是","o":["酶蛋白","酶作用物的类别","辅基或辅酶","催化基团","金属离子"],"a":0,"e":"结合酶中酶蛋白决定反应的特异性及催化机制，辅因子决定反应类型，二者单独存在时均无活性。底物类别只是被作用对象，不决定酶的特异识别。金属离子与辅基、辅酶同属辅因子范畴，本身不决定特异性"},{"q":"在呼吸链中，将复合物Ⅰ和复合物Ⅱ与细胞色素系统连接的物质是","o":["FMN","Fe-S蛋白","CoQ","Cyt b","Cyt a"],"a":2,"e":"CoQ为脂溶性醌类，能在复合体Ⅰ、Ⅱ与复合体Ⅲ之间接受并传递电子，把两条入链与细胞色素系统连接起来。FMN是复合体Ⅰ的辅基，铁硫蛋白参与复合体内电子传递，Cyt b位于复合体Ⅲ、Cyt a位于复合体Ⅳ，均不能承接复合体Ⅱ的电子"},{"q":"与受体型酪氨酸蛋白激酶（RTK）信号转导途径有关的物质是","o":["IP3","Ca2+","JAK","Raf","热休克蛋白"],"a":3,"e":"RTK与配体结合后自磷酸化，经Grb2-SOS激活Ras，Ras再招募Raf即MAPKKK，启动Raf-MEK-ERK级联，故Raf属该通路成员。JAK参与细胞因子受体通路，IP3与Ca2+为G蛋白偶联受体下游信使，热休克蛋白属分子伴侣"},{"q":"天然蛋白质中不存在的氨基酸是","o":["半胱氨酸","瓜氨酸","丝氨酸","色氨酸","丙氨酸"],"a":1,"e":"瓜氨酸是尿素合成中的中间产物，以游离形式存在而不参与蛋白质合成，故不属天然蛋白质的氨基酸。半胱氨酸、丝氨酸、色氨酸、丙氨酸均为组成蛋白质的20种标准氨基酸，鸟氨酸与精氨酸代琥珀酸同样不参与蛋白质合成，常与本项一并设错"},{"q":"载脂蛋白B（apo B）是乳糜微粒和低密度脂蛋白（LDL）的必需成分，在脂类代谢、胆固醇转运过程中起关键作用。载脂蛋白B分为apo B100和apo B48。二者是同一基因不同转录模式的产物。Apo B100 mRNA第6666位上的C变成U，此处编码谷氨酰胺的CAA密码子变成UAA终止密码子，导致截短的apo B48生成。这一过程是真核生物前体mRNA加工中的哪一种加工方式","o":["剪接","碱基修饰","选择性加工","RNA编辑","自我剪接"],"a":3,"e":"载脂蛋白B mRNA中特定胞嘧啶脱氨基转变为尿嘧啶，使谷氨酰胺密码子CAA变为终止密码子UAA，生成截短的apoB48，这种转录后碱基改变属于RNA编辑。剪接是去除内含子连接外显子，选择性加工为不同剪接方式，自我剪接为内含子自催化，碱基修饰泛指甲基化等，均非此类C→U转变"},{"q":"下列哪个物质可激活蛋白激酶A（PKA）","o":["GMP","cGMP","cAMP","AMP","ATP"],"a":2,"e":"cAMP与蛋白激酶A的调节亚基结合，使催化亚基释放而激活，是cAMP-蛋白激酶A途径的核心步骤。cGMP激活的是蛋白激酶G，AMP与GMP为核苷一磷酸无此作用，ATP是磷酸供体而非PKA的激活剂"},{"q":"采用定位克隆策略鉴定的第一个疾病相关基因是","o":["假肥大型肌营养不良基因","X-连锁慢性肉芽肿病基因","马方综合征基因","苯丙酮尿症基因","白化病基因"],"a":1,"e":"定位克隆先经家系连锁分析将致病位点定位于染色体区段，再逐步克隆候选基因，第一个以此策略鉴定的疾病相关基因是X连锁慢性肉芽肿病基因。假肥大型肌营养不良、马方综合征、苯丙酮尿症等基因的克隆均晚于该基因，白化病基因亦为后续工作"},{"q":"关于继发性痛风导致血中尿酸升高的情况，描述不正确的是","o":["与进食高嘌呤食物无关","体内核酸大量分解时（如恶性肿瘤）","肾功能不全导致尿酸排泄障碍时","临床常用别嘌呤醇进行治疗","尿酸盐结晶的沉积会导致关节和软组织的病变"],"a":0,"e":"继发性痛风继发于核酸分解增强的疾病，如白血病、多发性骨髓瘤、真性红细胞增多症及肿瘤化疗后，细胞大量破坏使嘌呤分解增多，尿酸生成增加。高嘌呤饮食、酒精摄入会进一步升高血尿酸；肾排泄减少也是常见诱因，故“与进食高嘌呤食物无关”之说不成立"},{"q":"糖尿病是由于什么原因所引起","o":["血糖浓度过高","糖代谢异常","糖异生异常","糖原合成异常","糖原分解异常"],"a":1,"e":"糖尿病以胰岛素分泌不足或作用障碍为根本，表现为糖、脂肪、蛋白质代谢的全面紊乱，糖代谢异常是其核心环节，涵盖糖的氧化、储存与异生各环节。血糖浓度过高是代谢紊乱的结果而非原因。糖异生异常、糖原合成异常、糖原分解异常都只是糖代谢异常的局部表现"},{"q":"与pCAGCT互补的DNA序列是","o":["pAGCTG","pGTCGA","pGUCGA","pAGCUG","pAGCCG"],"a":0,"e":"按碱基互补配对A-T、G-C，pCAGCT的互补链反向书写为pGTCGA，改按5'→3'方向书写即pAGCTG，故为答案。pGTCGA为3'→5'方向的写法，方向不符。含U的pGUCGA、pAGCUG为RNA序列，非DNA。pAGCCG碱基配对错误"},{"q":"下列关于物质代谢特点的描述，错误的是","o":["物质代谢的方向、速度和强度受到精细调节","代谢池中的内源性和外源性物质代谢途径不同","各种物质的代谢是相互联系的","不同的生理状态下，物质的代谢速度和方向可能改变","进入体内的能源物质超过需要，可以以脂肪形式储存"],"a":1,"e":"内源性与外源性物质进入同一代谢池，不分彼此，按机体需要进入相同代谢途径，故B项错误。物质代谢受精细调节，不同生理状态下速度与方向可改变，各物质代谢相互联系，多余能源物质以脂肪形式储存"},{"q":"基因表达过程中仅在原核生物中出现而并不出现在真核生物的是","o":["tRNA的稀有碱基","σ因子","冈崎片段","DNA连接酶","起始密码子AUG"],"a":1,"e":"σ因子为原核生物RNA聚合酶识别启动子的辅助因子，转录起始后即脱离，真核生物由通用转录因子承担类似功能而无σ因子，故仅见于原核。tRNA稀有碱基在真核与原核均存在。冈崎片段在两者DNA复制中均出现。DNA连接酶两者均有。起始密码子AUG为蛋白质合成共用"},{"q":"临床上自毁容貌征，是由于","o":["腺嘌呤磷酸核糖转移酶缺陷","次黄嘌呤脱氢酶缺陷","次黄嘌呤-鸟嘌呤磷酸核糖转移酶缺陷","鸟嘌呤合成酶缺陷","PRPP合成酶缺陷"],"a":2,"e":"自毁容貌征即Lesch-Nyhan综合征，由次黄嘌呤-鸟嘌呤磷酸核糖转移酶缺陷引起，嘌呤补救合成障碍，PRPP堆积使从头合成增强，尿酸生成过多并伴神经系统症状。APRT缺陷致尿路结石，PRPP合成酶活性增强亦致高尿酸血症但无自残表现"},{"q":"SOX9是调控软骨细胞增殖与分化的重要转录因子之一。现发现某一蛋白质的表达可以显著降低SOX9的表达，SOX9的表达不影响该蛋白的表达。下列哪种方法可以确定该蛋白是否直接通过调控SOX9的转录影响其表达的","o":["染色体免疫共沉淀（ChIP）","原位杂交（ISH）","染色体构象捕获（3C）","启动子活性检测","酵母双杂交"],"a":0,"e":"染色质免疫沉淀用特异性抗体沉淀蛋白质-DNA复合物，再经测序确定该蛋白结合的DNA序列，可直接证明它是否结合于SOX9启动子区。原位杂交检测核酸定位，3C研究染色质空间构象，启动子活性检测不能确定结合蛋白身份，酵母双杂交检测蛋白间相互作用"},{"q":"肝脏在物质代谢中的作用，哪项不正确","o":["肝脏是维持血糖水平稳定的重要器官","肝脏是酮体生成的主要器官","肝脏可以进行生物转化作用","维生素D3转变成1-OH-D3","肝脏可以合成胆汁酸"],"a":3,"e":"肝只把维生素D3羟化为25-羟维生素D3，1α-羟化在肾小管上皮细胞线粒体由1α-羟化酶完成，故该项不属肝的作用。肝是血糖调节、酮体生成、生物转化与胆汁酸合成的核心器官，糖原合成与分解、糖异生均在肝内进行"},{"q":"关于β-氨基异丁酸，叙述错误的是","o":["是胸腺嘧啶的分解产物","食入含DNA丰富的食物时，尿中排出会增多","肿瘤病人放化疗时，尿中排出会增多","是尿嘧啶的分解产物","可直接随尿排出或者进一步分解"],"a":3,"e":"β-氨基异丁酸是胸腺嘧啶的分解产物；尿嘧啶分解生成β-丙氨酸、NH3和CO2。食入DNA丰富的食物或肿瘤放化疗致细胞破坏增多时，胸腺嘧啶分解加强，尿中排出增多；该产物水溶性好，可随尿排出或进一步分解。故其并非尿嘧啶的分解产物"},{"q":"蛋白激酶A（PKA）中的每个调节亚基可结合环腺苷酸（cAMP）的分子数为","o":["2个","3个","4个","5个","6个"],"a":0,"e":"PKA由2个调节亚基和2个催化亚基组成四聚体，每个调节亚基可结合2个cAMP，全酶共结合4个cAMP后释放催化亚基，故每个调节亚基结合2个。3、5、6个均无对应结构基础，4个为全酶结合总量而非单个调节亚基"},{"q":"蛋白激酶A（PKA）所含亚基数为","o":["1","2","3","4","5"],"a":3,"e":"蛋白激酶A由2个调节亚基和2个催化亚基组成，共4个亚基，形成R2C2四聚体；cAMP结合调节亚基后释放催化亚基发挥活性。1、2、3、5个亚基均不符合其四聚体结构"},{"q":"某有机化合物，是合成脂肪酸、胆固醇、柠檬酸的原料，但不是糖异生的原料。该物质最可能是","o":["1,3-二磷酸甘油酸","丙酮酸","苹果酸","乙酰辅酶A","草酰乙酸"],"a":3,"e":"乙酰CoA是合成脂肪酸、胆固醇的碳源，也是柠檬酸合成的原料；丙酮酸羧化酶反应不可逆，乙酰CoA不能净生成丙酮酸，故不是糖异生原料。丙酮酸、苹果酸、草酰乙酸、1,3-二磷酸甘油酸均可异生为糖"},{"q":"能够合成酮体的器官是","o":["骨骼肌","脑","心","肝","肾"],"a":3,"e":"酮体在肝线粒体由酮体合成酶系生成，肝缺乏琥珀酰CoA转硫酶等利用酮体的酶，只能生成不能利用，故酮体经血运至肝外组织氧化。骨骼肌、脑、心、肾均含酮体利用酶，是酮体的消耗器官。肝内生成的酮体须经血液运输至肝外，才能被氧化利用"},{"q":"下列物质中，人体不能消化的是","o":["果糖","蔗糖","乳糖","纤维素","糖原"],"a":3,"e":"人体缺乏β-葡萄糖苷酶，不能水解纤维素的β-1,4-糖苷键，故不能消化利用。蔗糖、乳糖、糖原均可被相应酶水解为单糖后吸收，果糖为单糖可直接吸收。纤维素虽不供能，但可刺激肠蠕动、维持肠道健康"},{"q":"提出DNA双螺旋结构最直接的科学证据是","o":["Chargaff规则","特定组织的DNA，嘧啶和嘌呤克分子数的等量关系","X线衍射图","A=T，G=C","在电镜下观察到了双螺旋结构"],"a":2,"e":"DNA双螺旋结构的提出最直接依赖X线衍射图，揭示螺旋的周期性参数，故为答案。Chargaff规则及A=T、G=C的碱基等量关系为碱基配对提供了化学依据，但非直接结构证据。电镜受分辨率限制，当时无法直接观察到双螺旋结构"},{"q":"关于生长因子的叙述中，正确的是","o":["属于类固醇激素的一种","是调节细胞生长增殖的多肽类物质","是细胞内信息物质","化学本质是氨基酸及其衍生物","化学本质是脂酸衍生物"],"a":1,"e":"生长因子是一类调节细胞生长与增殖的多肽类物质，通过与靶细胞膜受体结合及信号转导发挥促进或抑制作用。类固醇激素属脂溶性甾体，化学本质与生长因子不同；生长因子多分泌至胞外经膜受体起作用，并非细胞内信息物质；其本质是多肽，既不是游离氨基酸及其衍生物，也不是脂酸衍生物"},{"q":"胃幽门部黏膜病变可导致缺乏的维生素是","o":["维生素A","维生素E","维生素C","维生素B6","维生素B12"],"a":4,"e":"胃壁细胞分泌内因子，幽门部黏膜病变或胃大部切除使内因子缺乏，维生素B12不能在回肠末端吸收，导致巨幼细胞贫血。维生素A、E为脂溶性维生素随脂类吸收，维生素C在小肠上段主动转运吸收，维生素B6吸收均不依赖内因子"},{"q":"蛋白质的α-螺旋结构，每上升一圈需要的氨基酸残基数目是","o":["2、5","2、7","3","3、6","4、5"],"a":3,"e":"α-螺旋中主链绕中心轴右手盘绕，每3.6个氨基酸残基上升一圈，螺距0.54nm，每个残基沿轴上升0.15nm，侧链伸向螺旋外侧。2.5、2.7、3.0、4.5均与实测不符，3.0常与310螺旋混淆，4.5是把每圈残基数与螺距数值混用"},{"q":"糖酵解过程中催化1mol六碳糖裂解为2mol三碳糖的反应的酶是","o":["磷酸己糖异构酶","6-磷酸果糖激酶-1","醛缩酶","磷酸丙糖异构酶","烯醇化酶"],"a":2,"e":"醛缩酶催化果糖-1,6-二磷酸裂解为磷酸二羟丙酮和3-磷酸甘油醛，实现六碳糖到三碳糖的转变，故为答案。磷酸己糖异构酶催化葡萄糖-6-磷酸与果糖-6-磷酸互变。6-磷酸果糖激酶-1为糖酵解限速酶，催化产生果糖-1,6-二磷酸。磷酸丙糖异构酶催化两种三碳糖互变。烯醇化酶催化脱水反应"},{"q":"可磷酸化蛋白质上酪氨酸残基的蛋白激酶是","o":["蛋白激酶C","依赖于cAMP的蛋白激酶","依赖于cGMP的蛋白激酶","Src蛋白激酶","磷酸化酶b激酶"],"a":3,"e":"Src属非受体型蛋白质酪氨酸激酶，可磷酸化底物蛋白的酪氨酸残基，其SH2结构域识别含磷酸化酪氨酸的模体。蛋白激酶C、PKA、PKG及磷酸化酶b激酶均属丝氨酸/苏氨酸激酶，作用于Ser或Thr残基，不磷酸化酪氨酸"},{"q":"N-连接型聚糖合成所必需的物质或步骤不包括","o":["单糖活化为UDP或GDP的衍生物","糖基转移酶","长萜醇","高尔基体内糖链加工成熟","细胞核内糖链加工"],"a":4,"e":"N-连接型聚糖合成需单糖活化为UDP或GDP衍生物、糖基转移酶催化、长萜醇作糖链载体，并在内质网和高尔基体内完成修剪与加工。加工场所只在内质网与高尔基体，细胞核内不进行糖链加工，故该项不属其必需步骤。O-连接型聚糖不需长萜醇载体，是两者的重要区别"},{"q":"通常与G蛋白偶联的受体含有的跨膜螺旋的数目为","o":["5个","6个","7个","8个","9个"],"a":2,"e":"G蛋白偶联受体为单体蛋白，肽链反复跨膜七次，故称七次跨膜受体，胞内环与异源三聚体G蛋白结合。离子通道受体由4个跨膜区段的亚基围成孔道，酶偶联受体多为1个跨膜区段。三类膜受体的跨膜次数不同，是区分依据"},{"q":"以下选项中属于癌基因的是","o":["Rb","p53","p16","APC/MCC","C-MYC"],"a":4,"e":"C-MYC属MYC家族转录因子基因，在淋巴瘤中因LTR插入、基因扩增或染色体易位而过度表达，属原癌基因。Rb、p53、p16与APC/MCC均为抑癌基因，须失活或缺失才促进肿瘤发生，与原癌基因激活方向相反"},{"q":"大鼠出生后饲以去脂膳食，结果将引起脂质缺乏的是","o":["磷脂酰胆碱","甘油三酯","胆固醇","鞘磷脂","前列腺素"],"a":4,"e":"必需脂肪酸是前列腺素合成的前体来源，去脂膳食使亚油酸缺乏，花生四烯酸不足，前列腺素生成减少。前列腺素、血栓烷与白三烯均为廿碳多不饱和脂肪酸衍生物，更新快、需持续合成。磷脂酰胆碱、甘油三酯、胆固醇、鞘磷脂均可由糖及非必需脂肪酸合成"},{"q":"下列对葡萄糖有氧氧化和脂肪酸β-氧化的比较中，错误的是","o":["酶系均存在线粒体和细胞质中","乙酰辅酶A为二者的共同中间产物","三羧酸循环为共有的代谢途径","肝脏主要通过葡萄糖有氧氧化功能","单位重量葡萄糖氧化产能少于单位重量脂肪酸氧化"],"a":3,"e":"肝主要通过脂肪酸β-氧化供能，并将乙酰CoA合成酮体输出肝外，葡萄糖有氧氧化并非其唯一或主要供能方式，故D项错误。两条途径的酶系均分布于线粒体与胞质，乙酰CoA为共同中间产物，都汇入三羧酸循环。单位重量脂肪酸产能高于葡萄糖"},{"q":"印迹技术的操作程序是","o":["电泳→转移→杂交→显色","杂交→电泳→转移→显色","电泳→显色→转移→杂交","转移→电泳→杂交→显色","电泳→显色→杂交→转移"],"a":0,"e":"印迹法先经凝胶电泳按分子大小分离待测分子，再转移并固定于硝酸纤维素膜等固相介质，然后与标记探针杂交，最后显色或显影检测。其余顺序颠倒，未经分离即转移、或先显色后杂交均不能成立"},{"q":"苹果酸穿梭作用的生理意义在于","o":["将草酰乙酸带人线粒体彻底氧化","维持线粒体内外有机酸的平衡","进行谷氨酸、草酰乙酸转氨基作用","为三羧酸循环提供足够的草酰乙酸","将细胞质中NADH+H+的2H带入线粒体内"],"a":4,"e":"胞质NADH经苹果酸-天冬氨酸穿梭：草酰乙酸受氢生成苹果酸进入线粒体基质，再脱氢生成草酰乙酸并释放NADH，进入NADH呼吸链氧化，实现还原当量的跨膜转移。草酰乙酸不能透过内膜，须转为天冬氨酸返回胞质。D项所述草酰乙酸供应属三羧酸循环的调节问题，与穿梭无关"},{"q":"都含铁卟啉的两种物质是","o":["铁硫蛋白和血红蛋白","过氧化物酶和过氧化氢酶","细胞色素C氧化酶和乳酸脱氧酶","过氧化物酶和琥珀酸脱氢酶","细胞色素b和乳酸脱氢酶"],"a":1,"e":"过氧化物酶与过氧化氢酶均以铁卟啉为辅基，属含铁卟啉的酶类。铁硫蛋白含非铁卟啉的铁硫簇，乳酸脱氢酶以NAD+为辅酶、不含铁，琥珀酸脱氢酶以FAD和铁硫簇为辅基，三者均不具铁卟啉结构"},{"q":"由肌肉组织通过血液向肝进行转运的过程是","o":["三羧酸循环","鸟氨酸循环","甲硫氨酸循环","γ-谷氨酰基循环","丙氨酸-葡萄糖循环"],"a":4,"e":"骨骼肌以丙酮酸为氨基受体，转氨基生成丙氨酸，随血运至肝，肝内脱氨后丙酮酸异生为葡萄糖，葡萄糖再回肌肉，构成丙氨酸-葡萄糖循环。鸟氨酸循环在肝合成尿素，甲硫氨酸循环提供活性甲基，γ-谷氨酰基循环参与氨基酸转运"},{"q":"原癌基因是","o":["抑制细胞过度生长和增殖的基因","体外引起细胞转化的基因","存在于正常细胞基因组中的癌基因","突变的p53基因","携带有转导基因的病毒癌基因"],"a":2,"e":"原癌基因是正常细胞基因组中固有的基因，参与调控细胞生长增殖，在理化因素作用下激活或过度表达才转化为癌基因，故为存在于正常细胞基因组中的癌基因。抑制细胞过度增殖的是抑癌基因。体外引起细胞转化是癌基因激活后的功能表现，突变的p53属抑癌基因失活，携带转导基因的病毒癌基因来自病毒，均与原癌基因定义不符"},{"q":"下列关于DNA变性描述正确的是","o":["DNA变性时糖苷键断裂","磷酸二酯键断裂","解链温度的最高点称为Tm","A260nm降低","双链间氢键被破坏"],"a":4,"e":"DNA变性是双链互补碱基间的氢键断裂、碱基堆积力被破坏，双链解离为单链，260nm吸光度升高即增色效应。变性不涉及糖苷键与磷酸二酯键的断裂，Tm是解链一半时的温度而非最高点，故其余各项描述均错误"},{"q":"PCR引物设计时，不需要考虑","o":["模板的GC含量","引物的GC含量","引物之间互补","引物长度","引物内部互补"],"a":0,"e":"引物设计需考虑引物长度、引物自身及引物间的互补情况、引物GC含量与Tm值，以避免二聚体和发夹结构。模板的GC含量影响解链温度与变性时间，属反应条件设置，不是引物设计本身的要求"},{"q":"启动子捕获技术（promoter trapping）的原理是","o":["双荧光素酶报告基因","染色体免疫沉淀","基因表达的定量","电泳迁移率变动实验","PCR克隆"],"a":0,"e":"启动子捕获将无自身启动子的报告基因载体随机整合入基因组，若插入到内源启动子附近则报告基因被激活表达，据此筛选启动子，双荧光素酶报告基因系统以荧光信号反映启动子活性，故为答案。染色体免疫沉淀检测蛋白-DNA结合，电泳迁移率变动实验检测蛋白-DNA相互作用，PCR克隆用于扩增片段"},{"q":"核酸分子杂交是分子生物学常用的实验技术，下面哪种技术不涉及核酸杂交","o":["Southern印迹杂交","Northern印迹杂交","PCR扩增","斑点印迹","琼脂糖凝胶电泳"],"a":4,"e":"琼脂糖凝胶电泳仅按分子大小分离核酸片段，依靠电荷与分子筛效应，全程无探针与靶序列的互补配对。Southern、Northern与斑点印迹均需标记探针杂交；PCR靠引物与模板互补延伸，属扩增而非杂交检测"},{"q":"STS（sequence-tagged site）是指","o":["指人类基因组中长度2～6bp的串联重复序列","指人类基因组中长度约200～600bp的单拷贝片段","指人类基因组中长度约20～60bp的单拷贝片段","指人类基因组中长度约2～6bp的反向串联重复序列","指人类基因组中长度随机的片段"],"a":1,"e":"序列标签位点是基因组中长度约200～600bp的单拷贝特异片段，序列已知且在基因组中唯一，可作为染色体定位的标记。2～6bp串联重复属微卫星DNA，20～60bp为短串联重复，随机片段无定位价值"},{"q":"促甲状腺素发挥作用时，其第二信使是","o":["cCMP","cGMP","cAMP","cUMP","AMP"],"a":2,"e":"促甲状腺素与甲状腺滤泡细胞膜受体结合，经Gs激活腺苷酸环化酶，cAMP升高并激活PKA，促进甲状腺激素合成与释放。cGMP介导心房钠尿肽信号，AMP、cUMP与cCMP均非第二信使"},{"q":"蛋白质分子一定具有","o":["α-螺旋","β-折叠","三级结构","四级结构","亚基"],"a":2,"e":"任何有功能的多肽链都必须折叠成特定三级结构，故蛋白质一定具有三级结构。α-螺旋与β-折叠并非所有蛋白质都具备，四级结构仅见于两条以上肽链组成的蛋白质，亚基是四级结构的组成单位，单个亚基单独存在时功能常与聚合体不同"},{"q":"下列关于肽键的叙述，错误的是","o":["肽键属于一级结构","肽键中C-N键所连的四个原子处于同一平面","肽键具有部分双键性质","肽键旋转而形成了β-折叠","肽键中的C-N键长度比N-Cα单键短"],"a":3,"e":"肽键因具有部分双键性质而不能自由旋转，β-折叠是由Cα—C和N—Cα单键旋转形成的二级结构，故该项叙述错误。肽键属于一级结构的基本连接键；其C、O、N、H及相邻Cα共处于同一平面，C—N键长约0.132nm，短于N—Cα单键"},{"q":"维系蛋白质一级结构的化学键是","o":["氢键","疏水键","盐键","肽键","范德华力"],"a":3,"e":"一级结构指多肽链自N端至C端的氨基酸排列顺序，主要化学键为肽键，二硫键的位置也属一级结构。氢键维系二级结构，疏水键、盐键与范德华力维系三级结构的空间构象。二级结构主要为α-螺旋、β-折叠、β-转角与Ω-环"},{"q":"表达序列标签（EST）是指","o":["具有遗传多态性的遗传标记","一段已知核苷酸序列的DNA标志","从组织提取的mRNA序列","代表完整基因一小部分的一段短cDNA序列","人类基因组中编码结构基因的DNA序列"],"a":3,"e":"EST是从cDNA文库中随机挑取克隆、测序获得的部分cDNA序列，长300～500bp，代表基因的一小部分，用作转录图谱的位标。SNP、微卫星等遗传多态性标记属DNA标志，与表达序列无关。EST并非mRNA本身，也不等同于完整基因的编码序列"},{"q":"需要NADPH提供还原当量的代谢反应有","o":["糖原合成","糖异生","胆固醇合成","酮体生成","蛋白质的生物合成"],"a":2,"e":"胆固醇合成各阶段均需NADPH供氢，HMG-CoA还原为甲羟戊酸及鲨烯环化前的多步还原都由NADPH提供还原当量，故其属需NADPH的反应。脂肪酸合成同样消耗NADPH，但选项所列为糖酵解、糖异生、核酸合成，三者分别消耗ATP、GTP与ATP，均不以NADPH为还原剂"},{"q":"呼吸链中的递氢体是","o":["烟酰胺","黄素蛋白","铁硫蛋白","细胞色素","泛醌"],"a":4,"e":"呼吸链中泛醌是脂溶性小分子，可在内膜中自由移动，一次接受2个氢原子生成还原型泛醌，再将氢传给复合体Ⅲ，是典型的递氢体。铁硫蛋白与细胞色素只传递电子，不传递氢；黄素蛋白的辅基FMN、FAD虽可递氢，但属酶蛋白的辅基，故单体形式的递氢体为泛醌"},{"q":"肝外组织利用乙酰乙酸时首先生成的是","o":["HMG-CoA","乙酰乙酰CoA","丁脂酰CoA","丙二酰CoA","乙酰CoA"],"a":1,"e":"肝外组织利用酮体时，乙酰乙酸在琥珀酰CoA转硫酶或乙酰乙酸硫激酶作用下活化为乙酰乙酰CoA，再裂解为2分子乙酰CoA进入三羧酸循环，故首先生成乙酰乙酰CoA。HMG-CoA为酮体生成与胆固醇合成的中间物，在肝内形成。丙二酰CoA为脂肪酸合成原料，乙酰CoA为后续产物"},{"q":"一种高能化合物小分子，低浓度时是作为6-磷酸果糖激酶-1的底物；高浓度时是作为6-磷酸果糖激酶-1的抑制剂，它是","o":["ATP","UTP","GTP","CTP","ADP"],"a":0,"e":"磷酸果糖激酶-1有催化部位与别构部位两个ATP结合位点，低浓度ATP作为底物与催化部位结合，高浓度ATP与别构部位结合而抑制酶活性。UTP、GTP、CTP不参与该酶反应，ADP是别构激活剂而非抑制剂"},{"q":"关于致癌病毒的描述，正确的是","o":["可以将正常细胞转化为癌细胞","能直接引起肿瘤","以DNA为遗传物质","以RNA为模板合成mRNA","含有转化酶"],"a":0,"e":"致癌病毒感染细胞后，其癌基因或整合位点附近的原癌基因被激活，使细胞获得无限增殖能力，实现正常细胞向癌细胞的转化，这是其致癌的核心表现。病毒不能直接引起肿瘤，需经转化与克隆扩增；致癌病毒既有DNA病毒也有RNA病毒，并非均以DNA为遗传物质；含转化酶并非共性"},{"q":"胆固醇在体内可转化为","o":["维生素A","辅酶A","乙酰辅酶A","肾上腺素","氢化可的松"],"a":4,"e":"胆固醇可转化为胆汁酸、类固醇激素和维生素D3，氢化可的松属肾上腺皮质激素，即由胆固醇合成。维生素A来自β-胡萝卜素，辅酶A含泛酸，乙酰CoA是胆固醇合成的原料而非产物。胆固醇在肝转变为胆汁酸是其主要去路，约占每日合成量的四成"},{"q":"催化α-酮戊二酸和氨生成谷氨酸的酶是","o":["谷氨酸脱羧酶","谷草转氨酶","谷氨酸脱氢酶","谷氨酰胺转肽酶","谷氨酰胺合成酶"],"a":2,"e":"谷氨酸脱氢酶催化α-酮戊二酸与氨还原氨基化生成谷氨酸，是联合脱氨基的逆反应，需NAD(P)H供氢。谷氨酸脱羧酶催化谷氨酸生成γ-氨基丁酸；谷草转氨酶催化转氨基；谷氨酰胺合成酶催化谷氨酸与氨生成谷氨酰胺，均非该反应"},{"q":"DNA变性是指","o":["寡核苷酸链解聚","DNA分子由超螺旋转变为双螺旋","分子中磷酸二酯键断裂","互补碱基间氢键断裂","碱基与脱氧戊糖间糖苷键断裂"],"a":3,"e":"DNA变性是双链间互补碱基的氢键断裂、碱基堆积力破坏，双链解离为单链，不涉及共价键。磷酸二酯键断裂属降解，糖苷键断裂属核苷酸水解；超螺旋转变为双螺旋是拓扑构象变化，与变性无关。Tm值随GC含量升高而升高"},{"q":"人体嘌呤核苷酸分解代谢的特征性终产物是","o":["NH3","CO2","黄嘌呤","次黄嘌呤","尿酸"],"a":4,"e":"人体嘌呤核苷酸分解的终产物是尿酸，因缺乏尿酸氧化酶不能进一步分解为尿囊素，故尿酸随尿排出，血尿酸过高可致痛风。氨是氨基酸脱氨基的产物，尿素是氨的解毒形式，β-丙氨酸与β-氨基异丁酸是嘧啶分解产物，均非嘌呤代谢的终产物"},{"q":"属于营养必需脂肪酸的是","o":["亚麻酸","软脂酸","硬脂酸","月桂酸","油酸"],"a":0,"e":"亚麻酸即α-亚麻酸，与亚油酸同属含两个以上双键的多不饱和脂肪酸，人体缺乏Δ9以上去饱和酶不能合成，为营养必需脂肪酸。软脂酸、硬脂酸、月桂酸为饱和脂肪酸，油酸是可由硬脂酸脱氢生成的单不饱和脂肪酸"},{"q":"以大肠杆菌体系生产真核生物基因产物，常常利用含有乳糖操纵子的质粒，将须表达DNA片段插入其某一区域，此区域常是","o":["O（操纵部位）","P（启动子）","Z基因","Y基因","A基因"],"a":2,"e":"利用含乳糖操纵子的质粒表达外源基因时，常将目的DNA片段插入Z基因区域，使其受乳糖启动子调控表达，插入后Z基因失活还可用于蓝白斑筛选。O是操纵序列、P是启动子，属调控区不宜插入；Y、A虽为结构基因，但常规克隆位点设在Z基因"},{"q":"下列哪种抑制作用属竞争性抑制作用","o":["磺胺类药物对细菌二氢叶酸合成酶的抑制作用","敌敌畏对胆碱酯酶的抑制作用","砷化合物对巯基酶的抑制作用","氰化物对细胞色素氧化酶的抑制作用","重金属盐对某些酶的抑制作用"],"a":0,"e":"磺胺药与对氨基苯甲酸结构相似，竞争二氢蝶酸合酶的同一活性中心，阻碍细菌四氢叶酸合成，属竞争性抑制。敌敌畏与胆碱酯酶活性中心丝氨酸羟基共价结合，砷化合物、重金属盐与巯基结合，氰化物抑制细胞色素氧化酶，均为不可逆抑制"},{"q":"脂肪大量动员时肝内生成的乙酰CoA主要转变为","o":["葡萄糖","胆固醇","脂肪酸","酮体","丙二酰CoA"],"a":3,"e":"脂肪大量动员时脂肪酸β-氧化生成大量乙酰CoA，同时草酰乙酸不足使乙酰CoA难以进入三羧酸循环，转而在肝线粒体酮体合成酶系催化下生成酮体，向肝外输出。乙酰CoA不能净异生为葡萄糖，胆固醇与脂肪酸合成虽消耗乙酰CoA但非主要去路"},{"q":"冈崎片段的生成是由于","o":["真核生物有多个复制起始点","拓扑酶的作用","RNA引物合成不足","后随链合成方向与解链方向相反","DNA连接酶缺失"],"a":3,"e":"DNA聚合酶只能按5'→3'合成，后随链模板解链方向与之相反，只能分段生成引物并合成短片段，即冈崎片段。多个复制起点影响复制速度，拓扑酶解决超螺旋，连接酶负责连接缺口。前导链连续合成只需一个引物，后随链需多个引物，故片段数目众多"},{"q":"下列化合物，哪项是乙酰CoA羧化酶的别构激活剂","o":["异柠檬酸","脂酰CoA","胰高血糖素","葡萄糖","乙酰乙酸"],"a":0,"e":"柠檬酸与异柠檬酸使乙酰CoA羧化酶由无活性原聚体聚合成有活性多聚体，属别构激活。长链脂酰CoA促其解聚而抑制，胰高血糖素经AMPK磷酸化使其失活，葡萄糖与乙酰乙酸不直接别构激活该酶"},{"q":"以下不属于初级胆汁酸成分是","o":["脱氧胆酸","胆酸","甘氨鹅脱氧胆酸","牛磺胆酸","牛磺鹅脱氧胆酸"],"a":0,"e":"初级胆汁酸由肝合成，包括胆酸、鹅脱氧胆酸及其与甘氨酸、牛磺酸结合的结合物，甘氨鹅脱氧胆酸、牛磺胆酸、牛磺鹅脱氧胆酸均属初级胆汁酸。脱氧胆酸由胆酸经肠菌脱去7α-羟基生成，属次级胆汁酸"},{"q":"体内合成胆固醇的原料是","o":["乙酰CoA","丙酮酸","胆汁酸","铁卟啉","胆色素"],"a":0,"e":"胆固醇合成的唯一碳源是乙酰CoA，在胞质溶胶及光面内质网经HMG-CoA还原酶催化，NADPH供氢。丙酮酸须先氧化脱羧生成乙酰CoA方能参与；胆汁酸与胆色素是胆固醇的转化或分解产物，铁卟啉由甘氨酸与琥珀酰CoA合成"},{"q":"下列基因调节模式涉及基因重组的是","o":["乳糖操纵子机制","色氨酸操纵子机制","阿拉伯糖操纵子机制","大肠杆菌的SOS反应","沙门氏菌的相变异"],"a":1,"e":"官方答案为【色氨酸操纵子机制】，但依据教材，正确答案为【沙门氏菌的相变异】。色氨酸操纵子通过阻遏蛋白与转录衰减调节表达，不涉及DNA重组；沙门氏菌相变异由H基因片段倒位这一位点特异性重组实现。乳糖、阿拉伯糖操纵子同为转录水平调控，SOS反应属DNA损伤修复"},{"q":"CoQ的特点是","o":["它是脂溶性物质，能在线粒体内膜中扩散","它是水溶性很强的物质","它是维生素之一","它仅仅是电子传递体","它只存在人体中"],"a":0,"e":"辅酶Q是脂溶性醌类化合物，在线粒体内膜中可自由扩散，作为流动载体在复合体Ⅰ/Ⅱ与Ⅲ之间传递电子和质子。它不是维生素；不仅传递电子还转运质子；人体和其他生物均存在；水溶性强与其脂溶性本质相悖"},{"q":"关于生物氧化，叙述错误的是","o":["总是伴有ATP的生成","可在细胞的线粒体内进行","可在细胞的内质网内进行","在温和条件下进行","需要一系列酶催化"],"a":2,"e":"生物氧化主要在线粒体内进行，由呼吸链一系列酶催化，在体温、近中性pH的温和条件下逐步放能，并偶联ADP磷酸化生成ATP。内质网主要承担蛋白质加工、脂质合成与生物转化，不是营养物质氧化释能的场所"},{"q":"通过代谢组学的方法分析急性肝损伤病人的代谢物，其尿液中含量显著升高的是","o":["尿胆素原","尿胆素","尿胆红素","尿素","尿酸"],"a":2,"e":"急性肝损伤时肝细胞摄取、转化、排泄胆红素的能力下降，结合胆红素反流入血，因其水溶性可经肾小球滤过，尿中尿胆红素呈阳性。尿胆素原在肝细胞性黄疸时高低不定，肝损伤重时反而降低。尿素由肝合成，肝损伤时生成减少；尿酸反映嘌呤代谢，与肝损伤无直接关系"},{"q":"Hb的α亚基与O2结合后产生变构效应，从而","o":["促进α亚基与O2结合，抑制β亚基与O2结合","促进β亚基与O2结合，抑制α亚基与O2结合","促进其他亚基与O2结合","抑制其他亚基与O2结合","促进其他亚基与CO2结合"],"a":2,"e":"Hb第一个亚基与O2结合后，Fe2+半径变小进入卟啉环孔，牵动F肽段使盐键断裂、亚基间结合松弛，从而促进其余亚基与O2结合，呈正协同效应，氧解离曲线为S形。A、B项把协同误作亚基间相互抑制，实际四个亚基结合O2并无先后排斥。E项混淆配体，CO2结合于珠蛋白末端氨基"},{"q":"在呼吸链中，既可作为NADH脱氢酶的受氢体，又可作为琥珀酸脱氢酶的受氢体的是","o":["Cyt c","Cyt b","CoQ","FAD","铁硫蛋白"],"a":2,"e":"复合体Ⅰ将NADH的电子交给CoQ，复合体Ⅱ将琥珀酸脱氢产生的FADH2电子也交给CoQ，故CoQ是二者共同的受氢体。Cyt c接受复合体Ⅲ的电子，Cyt b在复合体Ⅲ内传递，FAD是复合体Ⅱ的辅基，铁硫蛋白只在复合体内传递电子"},{"q":"在长期服用异烟肼时，易引起缺乏的维生素是","o":["维生素C","维生素A","维生素PP","维生素D","维生素K"],"a":2,"e":"异烟肼的结构与维生素PP即烟酸、烟酰胺相似，两者竞争性拮抗，长期服用使NAD+、NADP+生成不足，出现糙皮病样皮炎、腹泻与神经症状，故需补充维生素PP。维生素C、A、D、K的结构与异烟肼无关，其缺乏分别表现为坏血病、夜盲症、佝偻病与出血倾向"},{"q":"基因芯片是建立在哪种技术基础之上的","o":["核酸分子杂交","酵母双杂交","免疫印迹","EMSA","定量PCR"],"a":0,"e":"基因芯片（DNA微阵列）的原理是核酸分子杂交，将大量探针固定于芯片上，与标记的样品杂交以检测基因表达或序列。酵母双杂交用于研究蛋白互作；免疫印迹检测蛋白质；凝胶迁移实验研究DNA-蛋白结合；定量PCR是核酸扩增技术，均非基因芯片的技术基础"},{"q":"下列不参与调控真核基因特异性表达的是","o":["转录抑制因子","基本转录因子","转录激活因子","增强子","沉默子"],"a":1,"e":"基本转录因子是RNA聚合酶Ⅱ结合启动子所必需的一组蛋白质，所有基因转录均需其参与，故不决定基因表达的特异性。转录激活因子与抑制因子通过结合增强子、沉默子等顺式元件发挥特异调控，增强子与沉默子本身即决定表达的特异性"},{"q":"下列哪个数据库可以最便捷的检索到基因组信息","o":["Nucleotide","Genome","Structures","PubMed","OMIM"],"a":1,"e":"Genome数据库专门收录各物种全基因组序列与图谱，可按物种便捷检索基因组信息，故为首选。Nucleotide为核酸序列数据库，侧重单条序列而非完整基因组。PubMed为文献摘要库，OMIM收录孟德尔遗传病与基因表型关系，Structures为结构数据库，均非基因组检索的最便捷入口"},{"q":"DNA损伤修复方式中不包括","o":["切除修复","互补修复","光复活修复","重组修复","SOS修复"],"a":1,"e":"DNA损伤修复包括直接修复、切除修复、重组修复和跨越损伤修复，分别针对嘧啶二聚体、碱基或核苷酸损伤、双链断裂及复制叉阻滞。互补修复并非公认的修复方式，无此分类。切除修复最为普遍，SOS修复即跨越损伤修复保真性低，属诱导性应急反应"},{"q":"信号转导及转录激活因子（STAT）与下述哪个信号传递过程有关","o":["甲状旁腺素","肾上腺素","心房钠尿肽","干扰素","雌激素"],"a":3,"e":"干扰素与受体结合后激活JAK，使STAT磷酸化并形成二聚体进入核内调节基因转录，即JAK-STAT通路，故STAT主要介导干扰素信号。胰岛素经受体酪氨酸激酶激活IRS及MAPK、PI3K通路；类固醇激素经胞内受体直接调节转录；G蛋白偶联受体经cAMP或IP3传递，儿茶酚胺即属此类"},{"q":"下列对脂肪酸生物合成的描述中，正确的是","o":["脂肪酸主要是在线粒体内合成","脂肪酸合成是脂酸β-氧化的逆过程","脂肪酸的生物合成由NADH提供氢","脂肪酸的合成是以丙二酰CoA为中心的一种连续性缩合作用","脂肪酸生物合成的产物是硬脂酸"],"a":3,"e":"脂肪酸合成在细胞质中以丙二酰CoA为二碳单位供体，经缩合、加氢、脱水、再加氢循环延长碳链，由NADPH供氢，终产物为软脂酸。β-氧化在线粒体进行，与合成并非简单逆过程，酶系、辅因子与酰基载体均不同；合成产物是16碳软脂酸而非硬脂酸"},{"q":"以下关于嘌呤核苷酸合成的调节，描述错误的是","o":["以反馈调节方式为主","PRPP增加可抑制PRPP酰胺转移酶活性","IMP、AMP及GMP能使PRPP酰胺转移酶从活性形式转变为无活性形式","在合成调节中，PRPP合成酶比PRPP酰胺转移酶作用更大","PRPP酰胺转移酶是一类别构酶"],"a":1,"e":"PRPP增加可促进PRPP酰胺转移酶活性，加速5-磷酸核糖胺生成，故PRPP增加抑制该酶之说错误。IMP、AMP与GMP反馈抑制PRPP合成酶及酰胺转移酶，使活性单体转为无活性二聚体，调节以反馈为主"},{"q":"1mol葡萄糖酵解时净生成ATP的摩尔数为","o":["1","2","3","4","5"],"a":1,"e":"1mol葡萄糖酵解生成4mol ATP，扣除葡萄糖与果糖-6-磷酸磷酸化消耗的2mol，净得2mol。己糖激酶与磷酸果糖激酶-1各消耗1分子ATP，两次底物水平磷酸化共生成4分子。1为净生成不足的计算，4为生成总量而非净值，3与5无依据"},{"q":"糖、脂肪及氨基酸分解代谢的共同中间产物是","o":["磷酸烯醇式丙酮酸","丙酮酸","乙酰CoA","琥珀酸","延胡索酸"],"a":2,"e":"糖、脂肪及氨基酸分解均先经各自途径生成乙酰CoA，再进入三羧酸循环彻底氧化，故乙酰CoA是三者代谢的共同中间产物。丙酮酸只是葡萄糖及部分生糖氨基酸的中间物，脂肪酸β-氧化并不生成丙酮酸。琥珀酸、延胡索酸属三羧酸循环中间物，磷酸烯醇式丙酮酸是糖酵解与糖异生的中间物，均不能贯通三大物质代谢"},{"q":"下列关于启动子的描述，不正确的是","o":["核心序列是TATA盒","本质是DNA分子","蛋白质也是组成成分之一","属于顺式作用元件","与转录起始有关"],"a":2,"e":"启动子是DNA序列，属顺式作用元件，核心序列为TATA盒，与RNA聚合酶结合并决定转录起始的准确性与频率。原核启动子含-10区与-35区共有序列。其本质是核酸而非核蛋白，蛋白质成分不参与构成启动子，结合其上的转录因子才是蛋白质"},{"q":"下列对蛋白质α-螺旋的描述，错误的是","o":["通过氢键维持其结构稳定","通过侧链（R基团）之间的相互作用维持其结构稳定","通过分子内肽键之间的氢键维持其结构稳定","是蛋白质的一种二级结构类型","脯氨酸残基可打断α-螺旋"],"a":1,"e":"α-螺旋靠肽链主链的C=O与N-H形成链内氢键维系，侧链R基团伸向螺旋外侧，不参与稳定螺旋。脯氨酸为亚氨基酸，无N-H而不能形成氢键，可打断螺旋；每圈3.6个残基，氢键方向与螺旋轴基本平行"},{"q":"温度与酶促反应速率关系的叙述，错误的是","o":["最适温度是酶的特征性常数","最适温度时，反应速率最快","超过最适温度酶促反应速率降低","酶的最适温度与反应时间有关","酶在短时间内可耐受较高温度"],"a":0,"e":"酶的最适温度不是酶的特征性常数，它与反应时间有关，反应时间延长则最适温度降低，故A项错误。最适温度时反应速率最快，超过最适温度酶变性失活使速率下降，短时间可耐受较高温度，低温下活性降低而结构不变"},{"q":"缺乏维生素B12可引起下列哪种疾病","o":["夜盲症","脚气病","贫血","坏血病","佝偻病"],"a":2,"e":"维生素B12是甲硫氨酸合成酶的辅酶，缺乏时N5-CH3-FH4上的甲基不能转移给同型半胱氨酸，四氢叶酸再生障碍，核酸合成受阻，引起巨幼细胞贫血即恶性贫血。夜盲症由维生素A缺乏引起，脚气病由维生素B1缺乏引起，坏血病由维生素C缺乏引起，佝偻病由维生素D缺乏引起"},{"q":"生物转化的第一项反应，不包括","o":["单胺氧化酶催化的氧化反应","还原反应","水解反应","结合反应","加单氧酶催化的氧化反应"],"a":3,"e":"生物转化分两相，第一相为氧化、还原、水解，暴露极性基团；第二相为结合反应，与葡糖醛酸、硫酸、谷胱甘肽、乙酰基或甲基结合，进一步增加水溶性便于排泄，故结合不属第一相。氧化、还原、水解均直接改变底物分子上的功能基团，是典型的相反应"},{"q":"各种不同的底物都借助于同一呼吸链传递电子至氧是因为","o":["底物在线粒体被氧化","许多底物的氧化与NAD+或FAD为辅助因子氧化酶有关","底物通过一些酶类全部被氧化","来自各种底物的电子全部都传递给共同的电子受体","来自各种底物的质子都用于生成水"],"a":3,"e":"不同底物脱下的氢经各自脱氢酶交给NAD+或FAD，最终都把电子传递给共同受体氧，故共用一条呼吸链。底物并非都在同一部位氧化，NAD+与FAD只是递氢体而非最终受体，质子用于建立跨膜梯度驱动ATP合成，并非全部用于生成水"},{"q":"关于神经节苷脂功能的叙述，错误的是","o":["在神经冲动传递中起重要作用","参与细胞相互识别","在细胞生长、分化时起重要作用","霍乱毒素的受体","参与血液凝固和细胞黏着过程"],"a":4,"e":"神经节苷脂是含唾液酸的糖鞘脂，富集于神经细胞膜，参与神经冲动传递、细胞识别及生长分化，也是霍乱毒素的受体。血液凝固与细胞黏着主要由血浆凝血因子、血小板及黏附蛋白完成，与神经节苷脂无关，故E项错误"},{"q":"下列哪个酶是糖酵解和磷酸戊糖途径所共有的","o":["丙酮酸激酶","己糖激酶","6-磷酸果糖激酶-1","6-磷酸葡萄糖酸脱氢酶","葡萄糖-6-磷酸脱氢酶"],"a":1,"e":"糖酵解与磷酸戊糖途径均以葡萄糖为起点，第一步都由己糖激酶催化生成6-磷酸葡萄糖，故己糖激酶为二者共有。丙酮酸激酶与6-磷酸果糖激酶-1是糖酵解的关键酶；葡萄糖-6-磷酸脱氢酶与6-磷酸葡萄糖酸脱氢酶则是磷酸戊糖途径的特有的酶，二者均不为两途径所共有"},{"q":"关于N-连接型聚糖的叙述，错误的是","o":["糖基须活化成UDP或GDP的衍生物","糖基化位点是Asn-X-Ser/Thr","N-连接型聚糖分为高甘露糖型、复杂型和杂合型","糖基与多肽链丝氨酸残基连接","需要糖基转移酶催化"],"a":3,"e":"N-连接型聚糖的糖基与多肽链中天冬酰胺残基的酰胺氮共价连接，而非丝氨酸残基（那是O-连接型的特征），故此项错误。N-连接型的糖基需活化为UDP/GDP衍生物、位点为Asn-X-Ser/Thr、分为高甘露糖型/复杂型/杂合型、由糖基转移酶催化，均正确"},{"q":"食物蛋白质的互补作用是","o":["几种蛋白质食物混合食用，提高营养价值","脂肪与蛋白质食物混合食用，提高营养价值","糖、脂肪和蛋白质几种食物混合食用，提供营养价值","供应各种维生素，可节约食物蛋白质的摄入量","用蛋白质食物代替脂肪性高的食物，提高营养价值"],"a":0,"e":"蛋白质互补指几种营养价值较低的蛋白质混合食用，彼此必需氨基酸取长补短，提高整体利用率，如谷类与豆类同食。与脂肪、糖混合或补充维生素只改善能量与维生素供给，不能改变氨基酸模式；用蛋白质食物代替高脂食物属膳食结构调整，并非互补作用"},{"q":"丙酮酸氧化分解时，净生成ATP分子数是","o":["10","12、5","13","20","12"],"a":1,"e":"丙酮酸经丙酮酸脱氢酶复合体氧化脱羧生成乙酰CoA，后者进入三羧酸循环彻底氧化，按NADH 2.5、FADH2 1.5计算共生成12.5分子ATP。10分子是三羧酸循环本身的产量，未计入丙酮酸脱氢生成的1分子NADH；12项漏掉0.5，13与20无对应计算依据"},{"q":"关于酶活性中心的叙述中正确的是","o":["所有酶的活性中心都含有辅酶","所有酶的活性中心都含有金属离子","酶的必需基团都位于活性中心内","所有的抑制剂都作用于酶活性中心","所有的活性中心都具有结合基团和催化基团"],"a":4,"e":"酶活性中心由结合基团和催化基团构成，前者识别并结合底物、决定专一性，后者催化化学键的断裂与形成。并非所有酶都含辅酶或金属离子，必需基团可位于活性中心外以维持构象，抑制剂也可作用于活性中心外的别构部位"},{"q":"脂肪酸在肝脏进行β-氧化时，不生成的物质是","o":["NADH","FADH2","水","乙酰CoA","脂酸CoA"],"a":2,"e":"β-氧化每轮经脱氢、加水、再脱氢、硫解，生成1分子FADH2、1分子NADH、1分子乙酰CoA和缩短两个碳的脂酰CoA，其中加水反应消耗水而非生成水。还原当量只有经呼吸链把电子交给氧后才生成水，不属β-氧化本身；脂酰CoA既是产物又是下一轮底物"},{"q":"下列关于维生素D的描述，哪项是正确的","o":["是胆固醇的主要转化产物","是一种水溶性维生素","可以与核受体进行结合","25-OH-VitD3是其完全活性形式","是多种代谢关键酶的辅酶"],"a":2,"e":"维生素D的活性形式1,25-(OH)2-D3属脂溶性激素样分子，与靶细胞核内维生素D受体结合，调节钙结合蛋白、骨钙蛋白等基因表达。25-OH-D3需再经肾1α-羟化才有完全活性；它为脂溶性而非水溶性，也不作代谢酶辅酶"},{"q":"原核生物中，某种代谢途径相关的几种酶往往通过何种机制进行协调表达","o":["顺反子","操纵子","转录因子","衰减子","沉默子"],"a":1,"e":"原核生物功能相关的多个结构基因串联，共用启动子与操纵序列，由同一阻遏蛋白或激活蛋白协调调控，即操纵子机制。顺反子指编码一条肽链的遗传单位，衰减子与沉默子是调控元件而非协调表达单位"},{"q":"组蛋白修饰在时间与空间上的组合与生物学功能的关系可以作为一种重要的标志或语言，被称为“组蛋白密码”。研究组蛋白密码对药物开发具有战略意义，多种组蛋白修饰酶已经成为相关疾病治疗的靶标。比如，组蛋白去乙酰化酶（HDACs）抑制剂已应用于临床治疗多种肿瘤。下列关于“组蛋白密码”叙述错误的是","o":["组蛋白修饰属于染色质水平上的基因表达调控方式","组蛋白修饰主要包括组蛋白的乙酰化、磷酸化、甲基化、泛素化以及ADP核糖基化","组蛋白甲基化修饰既可抑制也可增强基因表达","组蛋白乙酰化修饰一般选择性地使某些染色质区域的结构从松散变得紧密","组蛋白乙酰化修饰和甲基化修饰一般相互排斥"],"a":3,"e":"乙酰化中和组蛋白尾部碱性氨基酸的正电荷，减弱其与DNA的结合，使染色质由紧密变松散、利于转录，故D项方向相反。组蛋白修饰属染色质水平的表达调控，包括乙酰化、磷酸化、甲基化、泛素化和ADP核糖基化，其中甲基化既可激活也可抑制转录"},{"q":"原核生物和真核生物的蛋白质合成过程虽有很多不同之处，但在基本机制等方面又有诸多共同之处。对于原核生物和真核生物的蛋白质合成都是必需的是","o":["核糖体小亚基与S-D序列结合","fMet-tRNA","mRNA从细胞核转运至细胞质","起始因子识别5'-帽子结构","肽酰基-tRNA从A位转位至P位"],"a":4,"e":"原核与真核核糖体均有A位、P位、E位，肽链延长时肽酰-tRNA由A位转位至P位，是两者共有的基本步骤。S-D序列结合、fMet-tRNA、5'-帽子识别分别为原核或真核特有，mRNA核内转运仅见于真核"},{"q":"催化三羧酸循环与脂肪酸β-氧化的酶分布在细胞的","o":["细胞质","细胞膜","细胞核","内质网","线粒体"],"a":4,"e":"三羧酸循环的酶系位于线粒体基质与内膜，脂肪酸β-氧化的酶系位于线粒体基质，两者产物乙酰CoA与还原当量直接进入同一线粒体的氧化磷酸化体系。糖酵解与脂肪酸合成在细胞质，磷脂与胆固醇合成主要在内质网，DNA复制与转录在细胞核，均非二者共同部位"},{"q":"下列关于RNA组学的叙述错误的是","o":["研究非编码RNA的集合","研究非编码RNA对基因表达的调控","研究小分子RNA的种类、表达情况及生物学意义","研究长非编码RNA的表达调控及生物学功能","是结构基因组学的重要组成部分"],"a":4,"e":"RNA组学研究细胞转录产物中的非编码RNA，包括miRNA等小RNA与lncRNA的种类、表达及调控功能。结构基因组学只做基因组作图与序列测定，RNA组学属功能基因组学范畴；小RNA与长非编码RNA的研究内容均为其组成部分"},{"q":"磷酸戊糖途径的真正意义在于产生许多中间物如核糖，同时还产生","o":["NADPH＋H＋","NAD＋","ADP","CoASH","含有不同糖原子的糖类物质"],"a":0,"e":"磷酸戊糖途径的重要生理意义是生成5-磷酸核糖和NADPH，后者为脂肪酸、胆固醇等合成供氢并维持谷胱甘肽还原状态，故为答案。NAD+主要来自氧化脱氢反应。ADP为能量代谢产物。CoASH为辅酶。含不同糖原子的糖类物质为途径中间物，均非该途径的特征产物"},{"q":"喜树碱（camptothecin）具有抗癌活性，是因为它在癌细胞内选择性地抑制","o":["DNA聚合酶","RNA聚合酶","DNA拓扑异构酶Ⅰ","DNA解链酶","DNA连接酶"],"a":2,"e":"喜树碱特异性抑制DNA拓扑异构酶Ⅰ，阻止DNA复制时超螺旋的解除，导致DNA损伤和细胞凋亡而发挥抗癌作用，故为答案。DNA聚合酶负责DNA合成，RNA聚合酶参与转录，DNA解链酶打开双链，DNA连接酶连接缺口，均非喜树碱的靶点"},{"q":"肝对血糖的调节不是通过","o":["糖异生","糖原合成","糖原分解","糖转变成非糖物质","加速氨基酸代谢"],"a":4,"e":"肝通过糖原合成与分解、糖异生以及把糖转变为脂肪等非糖物质来维持血糖恒定。加速氨基酸代谢属蛋白质代谢的调节，虽可为糖异生提供原料，但不是肝调节血糖的直接方式，故其余各项均参与血糖升降而本项不属于"},{"q":"转氨基作用可生成谷氨酸的α-酮酸是","o":["丙酮酸","草酰乙酸","乙酰乙酸","苯丙酮酸","α-酮戊二酸"],"a":4,"e":"转氨基反应中氨基的受体是α-酮戊二酸，接受氨基后生成谷氨酸，故催化其生成的α-酮酸为α-酮戊二酸。丙酮酸接受氨基生成丙氨酸，草酰乙酸生成天冬氨酸，苯丙酮酸生成苯丙氨酸；乙酰乙酸不参与转氨基反应"},{"q":"关于双向电泳的叙述正确的是","o":["第一向为聚丙烯酰胺凝胶电泳","第一向为变性聚丙烯酰胺凝胶电泳","第二向为聚丙烯酰胺凝胶电泳","第一向为等电聚焦电泳","第二向为琼脂糖凝胶电泳"],"a":3,"e":"双向电泳第一向为等电聚焦，按蛋白质等电点分离；第二向为SDS-聚丙烯酰胺凝胶电泳，按分子量分离。第一向并非普通或变性聚丙烯酰胺凝胶电泳，第二向也不是琼脂糖凝胶电泳，琼脂糖多用于核酸分离"},{"q":"合成脂肪酸的乙酰CoA的主要来源是","o":["细胞质直接提供","细胞质的乙酰肉碱提供","在线粒体产生并以乙酰CoA的形式转运到细胞质","在线粒体产生并由肉碱携带转运到细胞质","在线粒体产生并转化为柠檬酸而转运到细胞质"],"a":3,"e":"官方答案为【在线粒体产生并由肉碱携带转运到细胞质】，但依据教材，正确答案为【在线粒体产生并转化为柠檬酸而转运到细胞质】。乙酰CoA不能直接透过线粒体内膜，须与草酰乙酸缩合成柠檬酸，经载体转运至胞质后由柠檬酸裂解酶释出。肉碱穿梭转运的是长链脂酰CoA，用于β-氧化"},{"q":"巯基酶所含的巯基来自哪种氨基酸","o":["胱氨酸","亮氨酸","半胱氨酸","甲硫氨酸","谷氨酸"],"a":2,"e":"巯基酶活性中心的巯基来自半胱氨酸残基的侧链，该巯基是许多酶催化所必需的基团，故为答案。胱氨酸为半胱氨酸的氧化二聚体，含二硫键而非游离巯基。甲硫氨酸含硫醚基而非巯基。亮氨酸、谷氨酸侧链无巯基"},{"q":"嘧啶核苷酸生物合成途径的反馈抑制，是由于控制了","o":["二氢乳清酸酶的活性","乳清酸磷酸核糖转移酶的活性","二氢乳清酸脱氢酶的活性","天冬氨酸转氨甲酰酶的活性","胸苷酸合酶的活性"],"a":3,"e":"嘧啶核苷酸合成的限速步骤由天冬氨酸转氨甲酰酶催化，终产物CTP反馈抑制该酶。二氢乳清酸酶与脱氢酶催化后续反应，乳清酸磷酸核糖转移酶属补救合成，胸苷酸合酶负责dTMP生成。该酶受CTP反馈抑制，属别构酶，是嘧啶从头合成的关键调节点"},{"q":"没有引物，DNA聚合酶不能复制DNA，这是因为","o":["DNA聚合酶需要单链DNA模板","没有引物，DNA聚合酶无法进行新链合成","所有的RNA聚合酶和DNA聚合酶需要引物提供游离的3＇-羟基","需要引物来装配好滑动钳结构","需要引物解开DNA双链，以暴露模板链"],"a":1,"e":"DNA聚合酶只能催化已有3′-OH末端与dNTP聚合，不能催化两个游离dNTP之间成键，故无引物不能起始新链。引发酶属RNA聚合酶，不需3′-OH即可聚合，合成的RNA引物提供3′-OH，C项错在将RNA聚合酶也列为需引物；解链由解旋酶完成"},{"q":"肾上腺素发挥作用时，其第二信使是","o":["cUMP","cGMP","cCMP","GMP","cAMP"],"a":4,"e":"肾上腺素与β受体结合，激活Gs使腺苷酸环化酶活化，ATP生成cAMP并激活PKA，引起糖原分解与脂肪动员。cGMP由鸟苷酸环化酶生成，介导心房钠尿肽等信号；cUMP、cCMP与GMP均非第二信使"},{"q":"通过膜受体起调节作用的激素是","o":["性激素","糖皮质激素","甲状腺素","肾上腺素","活性维生素D3"],"a":3,"e":"肾上腺素属儿茶酚胺类，亲水不能透过脂双层，须与靶细胞膜受体结合，经腺苷酸环化酶-cAMP-蛋白激酶A通路传递信号。性激素与糖皮质激素为类固醇激素，甲状腺素、活性维生素D3亦为疏水激素，均透过细胞膜与胞内受体结合，故不属膜受体激素"},{"q":"脂肪酸β-氧化过程生成的1分子FADH2经呼吸链传递给氧生成水，同时经氧化磷酸化反应可生成ATP的分子数是","o":["0","1","1、5","2、5","3"],"a":2,"e":"FADH2经复合体Ⅱ进入呼吸链，绕过复合体Ⅰ，仅经复合体Ⅲ、Ⅳ泵出约6个H+，按每合成1分子ATP约需4个H+计算，生成约1.5分子ATP。若从NADH进入则经复合体Ⅰ泵出约10个H+，生成约2.5分子ATP，二者不可混淆"},{"q":"有关糖原代谢的叙述，正确的是","o":["CTP参与糖原的合成","糖原合成的关键酶的分支酶","在糖原引物上每添加1个葡萄糖基需要消耗3个ATP","糖原磷酸化酶催化的磷酸解生成6-磷酸葡萄糖","葡萄糖-6-磷酸酶不存在于肌肉中"],"a":4,"e":"肌肉中缺乏葡萄糖-6-磷酸酶，肌糖原分解产生的葡萄糖-6-磷酸不能水解为游离葡萄糖，故肌糖原不能直接补充血糖，该叙述正确。糖原合成以UTP而非CTP参与活化葡萄糖。糖原合成关键酶为糖原合酶而非分支酶。每添加1个葡萄糖基消耗1个UTP而非3个ATP。糖原磷酸化酶催化磷酸解生成葡萄糖-1-磷酸而非6-磷酸葡萄糖"},{"q":"脂肪动员的限速酶是","o":["甘油三酯脂肪酶","甘油二酯脂肪酶","甘油一酯脂肪酶","腺苷酸环化酶","蛋白激酶A"],"a":0,"e":"脂肪动员的限速酶是脂肪细胞中的甘油三酯脂肪酶（激素敏感性脂肪酶），其活性受胰高血糖素等激素经磷酸化调节，催化甘油三酯水解的第一步。甘油二酯脂肪酶和甘油一酯脂肪酶催化后续步骤，并非限速酶；腺苷酸环化酶和蛋白激酶A是激素信号转导的中间环节"},{"q":"在分子生物学领域，自然界的DNA重组不包括","o":["同源重组","位点特异性重组","聚合酶链式反应","转座重组","接合作用"],"a":2,"e":"自然界DNA重组包括同源重组、位点特异性重组、转座重组以及细菌接合、转化导致的基因转移，是生物体固有的遗传变异机制。PCR是体外酶促扩增DNA片段的人工技术，不涉及DNA片段的重新组合，故不属于自然重组"},{"q":"既可以分离蛋白质、也可以测定其分子量的实验技术是","o":["亲和层析","超速离心","透析","离子交换层析","盐析"],"a":1,"e":"超速离心按颗粒的沉降行为分离，沉降系数与分子大小、形状和密度相关，既可用于纯化蛋白质，又可测得沉降系数推算分子量。亲和层析靠配体特异结合，只用于纯化。离子交换层析按电荷差异分离，盐析按溶解度分级沉淀，透析按分子大小去除小分子，三者均不能给出分子量"},{"q":"汉斯·克雷布斯于1937年发现了三羧酸循环。揭示了生物体内糖经酵解途径变为三碳物质后，进一步氧化为二氧化碳和水的途径以及代谢能的主要来源。这一循环与糖、蛋白质、脂肪等的代谢都有密切关系，是所有需氧生物代谢中的重要环节。这一发现被公认为代谢研究的里程碑。在三羧酸循环中，下列哪一阶段的产物可以进行氧化磷酸化","o":["乙酰CoA→柠檬酸","异柠檬酸→α-酮戊二酸","琥珀酰CoA→琥珀酸","延胡索酸→苹果酸","柠檬酸→异柠檬酸"],"a":1,"e":"三羧酸循环中异柠檬酸经异柠檬酸脱氢酶氧化脱羧生成α-酮戊二酸，同时将NADH交给呼吸链，可经氧化磷酸化生成ATP。柠檬酸→异柠檬酸只是异构化，无脱氢；琥珀酸→延胡索酸脱下氢交给FAD；延胡索酸→苹果酸为加水反应，苹果酸→草酰乙酸虽产NADH，但选项中与之并列的步骤不含产能反应"},{"q":"mRNA差异显示（mRNA-DD）实验中分离PCR扩增产物使用的方法是","o":["SDS-聚丙酰胺凝胶电泳","聚丙酰胺凝胶电泳","琼脂糖凝胶电泳","亲和层析","双向电泳"],"a":1,"e":"mRNA差异显示将RT-PCR与聚丙烯酰胺凝胶电泳结合，扩增产物按分子大小在高分辨率凝胶上分离成条带，比较不同样本的条带差异。琼脂糖凝胶分辨率低，适于较大DNA片段。SDS-PAGE与双向电泳用于蛋白质分离，亲和层析依特异结合纯化，均不用于该实验"},{"q":"关于糖原合酶的调节，不正确的叙述是","o":["糖原合成酶受磷蛋白磷酸酶-1作用而失活","依赖cAMP蛋白激酶可使磷蛋白磷酸酶抑制物有抑制作用","依赖cAMP蛋白激酶可使糖原合酶失活","糖原合酶有活性和无活性两种形式","糖原合酶活性的调节受多种机制的调节"],"a":0,"e":"蛋白磷酸酶-1使糖原合酶去磷酸化而活化，同时使糖原磷酸化酶去磷酸化而失活，故“受磷蛋白磷酸酶-1作用而失活”错误。依赖cAMP的蛋白激酶A磷酸化糖原合酶使其失活，并磷酸化磷酸酶抑制物阻断去磷酸化；糖原合酶确有活性与无活性两种形式"},{"q":"DNA上的一个点突变不一定影响蛋白质的一级结构，是因为","o":["DNA的修复作用","遗传密码的简并性","校正tRNA的作用","核糖体对mRNA的校正","以上都正确"],"a":1,"e":"遗传密码的简并性使同一氨基酸可由多个密码子编码，第三位碱基改变常不改变所编码的氨基酸，故蛋白质一级结构不变。DNA修复针对损伤而非已发生的突变；校正tRNA只纠正误配，核糖体无校正功能"},{"q":"下列器官中能氧化酮体但几乎不能氧化脂肪酸的是","o":["肝","肾","脑","肌肉","心"],"a":2,"e":"脑组织缺乏氧化脂肪酸所需的酶，不能直接氧化脂肪酸，但可利用酮体供能，饥饿时酮体成为其主要能源。肝虽大量生成酮体，却缺乏利用酮体的酶。肾、心、骨骼肌既能氧化脂肪酸，也能利用酮体。故脑是能氧化酮体而几乎不能氧化脂肪酸的器官"},{"q":"45S rRNA是","o":["核糖体大亚单位的rRNA","由不同转录单位转录后组合而成","可翻译成组蛋白","除5S rRNA外的其余3种rRNA的前身","由RNA聚合酶Ⅱ催化转录"],"a":3,"e":"45S rRNA由RNA聚合酶Ⅰ在核仁内转录，经加工剪接生成18S、5.8S和28S三种rRNA，故为除5S外三种rRNA的前身。5S rRNA由RNA聚合酶Ⅲ独立转录，不在45S前体之内。45S rRNA不编码蛋白质，其基因以串联重复形式位于核仁组织区"},{"q":"将下述分子按信号传递通路中的先后顺序排列，居第五位的是","o":["受体","腺苷酸环化酶","环腺苷酸（cAMP）","G蛋白","蛋白激酶A（PKA）"],"a":4,"e":"该通路顺序为受体→G蛋白→腺苷酸环化酶→cAMP→蛋白激酶A，居第五位的是蛋白激酶A。受体识别配体居首位，G蛋白在胞内侧偶联，腺苷酸环化酶催化ATP生成cAMP，cAMP作为第二信使激活蛋白激酶A，再由它磷酸化下游靶蛋白产生效应"},{"q":"人表皮生长因子受体2（HER2）T790M突变是非小细胞肺癌的耐药机制之一，能够分析HER2突变位点的方法是","o":["BLAST分析","免疫共沉淀分析","基因测序分析","质谱分析","2-DE分析"],"a":2,"e":"T790M是第790位密码子的点突变，属明确的碱基序列改变，PCR扩增该位点所在片段后作基因测序是最直接的分析方法。BLAST为序列同源比对，免疫共沉淀检测蛋白相互作用，质谱与2-DE分析蛋白质，均不能确定突变位点"},{"q":"当乙酰CoA羧化酶受到抑制时，下列会受影响的代谢是","o":["糖异生","胆固醇的合成","酮体的合成","脂酸的氧化","脂酸的合成"],"a":4,"e":"乙酰CoA羧化酶催化乙酰CoA羧化为丙二酸单酰CoA，是脂肪酸合成的关键限速步骤，受抑制则脂肪酸合成受阻。该酶不参与糖异生、酮体生成和脂肪酸β-氧化，胆固醇合成虽以乙酰CoA为原料，但不依赖此羧化反应"},{"q":"ISH可以用于在组织原位定性分析哪项水平的变化","o":["基因组","转录","转录后","翻译","翻译后"],"a":1,"e":"原位杂交以标记核酸探针与组织切片中的mRNA互补结合，保持细胞形态的同时定位特定基因的转录产物，反映转录水平。基因组水平用DNA印迹或原位PCR，翻译水平需免疫组化检测蛋白；转录后加工与翻译后修饰无相应杂交靶分子"},{"q":"下列与生物素有关的代谢反应有","o":["丙酮酸氧化脱羧反应","氨基酸脱羧反应","一碳基团的转移","加氧反应","乙酰CoA羧化生成丙二酸单酰CoA"],"a":4,"e":"生物素是羧化酶的辅基，在乙酰CoA羧化酶催化下把CO2转给乙酰CoA生成丙二酸单酰CoA，是软脂酸合成的第一步。丙酮酸氧化脱羧需TPP、硫辛酸、CoA、FAD与NAD+，不含生物素；一碳单位转移靠四氢叶酸，加氧反应由加单氧酶催化"},{"q":"蛋白质分子中的下列氨基酸哪一种没有遗传密码","o":["色氨酸","羟脯氨酸","天冬氨酸","甲硫氨酸","赖氨酸"],"a":1,"e":"羟脯氨酸由脯氨酸在蛋白质翻译后羟化生成，无对应的密码子和tRNA，不参与翻译过程。色氨酸、天冬氨酸、甲硫氨酸和赖氨酸均为组成蛋白质的标准氨基酸，各有遗传密码。脯氨酸本身有密码子，羟化后才成为羟脯氨酸"},{"q":"脂肪酸在肝进行β-氧化的限速酶是","o":["肉碱脂酰转移酶Ⅰ","肉碱脂酰转移酶Ⅱ","脂酰辅酶A脱氢酶","脂酰辅酶A合成酶","β-酮脂酰辅酶A硫解酶"],"a":0,"e":"肉碱脂酰转移酶Ⅰ位于线粒体外膜，催化脂酰CoA转为脂酰肉碱，是脂肪酸β-氧化的限速步骤，受丙二酰CoA抑制。酶Ⅱ位于内膜内侧，催化相反方向的转运；脱氢酶与硫解酶催化β-氧化循环内部反应，不决定途径通量"},{"q":"饥饿时肝中代谢途径活性增强的是","o":["糖有氧氧化","脂肪合成","糖酵解","磷酸戊糖途径","糖异生"],"a":4,"e":"饥饿时胰高血糖素升高，果糖-2,6-二磷酸减少，磷酸果糖激酶-1活性下降，糖酵解减弱而糖异生增强，以维持血糖。糖有氧氧化、糖酵解与磷酸戊糖途径均减弱，脂肪合成受抑而脂肪动员加强"},{"q":"需经细胞质和线粒体完成的糖代谢途径有","o":["磷酸戊糖途径","三羧酸循环","糖异生途径","糖醛酸途径","糖原合成途径"],"a":2,"e":"糖异生途径跨越细胞质与线粒体：丙酮酸在线粒体内经丙酮酸羧化酶生成草酰乙酸，再转至细胞质经PEP羧激酶等反应生成葡萄糖，故需两个部位协同完成。磷酸戊糖途径、糖原合成途径、糖醛酸途径均在细胞质进行。三羧酸循环在线粒体进行"},{"q":"以下蛋白质或酶的作用不依赖于ATP的是","o":["DNA聚合酶Ⅰ","DNA连接酶","拓扑异构酶Ⅱ","DNA解旋酶","氨基酰tRNA合成酶"],"a":0,"e":"DNA聚合酶Ⅰ以dNTP为底物，依靠底物水解释放的能量催化聚合，不需额外消耗ATP。DNA连接酶需ATP（或NAD+）活化；拓扑异构酶Ⅱ、DNA解旋酶均需ATP供能；氨基酰-tRNA合成酶活化氨基酸也需ATP，故均依赖ATP"},{"q":"使蛋白质变性的因素是","o":["透析","超滤","有机溶剂","离心","盐析"],"a":2,"e":"乙醇、丙酮等有机溶剂破坏蛋白质分子内的疏水相互作用与氢键，使空间构象改变、理化性质异常、生物学活性丧失，属变性因素。透析与超滤用于去除小分子或浓缩，离心用于分离，盐析是加中性盐使蛋白质沉淀，均不引起变性"},{"q":"血红蛋白β链编码基因发生突变，是镰状细胞贫血的发生机制。β链编码基因发生的突变是","o":["插入","断裂","缺失","点突变","交联"],"a":3,"e":"镰状细胞贫血是β-珠蛋白基因第6密码子发生A→T的单核苷酸替换，使谷氨酸变为缬氨酸，属点突变中的错义突变。插入、缺失会引起移码，断裂与交联造成大片段改变或分子间异常连接，均不能解释单个氨基酸的替换"},{"q":"DNA拓扑异构酶不能","o":["切开DNA","松弛DNA","改变DNA的超螺旋密度","催化DNA链的断裂和结合","将环状DNA变为线状DNA"],"a":4,"e":"拓扑异构酶通过切断、旋转、再连接改变DNA超螺旋密度，Ⅰ型切单链、Ⅱ型切双链，均可松弛DNA并催化断链与连接。其切口随即封闭，不产生游离线状DNA；把环状DNA变为线状需核酸酶或机械断裂，故E项不能"},{"q":"研究蛋白质间相互作用的技术中不包括","o":["酵母双杂交","免疫共沉淀","基因组编辑技术","双分子荧光互补技术（BIFC）或生物发光共振能量转移技术（BRET）","模拟大分子空间结构的计算生物学软件技术"],"a":2,"e":"酵母双杂交、免疫共沉淀、双分子荧光互补与BRET均可检测蛋白质间相互作用，计算生物学软件可模拟分子对接。基因组编辑技术用于定向改变基因序列以研究基因功能，并非检测蛋白间相互作用的技术"},{"q":"下列结构中不属于结构模体的是","o":["锌指","Ω环","螺旋-环-螺旋","碱性亮氨酸拉链","螺旋-转角-螺旋"],"a":1,"e":"Ω环是二级结构的一种形式，与α-螺旋、β-折叠、β-转角并列，不属结构模体。锌指、螺旋-环-螺旋、碱性亮氨酸拉链和螺旋-转角-螺旋均由两个以上二级结构肽段组成，具有特定空间构象与功能，是典型的结构模体"},{"q":"人体储存能量的高能化合物是","o":["ATP","GTP","磷酸肌酸","葡萄糖","脂肪酸"],"a":2,"e":"磷酸肌酸是肌肉和脑中储存高能磷酸键的化合物，ATP消耗时可将磷酸基迅速转给ADP生成ATP，作为能量的即时储备库。ATP是直接供能物质而非储存形式，含量少、周转快。GTP主要用于蛋白质合成等特定过程。葡萄糖、脂肪酸需经氧化分解才释放能量，不属高能化合物"},{"q":"5-氟尿嘧啶在体内发挥作用时，必须转变成","o":["FdTTP","FdUMP","FdUDP","FdUTP","FdTMP"],"a":1,"e":"5-氟尿嘧啶本身无活性，须在体内转变为FdUMP及FUTP。FdUMP与dUMP结构相似，抑制胸苷酸合酶，阻断dTMP合成；FUTP以FUMP形式掺入RNA，破坏其结构与功能。FdUDP、FdTTP、FdTMP均非其活性形式，故不选"},{"q":"正常生理条件下，人体所需能量的60%以上来源于","o":["糖","脂肪","蛋白质","DNA","RNA"],"a":0,"e":"糖是人体最主要的供能物质，正常生理条件下氧化供能占总能量的60%以上，脑组织几乎完全依赖葡萄糖。脂肪是储能物质，饥饿时供能比例上升；蛋白质在正常情况下供能很少，DNA与RNA不参与供能"},{"q":"机体会增强糖异生来生成葡萄糖的情况是","o":["提高某种酶的活性时","饥饿状态下","疾病状态下","血糖浓度过高时","ATP供应不足时"],"a":1,"e":"饥饿时血糖下降、胰高血糖素升高，肝糖原耗尽后糖异生增强以维持血糖。血糖过高时糖异生受抑制，ATP不足并非其启动信号，疾病状态须视具体病理而定，不构成普遍规律。糖异生关键酶受胰高血糖素经cAMP-PKA途径促进，胰岛素则使其表达下降"},{"q":"CpG序列的高度甲基化对多数基因而言是","o":["染色质呈转录活性状态","促进转录","抑制转录","既不抑制也不促进转录","与基因表达无关"],"a":2,"e":"CpG岛位于基因5′-端启动子区，胞嘧啶甲基化后阻碍转录因子与启动子结合、招募染色质重塑蛋白形成致密结构，从而抑制转录。未甲基化状态为基因转录所必需，高度甲基化常使抑癌基因沉默，与促进转录或与表达无关的说法相反"},{"q":"Km值与酶对底物亲和力大小的关系是","o":["Km值越小，亲和力越大","Km值越大，亲和力越大","Km值越小，亲和力越小","Km值大小与酶对底物的亲和力无关","酶对不同亲和力的底物Km值是一定的"],"a":0,"e":"Km等于反应速率为最大速率一半时的底物浓度，Km越小表示达到半数饱和所需底物越少，酶对底物亲和力越大。Km是酶的特征性常数，与酶结构、底物结构、pH、温度、离子强度有关而与酶浓度无关，同一酶对不同底物的Km也可不同"},{"q":"下列有关核酸变性与复性叙述正确的是","o":["热变性DNA缓慢冷却可复性","复性的最适pH值为7、5","热变性DNA迅速降温过程也称作退火","复性最佳温度为25℃","缓慢升温可以使DNA变性"],"a":0,"e":"热变性DNA经缓慢冷却，互补单链可按碱基配对重新结合成双链，此过程称退火，是核酸分子杂交的基础。变性只断裂氢键、解离双链，一级结构不变。迅速降温至4℃时链间来不及配对，不能复性；复性不需pH 7.5，温度也不是25℃，升温方向是变性而非复性"},{"q":"利用信息学分析某分泌蛋白可能有糖基化修饰，用于分析该蛋白糖基化位点的技术是","o":["色谱/质谱技术","双向电泳/质谱技术","MPSS技术","基因芯片技术","ETS序列分析"],"a":0,"e":"糖基化位点分析靠糖肽的分离与质量测定，色谱-质谱联用可按保留时间分离糖肽、按质荷比确定糖基组成与连接位点，是糖蛋白糖基化分析的基本技术。双向电泳/质谱只分离完整蛋白并鉴定蛋白种类，不解析糖链结构。基因芯片、MPSS与ETS序列分析均属核酸水平检测，读取的是基因序列或转录本，不能反映翻译后的糖基化修饰"},{"q":"DNA复制时，以5'TAGA3'为母链模板，则合成的子链相应序列为","o":["5'TCTA3'","5'UCUA3'","5'ATCT3'","5'AUCU3'","5'GCGA3'"],"a":0,"e":"模板为5'-TAGA-3'，子链与之反向平行互补，为3'-ATCT-5'，改写即5'-TCTA-3'。含U者为RNA序列，不符DNA复制；GCGA与模板碱基不互补。复制中A与T配对、G与C配对，故模板的T对应子链的A"},{"q":"四环素族抗生素对人体蛋白质合成影响不大是因为","o":["可与30S亚基结合","可与50S亚基结合","易进入菌体，但不易透过哺乳类细胞的细胞膜","可与40S亚基结合","可与60S亚基结合"],"a":0,"e":"四环素作用于原核核糖体30S亚基，抑制氨酰-tRNA与小亚基结合，真核核糖体为80S、小亚基为40S，故对人体蛋白质合成影响小。50S是大环内酯类与氯霉素的靶点，40S与60S为真核核糖体亚基，C项描述的是药物在菌体与哺乳细胞间的分布差异"},{"q":"未结合胆红素的称法很多，但不包括下列哪种","o":["间接反应胆红素","血胆红素","间接胆红素","肝胆红素","游离胆红素"],"a":3,"e":"未结合胆红素又称间接胆红素、游离胆红素、血胆红素，与清蛋白结合运输，凡登白试验呈间接反应。肝胆红素即结合胆红素，是肝内与葡萄糖醛酸结合后的产物，分子小、水溶性大，呈直接反应，可经肾随尿排出"},{"q":"合成RNA的原料是","o":["dNMP","dNDP","dNTP","NTP","NDP"],"a":3,"e":"合成RNA以ATP、GTP、CTP、UTP四种核苷三磷酸为原料，聚合时释出焦磷酸供能。dNTP是DNA合成原料，NMP与NDP不能直接聚合，dNDP须先磷酸化为dNTP方可参与复制"},{"q":"下列描述可考虑作为“管家基因”候选的是","o":["电刺激后细胞表达“A”分子增加","电刺激后细胞表达“A”分子减少","电刺激前后细胞表达“A”分子水平相同","电刺激前细胞表达“A”分子增加","电刺激前细胞表达“A”分子减少"],"a":2,"e":"管家基因表达受环境因素影响小，在各组织细胞中表达相对恒定，故电刺激前后表达水平相同者才符合候选条件。表达增加属诱导表达，表达减少属阻遏表达，均说明该基因受外界信号调控，不能作为内参候选"},{"q":"关于Km值的意义，错误的是","o":["是酶的特征性常数","Km越大，酶与底物亲和力越小","Km值与酶所催化的底物有关","Km值等于反应速率为最大速率一半时的底物浓度","Km值与酶浓度有关"],"a":4,"e":"Km是酶的特征性常数，等于反应速率为最大速率一半时的底物浓度，只与酶和底物的结构、pH、温度及离子强度有关，与酶浓度无关。Km越大表示酶与底物亲和力越小。E项将Km与酶量挂钩，属概念错误"},{"q":"肾上腺素与膜上β受体结合，激活G蛋白后能","o":["激活鸟苷酸环化酶","抑制鸟苷酸环化酶","激活腺苷酸环化酶","抑制腺苷酸环化酶","激活磷脂酶C"],"a":2,"e":"肾上腺素与β受体结合后激活Gs，GTP使α亚基活化并与βγ解离，活化的Gsα激活腺苷酸环化酶，催化ATP生成cAMP，进而激活蛋白激酶A启动脂解。鸟苷酸环化酶由一氧化氮等激活，与cAMP通路无关；磷脂酶C由Gq偶联受体激活，生成IP3与DAG，不是β受体的主要效应"},{"q":"可以用于基因及表达产物定位分析的杂交技术是","o":["Southern blotting","Northern blotting","Western blotting","FISH","ChIP"],"a":3,"e":"荧光原位杂交以荧光标记探针与染色体或细胞核中的DNA、RNA杂交，可在原位显示基因位点及表达产物，用于基因定位分析。Southern、Northern和Western印迹分别检测电泳转移后的DNA、RNA和蛋白质，ChIP研究蛋白质与DNA的相互作用"},{"q":"关于酶的共价修饰，错误的是","o":["一般不需消耗能量","活性和非活性两种形式在不同酶催化下可以互变","催化互变的酶受激素等因素的控制","一般都有活性和非活性两种形式","最常见的共价修饰是多肽链的磷酸化和去磷酸化"],"a":0,"e":"酶的共价修饰（最常见为磷酸化与去磷酸化）需消耗能量，磷酸化由ATP提供磷酸基，故一般不需消耗能量的说法错误。共价修饰存在活性与非活性两种形式，可在不同酶催化下互变，催化互变的酶受激素调控，这些均正确"},{"q":"心房钠尿肽发挥调节作用是通过","o":["cAMP-蛋白激酶途径","cGMP-蛋白激酶途径","Ca2+-CaM激酶途径","RTK-Ras-MAPK途径","JAKs-STAT途径"],"a":1,"e":"心房钠尿肽与靶细胞膜受体结合，激活鸟苷酸环化酶使GTP生成cGMP，进而激活蛋白激酶G，促进排钠利尿与血管舒张。cAMP途径介导肾上腺素、胰高血糖素信号；Ca2+-CaM、RTK-Ras-MAPK与JAK-STAT属其他转导途径"},{"q":"下面有关血红素的叙述，哪一项不正确","o":["是含铁卟啉化合物","有四个吡咯环","是ALA合酶直接催化生成","可进一步转变成胆红素","可与珠蛋白结合生成血红蛋白"],"a":2,"e":"ALA合酶催化琥珀酰CoA与甘氨酸缩合生成ALA，并非直接生成血红素；血红素尚需经胆色素原、尿卟啉原、粪卟啉原、原卟啉Ⅸ等多步，最后由亚铁螯合酶掺入Fe2+而成。血红素含四个吡咯环，与珠蛋白结合为血红蛋白，并可降解为胆红素"},{"q":"PRPP酰胺转移酶活性过高可以导致痛风症，此酶催化","o":["从R-5-P生成PRPP","从甘氨酸合成嘧啶环","从PRPP生成磷酸核糖胺","从IMP合成AMP","从IMP生成GMP"],"a":2,"e":"PRPP酰胺转移酶催化PRPP脱去焦磷酸，接受谷氨酰胺的酰胺氮生成5-磷酸核糖胺，是嘌呤核苷酸从头合成的起始与限速步骤，其活性过高使嘌呤生成过多，尿酸升高而致痛风。该酶不催化PRPP与嘌呤碱的补救反应，那是磷酸核糖转移酶的功能；IMP转变为AMP、GMP属其后分支"},{"q":"下列关于rRNA分子的叙述，错误的是","o":["体内含量最多的RNA","真核细胞有4种rRNA","构成核糖体的组分","是体内最不稳定的RNA","原核生物有3种"],"a":3,"e":"rRNA与多种蛋白质结合成核糖体，是细胞内含量最丰富、寿命较长、代谢最稳定的RNA，故“最不稳定”之说错误。mRNA寿命最短，是体内最不稳定的RNA。rRNA由RNA聚合酶Ⅰ转录45S前体后加工而成，是蛋白质合成中肽键形成的催化组分，其种类与含量随细胞生长状态变化"},{"q":"胰岛素可促进脂肪合成的原因中，不正确的是","o":["可诱导脂酸合成酶的合成","可诱导ATP-柠檬酸裂解酶的合成","可诱导乙酰CoA羧化酶的合成","使乙酰CoA羧化酶磷酸化","促进游离脂肪酸进入脂肪组织"],"a":3,"e":"胰岛素经受体后信号使蛋白磷酸酶激活，乙酰CoA羧化酶去磷酸化而恢复活性，同时诱导脂肪酸合酶、乙酰CoA羧化酶及ATP-柠檬酸裂解酶合成，促进脂肪酸生成。使乙酰CoA羧化酶磷酸化而失活的是胰高血糖素，故“使乙酰CoA羧化酶磷酸化”与胰岛素作用方向相反，不是其促进脂肪合成的原因"},{"q":"在分子生物学技术领域所说的分子克隆是指","o":["建立单克隆抗体","无性繁殖DNA","建立多克隆抗体","构建重组DNA","有性繁殖DNA"],"a":1,"e":"分子克隆指将目的DNA片段与载体重组后导入宿主细胞，随细胞分裂无性繁殖、扩增得到大量相同DNA分子，即无性繁殖DNA。构建重组DNA只是其中一步；单克隆抗体、多克隆抗体属免疫学技术；有性繁殖DNA的说法错误"},{"q":"以下属于单基因遗传病的有","o":["肥胖","肿瘤","高血压","糖尿病","Duchenne氏肌营养不良"],"a":4,"e":"Duchenne肌营养不良由X染色体上抗肌萎缩蛋白基因突变所致，属单基因遗传病中的X连锁隐性遗传。原发性高血压、糖尿病、精神分裂症、哮喘均为多基因病，由多个微效基因与环境共同作用，不符合孟德尔单基因遗传规律，亦无明确的单基因缺陷"},{"q":"外显子是指","o":["基因表达中的调控序列","DNA链中的断裂基因","能够被翻译的编码序列","修饰时被剪除","不能转录的序列"],"a":2,"e":"外显子是断裂基因中保留在成熟mRNA内、可被翻译的编码序列，内含子在剪接中被切除。启动子、增强子等调控序列不转录为编码区，断裂基因指含内含子的基因整体，被剪除的是内含子，故其余各项均与定义不符"},{"q":"研究转录起始点（TSS）的基本方法是","o":["5'RACE","5'SAGE","5'CAGE","报告基因","足迹法"],"a":0,"e":"5'RACE通过锚定引物与基因特异引物扩增cDNA的5'端，可精确确定转录起始点，是研究TSS的基本方法，故为答案。5'SAGE、5'CAGE为高通量转录组相关方法。报告基因用于研究启动子活性。足迹法用于检测蛋白质与DNA结合位点，均非测定TSS的基本方法"},{"q":"下列途径与核酸合成关系密切的是","o":["糖酵解","糖异生","糖原合成","磷酸戊糖途径","三羧酸循环"],"a":3,"e":"磷酸戊糖途径生成5-磷酸核糖，为嘌呤、嘧啶核苷酸的从头合成提供核糖骨架，故与核酸合成关系最密切。糖酵解与糖原合成都只处理葡萄糖的分解与储存，不产生核糖。糖异生以生糖原料合成葡萄糖，三羧酸循环提供能量与草酰乙酸等中间物，也不直接供给核苷酸合成的核糖"},{"q":"以下不属于不依赖染色体定位的疾病相关基因克隆策略的是","o":["依据蛋白质氨基酸序列信息鉴定克隆疾病相关基因","用蛋白质特异性抗体鉴定疾病基因","从疾病的表型差异出发发现疾病相关基因","体细胞杂交法鉴定疾病相关基因","采用动物模型鉴定和克隆疾病相关基因"],"a":3,"e":"不依赖染色体定位的克隆策略从蛋白质或功能表型入手，包括功能克隆、表型克隆、差异显示与表达序列标签等。体细胞杂交法将人与鼠细胞融合，通过染色体丢失与表型对应关系把基因定位于特定染色体，属典型的依赖染色体定位的策略。候选基因克隆与位置克隆亦以染色体定位为前提"},{"q":"有维生素C参与的胶原分子中，羟化反应的氨基酸是","o":["甲硫氨酸","谷氨酸","亮氨酸","赖氨酸","精氨酸"],"a":3,"e":"维生素C是胶原脯氨酸羟化酶与赖氨酸羟化酶的辅因子，催化前胶原中脯氨酸与赖氨酸残基羟化，促进胶原成熟与交联。甲硫氨酸、谷氨酸、亮氨酸、精氨酸不发生依赖维生素C的羟化；维生素C缺乏使胶原合成障碍，导致坏血病"},{"q":"关于酮体的叙述，不正确的是","o":["酮体是肝细胞合成的","酮体的利用主要在肝外组织","酮体合成的原料是乙酰CoA","脑组织不能利用酮体","肝脏不能利用酮体"],"a":3,"e":"脑组织不能氧化脂肪酸，却能有效利用酮体，葡萄糖供应不足时酮体成为其主要能源，故D项错误。酮体在肝合成，原料为乙酰CoA，肝缺乏利用酮体的酶，须运至肝外氧化，A、B、C、E项均正确"},{"q":"有关乳糖操纵子的描述，以下说法错误的是","o":["别乳糖是阻遏蛋白的诱导剂","分解代谢物基因激活蛋白的结合部位是CAP位点","cAMP不是乳糖操纵子正性调控所必需的","低葡萄糖，高乳糖的时候乳糖操纵子高效表达","乳糖操纵子可以保证细菌优先利用葡萄糖"],"a":2,"e":"cAMP与CAP结合后结合CAP位点，是乳糖操纵子正性调控的必要条件，低葡萄糖时cAMP升高、转录高效，故C项错误。别乳糖结合阻遏蛋白使其去阻遏，低葡萄糖高乳糖时表达最强，该机制保证细菌优先利用葡萄糖"},{"q":"在体内生成胆汁酸的原料是","o":["胆汁","胆固醇","胆绿素","血红素","胆素"],"a":1,"e":"肝细胞以胆固醇为原料合成初级胆汁酸，这是胆固醇在体内代谢的主要去路，每日约0.4～0.6g。胆绿素、血红素属胆色素代谢，产物为胆红素；胆汁只是胆汁酸排出的载体，并非合成原料。胆固醇还可转变为类固醇激素与维生素D3，但生成胆汁酸是其主要去路"},{"q":"关于葡糖激酶说法正确的是","o":["基本上是肌肉中的酶","比其他己糖激酶的Km值高","催化生成F-6-P","可被G-6-P激活","催化葡萄糖与无机磷酸生成G-6-P"],"a":1,"e":"葡糖激酶是肝细胞的己糖激酶Ⅳ型，对葡萄糖亲和力低，Km约10mmol/L，远高于己糖激酶Ⅰ的0.2mmol/L，适于血糖升高后启动糖利用。它催化葡萄糖生成6-磷酸葡萄糖而非6-磷酸果糖，不被6-磷酸葡萄糖激活反受其抑制，主要分布于肝与胰岛β细胞"},{"q":"关于糖蛋白生物合成的叙述，错误的是","o":["N-连接型聚糖的合成部位是内质网和高尔基体","N-连接型聚糖的合成与蛋白肽链合成同步进行","O-连接型聚糖的合成在多肽链合成后进行","O-连接型聚糖的合成需要聚糖载体","O-连接型聚糖是在多肽链上逐个加上糖基"],"a":3,"e":"N-连接型聚糖在内质网与高尔基体合成，与肽链合成同步，需长萜醇焦磷酸载体一次性转移14个糖基，连接于Asn-X-Ser/Thr序列的天冬酰胺。O-连接型聚糖在多肽链合成后于高尔基体逐个加糖，不需聚糖载体，故该项错误"},{"q":"1,4,5-三磷酸肌醇（IP3）作用是","o":["在细胞内供能","是肌醇的活化形式","是细胞内第二信使","可直接激活蛋白激酶C（PKC）","细胞膜组成成分"],"a":2,"e":"IP3由磷脂酶C水解PIP2生成，属水溶性第二信使，作用于内质网膜上的IP3受体，促使钙库释放Ca2+，进而激活钙调蛋白与蛋白激酶C。DAG是同时生成的脂溶性第二信使，留在膜上激活蛋白激酶C。IP3不激活腺苷酸环化酶，也不是转录因子或膜受体本身"},{"q":"利用数据库中不同物种间的序列比较分析，拼接，预测新的全长基因等，进而通过实验证实，从组织细胞中克隆该基因的方法称为","o":["电子克隆","定位克隆","细胞克隆","分子克隆","器官克隆"],"a":0,"e":"电子克隆借助数据库同源性比较与不同物种序列拼接，预测全长基因后再经实验验证并从组织细胞中克隆。定位克隆依赖染色体定位，分子克隆指重组DNA操作，细胞克隆与器官克隆属细胞或个体水平技术"},{"q":"关于基因治疗的描述，正确的是","o":["可以使用生殖细胞作为靶细胞","最常用的载体是腺病毒载体","单基因遗传病非常适合进行基因治疗","恶性肿瘤、心脑血管等复杂性疾病不适合进行基因治疗","最为理想的基因治疗方法就是基因增补"],"a":2,"e":"基因治疗目前以体细胞为靶细胞，单基因遗传病因病因单一、明确，最适合用基因增补等方式治疗。生殖细胞涉及伦理与遗传风险，禁止作为靶细胞；常用载体为逆转录病毒，腺病毒并非最常用；肿瘤、心脑血管病等复杂疾病也可作为基因治疗靶点，并非不适合"},{"q":"底物水平磷酸化指","o":["ATP水解为ADP和Pi","底物经分子重排后形成高能磷酸键，经磷酸基团转移使ADP磷酸化为ATP分子","呼吸链上H+传递过程中释放能量使ADP磷酸化为ATP分子","使底物分子加上1个磷酸根","使底物分子水解掉1个ATP分子"],"a":1,"e":"底物水平磷酸化是高能化合物的高能键水解与ADP磷酸化直接偶联，将磷酸基转移给ADP生成ATP，如1,3-二磷酸甘油酸和磷酸烯醇式丙酮酸的反应。C项描述的是氧化磷酸化，经呼吸链电子传递建立质子梯度驱动ATP合酶。D项仅为磷酸化反应，不涉及能量偶联"},{"q":"DNA的一级结构实质上就是","o":["DNA分子中的碱基排列顺序","DNA分子中的碱基配对关系","DNA分子中的各碱基所占的比例","DNA分子的双螺旋结构","DNA分子中的碱基种类"],"a":0,"e":"核酸的一级结构指核苷酸从5′-端到3′-端的排列顺序，因核苷酸之间的差异仅在碱基，故一级结构即碱基排列顺序。碱基配对关系与双螺旋属二级结构内容，碱基比例是Chargaff规则，碱基种类只有四种，均不反映遗传信息的序列特征"},{"q":"在肝中与胆汁酸结合的化合物有","o":["葡萄糖醛酸","牛磺酸","硫酸","甲酸","S-腺苷甲硫氨酸"],"a":1,"e":"胆汁酸在肝内与甘氨酸或牛磺酸结合生成结合胆汁酸，增强亲水性与溶解性，随胆汁排入肠道。葡萄糖醛酸与硫酸是生物转化中常见的结合基团，硫酸亦用于硫酸化石胆酸；甲酸不参与结合反应，SAM提供甲基而非直接与胆汁酸结合"},{"q":"糖蛋白与蛋白聚糖中的蛋白质与糖之间通过哪种作用方式相连","o":["共价键","氢键","疏水作用","范德华力","离子键"],"a":0,"e":"糖蛋白中聚糖与蛋白以共价键相连：N-连接型由N-乙酰葡糖胺与天冬酰胺的酰胺氮相连，O-连接型由N-乙酰半乳糖胺与丝氨酸或苏氨酸的羟基相连。氢键、疏水作用、范德华力、离子键均为维持空间构象的非共价作用，不能形成稳定的糖与蛋白连接"},{"q":"复制中维持DNA单链状态的蛋白质是","o":["RecA","LexA","SSB","DnaB","UvrB"],"a":2,"e":"SSB即单链结合蛋白，与解开的单链DNA结合，防止其重新配对或被核酸酶降解，使模板保持伸展状态。DnaB为解旋酶，负责解开双链；DnaG为引发酶。RecA参与同源重组，LexA为SOS操纵子的阻遏蛋白，UvrB参与核苷酸切除修复"},{"q":"有关酶的活性中心的叙述，正确的是","o":["酶的活性中心包括结合基团和催化基团","酶的活性中心是由一级结构上相互邻近的基团组成的","酶的活性中心在与底物结合时不会发生构象改变","所有酶活性中心都含有辅助因子","酶活性中心外的必需基团也参与对底物的催化作用"],"a":0,"e":"酶的活性中心由结合基团和催化基团组成，前者与底物结合，后者催化底物转变，故该项正确。活性中心由一级结构上相距较远、空间结构上相互邻近的基团组成，并非一级结构邻近。底物结合时常发生诱导契合的构象改变。并非所有酶都含辅助因子。活性中心外的必需基团维持空间结构，不直接参与催化"},{"q":"参与胆固醇逆向转运的血浆脂蛋白是","o":["CM","LDL","HDL","VLDL","IDL"],"a":2,"e":"HDL在肝和小肠合成，新生HDL接受肝外细胞游离胆固醇并酯化，成熟HDL将胆固醇酯运回肝转化为胆汁酸排出，此即胆固醇逆向转运。LDL转运内源性胆固醇至肝外，VLDL与CM分别转运内源性和外源性甘油三酯，均不参与逆向转运"},{"q":"下列物质合成时，需要谷氨酰胺分子上酰胺基的是","o":["TMP上的2个氮原子","嘌呤环上的2个氮原子","UMP上的2个氮原子","嘧啶环上的2个氮原子","腺嘌呤上的氨基"],"a":1,"e":"嘌呤从头合成中，谷氨酰胺的酰胺基提供嘌呤环的N3和N9两个氮原子。甘氨酸提供C4、C5与N7，天冬氨酸提供N1，一碳单位提供C2与C8，CO2提供C6。嘧啶环的氮来自氨甲酰磷酸与天冬氨酸，与谷氨酰胺酰胺基无关"},{"q":"酶原激活的实质是","o":["酶原结合了辅酶或辅基","酶蛋白发生了别构调节","激活剂与酶结合使酶激活","酶原分子的空间构象发生了变化而一级结构不变","酶原分子一级结构发生改变，从而形成或暴露出酶的活性中心"],"a":4,"e":"酶原激活经蛋白酶水解去除一个或几个肽段，一级结构改变使活性中心形成或暴露。别构调节只改变构象而不改一级结构，辅酶或辅基结合也不是激活的实质；胰蛋白酶原去除六肽即为典型实例。酶原激活具级联放大效应，消化酶与凝血因子的激活均依赖逐级水解"},{"q":"链霉素阻断蛋白质生物合成的机制是","o":["与核糖体小亚基结合","与核糖体大亚基结合","阻碍氨基酸-tRNA进入“受位”","抑制转肽酶活性","过早终止多肽链合成"],"a":0,"e":"链霉素与细菌核糖体30S小亚基结合，引起读码错误并抑制蛋白质合成。氯霉素与大环内酯类结合50S大亚基、抑制肽酰转移酶，嘌呤霉素使肽链提前脱落，四环素阻碍氨酰-tRNA进入A位，均非链霉素的机制"},{"q":"乳糖、阿拉伯糖、色氨酸等小分子物质在基因表达调控中作用的共同特点是","o":["与转录起始位点结合影响模板活性","与RNA聚合酶结合影响其活性","与启动序列结合影响模板活性","与操纵序列结合影响模板活性","与蛋白质结合影响后者结合DNA"],"a":4,"e":"乳糖、阿拉伯糖、色氨酸等小分子效应物并不直接与DNA结合，而是与调控蛋白（阻遏蛋白或激活蛋白）结合，引起其构象改变，进而影响对操纵序列等DNA的结合能力以调控转录，故为共同特点。它们不与转录起始位点、启动序列或RNA聚合酶直接结合，也不是直接与操纵序列结合，而是通过蛋白质中介发挥作用"},{"q":"可检索已知基因的SNP位点的数据库是","o":["NCBI的dbSNP数据库","NCBI的GEO数据库","SWISS-PROT数据库","LIPID Maps数据库","CCSD数据库"],"a":0,"e":"dbSNP收录已知基因的SNP、插入缺失等多态位点及其频率信息。GEO存储基因表达谱数据，SWISS-PROT为蛋白质序列数据库，LIPID Maps为脂质分类数据库，CCSD为晶体结构数据库"},{"q":"在同一种哺乳动物细胞中，理论上叙述正确的是","o":["在过剩的DNA存在下，所有RNA都能与DNA杂交","在过剩的RNA存在下，所有DNA片段能与RNA杂交","RNA与DNA有相同的碱基比例","RNA与DNA有相同核苷酸组成","RNA和DNA含量相同"],"a":0,"e":"细胞内RNA种类多于DNA，且每种RNA的分子数远多于其模板，故过量DNA时所有RNA都能找到互补序列杂交。反之DNA中大量非转录序列无对应RNA，不能全部杂交；RNA与DNA的碱基组成和含量均不同，RNA含尿嘧啶与核糖"},{"q":"以下不是嘧啶核苷酸分解代谢产物的是","o":["NH3","CO2","β-丙氨酸","β-氨基异丁酸","尿酸"],"a":4,"e":"嘧啶核苷酸分解为NH3、CO2与β-丙氨酸（胞嘧啶）或β-氨基异丁酸（胸腺嘧啶），产物均易溶于水。尿酸是嘌呤核苷酸分解的终产物，水溶性差，其蓄积与痛风相关。胞嘧啶生成β-丙氨酸，胸腺嘧啶生成β-氨基异丁酸，据此可区分两者"},{"q":"奇数碳原子脂肪酸分解产生丙酰辅酶A彻底氧化分解时，需首先转变为","o":["琥珀酰辅酶A","酮体","乙酰辅酶A","丙酮酸","苹果酸"],"a":0,"e":"奇数碳脂肪酸经β-氧化末轮生成丙酰CoA，经丙酰CoA羧化酶作用生成甲基丙二酰CoA，再由变位酶催化转变为琥珀酰CoA，进入三羧酸循环氧化。乙酰CoA是偶数碳脂肪酸的终产物，酮体、丙酮酸、苹果酸均非此途径的中间物"},{"q":"小G蛋白是","o":["G蛋白的亚基","Grb-2结合蛋白","蛋白激酶G","Ras蛋白","Raf蛋白"],"a":3,"e":"小G蛋白是单体GTP结合蛋白，典型代表为Ras蛋白，参与细胞增殖信号转导并具有GTP酶活性。G蛋白亚基指异三聚体G蛋白的α、β、γ亚基；Grb-2是接头蛋白；蛋白激酶G是cGMP依赖的激酶；Raf是丝氨酸苏氨酸激酶，均为通路其他成员"},{"q":"在催化反应中不需要模版的酶是","o":["RNA聚合酶","引物酶","DNA聚合酶","端粒酶","DNA拓扑异构酶Ⅰ"],"a":4,"e":"DNA聚合酶、RNA聚合酶、引物酶均按模板互补规则掺入核苷酸，端粒酶以自带RNA为模板合成端粒重复序列，均需模板。拓扑异构酶Ⅰ只切断单链、使断端绕过缺口后再连接，改变超螺旋而不拷贝模板，故不需模板"},{"q":"调节血糖最主要的器官是","o":["肾","脑","肌肉","肾上腺","肝"],"a":4,"e":"肝是调节血糖的中心器官，通过糖原合成与分解、糖异生等维持血糖稳定，胰岛素与胰高血糖素亦主要作用于肝。肾在长期饥饿时参与糖异生，贡献次于肝。脑为耗能器官，几乎不参与血糖调节。肌肉缺乏葡萄糖-6-磷酸酶，肌糖原不能补充血糖。肾上腺分泌激素间接调节，非直接调节器官"},{"q":"一个利用poly(A)引物制备的肝细胞cDNA文库包含","o":["肝细胞的全部基因信息","肝细胞来源个体的全部基因信息","肝细胞的全部RNA信息","肝细胞来源个体的全部RNA信息","在获取肝细胞时，其所转录的mRNA信息"],"a":4,"e":"以poly(A)为引物逆转录，模板只能是带poly(A)尾的mRNA，文库反映取材时该细胞转录的mRNA信息。它不含基因组全部基因，也不代表个体全部基因或全部RNA，rRNA与tRNA无poly(A)尾而未被逆转录"},{"q":"处方药抗凝血剂华法林，在给出处方前，需要对CYP2C9、VKORC1进行基因检测，该研究属于","o":["药物基因组学","结构基因组学","SNP位点分析","疾病基因组学","转录组学"],"a":0,"e":"华法林经CYP2C9代谢、靶点为VKORC1，检测这两个基因的变异可预测疗效与出血风险，属研究基因变异与药物反应关系的药物基因组学。结构基因组学测定基因组序列与结构，疾病基因组学寻找致病基因，转录组学研究RNA表达，SNP位点分析只是检测手段"},{"q":"与甲硫氨酸、胆碱、脱氧胸苷酸等合成有关的维生素是","o":["维生素B6","维生素B12","维生素C","维生素PP","维生素A"],"a":1,"e":"维生素B12以甲钴胺素形式作为N5-CH3-FH4转甲基酶的辅因子，催化同型半胱氨酸生成甲硫氨酸，使四氢叶酸再生，一碳单位得以用于胆碱和脱氧胸苷酸的合成。维生素B6参与转氨基与脱羧，维生素C为羟化酶辅因子，维生素PP构成NAD+"},{"q":"别嘌呤醇治疗痛风的原理是","o":["别嘌呤醇与次黄嘌呤结构类似，可抑制黄嘌呤氧化酶，从而抑制尿酸的生成","降低HGPRT活性，限制嘌呤核苷酸的补救合成","促进尿酸的排泄","增加尿酸的水溶性","促进尿酸的分解"],"a":0,"e":"别嘌呤醇是次黄嘌呤的类似物，抑制黄嘌呤氧化酶，阻断次黄嘌呤、黄嘌呤转化为尿酸，降低血尿酸；其生成的别嘌呤核苷酸还可消耗PRPP并反馈抑制从头合成。它不促进尿酸排泄或分解，也不降低HGPRT活性"},{"q":"能直接结合氧的细胞色素类是","o":["Cyt b","Cyt a3","Cyt c1","Cyt c","Cyt P"],"a":1,"e":"复合体Ⅳ中Cyta3与CuB构成双核中心，直接结合O2并将其还原为水，是呼吸链中唯一直接结合氧的细胞色素。Cyt b、Cyt c1、Cyt c只传递电子不结合氧；Cyt P450属加单氧酶系，位于内质网，参与生物转化，与呼吸链递氧无关"},{"q":"通过胞内受体发挥作用的信息物质为","o":["乙酰胆碱","γ-氨基丁酸","胰岛素","甲状腺素","表皮生长因子"],"a":3,"e":"甲状腺素为疏水激素，可透过脂双层进入细胞，与核内受体结合调控基因转录。乙酰胆碱、γ-氨基丁酸为神经递质，作用于膜受体；胰岛素、表皮生长因子为肽类，与膜表面受体结合。类固醇激素与1,25-(OH)2-D3同属胞内受体激素"},{"q":"必需氨基酸是指","o":["体内合成量少，需由食物供给的氨基酸","合成蛋白质的编码氨基酸","合成蛋白质与核苷酸不可缺少的氨基酸","体内不能合成，需由食物供给的氨基酸","非成糖氨基酸"],"a":3,"e":"必需氨基酸指体内不能合成、必须由食物供给的氨基酸，共9种，包括亮氨酸、异亮氨酸、缬氨酸、苏氨酸、赖氨酸、甲硫氨酸、苯丙氨酸、色氨酸和组氨酸。A项所说合成量少只适用于精氨酸，其仍归非必需。B项为编码氨基酸的概念，E项描述的是生酮氨基酸"},{"q":"HDL的生理功能是","o":["转运内源性TG","转运外源性TG","将胆固醇从肝外组织转运至肝","从肝内到肝外组织转运胆固醇","运输自由的脂酸"],"a":2,"e":"HDL将肝外组织多余胆固醇经卵磷脂胆固醇酰基转移酶酯化后逆向转运至肝，完成胆固醇逆向转运。CM转运外源性甘油三酯，VLDL转运内源性甘油三酯，LDL把肝内胆固醇运至肝外；游离脂肪酸由清蛋白运输"},{"q":"关于关键酶的叙述，哪一项是错误的","o":["关键酶常位于代谢途径的第一步反应","关键酶在代谢途径中活性最低","关键酶常是别构酶","受激素调节的酶常是关键酶","关键酶催化反应是可逆的"],"a":4,"e":"关键酶催化代谢途径中单向不可逆的限速反应，其逆反应需由另一条途径的酶催化，故反应不可逆。关键酶常位于途径第一步或分支点，活性最低、多为别构酶，并常受激素调节，A、B、C、D四项均为关键酶的正确特征"},{"q":"关于核糖体转肽酶，错误的描述是","o":["转肽酶的化学本质不是蛋白质","转肽酶可以催化两个氨基酸间肽键的形成","活性中心在小亚基","活性中心在大亚基","活性中心与rRNA有关"],"a":2,"e":"转肽酶活性存在于大亚基，其活性中心由rRNA构成，本质是核酶而非蛋白质，催化P位肽酰基转移至A位氨酰tRNA的氨基形成肽键。小亚基负责结合mRNA与氨酰tRNA、参与译码。C项称活性中心在小亚基，与事实相反"},{"q":"在人体禁食阶段，脂肪动员释放出来的甘油主要的去向是","o":["在脂肪组织氧化成CO2和H2O","在肝细胞转变成酮体","在脂肪组织合成甘油三酯","在肝细胞合成葡萄糖","在肝细胞氧化成CO2和H2O"],"a":3,"e":"脂肪动员释出的甘油经血入肝，在甘油激酶作用下生成3-磷酸甘油，脱氢为磷酸二羟丙酮后循糖异生合成葡萄糖。脂肪组织缺乏甘油激酶，不能氧化或再利用甘油；肝也不将甘油直接转变为酮体。甘油经糖异生生成的葡萄糖可补充血糖，饥饿时约占糖异生原料的一成"},{"q":"下列哪种物质仅由肝脏合成","o":["糖原","胆固醇","脂肪酸","血浆蛋白","尿素"],"a":4,"e":"尿素是鸟氨酸循环的终产物，该循环的关键酶仅存在于肝脏，故尿素几乎只由肝脏合成。糖原在肝和肌肉均可合成；胆固醇在全身多种组织合成；脂肪酸在肝、脂肪等组织合成；血浆蛋白中免疫球蛋白由浆细胞产生，并非仅由肝脏合成"},{"q":"营养物质代谢脱下的成对氢原子以还原当量形式存在，再通过多种酶和辅酶催化的氧化还原的连锁反应逐步传递，最终与氧结合成水。在氧化呼吸链中，参与氧化还原作用的酶和辅酶按一定顺序排列在线粒体内膜上。在呼吸链电子传递过程中偶联ATP的生成，这就是氧化磷酸化。1个完整的三羧酸循环中生成的FADH2，在进入氧化磷酸化后可以产生多少ATP","o":["1","1、5","3","4","2"],"a":1,"e":"FADH2经复合体Ⅱ入链，跨越的质子泵较少，氧化磷酸化生成1.5分子ATP；NADH为2.5分子，乙酰CoA经三羧酸循环为10分子。1与2是旧版按整数计算的结果，3为每分子NADH的旧值，4无对应依据"},{"q":"胰高血糖素与相应受体结合激活Gs蛋白后主要引起","o":["激活受体型酪氨酸蛋白激酶","激活非受体型酪氨酸蛋白激酶","激活磷脂酰肌醇特异的磷脂酶C（PI-PLC","激活鸟甘酸环化酶","激活腺苷酸环化酶"],"a":4,"e":"胰高血糖素受体为GPCR，结合后激活Gs蛋白，α亚基激活腺苷酸环化酶，使cAMP生成增多进而激活PKA。受体型与非受体型酪氨酸激酶属酶联受体通路，与Gs无关。磷脂酶C由Gq蛋白激活产生IP3与DAG。鸟苷酸环化酶受心房钠尿肽等激活产生cGMP，均非Gs蛋白的效应"},{"q":"关于启动子的叙述，正确的是","o":["mRNA开始被翻译的序列","开始转录生成mRNA的DNA序列","RNA聚合酶开始结合的DNA序列","阻遏蛋白结合DNA的部位","产生阻遏物的基因"],"a":2,"e":"启动子是RNA聚合酶识别、结合并启动转录的一段DNA序列，位于转录起始点上游，属顺式作用元件。操纵序列才是阻遏蛋白结合的部位，mRNA开始翻译的序列是核糖体结合位点与起始密码子，产生阻遏物的基因是调节基因"},{"q":"只能传递电子的物质是","o":["NAD＋","cyt c","FAD","FMN","CoQ"],"a":1,"e":"细胞色素c为单电子传递体，通过血红素铁的Fe3+与Fe2+互变传递电子，不能传递质子或氢原子。NAD+、FAD、FMN、CoQ均可传递氢即电子加质子，其中FMN、FAD与CoQ为双电子递体，故只有Cyt c仅传递电子"},{"q":"N-连接型聚糖的五糖核心为","o":["GlcNAc-GlcNAc-Man-(Man)2","GlcNAc-GalNAc-Man-(Man)2","alNAc-GlcNAc-Man-(Man)2","GalNAc-GalNAc-Man-(Man)2","GlcNAc-GlcNAc-GalNAc-(Man)2"],"a":0,"e":"N-连接型聚糖的核心为2个N-乙酰葡萄糖胺和3个甘露糖，即GlcNAc-GlcNAc-Man-(Man)2，高甘露糖型、复杂型与杂合型均在此核心上延伸。核心不含GalNAc，GalNAc是O-连接型聚糖的特征成分"},{"q":"别乳糖在乳糖操纵子表达中的作用是","o":["作为辅阻遏物结合阻遏物","作为阻遏物结合操纵序列","作为引物引导聚合反应","使阻遏物变构而失去结合DNA的能力","作为该操纵子结构基因的产物"],"a":3,"e":"别乳糖是乳糖的异构体，作为诱导物结合阻遏蛋白，使其构象改变而失去结合操纵序列的能力，操纵子去阻遏。辅阻遏物是色氨酸等与阻遏蛋白结合后促进阻遏的分子；别乳糖由β-半乳糖苷酶作用于乳糖生成，并非结构基因产物"},{"q":"AMP分子中第六位碳原子上的氨基来源于","o":["谷氨酰胺的酰胺基","谷氨酸","天冬酰胺的酰胺基","甘氨酸","天冬氨酸"],"a":4,"e":"嘌呤从头合成中，IMP的C6位氨基由天冬氨酸提供，IMP转变为AMP时又经腺苷酸代琥珀酸途径由天冬氨酸供氨，故AMP的C6氨基来自天冬氨酸。谷氨酰胺的酰胺氮提供嘌呤环N3与N9，甘氨酸提供C4、C5与N7，CO2提供C6碳原子"},{"q":"AUC为异亮氨酸的密码子，tRNA中与其相应的反密码子应为","o":["UAG","TAG","GAU","GAT","LAG"],"a":2,"e":"密码子与反密码子按反向平行互补配对，A对U、U对A、C对G，故AUC对应的反密码子为GAU。T只存在于DNA，含T的选项可直接排除。GAT虽碱基相同，但书写方向与配对关系不符。反密码子环居中的3个核苷酸承担识别功能，摆动配对只发生在第1位"},{"q":"将标记的核酸探针与细胞或组织中的核酸进行杂交，称为","o":["杂交前处理","预杂交","原位杂交","Northern印迹杂交","免疫印迹"],"a":2,"e":"原位杂交用标记核酸探针直接与细胞涂片或组织切片中的DNA或RNA杂交，实现核酸的定位、定性和定量。预杂交与杂交前处理是原位杂交的操作步骤，Northern印迹检测电泳转移后的RNA，免疫印迹检测蛋白质"},{"q":"绝大多数真核生物mRNA的5'端有","o":["poly(A)","终止密码","帽子结构","Pribnow盒","起始密码"],"a":2,"e":"绝大多数真核生物mRNA的5'端具有帽子结构（7-甲基鸟苷帽），可保护mRNA、协助剪接与翻译起始。poly(A)尾位于3'端；起始密码子位于编码区起始；终止密码在编码区末端；Pribnow盒是原核启动子元件，均不在mRNA的5'端"},{"q":"真核生物基因组中没有的是","o":["内含子","外显子","增强子","转录因子","高度重复序列"],"a":3,"e":"真核生物基因组由DNA序列组成，包含内含子、外显子、增强子及高度重复序列等元件；转录因子是结合DNA调控转录的蛋白质，由基因编码但本身不是基因组的结构成分，故真核生物基因组中没有转录因子"},{"q":"核酸分子杂交可发生在DNA与DNA之间、DNA与RNA之间。可与单链DNA5'-CGGTA-3'发生杂交的RNA是","o":["5'-GCCAU-3'","5'-GCCUU-3'","5'-UACCG-3'","5'-UAGGC-3'","5'-AUCCG-3'"],"a":2,"e":"核酸杂交要求两条链反向平行且碱基互补。DNA链5'-CGGTA-3'的互补序列为3'-GCCAU-5'，写成5'→3'方向即5'-UACCG-3'。以GCCAU开头的两项方向与互补关系不符，另两项碱基配对存在错配，均不能与该单链DNA完全杂交"},{"q":"对原核肽链合成延长的转位步骤叙述，正确的是","o":["卸载tRNA直接从P位分离","转位由延长因子EF-G促进","肽酰-tRNA从P位进入A位","转位过程需水解ATP提供能量","转位后肽酰-tRNA占据E位"],"a":1,"e":"转位由延长因子EF-G即转位酶催化，需GTP水解供能，使肽酰-tRNA由A位移至P位、空载tRNA移入E位后脱落。EF-G水解的是GTP而非ATP，卸载tRNA先进入E位而非直接从P位分离，肽酰-tRNA的移动方向是A→P而非P→A"},{"q":"三羧酸循环中底物水平磷酸化产生的高能化合物是","o":["ATP","GTP","CTP","TTP","UTP"],"a":1,"e":"三羧酸循环中琥珀酰CoA合成酶催化琥珀酰CoA生成琥珀酸，同时使GDP磷酸化生成GTP，为循环中唯一的底物水平磷酸化。ATP可由GTP转变而来但不是该步直接产物，CTP、UTP、TTP不参与此反应"},{"q":"肝脏所特有的代谢反应是","o":["将糖转变为脂肪","由胆固醇转变为胆汁酸","糖异生","生物转化","生物氧化"],"a":1,"e":"胆固醇转化为胆汁酸只能由肝细胞完成，肝以胆固醇为原料合成初级胆汁酸，是胆固醇在体内的主要去路，每日约0.4～0.6g。将糖转变为脂肪、糖异生、生物转化、生物氧化在肝外组织如脂肪组织、肾、肠黏膜也可进行，并非肝所特有"},{"q":"维生素K依赖性γ-羧化酶激活凝血因子是使","o":["谷氨酸残基羧化","天冬氨酸残基羧化","酪氨酸残基羧化","组氨酸残基羧化","赖氨酸残基羧化"],"a":0,"e":"维生素K是γ-谷氨酰羧化酶的辅因子，使凝血因子前体中的谷氨酸残基羧化为γ-羧基谷氨酸，从而结合Ca2+。天冬氨酸、酪氨酸、组氨酸、赖氨酸残基均非该酶底物；骨钙蛋白的羧化同样依赖维生素K"},{"q":"下列哪种信息分子所激发的信号转导与STAT（信号转导及转录激活因子）关系最密切","o":["心房钠尿肽","甲状旁腺激素","肾上腺素","孕激素","干扰素"],"a":4,"e":"干扰素通过JAK-STAT信号通路发挥作用，受体结合后激活JAK使STAT磷酸化、二聚化入核调控基因表达，故与STAT关系最密切。心房钠尿肽经鸟苷酸环化酶-cGMP通路；甲状旁腺激素经cAMP-PKA；肾上腺素经cAMP或IP3；孕激素经胞内受体，均非STAT通路"},{"q":"白血病是恶性增殖性疾病，白血病细胞在机体内无限增殖，合成代谢和分解代谢都很旺盛，导致蛋白质和氨基酸代谢紊乱，使机体状况恶化。对白血病人血浆进行代谢组学的分析，以下哪种成分会较正常人低","o":["Glu","Gln","Gly","Phe","Lys"],"a":1,"e":"白血病细胞增殖旺盛，大量摄取谷氨酰胺作为碳源与氮源，血浆谷氨酰胺被快速消耗而降低。谷氨酸、甘氨酸、苯丙氨酸与赖氨酸并非肿瘤细胞的主要消耗氨基酸，其血浆水平相对稳定。肿瘤细胞有氧糖酵解增强，乳酸与谷氨酰胺代谢随之明显改变"},{"q":"可用于基因组DNA分析的方法是","o":["Southern blotting","Northern blotting","Western blotting","斑点杂交","质谱技术"],"a":0,"e":"Southern印迹法将电泳分离的DNA转印至硝酸纤维素膜或尼龙膜，再用标记探针杂交，用于基因组DNA的定性和定量分析，是最经典的基因诊断方法。Northern印迹法检测的是RNA，Western印迹法检测的是蛋白质，斑点杂交不经电泳、仅点样定性，质谱用于蛋白质与代谢物分析"},{"q":"不能利用酮体的细胞是","o":["脑细胞","骨骼肌细胞","心肌细胞","脂肪细胞","肝细胞"],"a":4,"e":"肝细胞缺乏琥珀酰CoA转硫酶及乙酰乙酸硫激酶，不能活化乙酰乙酸，故只生成酮体而不能利用酮体。脑、骨骼肌、心肌均含酮体利用酶，饥饿时脑与心肌利用酮体显著增加。脂肪细胞主要承担脂肪动员与储存，并非酮体的重要利用者"},{"q":"下面关于必需氨基酸的叙述错误的是","o":["食物蛋白质的营养价值取决于其中所含必需氨基酸的有无和多少","人体所需要的氨基酸有8种，其中包括半胱氨酸和酪氨酸","必需氨基酸的必需性可因生理状态而改变","动物的种类不同，其所需要的必需氨基酸也不同","植物含有人体所必需的各种氨基酸，有些氨基酸是人体不能合成的"],"a":1,"e":"人体必需氨基酸有8种，半胱氨酸和酪氨酸为条件必需氨基酸，可由蛋氨酸和苯丙氨酸转变而来，不属8种必需氨基酸，故该项错误。食物蛋白营养价值取决于必需氨基酸的种类与含量。必需性可随生理状态改变。不同动物所需必需氨基酸不同。植物含各类氨基酸，其中部分人体不能合成"},{"q":"某蛋白在肺癌中高表达，若确定该蛋白在肺癌发生过程中的作用，可采用的方法","o":["Crispr/Cas9","EST序列分析","SNP分析","BLAST分析","SAGE分析"],"a":0,"e":"要确定该蛋白在肺癌发生中的作用，需在细胞或动物中敲除或敲入其基因，观察增殖与成瘤能力变化，CRISPR/Cas9可定向编辑基因组实现这一目的。EST、SAGE与SNP分析属表达谱或变异筛查，BLAST为序列比对，均不能验证功能"},{"q":"DNA的生物合成方向是","o":["3'→5'","C→N","5'→3'","N→C","从两侧向中心"],"a":2,"e":"DNA聚合酶只能将新核苷酸加到延伸链的3'-OH端，故DNA链的合成方向为5'→3'，为答案。3'→5'为模板链的阅读方向而非合成方向。C→N、N→C为多肽链合成方向。从两侧向中心不符合DNA半保留复制的延伸特征"},{"q":"使细胞内环化腺苷酸（cAMP）水平升高的因素有","o":["蛋白激酶A","磷酸二脂酶","磷脂酶C","腺苷酸环化酶","蛋白激酶C"],"a":3,"e":"腺苷酸环化酶催化ATP生成cAMP，是细胞内cAMP的唯一生成酶，其活性升高直接提高cAMP水平。磷酸二酯酶催化cAMP水解为5′-AMP，作用相反。蛋白激酶A是cAMP的靶酶，蛋白激酶C由DAG和Ca2+激活，磷脂酶C水解PIP2生成IP3与DAG，均不升高cAMP"},{"q":"基因组代表一个细胞或生物体的","o":["整套遗传信息","部分遗传信息","可转录基因","非转录基因","可表达基因"],"a":0,"e":"基因组是一个细胞或生物体所携带的全套遗传信息，即所有DNA序列的总和。可转录基因、可表达基因和非转录基因都只是基因组的一部分，部分遗传信息的表述也不完整，均不能代表其整体"},{"q":"当肝功能严重受损时，合成及释入血中的LCAT降低，因此血中将出现","o":["胆固醇总量降低","游离胆固醇量降低","游离胆固醇占总胆固醇的比例降低","胆固醇酯占总胆固醇的比例降低","胆固醇酯占总胆固醇的比例升高"],"a":3,"e":"LCAT由肝合成并分泌入血，催化卵磷脂的脂酰基转移至游离胆固醇生成胆固醇酯。肝功能严重受损时LCAT减少，游离胆固醇酯化受阻，胆固醇酯占总胆固醇比例降低，游离胆固醇比例升高，总胆固醇亦下降但非特征性改变"},{"q":"稀有核苷酸一般存在于","o":["tRNA","mRNA","rRNA","线粒体DNA","核仁DNA"],"a":0,"e":"稀有核苷酸（如假尿苷、二氢尿苷、甲基化碱基）主要存在于tRNA，由转录后修饰形成，参与维持tRNA结构与密码识别。mRNA、rRNA中稀有碱基很少；线粒体DNA和核仁DNA是DNA，含常规脱氧核苷酸，不属于稀有核苷酸的主要分布处"},{"q":"缺氧情况下，糖酵解途径生成的NADH和H+的去路是","o":["进入呼吸链氧化供应能量","丙酮酸还原为乳酸","3-磷酸甘油酸还原为3-磷酸甘油醛","醛缩酶的辅助因子合成1，6-双磷酸果糖","醛缩酶的辅助因子分解1，6-双磷酸果糖"],"a":1,"e":"缺氧时呼吸链受阻，NADH不能经氧化磷酸化再生NAD+，胞质中NADH+H+由乳酸脱氢酶催化，将丙酮酸还原为乳酸，使NAD+再生，糖酵解得以继续。A项是有氧条件下的去路。C项方向相反，是耗氢的还原反应，并非NADH的出口"},{"q":"能被甲氨蝶呤拮抗的维生素是","o":["硫胺素","维生素A","叶酸","生物素","核黄素"],"a":2,"e":"甲氨蝶呤是叶酸类似物，竞争性抑制二氢叶酸还原酶，使四氢叶酸生成减少、一碳单位转移受阻，从而抑制嘌呤与胸腺嘧啶核苷酸合成。硫胺素、核黄素、生物素和维生素A各有其他辅酶功能，与其结构无相似性"},{"q":"关于核酶，下列描述不正确的是","o":["可催化特定的RNA降解","在研究rRNA的自剪接过程中发现的","具有酶活性的RNA分子","是核酸与蛋白质共同组成的酶","于20世纪80年代发现"],"a":3,"e":"核酶是具有催化活性的RNA，20世纪80年代初在研究四膜虫rRNA前体自我剪接时发现，可催化RNA链的切割与连接。核酸与蛋白质共同组成的酶是缀合酶即全酶，其催化作用来自酶蛋白，与核酶本质不同；核酶不含蛋白质组分，故该描述不正确"},{"q":"下列哪种物质，抑制电子从Cyt a3到氧之间的传递","o":["鱼藤酮","2,4-二硝基苯酚","抗毒素","寡毒素","一氧化碳"],"a":4,"e":"一氧化碳（以及氰化物）可与细胞色素氧化酶中Cyt a3结合，阻断电子由Cyt a3向氧的传递，使呼吸链中断。鱼藤酮抑制复合体Ⅰ的电子传递；2,4-二硝基苯酚是解偶联剂；寡霉素抑制ATP合酶，三者均不阻断Cyt a3到氧的环节"},{"q":"能通过线粒体内膜的物质有","o":["苹果酸","α-磷酸甘油","谷氨酰胺","草酰乙酸","琥珀酸"],"a":0,"e":"草酰乙酸不能直接透过线粒体内膜，需在线粒体内还原为苹果酸或转氨为天冬氨酸再运出，故苹果酸可经苹果酸-α-酮戊二酸转运体通过内膜。α-磷酸甘油穿梭运送的是还原当量，其本身不能自由穿越；谷氨酰胺、琥珀酸亦不能自由通过。草酰乙酸正是明确不能直接透过者"},{"q":"终产物不是尿酸的是","o":["AMP","UMP","IMP","GMP","ATP"],"a":1,"e":"UMP是嘧啶核苷酸，分解为NH3、CO2和β-丙氨酸，不生成尿酸。AMP、IMP与GMP经黄嘌呤氧化酶作用终产物均为尿酸，ATP经ADP、AMP降解亦归于尿酸，故只有UMP例外。嘧啶分解产物均易溶于水，故嘧啶代谢异常不引起痛风"},{"q":"tRNA分子上3′端序列的功能是","o":["稳定tRNA分子","提供3'-羟基与氨基酸结合","形成局部双链","识别mRNA分子","便于翻译蛋白质"],"a":1,"e":"tRNA的3'端为CCA序列，其末端腺苷的3'-羟基是氨基酸共价连接的位点，由氨酰-tRNA合成酶催化负载氨基酸。稳定分子靠稀有碱基和茎环结构；形成局部双链是二级结构特征；识别mRNA靠反密码子环，均非3'端CCA的功能"},{"q":"下列哪种RNA不需要在细胞核内进一步加工修饰","o":["pre-tRNA","mRNA","pre-rRNA","hnRNA","pri-miRNA"],"a":1,"e":"所给选项中pre-tRNA、pre-rRNA、hnRNA、pri-miRNA均为初级转录产物，需在细胞核内剪接、修饰加工；mRNA由hnRNA加工而来，已具帽子、poly(A)尾并去除内含子，不需再在细胞核内进一步加工，故不需加工的是mRNA"},{"q":"可产生五碳糖的途径是","o":["磷酸戊糖途径","糖酵解","糖异生","糖有氧氧化","糖原代谢"],"a":0,"e":"磷酸戊糖途径以葡萄糖-6-磷酸为起点，经氧化阶段生成5-磷酸核糖和NADPH，为核苷酸合成提供核糖，为脂肪酸等合成提供还原力。糖酵解、糖异生、有氧氧化主要处理三碳、六碳磷酸酯；糖原代谢只在糖原与葡萄糖-6-磷酸之间转换"},{"q":"在代谢的研究中，第一个被阐明的循环途径是","o":["鸟氨酸循环","三羧酸循环","丙氨酸-葡萄糖循环","Cori循环","尿素的肠肝循环"],"a":0,"e":"1932年Krebs与Henseleit提出尿素合成经鸟氨酸、瓜氨酸、精氨酸的循环，即鸟氨酸循环，是第一个被阐明的代谢循环。三羧酸循环1937年才被提出，时间在后。磷酸戊糖途径、糖酵解途径与甲硫氨酸循环均在其后阐明，糖酵解虽早期已知，但并非以循环形式描述"},{"q":"在生理pH情况下，下列氨基酸的混合物在电场中有多种氨基酸向正极移动，其中移动最快的是","o":["Pro","Lys","His","Glu","Gly"],"a":3,"e":"生理pH下氨基酸的净电荷取决于侧链基团，Glu侧链羧基解离带负电、等电点约3.22，净负电荷最多，向正极泳动最快。Lys与His带正电向负极移动，Pro和Gly侧链不解离、净电荷近零，几乎不泳动"},{"q":"脂蛋白脂肪酶催化","o":["脂肪细胞中甘油三酯的水解","肝细胞中甘油三酯的水解","VLDL中甘油三酯的水解","HDL中甘油三酯的水解","Lp(a)中的甘油三酯的水解"],"a":2,"e":"脂蛋白脂肪酶位于毛细血管内皮细胞表面，由apoCⅡ激活，水解CM与VLDL内核的甘油三酯，释放甘油与游离脂肪酸供组织摄取。脂肪细胞与肝细胞内的甘油三酯由激素敏感性脂肪酶和ATGL水解，HDL含甘油三酯少且非其主要底物"},{"q":"谷胱甘肽过氧化物酶中含有的微量元素是","o":["铬","锌","锰","硒","铜"],"a":3,"e":"谷胱甘肽过氧化物酶以硒代半胱氨酸为活性中心，催化H2O2和脂质过氧化物还原，保护膜结构，故其微量元素为硒。超氧化物歧化酶的辅基含铜、锌或锰，过氧化氢酶与细胞色素氧化酶含铁，均不含硒。硒缺乏与克山病有关"},{"q":"假设目的基因插入载体lacZ基因内，利用α互补筛选转化子细胞，其阳性菌落应为","o":["白色","红色","蓝色","绿色","黄色"],"a":0,"e":"目的基因插入lacZ基因内部后，α片段不能正常表达，β-半乳糖苷酶无α互补活性，不能水解X-gal，菌落呈白色，即为重组转化子。未插入外源基因的转化菌lacZ完整，水解X-gal生成蓝色产物，菌落呈蓝。红、绿、黄均非该显色系统的结果；蓝白筛选正是据此区分重组与未重组"},{"q":"关于真核细胞RNA的叙述，错误的是","o":["mRNA主要存在于细胞质中","tRNA分子中的稀有碱基是转录后修饰而成的","有mRNA、tRNA、rRNA三种","mRNA中含有遗传密码","rRNA在细胞内含量最多"],"a":2,"e":"真核细胞RNA除mRNA、tRNA、rRNA三大类外，还有snRNA、snoRNA、miRNA、lncRNA等多种非编码RNA，故有mRNA、tRNA、rRNA三种的表述错误。mRNA主要位于细胞质；tRNA稀有碱基为转录后修饰形成；mRNA含遗传密码；rRNA在细胞内含量最多，均正确"},{"q":"下列对于突变的描述正确的是","o":["都是由有害因素引起的有害结果","反映遗传的保守性","自然突变频率很低，可以忽略","一定会引起功能受损","是进化的基础"],"a":4,"e":"基因突变是随机发生的遗传信息改变，为生物进化提供原材料，是进化的分子基础。突变有自发与诱发两类，并非都由有害因素引起，也不必然损害功能，可不改变表型而形成多态性。自然突变频率虽低，却不能忽略其累积效应，故E项正确"},{"q":"1'-焦磷酸-5'-磷酸核糖（PRPP）不参与的反应是","o":["由腺嘌呤转变为腺苷酸","由鸟嘌呤转变为鸟苷酸","由次黄嘌呤转变为次黄苷酸","乳清酸的生成","嘧啶生物合成中乳清酸核苷酸的生成"],"a":3,"e":"PRPP是嘌呤、嘧啶补救合成的磷酸核糖供体，腺嘌呤、鸟嘌呤、次黄嘌呤经各自的磷酸核糖转移酶接受PRPP生成相应核苷酸。乳清酸由氨基甲酰磷酸经天冬氨酸缩合、二氢乳清酸脱氢生成，此阶段尚未与PRPP结合；PRPP参与的是其后乳清酸生成乳清酸核苷酸的反应"},{"q":"下列有关水溶性维生素的叙述哪项是对的","o":["不易溶于水，吸收难","体内储存量较大","摄入量超过机体饱和程度，即导致相应维生素中毒","它们多是构成酶的辅基或辅酶成分","不需要经常摄入"],"a":3,"e":"水溶性维生素（B族、C）多参与构成酶的辅酶或辅基，如B1形成TPP、B2形成FAD与FMN、B6形成磷酸吡哆醛、PP形成NAD与NADP，故该项正确。水溶性维生素易溶于水、体内储存少、需经常摄入，摄入过量一般随尿排出而不易中毒，易蓄积中毒的是脂溶性维生素"},{"q":"1969年，哈里斯将癌细胞与同种正常成纤维细胞融合，所获杂种细胞的后代，只要保留某些正常亲本染色体时就可表现为正常表型，但是随着染色体的丢失又可重新出现恶变细胞。这一现象表明，正常染色体内可能存在某些抑制肿瘤发生的基因，它们的丢失、突变或失去功能，使激活的癌基因发挥作用而致癌。这些基因为抑癌基因。关于抑癌基因的叙述，正确的是","o":["具有抑制细胞增殖的作用","与癌基因的表达无关","缺失与细胞增殖和分化无关","不存在于人类正常细胞","在所有肿瘤细胞正常表达"],"a":0,"e":"抑癌基因对细胞增殖起负性调控，编码产物抑制细胞周期行进，丢失或失活后增殖失控。这类基因在正常细胞中普遍存在，通过对抗癌基因的促增殖效应发挥作用，并非与癌基因表达无关；其缺失直接影响增殖与分化，也并非在所有肿瘤细胞中都正常表达"},{"q":"下列物质在体内彻底氧化时，生成ATP最多的是","o":["3分子葡萄糖","1分子硬脂酸","6分子甘油","6分子丙酮酸","9分子乙酰CoA"],"a":1,"e":"硬脂酸为18碳饱和脂肪酸，经β氧化生成9分子乙酰CoA及相应NADH、FADH2，彻底氧化净生成约120分子ATP，产能最高。9分子乙酰CoA经三羧酸循环约产90分子ATP，3分子葡萄糖约产96分子ATP，6分子甘油约产111分子ATP，6分子丙酮酸约产75分子ATP，均低于硬脂酸"},{"q":"蛋白质生物合成中肽链延长所需要的能量来源于","o":["ATP","GTP","GDP","UTP","CTP"],"a":1,"e":"肽链延长中进位与转位各水解1分子GTP，每生成一个肽键消耗2个高能磷酸键，能量来自GTP。起始阶段亦消耗GTP，氨基酸活化消耗ATP，UTP与CTP分别参与糖原和磷脂合成，不直接为翻译延长供能"},{"q":"白化病是由哪种酶缺陷造成","o":["苯丙氨酸转氨酶","酪氨酸酶","苯丙氨酸羟化酶","苯丙酮酸脱氢酶","酪氨酸羟化酶"],"a":1,"e":"白化病由酪氨酸酶先天缺乏所致，黑色素细胞不能将酪氨酸羟化为多巴，黑色素合成中断，皮肤毛发发白，对光敏感易患皮肤癌。苯丙氨酸羟化酶缺乏引起苯丙酮尿症，苯丙氨酸转氨酶与酪氨酸羟化酶分别参与一般转氨及儿茶酚胺合成，苯丙酮酸脱氢酶并非该代谢的关键酶"},{"q":"蛋白质生物合成中多肽链的氨基酸排列顺序取决于","o":["相应tRNA中的核苷酸排列顺序","相应氨酰-tRNA合成酶的专一性","相应tRNA上的反密码子","相应mRNA中核苷酸排列顺序","相应rRNA的专一性"],"a":3,"e":"蛋白质合成时，多肽链的氨基酸排列顺序由mRNA上的核苷酸（密码子）排列顺序决定，tRNA通过反密码子识别密码子并转运相应氨基酸。氨酰-tRNA合成酶的专一性保证氨基酸与tRNA正确匹配，但不决定顺序；tRNA、rRNA自身序列也不决定多肽顺序"},{"q":"蛋白质的一级结构是指","o":["N端到C端氨基酸残基的排列顺序","C端到N端氨基酸残基的排列顺序","多肽链的形状和大小","氨基酸种类的数目","分子中的共价键"],"a":0,"e":"蛋白质一级结构指多肽链中氨基酸从N-端到C-端的排列顺序，由肽键连接，决定其空间构象与功能。多肽链的形状和大小属三维结构特征，氨基酸种类与数目不反映序列，共价键包含肽键与二硫键，是维持结构的化学键而非一级结构的定义"},{"q":"血液中的葡萄糖称为血糖。由于颗粒小，拥有良好的生物活性，易于透过人体血脑屏障，体内各组织细胞活动所需的能量大部分来自葡萄糖，所以血糖必须保持一定的水平才能维持体内各器官和组织的需要。葡萄糖进入肌肉细胞后不可以进行的代谢是","o":["糖异生","糖原合成","有氧氧化","糖酵解","进行乳酸循环"],"a":0,"e":"肌组织缺乏葡萄糖-6-磷酸酶，肌糖原分解生成的葡萄糖-6-磷酸只能进入糖酵解生成乳酸，不能脱磷酸释放葡萄糖，更不能进行糖异生，因糖异生关键酶在肌中不表达。糖酵解、糖原合成与磷酸戊糖途径在肌细胞内均可进行，故不可进行的是糖异生"},{"q":"降低血糖的激素是","o":["胰高血糖素","肾上腺素","甲状腺素","胰岛素","肾上腺皮质激素"],"a":3,"e":"胰岛素由胰岛β细胞分泌，促进肌肉与脂肪组织经GLUT4摄取葡萄糖，激活糖原合酶、抑制糖原分解与糖异生，是唯一降低血糖的激素。胰高血糖素、肾上腺素、肾上腺皮质激素均升高血糖，甲状腺素加速糖代谢但整体不具降血糖作用"},{"q":"内质网软脂酸碳链加长所需二碳单位供体为","o":["乙酰CoA","丁酰CoA","丙二酰CoA","乙酰乙酰CoA","羟甲基戊二酸单酰CoA"],"a":2,"e":"内质网脂肪酸碳链延长以丙二酰CoA为二碳单位供体，经缩合、还原、脱水、再还原使碳链延长。乙酰CoA是脂肪酸合成的起始原料，丁酰CoA、乙酰乙酰CoA与HMG-CoA均为酮体代谢中间物"},{"q":"Ⅰ型高脂蛋白血症患者空腹血浆","o":["CM升高","VLDL升高","LDL升高","VLDL及LDL升高","CM及VLDL升高"],"a":0,"e":"Ⅰ型脂蛋白异常血症由脂蛋白脂肪酶或apoCⅡ缺陷致CM清除障碍，空腹血浆CM升高，甘油三酯极度升高。Ⅱa型为LDL升高，Ⅳ型为VLDL升高，Ⅴ型为CM与VLDL同时升高，Ⅱb型为VLDL与LDL同时升高，均与Ⅰ型的单纯CM升高不同"},{"q":"结合RNA聚合酶并启动转录的DNA序列是","o":["启动子","操纵子","增强子","沉默子","衰减子"],"a":0,"e":"启动子是RNA聚合酶识别、结合并启动转录的DNA序列，位于基因上游，决定转录起始位置与方向，故为答案。操纵子是由启动子、操纵序列与结构基因构成的转录调控单位。增强子远程增强转录，沉默子抑制转录，衰减子通过前导序列调控转录终止，均不直接结合RNA聚合酶启动转录"},{"q":"DNA对哪一波长紫外光具有强烈的吸收","o":["220nm","240nm","260nm","280nm","300nm"],"a":2,"e":"DNA因碱基的共轭双键在260nm处有最大紫外吸收，这一特性常用于核酸定量与纯度鉴定。280nm是蛋白质的最大吸收峰（色氨酸、酪氨酸贡献）；220nm、240nm、300nm均非核酸的特征吸收波长"},{"q":"催化软脂酸碳链延长的酶系存在于","o":["细胞质","细胞质膜","线粒体","溶酶体","高尔基复合体"],"a":2,"e":"软脂酸碳链延长在内质网和线粒体两处进行：内质网途径以丙二酸单酰CoA为二碳供体，线粒体途径以乙酰CoA为供体，经缩合-还原-脱水-再还原延长至24碳。胞质溶胶是软脂酸从头合成的场所，含脂肪酸合酶复合体，并非延长部位"},{"q":"N-连接型聚糖的糖基化位点为","o":["Asp-X-Ser/Thr","Asn-X-Ser/Thr","Gln-X-Ser/Thr","Glu-X-Ser/Thr","Asn-X-Thr/Tyr"],"a":1,"e":"N-连接型聚糖中N-乙酰葡萄糖胺与多肽链天冬酰胺残基的酰胺氮共价相连，其识别序列为Asn-X-Ser/Thr，X可为除脯氨酸外的任意氨基酸。Asp、Glu为酸性氨基酸，侧链为羧基，不提供酰胺氮；Gln的酰胺氮不参与连接；Asn-X-Thr/Tyr的第二位残基不符，故均错"},{"q":"参与形成蛋白质一级结构的化学键有","o":["二硫键、氢键","疏水键、氢键","范德华力、肽键","肽键、二硫键","氢键、盐键"],"a":3,"e":"蛋白质一级结构指肽链中氨基酸自N端至C端的排列顺序，主链由肽键相连，链内或链间二硫键的位置也属一级结构范畴，故肽键与二硫键共同参与一级结构的形成与稳定。氢键、疏水键、盐键、范德华力属次级键，维系二、三级结构，肽键才是主链骨架的共价连接"},{"q":"真核细胞DNA复制发生在细胞周期的","o":["G1期","S期","G2期","M期","G0期"],"a":1,"e":"真核染色体DNA复制只发生在S期，每个细胞周期仅复制一次，复制起点激活受CDK2严格调控。真核复制为多起点双向复制，冈崎片段较短，染色体末端由端粒酶延长。G1期进行复制前体装配，G2期为分裂做准备，M期染色体凝集分离，G0期细胞暂不增殖"},{"q":"最常用的从cDNA文库中筛选含目的基因的克隆方法是","o":["核酸分子杂交法","免疫筛选法","蛋白质功能测定筛选法","PCR法","Western Blotting法"],"a":0,"e":"cDNA文库筛选常用核酸分子杂交法，以标记探针与菌落或噬斑原位杂交，直接鉴定含目的DNA的克隆，灵敏度和特异性最高。免疫筛选法用于表达文库中检测目的蛋白，蛋白质功能测定依赖活性检测，Western印迹只鉴定已分离的蛋白，PCR需已知序列设计引物"},{"q":"两段DNA序列非常相似时，下列描述正确的是","o":["来自同一物种","具有相似的功能","编码产物相似","可能功能差异很大","基因组中的重复序列"],"a":3,"e":"两段DNA序列高度相似时，少数关键碱基的差异即可导致编码产物或调控特性显著改变，故可能功能差异很大。仅凭序列相似不能断定来自同一物种、功能相似或编码产物相似；重复序列只是基因组组成的一类，与功能相似无必然联系"},{"q":"下列关于RNA和DNA聚合酶的叙述，正确的是","o":["RNA聚合酶用二磷酸核苷合成多核苷酸链","RNA聚合酶需要引物，并在延长链的5'端加接碱基","DNA聚合酶可在链的两端加接核苷酸","仅能以DNA为模板合成DNA或RNA","所有RNA聚合酶和DNA聚合酶只能在生长中的多核苷酸链的3'端加接核苷酸"],"a":4,"e":"无论RNA聚合酶还是DNA聚合酶，新核苷酸均只能加到延伸链的3'-OH端，合成方向为5'→3'，故该项正确。RNA聚合酶以三磷酸核苷为底物并无需引物。DNA聚合酶不能从两端加接，只能3'端延伸。仅能以DNA为模板的表述过于绝对，某些RNA聚合酶可以RNA为模板"},{"q":"自然界游离核苷酸中的磷酸最常位于","o":["戊糖的C-2'上","戊糖的C-3'上","戊糖的C-5'上","戊糖的C-2'及C-3'","戊糖的C-2'及C-5'上"],"a":2,"e":"生物体内游离存在的核苷酸多为5′-核苷酸，即戊糖C-5′的羟基与磷酸酯化生成磷酸酯键。C-2′与C-3′的羟基参与形成3′,5′-磷酸二酯键，构成核酸链骨架；C-2′、C-3′同时磷酸化只见于环核苷酸等特殊形式，不是游离核苷酸的常态"},{"q":"生物素是哪个酶的辅酶","o":["丙酮酸脱氢酶","丙酮酸羧化酶","烯醇化酶","醛缩酶","磷酸烯醇式丙酮酸羧激酶"],"a":1,"e":"生物素作为羧化酶辅因子，与酶蛋白赖氨酸残基的ε-氨基共价结合成生物胞素，参与CO2固定，丙酮酸羧化酶即以其为辅酶，催化丙酮酸生成草酰乙酸。丙酮酸脱氢酶复合体含TPP、硫辛酸、FAD、NAD+及CoA，不含生物素。烯醇化酶需Mg2+，醛缩酶为裂解酶，磷酸烯醇式丙酮酸羧激酶以GTP供能"},{"q":"影响离子通道开关的配体主要是","o":["神经递质","类固醇激素","生长因子","无机离于","甲状腺素"],"a":0,"e":"离子通道型受体的配体主要为神经递质，如乙酰胆碱、GABA、谷氨酸等，结合后引起通道开放或关闭，产生膜电位变化，故为答案。类固醇激素与甲状腺素为胞内受体配体，生长因子多为酶联受体配体，无机离子不是典型的门控配体"},{"q":"关于丝氨酸在体内的生物转化过程，下列哪个说法是错误的","o":["丝氨酸可在羟甲基转移酶的作用下转化生成N5,N10-甲烯四氢叶酸和甘氨酸","丝氨酸可以转化生成丙酮酸，并进一步彻底氧化分解","丝氨酸可以与CDP-甘油二酯直接缩合生成磷脂酰丝氨酸","丝氨酸可以脱羧生成乙醇胺，并进一步生物转化合成磷脂酰乙醇胺","丝氨酸可以在氨基甲酰磷酸合成酶Ⅱ的作用下转化生成氨基甲酰磷酸，并进一步生成嘧啶"],"a":4,"e":"氨基甲酰磷酸合成酶Ⅱ位于胞质，以谷氨酰胺为氮源合成氨基甲酰磷酸供嘧啶合成，并不以丝氨酸为底物，故该说法错误。丝氨酸经羟甲基转移酶生成N5,N10-甲烯四氢叶酸和甘氨酸；亦可转变为丙酮酸后彻底氧化；与CDP-甘油二酯缩合可生成磷脂酰丝氨酸；脱羧生成乙醇胺进而合成磷脂酰乙醇胺，均成立"},{"q":"肾脏中产生的氨主要来自","o":["胺的氧化","氨基酸的联合脱氨基","氨基酸的氧化脱氨基","谷氨酰胺的水解","尿素的水解"],"a":3,"e":"肾小管上皮细胞中的谷氨酰胺在谷氨酰胺酶催化下水解为谷氨酸和氨，氨分泌入管腔与H+结合成铵盐排出，参与酸碱平衡调节。胺氧化、联合脱氨基与氧化脱氨基是其他组织的产氨方式，尿素水解主要发生在肠道细菌"},{"q":"催化转录产生snRNA的酶是","o":["RNA聚合酶Ⅰ","RNA聚合酶Ⅱ","RNA聚合酶Ⅲ","RNA聚合酶核心酶","RNA聚合酶全酶"],"a":2,"e":"真核RNA聚合酶Ⅲ转录生成tRNA、5S rRNA与snRNA等小分子RNA。RNA聚合酶Ⅰ合成45S rRNA前体，RNA聚合酶Ⅱ合成mRNA前体，核心酶与全酶是原核RNA聚合酶的两种形式"},{"q":"有关竞争性抑制剂的叙述，错误的是","o":["与底物结构相似","与酶的活性中心相结合","抑制程度与[S]和[I]有关","增加底物浓度可解除抑制","与酶共价结合"],"a":4,"e":"竞争性抑制剂与底物结构相似，可逆地结合于酶活性中心，增加底物浓度可解除抑制，抑制程度取决于底物与抑制剂的浓度之比。与酶共价结合的是不可逆抑制剂，如有机磷；非竞争性抑制剂结合于活性中心之外的位点"},{"q":"下列哪个因素不会破坏蛋白质的空间构象","o":["盐析","加热","酸碱","β-巯基乙醇","重金属盐"],"a":0,"e":"盐析用高浓度中性盐破坏水化膜并中和表面电荷，使蛋白质沉淀却不破坏其空间构象，沉淀可复溶并保持活性。加热、强酸碱、重金属盐及β-巯基乙醇均使蛋白质变性，其中β-巯基乙醇还原二硫键，破坏三级结构"},{"q":"环腺苷酸（cAMP）激活依赖cAMP蛋白激酶的作用方式是","o":["cAMP与蛋白激酶的活性中心结合","cAMP与蛋白激酶活性中心外的必需基团结合","cAMP使蛋白激酶磷酸化","cAMP与蛋白激酶的调节亚基结合，使其与催化亚基解离","cAMP使蛋白激酶去磷酸化"],"a":3,"e":"PKA为2个催化亚基与2个调节亚基组成的四聚体，调节亚基的假底物序列占据催化位点而抑制活性。cAMP与调节亚基结合引起构象改变，释放出游离的活性催化亚基，故D项正确。cAMP不进入活性中心，也不通过磷酸化修饰PKA本身"},{"q":"作为基因治疗靶细胞，具有高度自我更新和分化能力的是","o":["造血干细胞","成纤维细胞","生殖细胞","肌细胞","癌细胞"],"a":0,"e":"造血干细胞具有高度自我更新能力，可进一步分化为各类血细胞，并保持基因组DNA稳定，是基因治疗最有前途的靶细胞。成纤维细胞与肌细胞分化程度高、自我更新能力弱，生殖细胞涉及伦理，癌细胞基因组不稳定，均不宜作靶细胞"},{"q":"1分子氨基酸活化为氨酰-tRNA，消耗高能键数为","o":["1","2","3","4","5"],"a":1,"e":"氨基酸与tRNA形成氨酰-tRNA时，ATP分解为AMP和焦磷酸，消耗2个高能磷酸键。1个高能键对应ATP水解为ADP的情形，3个与4个是高能键消耗的累计值，单一活化反应只耗2个"},{"q":"糖酵解进行的部位是在细胞的","o":["线粒体基质","细胞质中","内质网膜上","细胞核内","线粒体基质和细胞质中"],"a":1,"e":"糖酵解的全部反应均在细胞质中进行，不需要氧，终产物为丙酮酸。线粒体基质是三羧酸循环和脂肪酸β-氧化的场所；内质网膜主要参与脂质合成与蛋白质加工；细胞核内进行DNA复制与转录，三者均不是糖酵解进行的部位"},{"q":"长期饥饿时大脑的能量来源主要是","o":["葡萄糖","氨基酸","甘油","酮体","糖原"],"a":3,"e":"长期饥饿时肝内酮体生成大量增加，酮体分子小、水溶性强，可透过血脑屏障，脑利用酮体供能超过葡萄糖，占总耗氧量约60%。葡萄糖此时主要供给红细胞等必需糖的组织，糖原早已耗尽，氨基酸与甘油主要作为糖异生原料"},{"q":"紫外线辐射造成的DNA损伤最易形的二聚体是","o":["CC","TT","TC","AU","CU"],"a":1,"e":"紫外线使同一条链上相邻的胸腺嘧啶以共价键连接，形成环丁烷型胸腺嘧啶二聚体，TT最易形成，也可形成CT、CC二聚体。AU、CU含尿嘧啶，只见于RNA，DNA中不存在尿嘧啶。嘧啶二聚体使DNA弯曲扭结，阻碍复制与转录，可由光复活酶或切除修复去除"},{"q":"G蛋白是指","o":["蛋白激酶A","鸟苷酸环化酶","蛋白激酶G","Grb-2结合蛋白","鸟苷酸结合蛋白"],"a":4,"e":"G蛋白即鸟苷酸结合蛋白，以GTP/GDP结合状态转换传递信号，α亚基具GTP酶活性。蛋白激酶A是cAMP的靶酶，鸟苷酸环化酶催化GTP生成cGMP，蛋白激酶G是cGMP的靶酶，Grb-2是接头蛋白而非G蛋白"},{"q":"食品中的添加剂，色素等作为外源性非营养物质经生物转化后","o":["极性增加，利于排泄","极性减小，利于排泄","分子以原形排泄","极性增加，易于肠肝循环","极性减小，易于肠肝循环"],"a":0,"e":"生物转化使脂溶性非营养物质经第一相反应引入极性基团，再经第二相结合葡萄糖醛酸、硫酸等，水溶性和极性增加，易经胆汁或尿排出。极性减小反而更易在体内蓄积。原形排泄只适用于少数水溶性物质，极性增加并不促进肠肝循环"},{"q":"核糖体“受位”的功能是","o":["催化肽键生成","从tRNA水解新生肽链","转肽","接受新进位的氨酰-tRNA","活化氨基酸"],"a":3,"e":"A位即氨酰位，结合新进位的氨酰tRNA，其反密码子与mRNA密码子配对；P位为肽酰位，结合肽酰tRNA；E位为排出位，释放卸载的tRNA。转肽由大亚基的转肽酶催化，属成肽步骤，并非A位功能。活化氨基酸由氨酰tRNA合成酶完成"},{"q":"蛋白质的一级结构及高级结构取决于","o":["分子中的氢键","分子中的盐键","分子内部疏水键","氨基酸的组成及排列顺序","氨基酸残基的性质"],"a":3,"e":"蛋白质一级结构是氨基酸自N端至C端的排列顺序，其组成与顺序决定肽链的折叠方式及高级结构。氢键、盐键与疏水键是维持二级、三级结构的次级键，氨基酸残基的性质通过序列体现，不能单独说明构象的决定因素"},{"q":"蛋白质变性是由于","o":["蛋白质空间构象的破坏","蛋白质亚基的解聚","蛋白质的水解","蛋白质一级结构的改变","辅基的脱落"],"a":0,"e":"蛋白质变性是空间构象（二、三、四级结构）被破坏、生物活性丧失、理化性质改变的现象，一级结构不变。亚基解聚仅是四级结构变化的一部分；蛋白质水解、一级结构改变属于降解而非变性；辅基脱落只是某些结合蛋白的变化，均非变性的本质"},{"q":"1分子乙酰CoA经三羧酸循环氧化后的产物是","o":["草酰乙酸","草酰乙酸和CO2","CO2+H2O","草酰乙酸+CO2+H2O","2CO2+4分子还原当量+GTP"],"a":4,"e":"1分子乙酰CoA经三羧酸循环4次脱氢、2次脱羧，生成3分子NADH、1分子FADH2和1分子GTP，并释出2分子CO2；草酰乙酸在循环中只被再生，量不变。B、D项把草酰乙酸当作产物，混淆了循环中间物与终产物。C项遗漏还原当量与GTP"},{"q":"DNA分子中G+C含量越高","o":["解链越容易","氢键破坏所需要温度越高","50%复性时需要的温度越高","信息含量越丰富","50%变性时需要的温度越低"],"a":1,"e":"DNA中G≡C之间为三个氢键、A=T之间为两个氢键，G+C含量越高氢键越多，双链越稳定，破坏氢键及解链所需温度越高，Tm值越大。G+C高者不易解链，解链越容易一说相反；50%变性时的温度即Tm，含量越高应越高而非越低；碱基数目相同时信息量不因G+C比例改变"},{"q":"当肝细胞内ATP/AMP降低时，下列叙述错误的是","o":["丙酮酸激酶激活","磷酸果糖激酶-1激活","丙酮酸脱氢酶复合体激活","磷酸果糖激酶-2激活","丙酮酸羧化酶激活"],"a":4,"e":"ATP/AMP降低提示能量不足，糖酵解关键酶磷酸果糖激酶-1、丙酮酸激酶被激活，丙酮酸脱氢酶复合体因ADP升高而激活，磷酸果糖激酶-2去磷酸化而激活。丙酮酸羧化酶受乙酰CoA别构激活，是糖异生关键酶，不因ATP/AMP下降而激活"},{"q":"在线粒体中，脂肪酸碳链延长的原料是","o":["丙二酰CoA","乙酰CoA","既用乙酰CoA，也用丙二酰CoA","一碳单位","甘油"],"a":1,"e":"线粒体内脂肪酸延长以乙酰CoA为二碳单位供体，经缩合、还原、脱水、再还原延长碳链，主要延长至18碳。内质网延长途径以丙二酰CoA为供体，一碳单位参与甲基化反应，甘油是甘油磷脂的骨架"},{"q":"下列关于质粒的描述中，作为克隆载体最基本的原因是","o":["小型环状双链DNA分子","有一定遗传标志","在细胞分裂时恒定地传给子代细胞","具有自我复制能力","有多克隆位点"],"a":3,"e":"质粒能在宿主细胞内自主复制并随细胞分裂传给子代，这是其作为克隆载体最基本的条件，否则外源基因无法扩增。遗传标志用于筛选重组体，多克隆位点便于插入目的基因，环状双链结构只是其存在形式"},{"q":"DNA分子与RNA分子具有很多不同的特点。但它们共同的特点是","o":["电泳时移向正极","是线性单链分子","是线性双链分子","通常在序列中A与T浓度相等","含有脱氧胸苷"],"a":0,"e":"DNA与RNA的磷酸基团在生理pH下解离带负电，电泳时均向正极移动。DNA为双链、RNA多为单链，RNA含尿嘧啶而不含胸腺嘧啶；A与T浓度相等仅是双链DNA的特征。泳动速率还取决于分子大小与构象，故电泳可用于核酸的分离与鉴定"},{"q":"肝脏生成乙酰乙酸的直接前体是","o":["β-羟丁酸","乙酰乙酰CoA","丙酮酸","甲羟戊酸","羟甲基戊二酸单酰CoA"],"a":4,"e":"肝内乙酰乙酸由乙酰乙酰CoA经HMG-CoA合成酶生成HMG-CoA，再经HMG-CoA裂解酶裂解产生，故直接前体为HMG-CoA。β-羟丁酸是乙酰乙酸的还原产物，乙酰乙酰CoA是更早的前体，丙酮酸与甲羟戊酸分别属糖代谢与胆固醇合成"},{"q":"α地中海贫血主要是由于α珠蛋白基因缺失，使α珠蛋白链的合成受到抑制而引起的溶血性贫血。对这种α珠蛋白基因缺失进行快速检测的首选方法是","o":["Northern印迹","PCR","反向斑点杂交","变性高效液相色谱","DNA指纹技术"],"a":1,"e":"PCR可设计特异引物快速扩增α珠蛋白基因区域，依据扩增产物有无及大小判断基因缺失，操作简便快速，为首选方法。Northern印迹用于RNA检测，反向斑点杂交用于已知突变位点筛查，变性高效液相色谱用于突变扫描，DNA指纹用于个体识别，均非基因缺失快速检测的首选"},{"q":"有机磷杀虫剂对胆碱酯酶的抑制作用属于","o":["不可逆性抑制作用","可逆性抑制作用","竞争性抑制作用","反竞争性抑制作用","非竞争性抑制作用"],"a":0,"e":"有机磷与胆碱酯酶活性中心丝氨酸羟基共价结合，属不可逆抑制，酶活性不能经透析恢复，须待新酶合成。竞争性抑制是抑制剂与底物竞争活性中心且可逆结合；非竞争性与反竞争性抑制同属可逆抑制，动力学参数改变而抑制剂可被除去"},{"q":"胆固醇生物合成不需要","o":["乙酰CoA","NADPH","ATP","HMG-CoA还原酶","HMG-CoA裂解酶"],"a":4,"e":"胆固醇合成以乙酰CoA为原料，经甲羟戊酸、鲨烯等步骤完成，需NADPH供氢、ATP供能，HMG-CoA还原酶为限速酶。HMG-CoA裂解酶催化HMG-CoA裂解生成乙酰乙酸和乙酰CoA，是酮体生成的特有酶，不参与胆固醇合成"},{"q":"不是由RNA poll催化转录生成的rRNA是","o":["5、8rRNA","16rRNA","18rRNA","28rRNA","45rRNA"],"a":1,"e":"真核RNA聚合酶Ⅰ位于核仁，转录生成45S rRNA前体，再加工为18S、5.8S和28S rRNA。5S rRNA由RNA聚合酶Ⅲ转录。16S rRNA是原核核糖体小亚基的成分，真核细胞无此分子，故不由RNA polⅠ生成"},{"q":"抗霉素A对呼吸链（电子传递链）抑制的作用点位于","o":["NADH脱氢酶附近","细胞色素b附近","细胞色素氧化酶","偶联ATP的生成","琥珀酸脱氢酶附近"],"a":1,"e":"抗霉素A阻断复合体Ⅲ中电子由Cyt b向QN位点的传递，作用点在细胞色素b附近。NADH脱氢酶受鱼藤酮抑制，琥珀酸脱氢酶受丙二酸竞争性抑制，细胞色素氧化酶受CN-、CO、NaN3抑制；抗霉素A不直接作用于ATP合酶，不影响偶联磷酸化本身"},{"q":"某DNA分子中胸腺嘧啶的含量为20%，则胞嘧啶的含量应为","o":["20%","30%","40%","60%","80%"],"a":1,"e":"按碱基互补规则A=T、G=C，T为20%则A为20%，A+T共40%，G+C共60%，故C为30%。双链DNA中嘌呤与嘧啶总量相等，A+G=T+C各占50%。20%为T与A各自的含量，40%为A+T合计，60%为G+C合计，80%无对应关系"},{"q":"关于端粒酶的叙述，不正确的是","o":["端粒酶具有逆转录酶的活性","端粒酶是DNA与蛋白质的复合物","可维持真核生物DNA的完整性","端粒酶可提供催化时所需模板","端粒酶的催化机制为爬行模型"],"a":1,"e":"端粒酶由端粒酶RNA、端粒酶协同蛋白1和端粒酶逆转录酶组成，是核糖核蛋白而非DNA与蛋白质的复合物。它以自带RNA为模板逆转录合成端粒重复序列，补偿复制所致的末端缩短，维持染色体DNA完整性，催化过程按爬行模型进行"},{"q":"cAMP可通过哪种酶发挥作用","o":["丙酮酸激酶","蛋白激酶","己糖激酶","脂肪酸硫激酶","磷酸化酶激酶"],"a":1,"e":"cAMP作为第二信使激活cAMP依赖的蛋白激酶A，使靶蛋白丝氨酸或苏氨酸残基磷酸化而调节活性。丙酮酸激酶与己糖激酶是糖酵解关键酶，磷酸化酶激酶由磷酸化激活，脂肪酸硫激酶催化脂酰CoA生成，均非cAMP直接靶点"},{"q":"Cori循环之所以是单向的，是因为","o":["肌细胞内葡萄糖浓度总是较血糖低","肌肉内没有果糖双磷酸酶-1","肝内不进行糖酵解","肝有葡萄糖-6-磷酸酶，肌肉没有","由于缺少相应的运输载体"],"a":3,"e":"Cori循环中肌肉缺乏葡萄糖-6-磷酸酶，不能将葡萄糖-6-磷酸水解为葡萄糖；而肝具备该酶，可将乳酸经糖异生生成的葡萄糖-6-磷酸水解为葡萄糖释放入血，故循环只能单向由肌肉向肝进行。肌肉内葡萄糖浓度并非总低于血糖。肝也进行糖酵解。运输载体并非限制因素"},{"q":"鸟氨酸氨甲酰转移酶催化下述哪种反应","o":["鸟氨酸的合成反应","鸟氨酸转变成精氨酸","精氨酸的水解反应","瓜氨酸转变成精氨酸","鸟氨酸转变成瓜氨酸"],"a":4,"e":"鸟氨酸氨甲酰转移酶在线粒体内将氨基甲酰磷酸的氨基甲酰基转移至鸟氨酸，生成瓜氨酸，为尿素合成的第二步。鸟氨酸由谷氨酸经多步生成，精氨酸水解由精氨酸酶催化，瓜氨酸转为精氨酸尚需天冬氨酸参与"},{"q":"真核生物体在不同发育阶段，蛋白质的表达谱也发生变化是由于","o":["特异转录因子的差异","基本转录因子的差异","翻译起始因子的差异","衰减子的差异","核心启动子的差异"],"a":0,"e":"通用转录因子各组织相同，不决定表达的时空特异性；特异转录因子在特定细胞或特定发育阶段表达，与相应顺式元件结合，决定基因表达的时间与空间选择性，故不同发育阶段表达谱改变源于其差异。核心启动子与基本转录因子属共有装置，衰减子见于原核色氨酸操纵子，翻译起始因子差异只影响翻译效率"},{"q":"原癌基因产物不包括","o":["细胞外生长因子","跨膜生长因子受体","细胞内信号转导体","儿茶酚胺类激素","核内转录因子"],"a":3,"e":"原癌基因产物按功能分为细胞外生长因子、跨膜生长因子受体、细胞内信号转导分子与核内转录因子四类，如SIS、EGFR、RAS、MYC。儿茶酚胺类激素是肾上腺髓质分泌的激素，其受体才是膜受体，激素本身不由原癌基因编码"},{"q":"由鸦片促黑皮质素原（POMC）水解加工生成的物质是","o":["胰岛素","糖蛋白","脂蛋白","ACTH","cAMP"],"a":3,"e":"POMC经组织特异性水解加工生成ACTH、β-促脂解素、β-内啡肽、促黑激素等多种活性肽，ACTH为其中之一。胰岛素由胰岛B细胞合成，cAMP是核苷酸衍生物，糖蛋白与脂蛋白属另一类物质"},{"q":"维生素B1的生理功能是","o":["增加胆碱酯酶活性","构成转氨酶的辅酶","参与糖代谢过程中的氧化脱羧反应","促进肝脏凝血酶原的合成","参与氧化呼吸链氢的传递"],"a":2,"e":"维生素B1的活性形式TPP是α-酮酸氧化脱羧酶复合体的辅因子，参与丙酮酸与α-酮戊二酸的氧化脱羧。转氨酶辅酶是磷酸吡哆醛，维生素K促凝血酶原合成，呼吸链递氢靠FMN、FAD与CoQ；维生素B1抑制胆碱酯酶而非增强其活性"},{"q":"常规PCR反应体系不含","o":["模板DNA","引物","ddNTP","合适的缓冲液体系","耐热的TaqDNA聚合酶"],"a":2,"e":"常规PCR体系含模板DNA、一对引物、四种dNTP、耐热Taq DNA聚合酶、Mg2+与缓冲液。ddNTP的3′-位缺羟基，掺入后链延伸即终止，只用于Sanger测序反应，且需分四管分别加入不同ddNTP，常规扩增体系中不含"},{"q":"与原核生物DNA复制比较，真核生物DNA复制特点的描述，正确的是","o":["RNA引物较长","冈崎片段较短","添加新的碱基需要由ATP供给能量","在复制单位中，DNA链的延长速度较慢","仅有一个复制起点"],"a":1,"e":"真核生物以复制子为单位复制，冈崎片段长约100～200核苷酸，原核生物约1000～2000核苷酸，故真核片段明显偏短。A项实为引物同样较短，与核小体间距相适应；E项描述的是原核生物单一复制起点的特点，真核为多起点。C项所述聚合能量来自dNTP自身水解，不经ATP供给"},{"q":"关于真核生物的转录特点叙述，正确的是","o":["转录起始辨认位点是TTGACA","形成转录起始复合物","σ因子辨认起始点","需要引物","RNA聚合酶催化转录，此外还需要其他转录因子"],"a":4,"e":"真核生物由RNA聚合酶Ⅰ、Ⅱ、Ⅲ分别催化rRNA、mRNA前体及tRNA等合成，聚合酶自身不能识别启动子，须由TFⅡD等转录因子协助组装前起始复合物，故转录需聚合酶与转录因子共同完成。TTGACA是原核-35区，σ因子为原核所有。真核转录不需引物，RNA聚合酶可直接起始"},{"q":"G蛋白的α亚基具有","o":["GTP酶活性","ATP酶活性","TTP酶活性","CTP酶活性","UTP酶活性"],"a":0,"e":"G蛋白α亚基具有GTP酶活性，与GTP结合时为活化态，水解GTP为GDP后失活并与βγ亚基重新结合，从而实现对信号的定时关闭。βγ亚基无GTP酶活性，可调节效应器；霍乱毒素与百日咳毒素正是通过修饰α亚基使GTP酶失活而致病，可见该活性为其核心特征"},{"q":"嘌呤核苷酸从头合成的原料，不包括","o":["磷酸核糖","CO2","一碳单位","谷氨酰胺","O2"],"a":4,"e":"嘌呤从头合成原料为磷酸核糖、氨基酸、一碳单位与CO2，氧不参与。谷氨酰胺提供N3与N9，甘氨酸提供C4、C5与N7，CO2提供C6，一碳单位提供C2与C8。天冬氨酸提供N1，谷氨酰胺提供N3与N9，甘氨酸提供C4、C5与N7"},{"q":"当6-磷酸葡萄糖脱氢受抑制时，影响脂酸生物合成的原因是","o":["乙酰CoA生成减少","柠檬酸减少","ATP形成减少","NADPH生成减少","丙二酰CoA减少"],"a":3,"e":"6-磷酸葡萄糖脱氢酶是磷酸戊糖途径的限速酶，受抑制后NADPH生成减少，脂肪酸合成所需还原当量不足而受阻。乙酰CoA与柠檬酸由糖酵解及三羧酸循环提供，ATP不足影响的是能量供应，丙二酰CoA减少是合成受阻的结果而非原因"},{"q":"糖酵解的速度决定于","o":["磷酸葡糖变位酶","6-磷酸果糖激酶-1","醛缩酶","磷酸甘油激酶","磷酸甘油变位酶"],"a":1,"e":"糖酵解的关键限速酶为6-磷酸果糖激酶-1，其活性决定糖酵解整体速度，受ATP、柠檬酸抑制及AMP、果糖-2,6-二磷酸激活，故为答案。磷酸葡糖变位酶、醛缩酶、磷酸甘油激酶、磷酸甘油变位酶催化可逆步骤，非限速酶，不决定酵解速度"},{"q":"下列关于嘌呤核苷酸从头合成的叙述正确的是","o":["甘氨酸、谷氨酸、天冬氨酸都是合成原料","最先合成的是AMP","由IMP合成AMP和GMP均由ATP供能","一碳单位不是一种必需的合成原料","生成过程中不会产生自由嘌呤碱"],"a":4,"e":"嘌呤核苷酸从头合成在核糖-5-磷酸分子上逐步构建嘌呤环，先形成IMP，全程不产生游离嘌呤碱。原料为甘氨酸、谷氨酰胺、天冬氨酸、一碳单位及CO2，谷氨酸不参与；IMP转变为AMP由GTP供能，转变为GMP由ATP供能"},{"q":"1分子葡萄糖经磷酸戊糖途径代谢时可生成","o":["1分子NADH＋H＋","2分子NADH＋H＋","1分子NDPH＋H＋","2分子NADPH＋H＋","2分子CO2"],"a":3,"e":"磷酸戊糖途径第一阶段1分子葡萄糖-6-磷酸经两次脱氢生成2分子NADPH和1分子核糖-5-磷酸，释出1分子CO2。NADH由糖酵解和三羧酸循环的脱氢酶生成，受氢体为NAD+；CO2只释出1分子，2分子不符合"},{"q":"催化磷脂酰肌醇-4,5-二磷酸（PIP2）水解为1,4,5-三磷酸肌醇（IP3）的酶是","o":["磷脂酶A","磷脂酶C","磷脂酶A2","蛋白激酶C","蛋白激酶A"],"a":1,"e":"磷脂酶C水解磷脂酰肌醇-4,5-二磷酸生成1,4,5-三磷酸肌醇和二酰甘油，两者分别作为第二信使，故为答案。磷脂酶A2水解磷脂生成溶血磷脂与脂肪酸，磷脂酶A作用类似。蛋白激酶C与蛋白激酶A分别为被DAG、cAMP激活的蛋白激酶，并非水解PIP2的酶"},{"q":"下列化合物是乙酰CoA羧化酶的别构抑制剂的是","o":["柠檬酸","异柠檬酸","ATP","乙酰CoA","长链脂酰CoA"],"a":4,"e":"乙酰CoA羧化酶受柠檬酸、异柠檬酸别构激活，受软脂酰CoA及长链脂酰CoA别构抑制，后者使有活性多聚体解聚为无活性原聚体。AMPK使其磷酸化而失活，属化学修饰调节；乙酰CoA是该酶底物，柠檬酸是最重要的别构激活剂而非抑制剂"},{"q":"用于双向电泳分析的蛋白质样品制备，不正确的是","o":["待分析的蛋白质样品应处于溶解状态","样品在电泳时不能产生聚集和沉淀","应防止样品在制备过程中发生化学修饰","样品中含有核酸成分不影响蛋白质分离","应尽量除去高丰度的蛋白质"],"a":3,"e":"双向电泳要求蛋白质充分溶解、始终不聚集沉淀，制备过程避免人为化学修饰，并尽量去除高丰度蛋白以提高低丰度蛋白检出。核酸会显著增加样品黏度并与蛋白质结合，造成拖尾和假点，必须用DNase、RNase或超速离心除去，故“不影响分离”之说不成立"},{"q":"胆固醇代谢在肝内的最终产物是","o":["7α-胆固醇","脂酰CoA","结合胆汁酸","维生素D3","胆色素"],"a":2,"e":"胆固醇在肝内受7α-羟化酶催化生成初级胆汁酸，再与甘氨酸或牛磺酸结合成结合胆汁酸，随胆汁排入肠道，这是胆固醇在体内最主要的代谢去路。7α-羟胆固醇是中间产物，维生素D3与胆色素分别来自胆固醇侧链代谢和血红素分解，脂酰CoA与胆汁酸合成无关"},{"q":"印迹技术中最常用的固相介质是","o":["琼脂糖凝胶","醋酸纤维素薄膜","琼脂胶","硝酸纤维素膜","聚丙烯酰胺凝胶"],"a":3,"e":"印迹技术中最常用的固相介质是硝酸纤维素膜，DNA、RNA和蛋白质均可经毛细作用或电泳转移并吸附于此膜。琼脂糖凝胶与聚丙烯酰胺凝胶是电泳分离介质，醋酸纤维素薄膜用于电泳，均非印迹的固相支持物"},{"q":"使用质谱技术鉴定蛋白质组时，酶解的目的是","o":["使蛋白质降解成为单个氨基酸","使蛋白质降解成为肽段，形成肽质量指纹图谱","将多余的核酸除去","去掉蛋白质的磷酸化修饰","形成可供连接的黏性末端"],"a":1,"e":"蛋白质组学质谱分析前用胰蛋白酶等将蛋白质酶解为特定肽段，测定各肽段质量形成肽质量指纹图谱，再与数据库比对鉴定蛋白质，故为答案。酶解并非降解为单个氨基酸，也不是去除核酸或磷酸化修饰，形成黏性末端为分子克隆中限制酶的作用"},{"q":"下列哪种不是肝在脂类代谢中特有的作用","o":["酮体的生成","LDL的生成","VLDL的生成","胆汁酸的生成","LCAT的生成"],"a":1,"e":"LDL由VLDL在血浆中经脂解转变生成，并非在肝内生成，故不属于肝特有的作用。酮体在肝内生成，肝合成VLDL输出内源性甘油三酯，胆汁酸由肝内胆固醇转化生成，卵磷脂-胆固醇酰基转移酶由肝合成，均主要在肝进行"},{"q":"与原核生物核糖体小亚基结合的蛋白质合成抑制剂是","o":["链霉素","氯霉素","利福霉素","放线菌素","青霉素"],"a":0,"e":"链霉素与30S小亚基结合，使氨酰-tRNA在A位的校对出错、读码错误，并抑制起始复合物形成，属静止期杀菌药。氯霉素与50S亚基结合，抑制肽酰转移酶；四环素结合30S但阻断的是氨酰-tRNA进入A位；红霉素、克林霉素作用于50S，均不属小亚基结合类"},{"q":"关于应激状态血中成分的改变，错误的是","o":["脂肪动员加速","蛋白质分解减少","胰岛素水平降低","葡萄糖水平增高","肾上腺素水平增高"],"a":1,"e":"应激时交感神经兴奋，儿茶酚胺与糖皮质激素分泌增加、胰岛素分泌减少，肝糖原分解和糖异生增强使血糖升高，脂肪动员加速，蛋白质分解增强以提供糖异生原料。B项所述与应激时蛋白质分解加速的事实相反"},{"q":"某RNA为5'-UGACGA-3'，与其对应的DNA双链中的编码链为","o":["5'-ACTGCT-3'","5'-TGACGA-3'","5'-TCGTCA-3'","5'-UCGTCA-3'","5'-ACTGCU-3'"],"a":1,"e":"编码链序列与转录出的RNA一致，仅以T代替U，故5'-UGACGA-3'对应编码链为5'-TGACGA-3'。5'-ACTGCT-3'为与RNA互补的模板链序列，5'-TCGTCA-3'方向倒置出错。含U的5'-UCGTCA-3'、5'-ACTGCU-3'为RNA序列，不属DNA编码链"},{"q":"一个酶有多个底物时，其最适底物的Km","o":["＞10-3mmol/L","最大","＜10-6mmol/L","最小","与其他底物相同"],"a":3,"e":"Km反映酶与底物的亲和力，Km越小亲和力越大，故多种底物中最适底物的Km最小。Km数值随底物而异，不能以10-3或10-6mmol/L的绝对界限判断，也不存在各底物Km相同的规律"},{"q":"VLDL的生理功能是","o":["转运外源性甘油三酯","转运内源性胆固醇","转运自由脂酸","逆向转运胆固醇","转运内源性甘油三酯和胆固醇"],"a":4,"e":"VLDL由肝细胞组装，主要转运内源性甘油三酯，同时携带肝合成的胆固醇，其代谢终产物LDL转运内源性胆固醇。CM转运外源性甘油三酯，HDL逆向转运胆固醇，游离脂肪酸由清蛋白运输。VLDL在血中经LPL水解后依次转为IDL与LDL，密度逐渐升高"},{"q":"苯丙酮尿症绝大多数是由于苯丙氨酸羟化酶基因点突变（多为错义突变），导致肝脏苯丙氨酸羟化酶缺乏，致使苯丙氨酸不能转变为酪氨酸而产生的先天性代谢缺陷病。苯丙氨酸羟化酶催化的反应是","o":["天冬氨酸→苯丙氨酸","酪氨酸→苯丙氨酸","苯丙氨酸→酪氨酸","丙氨酸→苯丙氨酸","苯丙氨酸→苯丙酮酸"],"a":2,"e":"苯丙氨酸羟化酶是单加氧酶，以四氢生物蝶呤为辅酶，催化苯丙氨酸羟化为酪氨酸，反应不可逆。酶缺陷时苯丙氨酸经转氨基生成苯丙酮酸，由尿排出形成苯丙酮尿症。酪氨酸不能逆向转变为苯丙氨酸，转氨基产物是苯丙酮酸而非直接生成酪氨酸"},{"q":"将大肠杆菌的碳源由葡萄糖转变为乳糖时，细菌细胞内不发生","o":["乳糖转变为别乳糖","cAMP浓度升高","半乳糖与阻遏蛋白结合","RNA聚合酶与启动序列结合","阻遏蛋白与操纵序列结合"],"a":4,"e":"有乳糖时，乳糖经β-半乳糖苷酶转变为别乳糖，别乳糖与阻遏蛋白结合使其构象改变而脱离操纵序列，同时cAMP升高、CAP结合启动子，转录开放。此时半乳糖不是生理诱导物，RNA聚合酶可与启动序列结合，阻遏蛋白不再占据操纵序列"},{"q":"仅在细胞质内进行的代谢途径是","o":["三羧酸循环","氧化磷酸化","丙酮酸羧化","脂酸β-氧化","脂酸合成"],"a":4,"e":"脂肪酸合成从乙酰CoA羧化到软脂酸释放，全过程在细胞质溶胶中由脂肪酸合酶复合体完成，仅碳链延长可在线粒体或内质网进行。三羧酸循环在线粒体基质，氧化磷酸化在线粒体内膜，丙酮酸羧化在线粒体基质，β-氧化在线粒体"},{"q":"下述哪种物质专一地抑制F0因子","o":["鱼藤酮","抗霉素A","寡霉素","一氧化碳","H2S"],"a":2,"e":"寡霉素结合ATP合酶Fo的c亚基环，阻断质子回流，抑制氧化磷酸化。鱼藤酮抑制复合体Ⅰ，抗霉素A抑制复合体Ⅲ，一氧化碳与H2S抑制细胞色素c氧化酶，三者均作用于呼吸链而非Fo。寡霉素与Fo结合后质子通道关闭，膜两侧质子梯度不能经ATP合酶回流"},{"q":"反应6-磷酸果糖→1,6-双磷酸果糖，需要哪些条件","o":["果糖双磷酸酶-1、ATP和Mg2+","果糖双磷酸酶-1、ADP、Pi和Mg2+","6-磷酸果糖激酶-1、ATP和Mg2+","6-磷酸果糖激酶-1、ADP、Pi和Mg2+","ATP和Mg2+"],"a":2,"e":"6-磷酸果糖转变为1,6-双磷酸果糖是糖酵解第二个限速反应，由磷酸果糖激酶-1催化，需ATP与Mg2+参与，反应不可逆。果糖双磷酸酶-1催化其逆反应，是糖异生的关键酶；ADP与Pi不参与该磷酸化，只给ATP和Mg2+而缺酶也不能进行"},{"q":"关于别构调节叙述，错误的是","o":["别构调节具有放大效应","别构酶的动力学特点，是酶促反应速率与底物浓度的关系呈S形而非矩形双曲线","别构效应剂与酶的结合是可逆的","代谢途径的终产物通常是该途径起始反应酶的别构抑制剂","别构调节剂常是些小分子代谢物"],"a":0,"e":"别构调节通过效应剂与别构部位可逆结合改变酶构象，不具逐级放大效应；具有放大效应的是蛋白激酶级联的共价修饰调节。别构酶动力学呈S形曲线而非矩形双曲线；效应剂多为小分子代谢物；终产物常抑制途径起始酶且结合可逆，这些均正确"},{"q":"哺乳类动物自身能合成的脂肪酸是","o":["亚麻酸","软脂酸","花生四烯酸","亚油酸","二十二碳六烯酸"],"a":1,"e":"软脂酸是脂肪酸合酶复合体在胞质溶胶中以乙酰CoA为原料合成的16碳产物，是人体内源性脂肪酸合成的主要产物，再经延长与去饱和生成其他脂肪酸。亚油酸、亚麻酸属必需脂肪酸，人体缺乏Δ12、Δ15去饱和酶不能合成。花生四烯酸、二十二碳六烯酸需由必需脂肪酸衍生，同样不能自身合成"},{"q":"关于天然核酶描述正确的是","o":["是具有酶活性的RNA分子","是具有酶活性的DNA分子","是核酸与蛋白质共同组成的酶","只能水解RNA，不能水解DNA","可以水解多肽链"],"a":0,"e":"天然核酶是具有催化活性的RNA分子，可自我剪接或催化RNA水解，故为答案。其化学本质为RNA而非DNA，也不是核酸与蛋白质组成的复合酶。水解多肽链为蛋白酶的功能。只能水解RNA不能水解DNA的表述过于绝对且非核酶的定义要点，均非正确描述"},{"q":"百日咳毒素主要直接干扰哪种G蛋白活性","o":["激动型G蛋白（Gs）","抑制型G蛋白（Gi）","与视觉相关的G蛋白（Gt）","与离子通道开放相关的G蛋白（Go）","与磷脂酶C（PLC）活化相关的G蛋白（Gq）"],"a":1,"e":"百日咳毒素使Gi的α亚基ADP-核糖化，阻断Gi对腺苷酸环化酶的抑制，使cAMP升高。霍乱毒素修饰Gs并抑制其GTP酶活性而持续激活；Gt参与视觉信号转导，Gq激活磷脂酶C，Go调节离子通道"},{"q":"小明因为受伤需要抹点红霉素，红霉素作为一种抗生素，其作用原理是","o":["阻碍翻译起始复合物的形成","抑制氨酰-tRNA与小亚基结合","抑制转肽酶","引起读码错误","抑制EF-G"],"a":2,"e":"红霉素属大环内酯类，与细菌核糖体50S大亚基结合，抑制肽酰转移酶即转肽酶活性，并封阻肽链排出通道，阻断肽链延长。伊短菌素阻碍翻译起始，四环素抑制氨酰-tRNA结合小亚基，氨基糖苷类引起读码错误，夫西地酸抑制EF-G"},{"q":"下列有关蛋白聚糖的叙述，错误的是","o":["蛋白聚糖由糖胺聚糖共价连接于核心蛋白所组成","糖胺聚糖必含有糖胺","糖胺聚糖由二糖单位重复连接形成具有分支的结构","蛋白聚糖糖链的加工修饰主要在高尔基体内进行","糖胺的氨基来自谷氨酰胺"],"a":2,"e":"糖胺聚糖是由二糖单位重复连接而成的杂多糖，不分支，故C项错误。二糖单位之一为糖胺，即N-乙酰葡萄糖胺或N-乙酰半乳糖胺，其氨基来自谷氨酰胺；另一为糖醛酸。糖胺聚糖以共价键连于核心蛋白构成蛋白聚糖，糖链延长与修饰主要在高尔基体内完成"},{"q":"糖酵解途径中，可以生成ATP的第1个反应是","o":["葡萄糖到G-6-P反应","3-磷酸甘油醛到1,3-二磷酸甘油酸反应","6-磷酸果糖到1,6-双磷酸果糖反应","1,3-二磷酸甘油酸到3-磷酸甘油酸反应","3-磷酸甘油酸到2-磷酸甘油酸反应"],"a":3,"e":"1,3-二磷酸甘油酸在磷酸甘油酸激酶催化下将高能磷酸基转给ADP，生成3-磷酸甘油酸和ATP，是糖酵解首次底物水平磷酸化。葡萄糖磷酸化与果糖-6-磷酸磷酸化均消耗ATP，3-磷酸甘油酸转为2-磷酸甘油酸不产能"},{"q":"以下哪一项不涉及目的基因与载体的连接","o":["限制酶","单链核酸酶","核酸外切酶","DNA连接酶","末端脱氧核苷酸转移酶"],"a":2,"e":"目的基因与载体连接需用限制酶切割、DNA聚合酶补平或单链核酸酶削平末端、末端脱氧核苷酸转移酶加同聚物尾、DNA连接酶封口。核酸外切酶从末端逐步水解核苷酸，不参与连接反应，故不涉及目的基因与载体的连接"},{"q":"环化鸟苷酸（cGMP）能激活","o":["磷脂酶C","蛋白激酶A","蛋白激酶G","酪氨酸蛋白激酶","蛋白激酶C"],"a":2,"e":"环化鸟苷酸作为第二信使主要激活蛋白激酶G，进而磷酸化靶蛋白引发生理效应。磷脂酶C由Gq或受体酪氨酸激酶激活；蛋白激酶A受cAMP激活；蛋白激酶C受二酰甘油和Ca2+激活；酪氨酸蛋白激酶受生长因子受体等激活，均非cGMP的直接靶点"},{"q":"可激活胰蛋白酶原的是","o":["寡肽酶","二肽酶","肠激酶","胰蛋白酶","胃蛋白酶"],"a":2,"e":"胰蛋白酶原进入小肠后由肠黏膜分泌的肠激酶在第6位赖氨酸与第7位异亮氨酸间切断，去除六肽而激活，生成的胰蛋白酶又可自身激活。寡肽酶与二肽酶为消化肽类的酶，胃蛋白酶由胃酸激活，均不激活胰蛋白酶原"},{"q":"核苷酸中碱基（N）、戊糖（R）和磷酸（P）之间的连接关系是","o":["N-R-P","N-P-R","R-N-P","P-N-R","R-P-P-N"],"a":0,"e":"核苷酸中碱基与戊糖以糖苷键相连成核苷，戊糖C-5′的羟基再与磷酸酯化，故连接关系为碱基-戊糖-磷酸。核苷酸之间才通过3′,5′-磷酸二酯键相连成多核苷酸链，N-P-R、R-N-P等顺序均不符合实际连接方式"},{"q":"关于DNA损伤修复的SOS系统的叙述正确的是","o":["是一种保真性很高的复制过程","LexA蛋白是一系列操纵子的阻遏物","RecA基因在DNA损伤时被抑制","该系统只能修复嘧啶二聚体","紫外线损伤是主要的信号"],"a":1,"e":"SOS修复由RecA蛋白与LexA阻遏物相互作用启动，LexA是一系列SOS基因操纵子的共同阻遏物，DNA严重损伤时RecA被激活，促使LexA自水解而去阻遏。该修复由低保真DNA聚合酶介导、易出错，可修复多种损伤，紫外线只是诱因之一"},{"q":"在糖酵解、三羧酸循环中，都会产生还原型NADH＋H＋。此还原当量含有高电极电势的电子，也就是说，它们将在氧化时释放出大量的能量。然而，细胞不会一次性释放完全的能量，因为在这种情况下，反应将无法控制。相反，电子从NADH释放出来，并通过一系列的酶传递给氧气，其中每步只释放少量的能量。通过氧化磷酸化生成的高能化合物是","o":["ATP","辅酶A","UTP","CTP","磷酸烯醇式丙酮酸"],"a":0,"e":"氧化磷酸化是NADH、FADH2经呼吸链逐步传递电子、释放能量驱动ATP合酶使ADP磷酸化，生成的高能化合物为ATP。辅酶A为酰基载体，UTP、CTP参与糖原及磷脂合成，磷酸烯醇式丙酮酸是糖酵解中间物"},{"q":"关于疾病相关基因，以下说法中错误的是","o":["许多疾病都与基因结构或者表达变化有关","疾病相关基因可以分为致病基因和疾病易感基因","在肿瘤、心血管疾病中，通常包含2个以上疾病相关基因","疾病相关基因不具有正常的生物学功能","克隆疾病相关基因与确定基因功能密不可分"],"a":3,"e":"疾病相关基因在正常情况下仍执行正常的生物学功能，仅因结构变异或表达异常而参与疾病发生，故D项错误。许多疾病与基因结构或表达变化有关，疾病相关基因分为致病基因与易感基因，肿瘤与心血管疾病常涉及多个基因，克隆基因与确定其功能密不可分"},{"q":"有抗动脉粥样硬化作用的脂蛋白是","o":["CM","LDL","VLDL","oxLDL","HDL"],"a":4,"e":"HDL参与胆固醇逆向转运，把肝外组织包括动脉壁巨噬细胞的胆固醇运回肝代谢，故有抗动脉粥样硬化作用，其水平与发病率呈负相关。LDL将胆固醇送往肝外组织，过高促斑块形成；oxLDL被清道夫受体摄取，促泡沫细胞生成；CM与VLDL主要运输甘油三酯"},{"q":"原核生物蛋白质生物合成需要多种酶和蛋白质因子的参与，具有GTP酶活性的是","o":["RF-1","RF-2","RF-3","IF-1","IF-3"],"a":2,"e":"RF-3具有GTP酶活性，新生肽链释放后促进RF-1或RF-2与核糖体分离。RF-1识别UAA、UAG，RF-2识别UAA、UGA，二者诱导肽酰转移酶转变为酯酶；IF-1占据A位、IF-3防止大小亚基过早结合，均不具GTP酶活性"},{"q":"同工酶是指","o":["催化作用相同，但分子组成和理化性质不同的一类酶","催化相同反应，分子组成相同，但辅酶不同的一类酶","催化同一底物起不同反应的酶的总称","多酶体系中酶组分的统称","催化作用、分子组成及理化性质相同，但组织分布不同的酶"],"a":0,"e":"同工酶指催化相同的化学反应，但酶蛋白分子结构、理化性质与免疫学特性各不相同的一组酶，如乳酸脱氢酶的五种四聚体。催化不同反应者不属同工酶；辅基相同、Km相同均非其共同特征，各成员Km常有差异以适应不同组织的代谢需要"},{"q":"不以FAD为辅基的脱氢酶是","o":["二氢硫辛酰胺脱氢酶","脂酰CoA脱氢酶","琥珀酸脱氢酶","线粒体内膜磷酸甘油脱氢酶","β-羟脂酰CoA脱氢酶"],"a":4,"e":"β-羟脂酰CoA脱氢酶以NAD+为辅酶，催化β-羟脂酰CoA脱氢生成β-酮脂酰CoA。二氢硫辛酰胺脱氢酶、脂酰CoA脱氢酶、琥珀酸脱氢酶和线粒体内膜磷酸甘油脱氢酶均以FAD为辅基"},{"q":"彻底氧化一分子硬脂酰辅酶A（18∶0）所需消耗氧的分子数是","o":["16","23","26","30","32"],"a":2,"e":"硬脂酰CoA经8轮β-氧化生成9分子乙酰CoA、8分子FADH2和8分子NADH；9分子乙酰CoA经三羧酸循环耗18分子O2，8分子FADH2与8分子NADH各耗4分子O2，合计26分子O2。16、23分别按碳链长度或漏算脱氢当量得出，30与32是葡萄糖彻底氧化所得ATP数，单位与算法均错"},{"q":"e-PCR比BLAST具有更高的","o":["专一性","稳定性","同源性","保守性","变异性"],"a":0,"e":"e-PCR以多对引物在同一管内同时扩增多个已知序列，引物与模板必须完全互补才能延伸，非特异结合难以出峰，故专一性高于以局部相似性打分为基础的BLAST；后者善于发现远缘同源序列，灵敏度与信息量占优。速度、稳定性与灵敏度均非e-PCR所长，其优势在可同时检出多种病原或突变"},{"q":"维生素B1缺乏时出现的消化道蠕动慢，消化液比较少，食欲缺乏等症状，原因是","o":["维生素B1能促进胰蛋白酶的活性","维生素B1能促进胃蛋白酶的活性","维生素B1能抑制胆碱酯酶的活性","维生素B1能抑制乙酰胆碱的活性","维生素B1能促进胃蛋白酶原的活性"],"a":2,"e":"维生素B1是胆碱酯酶抑制剂，参与乙酰胆碱代谢调控；缺乏时乙酰胆碱分解加强、合成减少，神经传导受阻，出现消化液减少、胃蠕动变慢、食欲缺乏。维生素B1并不直接促进胰蛋白酶或胃蛋白酶活性，也不抑制乙酰胆碱的活性，故C项成立"},{"q":"人类DNA序列最常见的、最稳定的遗传变异是","o":["限制性片段长度多态性","可变数目串联重复序列","单核苷酸多态性","DNA指纹图谱","DNA甲基化"],"a":2,"e":"单核苷酸多态性指基因组中单个核苷酸置换或颠换引起的变异，人群频率高于1%，数量大、分布广、遗传稳定，是最常见的遗传变异与遗传标记。限制性片段长度多态性与可变数目串联重复属长度多态性，DNA指纹图谱是检测结果，甲基化属表观修饰"},{"q":"cAMP与CAP结合，CAP介导正性调节发生在下列的哪个阶段","o":["有葡萄糖及cAMP较高时","有葡萄糖及cAMP较低时","没有葡萄糖及cAMP较高时","没有葡萄糖及cAMP较低时","葡萄糖及cAMP浓度极高时"],"a":2,"e":"CAP须与cAMP结合后才能结合lac启动子上游的CAP位点，促进RNA聚合酶转录；细胞内cAMP水平受葡萄糖制约，缺乏葡萄糖时cAMP升高，同时乳糖存在解除阻遏，操纵子才高效表达。有葡萄糖时cAMP降低，CAP不能结合；葡萄糖抑制cAMP生成，故不可能出现葡萄糖缺乏又被抑制的并存状态"},{"q":"酶化学修饰调节的主要方式是","o":["酶蛋白的合成与降解","磷酸化与去磷酸化","聚合与解聚","甲基化与去甲基化","乙酰化与脱乙酰化"],"a":1,"e":"酶化学修饰以磷酸化与去磷酸化最为常见，由蛋白激酶和蛋白磷酸酶催化，修饰位点为丝氨酸、苏氨酸和酪氨酸的羟基。酶蛋白的合成与降解属酶含量调节，聚合与解聚、甲基化与乙酰化修饰均较少见"},{"q":"血浆蛋白质pI大多在5～6之间，它们在血液中的主要存在形式是","o":["带正电荷","疏水分子","非极性离子","兼性离子","带负电荷"],"a":4,"e":"血浆pH约7.4，高于血浆蛋白的等电点5～6，蛋白质的羧基解离多于氨基，净带负电荷，电泳时向正极移动。等电点时才呈兼性离子而净电荷为零，疏水分子与非极性离子的说法与其两性电离性质不符"},{"q":"通过免疫共沉淀的方法分析与抑癌蛋白TP53的相互作用蛋白质，经质谱分析后，下列哪个数据库可以检索到可能与TP53存在相互作用的蛋白质","o":["Swiss-Prot数据库","KEGG数据库","EST数据库","UniGene","MPSS"],"a":0,"e":"质谱测得肽段序列后须检索蛋白质序列数据库以确定蛋白身份，Swiss-Prot注释详尽，含序列、功能及相互作用信息，是首选库。KEGG为通路数据库，EST与UniGene属转录本相关库，MPSS用于表达标签测序，均不提供蛋白质序列的比对与鉴定"},{"q":"聚合酶链反应扩增产物片段大小决定于","o":["DNA聚合酶","引物","模板","循环次数","三磷酸脱氧核苷的纯度"],"a":1,"e":"PCR扩增产物的长度严格限定在一对引物5′-端之间，故片段大小由引物在模板上的位置决定。DNA聚合酶、dNTP纯度与循环次数影响产量和保真性，模板只提供序列信息，均不决定产物长度"},{"q":"合成磷脂酰胆碱时所需的活性胆碱是","o":["ADP-胆碱","GDP-胆碱","UDP-胆碱","CDP-胆碱","TDP-胆碱"],"a":3,"e":"合成磷脂酰胆碱时，胆碱先活化生成CDP-胆碱，再与甘油二酯缩合形成磷脂酰胆碱。ADP-胆碱、GDP-胆碱、UDP-胆碱、TDP-胆碱均不是该途径的活化形式；UDP-糖参与糖原合成，CDP-胆碱才是胆碱的活化载体"},{"q":"艾滋病（AIDS）是目前威胁人类生命的重要疾病之一。能导致艾滋病的HIV病毒是RNA病毒。它感染人的T淋巴细胞，导致人的免疫力下降，使患者死于广泛感染。该病毒进入细胞后，能以病毒RNA为模板，合成病毒DNA，并整合于人的基因组中。这一过程称为","o":["复制","转录","逆转录","RNA复制","翻译"],"a":2,"e":"以RNA为模板合成DNA称逆转录，由逆转录酶催化，产物双链DNA整合入宿主基因组形成前病毒。以DNA为模板合成RNA为转录；RNA直接指导RNA合成见于RNA复制。翻译指以mRNA为模板合成蛋白质，复制指DNA的自我拷贝"},{"q":"生物体内物质代谢调节的基础是","o":["整体水平调节","激素水平调节","细胞水平调节","代谢通路的调节","关键酶的调节"],"a":2,"e":"代谢调节分细胞、激素、整体三个水平，细胞水平调节通过改变关键酶的活性与含量控制代谢流量，是激素与神经调节得以实现的最终环节，故为整个调节体系的基础。激素水平调节与整体水平调节均须通过细胞水平发挥作用；代谢通路的调节与关键酶的调节是细胞水平调节的具体方式，不是层次概括"},{"q":"在基因治疗中，基因转移的生物学方法主要是用哪项来介导基因导入","o":["质粒载体","病毒载体","脂质体","电穿孔","基因枪"],"a":1,"e":"基因转移的生物学方法以病毒为载体介导基因导入，利用病毒对细胞的天然感染能力将目的基因送入细胞。质粒载体、脂质体、电穿孔和基因枪分别属于非病毒载体或物理、化学方法，不依赖病毒的生物学感染机制"},{"q":"Cori循环以其发现者卡尔·斐迪南·科里（Carl Ferdinand Cori）和盖蒂·科里（Gerty Cori）夫妇命名，因为科里夫妇在糖原分解方面的贡献而与阿根廷的科学家伯纳德·何塞（Bcrnardo Houssay，1887~1971）共同分享1947年的诺贝尔生理学或医学奖。Cori循环是指","o":["肌肉内葡萄糖酵解成乳酸，有氧时乳酸重新合成糖原","肌肉从丙酮酸生成丙氨酸，肝内丙氨酸重新变成丙酮酸","肌肉内蛋白质降解生成丙氨酸，经血液循环至肝内界生为糖原","肌肉内葡萄糖酵解成乳酸，经血液循环至肝内异生为葡萄糖供外周组织利用","肌肉内蛋白质降解生成氨基酸，经转氨酶与腺苷酸脱氨酶偶联脱氨基的循环"],"a":3,"e":"肌肉糖无氧氧化生成乳酸，乳酸经血入肝异生为葡萄糖，再回肌肉利用，即乳酸循环。肌组织缺乏葡萄糖-6-磷酸酶，乳酸不能直接复糖原；丙氨酸-葡萄糖循环转运的是氨，两者常被互换设错。该循环每转运2分子乳酸需消耗6个高能磷酸键，属耗能过程"},{"q":"Gly和Ser在分解代谢中形成的一碳单位均为","o":["二氧化碳","—CH3","＝CH2","≡CH","—CHO"],"a":2,"e":"甘氨酸经甘氨酸裂解酶系脱去CO2与氨，生成N5,N10-亚甲基四氢叶酸；丝氨酸经丝氨酸羟甲基转移酶脱去羟甲基，同样生成N5,N10-亚甲基四氢叶酸，故二者的共同一碳单位形式为亚甲基。—CH3为N5-甲基，—CHO为N10-甲酰基，≡CH为N5,N10-次甲基，CO2不属一碳单位"},{"q":"下列关于肽的叙述，错误的是","o":["肽是两个或两个以上氨基酸通过肽键连接而成的化合物","组成肽的氨基酸分子都不完整","肽没有氨基末端和羧基末端","肽链中的氨基酸称为氨基酸残基","肽分为寡肽和多肽"],"a":2,"e":"肽链两端分别保留游离的α-氨基（氨基末端）和α-羧基（羧基末端），故肽没有氨基末端和羧基末端的说法错误。肽由两个以上氨基酸经肽键连接而成，组成后氨基酸残余部分称为氨基酸残基，肽分为寡肽和多肽，这些均正确"},{"q":"下列哪项不是糖异生途径的关键酶","o":["葡糖-6-磷酸酶","果糖双磷酸酶-1","丙酮酸激酶","磷酸烯醇丙酮酸羧化激酶","丙酮酸羧化酶"],"a":2,"e":"糖异生绕过糖酵解的三个不可逆反应，关键酶为丙酮酸羧化酶、磷酸烯醇式丙酮酸羧激酶、果糖二磷酸酶-1和葡糖-6-磷酸酶。丙酮酸激酶催化磷酸烯醇式丙酮酸生成丙酮酸，是糖酵解的关键酶，与糖异生方向相反，故不属糖异生关键酶"},{"q":"进食后被吸收入血的单糖，最主要的去路是","o":["在肝、肌肉等组织中合成糖原","在组织器官中氧化供能","在体内转变为脂肪","在体内转变为部分氨基酸","进行无氧氧化供能"],"a":1,"e":"吸收入血的葡萄糖在各组织氧化分解供能，是其最主要去路，占绝大部分。合成糖原受肝、肌糖原容量限制，转变为脂肪与氨基酸的量很少，无氧氧化仅在供氧不足时增强。血糖升高时胰岛素促进葡萄糖进入肌肉与脂肪组织，氧化与储存同步增强"},{"q":"有关血浆脂蛋白的叙述正确的是","o":["CM在脂肪组织中合成","HDL是从LDL中转变来","VLDL可转变成LDL","LDL和HDL竞争肝外受体","HDL运输胆固醇到肝外利用"],"a":2,"e":"VLDL在血液中经脂蛋白脂肪酶水解甘油三酯、接受HDL转移的胆固醇酯，逐步转为中间密度脂蛋白，最终成为LDL。CM在小肠黏膜合成，HDL由肝和小肠分泌新生颗粒并逆向转运胆固醇至肝，LDL受体分布于肝及肝外组织"},{"q":"视网膜母细胞瘤癌变是RB基因突变为rb或缺失引起的，其中涉及的机制属于","o":["癌基因异常活化","抑癌基因异常失活","基因组不稳定","表观遗传改变","基因重排"],"a":1,"e":"RB是最早发现的抑癌基因，两个等位基因先后突变或缺失即二次打击导致功能丧失，G1/S检查点失控而癌变，属抑癌基因异常失活。癌基因异常活化需原癌基因突变或扩增，基因组不稳定与表观遗传改变是其他机制，基因重排多见于白血病"},{"q":"关于细胞癌基因的叙述正确的是","o":["又称为病毒癌基因","存在于DNA病毒中","存在于RNA病毒中","存在于正常生物基因组中","正常细胞含有即可导致肿瘤的发生"],"a":3,"e":"细胞癌基因即原癌基因，存在于正常细胞基因组中，是调控增殖与分化的正常基因，仅在突变、扩增或易位激活后才致癌。病毒癌基因存在于逆转录病毒中，是原癌基因的转导拷贝；正常细胞含原癌基因并不必然发生肿瘤"},{"q":"心房钠尿肽发挥调节作用的信息通路是","o":["JAK-STAT途径","cGMP-PKG途径","RTK-Ras-MAPK途径","Ca2+-CaM途径","cAMP-PKA途径"],"a":1,"e":"心房钠尿肽与受体结合后激活受体型鸟苷酸环化酶，使cGMP生成增多，cGMP激活蛋白激酶G发挥排钠利尿、扩血管作用，故为cGMP-PKG途径。JAK-STAT为细胞因子受体通路，RTK-Ras-MAPK为生长因子通路，Ca2+-CaM与cAMP-PKA为其他第二信使途径，均非心房钠尿肽的主要通路"},{"q":"转录前起始复合物（PIC）是指","o":["RNA聚合酶与DNA结合的复合物","RNA聚合酶与pppGpN-OH结合的复合物","各类转录因子与DNA模板结合后的复合物","各种转录因子与RNA聚合酶及DNA模板结合的复合物","各种转录因子与RNA聚合酶结合的复合物"],"a":3,"e":"转录前起始复合物由RNA聚合酶Ⅱ、通用转录因子与启动子DNA有序结合形成，三者缺一不可，故D项完整。A、E项遗漏转录因子或DNA模板，C项缺少RNA聚合酶。B项描述的是转录起始后形成首个磷酸二酯键的产物，并非复合物本身"},{"q":"乳糖操纵子及色氨酸操纵子阻遏蛋白去阻遏通过","o":["阻遏蛋白化学修饰","阻遏蛋白变构调节","阻遏蛋白水平改变","组蛋白乙酰化","蛋白水解酶水解"],"a":1,"e":"乳糖操纵子的诱导物、色氨酸操纵子的辅阻遏物均通过与阻遏蛋白结合引起其构象（变构）改变，从而改变其与操纵序列的结合能力，实现去阻遏或阻遏，属阻遏蛋白的变构调节。该过程不涉及阻遏蛋白的化学修饰、水平改变、组蛋白乙酰化或蛋白水解"},{"q":"脂肪酰CoA进行β-氧化的反应顺序为","o":["脱氢、脱水、再脱氢、硫解","硫解、脱氢、加水、再脱氢","脱氢、加水、再脱氢、硫解","脱氢、再脱氢、加水、硫解","加水、脱氢、硫解、再脱氢"],"a":2,"e":"一次β-氧化依次为脂酰CoA脱氢生成烯脂酰CoA、加水生成β-羟脂酰CoA、再脱氢生成β-酮脂酰CoA、硫解断裂释放乙酰CoA。硫解是末步而非首步；先加水或连续两次脱氢均与酶促反应的实际顺序不符"},{"q":"下列哪项不是限制性核酸内切酶识别序列的特点","o":["特异性很高","其切口均为黏性末端","一般具有回文结构","有些限制性酶虽然识别的序列不同但是可产生相同的黏端","常由4～6个核苷酸组成"],"a":1,"e":"Ⅱ型限制酶识别4～8个碱基的回文序列，切割具高度特异性，不同酶识别不同序列却可产生相同黏端（同尾酶），故特异性高、回文结构、4～6个核苷酸、可产生相同黏端均是其特点。切口并非都是黏性末端，SmaⅠ等切割产生平末端，无法互补配对连接，故“均为黏性末端”不能成立"},{"q":"关于脂组学的描述，错误的是","o":["研究生物体内所有脂质分子","不研究蛋白质的脂质化修饰","研究脂质及其代谢物","寻找疾病诊断的脂质标志物","研究血液中的脂质分子"],"a":1,"e":"脂质组学研究生物样本中全部脂质及其代谢物，用于寻找疾病脂质标志物，也涵盖蛋白质的脂质化修饰等脂质修饰。认为它不研究蛋白质脂质化修饰与该定义相悖；研究所有脂质分子、脂质代谢物、血液脂质均属其范围"},{"q":"通过检测DNA序列线性核苷酸信息来分析基因异常的方法是","o":["基因芯片","DNA测序","核型分析","荧光原位杂交","等位基因特异性寡核苷酸杂交"],"a":1,"e":"DNA测序通过测定片段中四种碱基的排列顺序，直接读出核苷酸的线性序列，是鉴定基因异常最准确的方法。基因芯片与等位基因特异性寡核苷酸杂交属杂交类检测，只能判断已知位点；核型分析观察染色体数目与结构，荧光原位杂交定位特定序列，均不读取序列"},{"q":"某种遗传性疾病患者，其皮肤对阳光特别敏感，照射后出现红斑、水肿、继而出现色素沉着，儿童期即可诱发皮肤肿瘤。该病发生的分子机制为","o":["LexA类基因缺陷","Uvr类基因缺陷","XP类基因缺陷","光修复基因缺陷","DNA聚合酶基因缺陷"],"a":2,"e":"着色性干皮病因XP类基因缺陷致核酸内切酶缺乏，切除修复功能受损，紫外线形成的嘧啶二聚体不能清除，故光敏并早发皮肤肿瘤。Uvr类基因是细菌切除修复基因，LexA为细菌SOS调控基因，光修复依赖光复活酶而非XP基因"},{"q":"胰岛素作为抗脂解激素，主要作用是抑制了","o":["磷酸二酯酶","甘油一酯脂肪酶","甘油二酯脂肪酶","甘油三酯脂肪酶","腺苷酸环化酶"],"a":3,"e":"胰岛素是抗脂解激素，通过激活磷酸二酯酶降低cAMP，使激素敏感性甘油三酯脂肪酶去磷酸化而失活，抑制脂肪动员。脂解激素经cAMP激活蛋白激酶A，磷酸化该酶与ATGL促进脂解；腺苷酸环化酶催化cAMP生成，抑制它与抗脂解作用相反"},{"q":"关于Lesch-Nyhan综合征，下列叙述有误的是","o":["又称为自毁容貌症","是一种X染色体连锁的隐性遗传的先天性嘧啶代谢缺陷症","主要是由于基因缺陷导致HGPRT完全缺失","患者常出现自残行为","常伴随高尿酸血症"],"a":1,"e":"Lesch-Nyhan综合征因HGPRT基因缺陷致嘌呤补救合成障碍，PRPP堆积使从头合成增强、尿酸生成增多，表现为自残、智力低下与高尿酸血症。该病是X连锁隐性遗传的嘌呤代谢缺陷，而非嘧啶代谢缺陷"},{"q":"1g软脂酸钠（分子量=256）较1g葡萄糖（分子量=180）彻底氧化所释放出的ATP数约高","o":["2倍","2、5倍","3倍","3、5倍","5倍"],"a":1,"e":"1g软脂酸（分子量256）彻底氧化净生成106分子ATP，约0.41mol ATP/g；1g葡萄糖（180）生成32分子ATP，约0.18mol ATP/g，比值约2.3～2.5。脂肪酸碳氢比例高、还原当量多，单位质量产能显著高于糖；2倍、3倍、3.5倍与5倍均偏离该计算值"},{"q":"催化单纯电子转移的酶是","o":["以NAD+为辅酶的酶","需氧脱氢酶","加单氧酶","细胞色素氧化酶","泛醌"],"a":3,"e":"细胞色素氧化酶通过血红素铁与铜离子的价态变化催化单纯电子传递，将电子从细胞色素c传给氧，故为答案。以NAD+为辅酶的脱氢酶催化氢即电子加质子的转移。需氧脱氢酶以氧为受氢体生成H2O2。加单氧酶催化羟基化反应。泛醌为电子传递体而非酶"},{"q":"假设大肠杆菌中cAMP环化酶基因突变，其乳糖操纵子基因表达调控会受到什么影响","o":["β-半乳糖苷酶的表达减少","cAMP-CAP复合物增加","阻遏蛋白不结合在操纵序列上","RNA聚合酶与启动序列结合","可在没有葡萄糖只有乳糖的培养基中正常生长"],"a":0,"e":"腺苷酸环化酶基因突变使cAMP生成减少，CAP-cAMP复合物不足，RNA聚合酶难以结合启动子，β-半乳糖苷酶表达下降。阻遏蛋白仍结合操纵序列，该菌在仅有乳糖的培养基中不能正常生长"},{"q":"N-连接型聚糖合成时的糖基供体底物必须活化成","o":["UDP或GDP衍生物","UDP或ADP衍生物","UDP或CDP衍生物","ADP或GDP衍生物","ADP或TDP衍生物"],"a":0,"e":"N-连接型聚糖合成时糖基须活化为UDP或GDP衍生物，如UDP-GlcNAc、GDP-甘露糖，再转移至长萜醇载体上组装。ADP、CDP、TDP衍生物另有用途，如CDP-胆碱用于磷脂酰胆碱合成"},{"q":"下列代谢途径不需要线粒体内反应的是","o":["磷脂合成","酮体合成","糖异生","脂肪酸β-氧化","柠檬酸循环"],"a":0,"e":"磷脂合成的酶系位于内质网，全程不需线粒体参与。糖异生部分步骤在线粒体，如丙酮酸羧化；尿素合成起始于线粒体，氨甲酰磷酸在此生成；三羧酸循环与氧化磷酸化完全在线粒体；胆固醇合成虽主要在内质网与胞质，其原料乙酰CoA仍需线粒体生成后转运"},{"q":"胰液中的蛋白水解酶最初以酶原形式存在其意义是","o":["抑制蛋白酶的分泌","缺乏适当的酶原激活剂","促进蛋白酶的分泌","避免胰腺自身被消化","抑制蛋白质发挥消化作用"],"a":3,"e":"胰蛋白酶、糜蛋白酶、弹性蛋白酶均以酶原形式分泌，入十二指肠后由肠激酶激活胰蛋白酶原，再依次激活其余酶原，可避免酶在胰腺内提前激活而消化自身组织，胰液中还有胰蛋白酶抑制剂作保障。缺乏激活剂、促进分泌、抑制分泌均不能解释酶原形式的意义"},{"q":"下列关于O-连接型聚糖的叙述，不正确的是","o":["核心二糖可形成分支","在多肽链合成的同时进行O-连接型聚糖的合成","合成时需要糖基转移酶","含有N-乙酰半乳糖胺和半乳糖组成的核心二糖","O-连接型聚糖的合成不需要糖链载体"],"a":1,"e":"O-连接型聚糖是在多肽链合成完毕后，由GalNAc转移酶将UDP-GalNAc中的GalNAc转移至丝氨酸或苏氨酸羟基上，再逐个延长糖基，不需要糖链载体，故B项错误。其核心二糖由N-乙酰半乳糖胺与半乳糖组成，可以分支，合成依赖糖基转移酶。N-连接型聚糖才在肽链合成的同时于内质网进行"},{"q":"ATP的功能不包括","o":["为生物反应供能","合成RNA","转变成cAMP","贮存化学能","转变为UDPGA"],"a":4,"e":"ATP可为生物反应供能、贮存化学能、作为RNA合成的原料，并可经腺苷酸环化酶转变为cAMP。UDPGA由UTP与葡萄糖-1-磷酸反应生成，其葡萄糖醛酸基供体来源于UTP而非ATP"},{"q":"1分子琥珀酸脱氢生成延胡索酸时，脱下的1对氢经过呼吸链氧化生成水，同时生成多少分子ATP","o":["1","1、5","2","2、5","3"],"a":1,"e":"琥珀酸脱氢酶以FAD为辅基，脱下的氢经FADH2从复合体Ⅱ进入呼吸链，只经过复合体Ⅲ、Ⅳ两个偶联部位，生成1.5分子ATP。经NADH呼吸链氧化则生成2.5分子ATP，2与3为旧版计算值，不适用于现行P/O比值"},{"q":"可用于蛋白质乙酰化修饰分析的技术是","o":["NMR","HPLC/MS/MS","2DE/MS","SAGE","SNP分析"],"a":1,"e":"乙酰化修饰发生于赖氨酸残基的ε-氨基，质谱可测出修饰肽段的质量增加，故用高效液相色谱串联质谱分析富集后的修饰肽。NMR测定空间结构，2DE/MS用于蛋白质表达谱比较，SAGE用于转录本定量，SNP分析检测的是基因序列多态性"},{"q":"健康成年人摄入充足的高脂低糖低蛋白膳食1小时后，心肌细胞中哪个酶的活性会明显增强","o":["乙酰CoA羧化酶","磷酸果糖激酶-1","肉碱脂酰转移酶Ⅰ","丙酮酸脱氢酶复合体","L-谷氨酸脱氢酶"],"a":2,"e":"高脂低糖膳食使糖供能不足，脂肪酸氧化加强，肉碱脂酰转移酶Ⅰ活性升高，该酶催化脂酰CoA进入线粒体，是β-氧化的限速步骤。乙酰CoA羧化酶为脂肪酸合成的限速酶，此时受丙二酸单酰CoA减少而相对活跃，方向相反。磷酸果糖激酶-1与丙酮酸脱氢酶复合体在糖供应不足时活性下降"},{"q":"下列关于血浆中的胆固醇酯正确的叙述是","o":["由小肠吸收入血","由血浆脂蛋白释出","由肝外组织释放入血","在血浆中经酶的催化生成","由肝脏合成后释放入血"],"a":3,"e":"血浆游离胆固醇由卵磷脂-胆固醇酰基转移酶催化，接受卵磷脂sn-2位脂酰基生成胆固醇酯，故胆固醇酯在血浆内经酶促反应生成。小肠吸收的是游离胆固醇，酯需先水解；肝外组织与肝释放入血的是游离胆固醇，酯化主要在血浆完成，脂蛋白本身不释出胆固醇酯"},{"q":"催化PIP2水解产生第二信使DAG和IP3的酶是","o":["磷脂酶A1","磷脂酶A2","磷脂酶B","磷脂酶C","磷脂酶D"],"a":3,"e":"磷脂酰肌醇特异性磷脂酶C水解PIP2的磷酸二酯键，生成DAG和IP3两种第二信使。磷脂酶A1、A2水解甘油磷脂的酯键释出脂肪酸，磷脂酶B兼具A1与A2活性，磷脂酶D水解磷酸胆碱键生成磷脂酸，均不产生DAG和IP3"},{"q":"生物体内脱氨基主要方式是","o":["直接脱氨基","联合脱氨基","转氨基","氧化脱氨","还原脱氨"],"a":1,"e":"联合脱氨基即转氨基与L-谷氨酸氧化脱氨基相偶联，先由转氨酶把氨基转给α-酮戊二酸生成谷氨酸，再由谷氨酸脱氢酶脱氨，是体内脱氨基的主要方式。单纯转氨基并未真正脱去氨基，故C项不算脱氨方式。直接脱氨基与还原脱氨在体内均少见"},{"q":"现有15N标记DNA双链，当以NH4Cl作为氮源复制DNA时，产生不含15N的子代DNA分子时是","o":["第1代","第2代","第3代","第4代","第5代"],"a":1,"e":"半保留复制时亲代两条15N链彼此分离，子代各保留一条旧链。第1代全部为15N/14N杂合DNA；第2代中两条链均含14N的分子才开始出现，占1/2。第3、4代只是纯14N分子的比例增加，故不含15N者始见于第2代"},{"q":"不需要SAM提供甲基生成的物质是","o":["肾上腺素","胸腺嘧啶","胆碱","肌酸","肉碱"],"a":1,"e":"dTMP由dUMP经胸苷酸合酶催化甲基化生成，甲基供体是N5,N10-亚甲四氢叶酸而非SAM。肾上腺素由去甲肾上腺素经SAM提供甲基生成，胆碱、肌酸、肉碱的合成都需SAM作为甲基供体，SAM是体内最主要的甲基直接供体"},{"q":"下列关于DNA自动测序技术的描述，正确的是","o":["比传统DNA测序更快捷方便","其基本原理完全不同于Sanger测序法","需要放射性核素处","基本Sanger测序法的原理","4个反应管中的引物所标记的荧光染料波长相同"],"a":0,"e":"自动DNA测序以Sanger双脱氧链终止法为基础，用四色荧光标记ddNTP，经毛细管电泳与激光检测自动读序，较手工测序快捷方便。其原理与Sanger法相同而非完全不同，不需放射性核素，四种荧光染料的波长各不相同"},{"q":"基因重组中对于重组DNA分子的筛选方法，下列哪种不正确","o":["分子杂交和放射自显影法","酶切后电泳方法","表型筛选","基因表达产物的鉴定","DNA分子量分析"],"a":4,"e":"重组体筛选依靠载体选择标记、限制性酶切图谱、核酸杂交及表达产物鉴定，DNA分子量分析只是电泳显示的片段大小，不能区分重组体与空载体，故E项不正确。分子杂交结合放射自显影可定位目的序列，表型筛选依据抗性或营养缺陷，酶切电泳可比较插入片段长度"},{"q":"肝细胞性黄疸，临床生化检查不应该出现","o":["血清结合胆红素上升","血清总胆红素上升","血清未结合胆红素上升","尿胆红素阳性","粪便颜色呈陶土色"],"a":4,"e":"肝细胞性黄疸时肝细胞摄取、转化与排泄胆红素功能障碍，血中结合与未结合胆红素均升高，尿胆红素阳性，粪胆素原减少使粪便颜色变浅，但不会呈陶土色。陶土色粪便是胆道完全阻塞、胆红素不能进入肠道的特征，故该项不应出现"},{"q":"转氨酶一般含有哪种维生素","o":["B1","B2","B3","B5","B6"],"a":4,"e":"转氨酶的辅酶是磷酸吡哆醛，为维生素B6的活性形式，在转氨基反应中作为氨基载体。维生素B1（TPP）参与α-酮酸氧化脱羧，维生素B2（FAD/FMN）参与氧化还原，维生素B3（NAD+/NADP+）为脱氢酶辅酶，维生素B5（泛酸）构成辅酶A，均非转氨酶的辅酶"},{"q":"下列选项中，一般不用于未知疾病相关基因分离鉴定的方法是","o":["抑制性消减杂交","基因表达阵列分析","基因鉴定集成法","重组克隆表达抗原的血清学鉴定（SEREX）","RT-PCR"],"a":4,"e":"抑制性消减杂交、基因表达阵列分析、基因鉴定集成法、SEREX均可从差异入手分离未知疾病相关基因。RT-PCR需已知序列设计引物，用于已知基因的表达检测与定量，不适用于未知基因的分离鉴定"},{"q":"磷酸戊糖途径的重要生理功能之一是生成","o":["6-磷酸葡萄糖","NADH+H+","NADPH+H+","5-磷酸葡萄糖","生成多碳糖"],"a":2,"e":"戊糖磷酸途径的生理功能是生成NADPH和核糖-5-磷酸，前者供脂肪酸、胆固醇合成及谷胱甘肽还原所需。6-磷酸葡萄糖是该途径底物，NADH由糖酵解产生，5-磷酸葡萄糖并非代谢物，多碳糖不是其产物形式"},{"q":"经转氨基作用生成草酰乙酸的氨基酸是","o":["色氨酸","酪氨酸","丙氨酸","谷氨酸","天冬氨酸"],"a":4,"e":"天冬氨酸经谷草转氨酶催化脱去氨基，其碳骨架即草酰乙酸。丙氨酸脱氨生成丙酮酸，谷氨酸脱氨生成α-酮戊二酸，色氨酸与酪氨酸分解生成乙酰乙酰CoA等生酮中间物。谷氨酰胺与天冬酰胺须先脱去酰胺氮生成谷氨酸、天冬氨酸，再参与转氨基"},{"q":"下列哪一种氨基酸是亚氨基酸","o":["赖氨酸","脯氨酸","组氨酸","精氨酸","异亮氨酸"],"a":1,"e":"脯氨酸的α-氨基与侧链形成吡咯环，属亚氨基酸，其氮原子在环中，旋转自由度受限，但仍能与羧基形成肽键。赖氨酸、组氨酸、精氨酸为碱性氨基酸，异亮氨酸为支链氨基酸，均含游离的α-氨基。亚氨基酸的氮不游离，性质与α-氨基不同，是氨基酸分类的依据之一"},{"q":"肝脏在维生素代谢中的作用不包括","o":["多种B族维生素转变成辅酶成分","肝细胞内加双氧酶可将β-胡萝卜素裂解成维生素A","95%的维生素B1贮存于肝脏","95%的维生素A贮存于肝脏","将维生素D3羟化成25-OH-D3"],"a":2,"e":"维生素B1为水溶性维生素，体内贮存量很少，并不在肝大量贮存；而约95%的维生素A为脂溶性，主要贮存于肝，故该项错误。肝可将多种B族维生素转变成辅酶成分，含加双氧酶将β-胡萝卜素裂解成维生素A，并将维生素D3羟化为25-OH-D3，均为肝在维生素代谢中的作用"},{"q":"1mol葡萄糖经糖的有氧氧化过程，可生成的乙酰CoA是","o":["1mol","2mol","3mol","4mol","5mol"],"a":1,"e":"1分子葡萄糖经糖酵解生成2分子丙酮酸，每分子丙酮酸氧化脱羧生成1分子乙酰CoA，共生成2分子乙酰CoA，故为2mol。1mol仅对应不完全氧化。3、4、5mol均不符合6碳葡萄糖分解为2分子三碳丙酮酸再各生成1分子乙酰CoA的计量关系"},{"q":"限制性内切核酸酶切割5'…GG▼AATTCC…3'序列后应产生","o":["5'突出末端","3'突出末端","5'或3'突出末端","平端","黏性末端与平末端都会生成"],"a":0,"e":"EcoRⅠ识别GGATCC，在G与A之间交错切割，产生5'端突出的黏性末端AATT，便于与配伍末端连接。平端由SmaⅠ等在同一位置切断双链产生。该酶只生成黏端，既不产生3'突出末端，也不会同时生成黏端与平端"},{"q":"下列哪种化合物不是高能化合物","o":["6-磷酸葡萄糖","ATP","琥珀酰辅酶A","PEP","GTP"],"a":0,"e":"6-磷酸葡萄糖的磷酸酯键为普通低能键，水解仅释放少量能量，不属高能化合物。ATP、GTP的末端磷酸键，琥珀酰CoA的硫酯键，磷酸烯醇式丙酮酸的烯醇磷酸键均为高能键。高能键指水解时释放能量大于21kJ/mol的化学键"},{"q":"患急性肝损伤的病人，其尿液检测指标与正常人不同，通过代谢组学分析，发现其尿液中含量显著升高的是","o":["尿胆素原","尿胆素","尿胆红素","尿素","尿酸"],"a":2,"e":"急性肝损伤时肝细胞摄取、结合和排泄胆红素障碍，结合胆红素反流入血，经肾滤过使尿胆红素阳性并显著升高。尿胆红素为结合胆红素，水溶性强可直接经尿排出。尿胆素原、尿胆素为肠道还原产物，其变化见于溶血或肠肝循环改变；尿素、尿酸反映蛋白与嘌呤代谢，非肝损伤胆红素代谢的特异指标"},{"q":"可降低细胞内环化腺苷酸（cAMP）含量的酶是","o":["腺苷酸环化酶","ATP酶","磷脂酶","磷酸二脂酶","蛋白激酶"],"a":3,"e":"磷酸二酯酶水解cAMP的3′,5′-磷酸二酯键生成5′-AMP，从而降低细胞内cAMP含量。腺苷酸环化酶催化ATP生成cAMP使其升高，ATP酶水解ATP，磷脂酶水解磷脂，蛋白激酶催化蛋白质磷酸化"},{"q":"在四氢叶酸中，除了影响蛋白质的合成外，还可以迅速影响下列哪种物质合成","o":["糖","三磷脂酰甘油","胆固醇酯","DNA","磷脂"],"a":3,"e":"四氢叶酸是一碳单位载体，其N5,N10-亚甲基衍生物提供dUMP甲基化生成dTMP所需甲基，N10-甲酰基参与嘌呤环合成，故缺乏时DNA合成迅速受阻、细胞分裂停滞。糖、磷脂、胆固醇酯的合成都不需要一碳单位，不受影响；蛋白质合成减少是核酸合成障碍的继发结果"},{"q":"下列关于胆红素的叙述，错误的是","o":["完全游离的胆红素可引起大脑不可逆的损害","血液中胆红素与清蛋白结合而被运输","血浆中胆红素含量超过17、1μmol/L，即为高胆红素血症","胆红素本身是强抗氧化剂","正常人血清胆红素中80%是结合胆红素"],"a":4,"e":"正常成人血清总胆红素中未结合胆红素约占80%，结合胆红素仅0～8μmol/L，故该项错误。游离胆红素为脂溶性，易透过细胞膜对神经细胞造成不可逆损害，血中主要与清蛋白结合运输，本身是强抗氧化剂，超过参考上限即为高胆红素血症"},{"q":"供氧不足时，3-磷酸甘油醛脱氢产生的NADH+H+的主要去路是","o":["参加脂肪酸的合成","使丙酮酸还原生成乳酸","维持GSH处于还原状态","经α-磷酸甘油穿梭进入线粒体氧化","苹果酸-天冬氨酸穿梭进入线粒体氧化"],"a":1,"e":"供氧不足时，胞质中NADH不能经穿梭进入线粒体氧化，丙酮酸在乳酸脱氢酶催化下接受NADH的氢还原为乳酸，同时使NAD+再生以维持糖酵解。α-磷酸甘油穿梭和苹果酸-天冬氨酸穿梭是有氧时把胞质NADH还原当量送入线粒体的方式；脂肪酸合成与维持GSH还原态不是此时NADH的主要去路"},{"q":"6-磷酸果糖激酶-1的别构抑制剂是","o":["6-磷酸果糖","1，6-双磷酸果糖","柠檬酸","乙酰CoA","AMP"],"a":2,"e":"磷酸果糖激酶-1的别构抑制剂是ATP和柠檬酸，二者降低酶与底物的亲和力。AMP与果糖-2,6-二磷酸是别构激活剂，可取消ATP与柠檬酸的抑制；6-磷酸果糖是该酶底物，1,6-双磷酸果糖是其产物，乙酰CoA不参与糖酵解调节，主要抑制丙酮酸脱氢酶复合体"},{"q":"γ-氨基丁酸（GABA）是哪种氨基酸脱羧的产物","o":["谷氨酸","天冬氨酸","甘氨酸","色氨酸","精氨酸"],"a":0,"e":"谷氨酸经L-谷氨酸脱羧酶脱羧生成γ-氨基丁酸，该酶在脑与肾活性高，GABA为抑制性神经递质。天冬氨酸脱羧生成β-丙氨酸，色氨酸经羟化脱羧生成5-羟色胺，组氨酸脱羧生成组胺，精氨酸脱羧生成腐胺"},{"q":"维生素B2的活性形式是","o":["核黄素","FMN和FAD","CoASH","NAD+","NADH+H+"],"a":1,"e":"维生素B2即核黄素，其活性形式为FMN和FAD，二者作为氧化还原酶的辅基传递氢和电子，参与糖、脂及氨基酸的氧化。核黄素是未活化的维生素本体；CoASH是泛酸的衍生物；NAD+与NADH+H+是维生素PP即烟酸的活性形式，均与维生素B2无关"},{"q":"下列对嘌呤核苷酸合成的描述，正确的是","o":["利用氨基酸、一碳单位和CO2合成嘌呤环，再与5'-磷酸核糖结合而成","利用天冬氨酸、一碳单位、CO2和5'-磷酸核糖为原料直接合成","在氨基甲酰磷酸的基础上逐步合成","嘌呤核苷酸是在5-磷酸核糖-1-焦磷酸（PRPP）提供磷酸核糖分子的基础上与氨基酸、CO2及一碳单位作用逐步形成","嘌呤核苷酸是先合成黄嘌呤核苷酸（XMP），再转变为AMP、GMP"],"a":3,"e":"嘌呤从头合成并非先造环再连糖，而是在5-磷酸核糖-1-焦磷酸即PRPP提供核糖的基础上，逐步由氨基酸、CO2及一碳单位构建嘌呤环，故A项把顺序颠倒。嘧啶合成才以氨基甲酰磷酸为起点。IMP生成后才转变为AMP与GMP，XMP只是GMP途径的中间物"},{"q":"下列是构成磷脂酰胆碱的成分之一的物质是","o":["丝氨酸","乙醇胺","胆碱","胞嘧啶","胆胺"],"a":2,"e":"磷脂酰胆碱（卵磷脂）由甘油、脂肪酸、磷酸和胆碱组成，故胆碱是其组成成分。丝氨酸为磷脂酰丝氨酸的组分，乙醇胺（胆胺）为磷脂酰乙醇胺的组分，胞嘧啶为含氮碱基不参与磷脂酰胆碱构成，胆胺即乙醇胺，均非磷脂酰胆碱的组成成分"},{"q":"哺乳动物肝中，2分子乳酸转变成葡萄糖需要","o":["2分子ATP","3分子ATP","4分子ATP","5分子ATP","6分子ATP"],"a":4,"e":"2分子丙酮酸异生为葡萄糖时，丙酮酸羧化消耗2个ATP，磷酸烯醇式丙酮酸羧激酶消耗2个GTP，磷酸甘油酸激酶逆反应消耗2个ATP，共需6个高能磷酸键。2分子乳酸异生为葡萄糖净耗6个高能键，其中4个来自ATP、2个来自GTP"},{"q":"关于胆红素，哪项说法是错误的","o":["在生理条件下它是难溶于水的脂溶性物质","主要由衰老破坏的红细胞中血红素代谢而来","在血中与清蛋白结合成血胆红素的形式运输","在肝细胞内主要与葡萄糖醛酸结合","正常人尿中会出现胆红素"],"a":4,"e":"正常人尿中不含胆红素，血中主要是与清蛋白结合的结合胆红素，因分子大不能经肾小球滤过，故尿胆红素阴性。胆红素为脂溶性、难溶于水；主要来自衰老红细胞血红素分解；在肝细胞内与葡萄糖醛酸结合成结合胆红素经胆汁排出"},{"q":"受体与其相应配体的结合是","o":["离子键结合","非共价可逆结合","共价可逆结合","非共价不可逆结合","共价不可逆结合"],"a":1,"e":"受体与配体通过氢键、离子键、疏水作用及范德华力等非共价键可逆结合，结合后可解离，这保证信号的可调控性。离子键只是其中一种作用力，不能概括全部；共价结合（可逆或不可逆）不符合受体配体结合的一般特征，不可逆结合还会持续激活信号"},{"q":"葡糖-6-磷酸对己糖激酶活性的调节作用是一种","o":["酶的慢速调节","酶的别构调节","酶的共价修饰调节","酶原激活","反馈促进"],"a":1,"e":"6-磷酸葡萄糖是己糖激酶反应的产物，作为别构抑制剂与酶调节部位非共价结合，使酶构象改变而活性下降，属别构调节。酶的化学修饰调节需共价结合磷酸基等基团，由激酶和磷酸酶催化；酶原激活是肽键断裂；G6P对己糖激酶起反馈抑制而非反馈促进"},{"q":"下列有关脂肪代谢的叙述错误的是","o":["1分子软脂酸彻底氧化生成的ATP分子数少于丙酮酸彻底氧化所生成的ATP","酮体在肝内生成的速度大于肝外组织氧化的速度时即产生酮症","乙酰辅酶A不能净合成葡萄糖","1分子软脂酸在肝脏经β-氧化为乙酰辅酶A时需7分子水参与","胰岛素能促进乙酰辅酶A羧化酶去磷酸化故可增强其活性，从而加速脂肪酸合成"],"a":0,"e":"1分子软脂酸彻底氧化净生成106分子ATP，1分子丙酮酸彻底氧化约生成12.5分子ATP，故A项关系颠倒。酮体生成超过肝外利用即出现酮症；丙酮酸脱氢酶反应不可逆，乙酰CoA不能净合成葡萄糖；软脂酸7次β-氧化需7分子水；胰岛素使乙酰CoA羧化酶去磷酸化而激活"},{"q":"核小体是组成染色质的基本单位，它是由DNA和组蛋白构成。下面对核小体构成成分的描述正确的是","o":["目前已知核小体由DNA和非组蛋白共同构成","目前已知核小体由DNA和H1，H2，H3，H4各1分子构成","目前已知构成核小体的组蛋白种类有H1，H2A，H2B，H3和H4","目前已知核小体由DNA和H1，H2，H3，H4各2分子构成","目前已知构成核小体的组蛋白是由组氨酸构成的蛋白质"],"a":2,"e":"核小体由DNA与H2A、H2B、H3、H4各两分子组成的八聚体核心及一分子H1构成，故组蛋白种类为H1、H2A、H2B、H3、H4。核心八聚体不含H1，H1位于连接区；组蛋白富含赖氨酸与精氨酸，并非仅由组氨酸构成，非组蛋白也不参与核小体组成"},{"q":"以病毒DNA为载体，将目的基因导入哺乳动物细胞的过程称","o":["感染","转导","转化","转染","转位"],"a":0,"e":"以病毒DNA为载体借助病毒颗粒将目的基因导入哺乳动物细胞，称感染；病毒复制缺陷时需辅助病毒或包装细胞提供结构蛋白。转染指以裸露DNA直接导入真核细胞，转导指噬菌体介导细菌间的基因转移，转化指细菌摄取裸DNA，三者导入方式与受体细胞均不同"},{"q":"糖原合成时，下列哪一个是葡萄糖供体","o":["葡萄糖","6-磷酸葡萄糖","UDPG","CDPG","1-磷酸葡萄糖"],"a":2,"e":"糖原合成中，1-磷酸葡萄糖与UTP反应生成尿苷二磷酸葡萄糖（UDPG），UDPG作为活性葡萄糖供体，在糖原合酶催化下将葡萄糖基转移至糖原引物的非还原端。游离葡萄糖、6-磷酸葡萄糖、1-磷酸葡萄糖均不能直接作为供体；CDPG不是糖原合成的活化形式"},{"q":"对于p53蛋白的描述，错误的是","o":["突变后可致癌","能引发修复失败的细胞程序自杀","有“基因卫士”的称号","有转录因子作用","能激活解链酶"],"a":4,"e":"p53是抑癌基因产物，具转录因子作用，可诱导p21使细胞周期停滞并启动修复，修复失败时引发凋亡，故称基因卫士，突变后促癌。p53还调控血管生成与细胞衰老。解链酶由复制起始相关因子激活，p53不具此功能"},{"q":"谷丙转氨酶的辅酶是","o":["NAD+","NADP+","磷酸吡哆醛","烟酸","核黄素"],"a":2,"e":"转氨酶的辅基是维生素B6的磷酸酯即磷酸吡哆醛，结合于活性中心赖氨酸的ε-氨基，在氨基转移中起传递氨基作用。NAD+与NADP+为脱氢酶辅酶，烟酸、核黄素是维生素本体而非辅酶形式。磷酸吡哆醛接受氨基后转为磷酸吡哆胺，再将氨基转给α-酮酸"},{"q":"参与酮体生成和胆固醇合成的共同中间产物是","o":["乙酰CoA","羟甲基戊二酸单酰CoA","甲羟戊酸","乙酰乙酸","异戊烯焦磷酸"],"a":1,"e":"酮体生成与胆固醇合成的共同中间产物是羟甲基戊二酸单酰CoA（HMG-CoA），由乙酰CoA缩合生成；在肝细胞线粒体用于生酮，在胞质用于合成胆固醇。乙酰CoA是更上游的共同原料；甲羟戊酸、异戊烯焦磷酸仅属胆固醇合成；乙酰乙酸是酮体之一，并非共同中间体"},{"q":"DNA完整克隆过程由哪些步骤组成","o":["载体和目的基因分离、提纯和鉴定","分、选、连、转、筛","将重组体导入宿主细胞，筛出含目的基因菌株","将载体和目的基因连接成重组体","限制性内切核酸酶的应用"],"a":1,"e":"完整DNA克隆包括目的基因与载体的分离纯化、重组体连接、导入宿主细胞及筛选鉴定，概括为分、选、连、转、筛。分即分离目的基因，选为载体的选择与构建，连为体外连接，转是导入宿主，筛为重组体的筛选与鉴定"},{"q":"与碳酸酐酶作用有关的元素是","o":["锌","铁","铜","硒","锰"],"a":0,"e":"碳酸酐酶是含锌金属酶，锌离子位于活性中心，催化CO2与水生成碳酸。铁为血红蛋白与细胞色素组分，铜见于细胞色素c氧化酶与铜蓝蛋白，硒为谷胱甘肽过氧化物酶组分，锰为精氨酸酶与超氧化物歧化酶的辅因子"},{"q":"N-连接型聚糖的合成不需要","o":["糖基化位点Asn-X-Ser/Thr","长萜醇载体","活化的单糖","五糖核心","富含脯氨酸的序列"],"a":4,"e":"N-连接聚糖连接于Asn-X-Ser/Thr序列子中天冬酰胺的酰胺氮，合成需长萜醇载体、活化的单糖核苷酸及五糖核心。富含脯氨酸的序列是O-连接型糖基化位点的特征，与N-连接型无关"},{"q":"苯丙酮尿症（PKU）是一种常见的婴儿疾病。这种疾病是由于缺失将苯丙氨酸水解成酪氨酸所需的苯丙氨酸水解酶基因，导致血液中苯丙氨酸累积造成的。若是不能及时检测出这种天生的代谢缺乏，在婴儿出生后9个月内，就会引起无法挽救的大脑损伤。采用下述何种技术可检测患者血清苯丙氨酸含量","o":["液相/质谱技术","二维电泳/质谱技术","串联质谱技术","生物芯片技术","紫外分光技术"],"a":0,"e":"液相色谱-质谱联用可对血清中的苯丙氨酸进行分离与定量，特异性高、灵敏度好，适用于苯丙酮尿症的生化确诊与浓度监测。串联质谱多用于干血片新生儿筛查，二维电泳/质谱针对蛋白质，生物芯片检测核酸，紫外分光不能区分氨基酸种类"},{"q":"下列有关生物转化作用的叙述，哪项是正确的","o":["被转化的是营养性物质","被转化的是NADH","被转化的是FADH2","被转化的是NADPH","被转化的是非营养性物质"],"a":4,"e":"生物转化处理的是内源性或外源性的非营养物质，如胺类、胆红素、激素、药物，通过化学转变增加水溶性和极性便于排出。糖、脂、蛋白质等营养性物质走分解与合成代谢，不属生物转化；NADH、FADH2、NADPH是递氢体，为反应提供还原当量而非被转化的底物"},{"q":"合成CM的主要场所在","o":["小肠","肝","血浆","脑","脂肪组织"],"a":0,"e":"CM在小肠黏膜细胞合成，由食物脂肪消化产物酯化生成的甘油三酯与apoB48、磷脂、胆固醇组装，经淋巴入血。肝合成VLDL与HDL，血浆中CM经LPL水解转变为残粒，脑与脂肪组织不合成CM，脂肪组织以储存甘油三酯为主"},{"q":"乙酰CoA从线粒体基质进入细胞质通过","o":["柠檬酸-丙酮酸循环","苹果酸-天冬氨酸穿梭","嘌呤核苷酸循环","乳酸循环","葡萄糖-丙氨酸循环"],"a":0,"e":"乙酰CoA不能直接透过线粒体内膜，需在线粒体内与草酰乙酸缩合成柠檬酸，经载体转运至细胞质，再裂解为乙酰CoA和草酰乙酸，此即柠檬酸-丙酮酸循环，故为答案。苹果酸-天冬氨酸穿梭转运的是胞质NADH的还原当量。嘌呤核苷酸循环为肌肉脱氨方式。乳酸循环与葡萄糖-丙氨酸循环参与糖异生与氮转运"},{"q":"乙酰辅酶A在细胞质中合成一分子软脂酸时需要NADPH的分子数是","o":["10","12","14","16","18"],"a":2,"e":"合成1分子软脂酸需经7次缩合-还原-脱水-再还原循环，每轮消耗2分子NADPH，总计14分子，同时消耗8分子乙酰CoA和7分子ATP。10、12、16等数值与7轮循环的化学计量不符，属未计起始活化或误按碳数推算的结果"},{"q":"关于氨基酸代谢的错误论述是","o":["氨基酸的吸收是耗能的主动转运","氨基酸经脱氨基后生成α-酮酸和氨","转氨基作用是各种氨基酸共有的代谢途径","氨基酸脱氨基的主要方式是联合脱氨基作用","通过氨基酸脱羧，可以合成一些重要的含氮化合物"],"a":2,"e":"转氨基作用需专一的氨基转移酶，除赖氨酸、苏氨酸、脯氨酸和羟脯氨酸外大多数氨基酸可转氨基，故C项错误。氨基酸吸收属耗能主动转运，脱氨基后生成α-酮酸和氨，联合脱氨基是主要方式，脱羧可生成胺类等含氮化合物"},{"q":"蛋白质二级结构中，不存在的构象是","o":["α-螺旋","锌指","β-折叠","β-转角","Ω环"],"a":1,"e":"蛋白质二级结构指主链局部折叠形成的α-螺旋、β-折叠、β-转角与Ω环。锌指是含Zn2+的结构模体，由α-螺旋与β-折叠组合而成，属超二级结构即模体层次，不由主链局部氢键单独定义。二级结构只涉及主链原子的空间排布，不涉及侧链的相互关系"},{"q":"下列对结合胆红素的叙述哪一项是错误的","o":["主要是双葡萄糖醛酸胆红素","与重氮试剂呈间接反应","水溶性大","随正常人尿液排出","不易透过生物膜"],"a":1,"e":"结合胆红素由肝细胞以双葡萄糖醛酸结合生成，水溶性大，与重氮试剂直接反应，可随尿排出，且不易透过生物膜。呈间接反应的是未结合胆红素，其分子内氢键掩盖亚甲桥，须加乙醇破坏氢键后才显色"},{"q":"线粒体DNA","o":["通常成双股线形","与组蛋白相结合","为线粒体核糖体的rRNA编码","编码三羧酸循环的酶","有损伤修复系统"],"a":2,"e":"线粒体DNA为环状双链分子，编码线粒体核糖体所需的rRNA、tRNA及部分呼吸链亚基。它不与组蛋白结合；三羧酸循环的酶由核基因编码；其损伤修复系统有限且不完善；通常成双股线形与环状结构不符"},{"q":"功能基因组学不包含下列哪项内容","o":["分析基因组DNA序列中的编码序列的功能","分析基因组DNA序列中的非编码序列的功能","测定基因组DNA序列","分析基因组调控的网络及机制","利用基因芯片研究基因组表达谱"],"a":2,"e":"功能基因组学利用结构基因组学提供的信息，分析编码序列与非编码序列的功能、基因表达谱及调控网络，常用基因芯片等高通量手段。测定基因组DNA序列属结构基因组学的任务，是基因组作图与测序阶段的内容，不属功能研究"},{"q":"氨基酸分解产生的氨在体内储存及运输的主要形式是","o":["天冬酰胺","谷氨酸","尿素","谷胱甘肽","谷氨酰胺"],"a":4,"e":"氨在组织中与谷氨酸结合生成谷氨酰胺，经血液运至肝或肾，是氨储存与运输的主要形式，也是氨的解毒方式。天冬酰胺参与氮代谢但非主要运氨形式。尿素为氨在肝内解毒的终产物，经肾排出而非运输形式。谷氨酸为转氨作用的氨基受体，谷胱甘肽参与抗氧化，均非氨的主要运输形式"},{"q":"真核生物线粒体DNA复制的主要酶是","o":["DNA聚合酶β","DNA聚合酶γ","DNA聚合酶δ","DNA聚合酶ε","DNA聚合酶α"],"a":1,"e":"真核线粒体DNA由DNA聚合酶γ催化复制，该酶为二聚体，具校正活性。pol α具引物酶活性，pol δ合成后随链，pol ε合成前导链，三者均作用于核DNA。pol β参与碱基切除修复，不承担线粒体复制"},{"q":"关于6-巯基嘌呤的叙述，错误的是","o":["抑制IMP生成GMP","抑制IMP生成AMP","抑制次黄嘌呤生成IMP","抑制鸟嘌呤生成GMP","抑制腺苷生成AMP"],"a":4,"e":"6-巯基嘌呤在体内转变为硫代肌苷酸，抑制IMP生成AMP和GMP，并抑制嘌呤补救合成（如次黄嘌呤-鸟嘌呤磷酸核糖转移酶），从而抑制核酸合成。抑制腺苷生成AMP并非其主要作用机制且表述不准，故为错误项"},{"q":"三羧酸循环中，下列哪一个酶是调控酶","o":["琥珀酸脱氢酶","延胡索酸酶","苹果酸脱氢酶","α-酮戊二酸脱氢酶","顺乌头酸酶"],"a":3,"e":"三羧酸循环的关键调控酶有柠檬酸合酶、异柠檬酸脱氢酶和α-酮戊二酸脱氢酶复合体，故α-酮戊二酸脱氢酶为调控酶。琥珀酸脱氢酶、延胡索酸酶、苹果酸脱氢酶、顺乌头酸酶催化可逆或非限速步骤，不属于主要调控酶"},{"q":"下列关于ribozyme的叙述，正确的是","o":["即核酸酶","本质是蛋白质","本质是核糖核酸","其辅酶是辅酶A","即核酸外切酶"],"a":2,"e":"核酶本质是具有催化活性的核糖核酸，可催化自身剪接或切割其他RNA分子。它不是蛋白质，也不是核酸酶或核酸外切酶（后者多为蛋白质），其催化活性不依赖辅酶A，故本质是核糖核酸的叙述正确"},{"q":"正常人禁食12小时后，血浆中不含","o":["VLDL","HDL","LDL","IDL","CM"],"a":4,"e":"CM由小肠黏膜合成，含apoB48，颗粒最大、密度最低，运输外源性甘油三酯，半衰期仅5～15分钟，空腹12～14小时后血浆中已不存在。VLDL、IDL、LDL、HDL均由肝合成或血浆内代谢生成，空腹时仍可检出"},{"q":"电子传递链的组成成分不包括","o":["NAD＋","FMN","FAD","CoA","CoQ"],"a":3,"e":"呼吸链由复合体Ⅰ～Ⅳ及泛醌、细胞色素c组成，其辅基含NAD+、FMN、FAD、铁硫簇、血红素和铜离子，故NAD+、FMN、FAD、CoQ均属呼吸链组分。CoA是酰基转移载体，参与丙酮酸氧化脱羧、三羧酸循环与脂肪酸氧化，传递的是酰基而非电子，不参与电子传递"},{"q":"下列有关脂肪酸生物合成的叙述中，正确的是","o":["不需乙酰CoA","中间产物是丙二酰CoA","在线粒体内进行","所需的氢来自NADH","最终产物为10碳以下脂酸"],"a":1,"e":"脂肪酸合成以乙酰CoA为起始物，在乙酰CoA羧化酶催化下生成丙二酸单酰CoA，作为二碳单位供体参与缩合，故中间产物为丙二酰CoA。反应在胞质溶胶的脂肪酸合酶复合体上完成，所需氢由NADPH提供。终产物为16碳软脂酸，并非10碳以下"},{"q":"胰岛素受体具有下列哪种酶的活性","o":["蛋白激酶A（PKA）","蛋白激酶G（PKG）","蛋白激酶C（PKC）","Ca2+-CaM依赖性蛋白激酶","酪氨酸蛋白激酶"],"a":4,"e":"胰岛素受体为受体型酪氨酸蛋白激酶，配体结合后受体二聚化并自身磷酸化，进而磷酸化胰岛素受体底物传递信号，故为答案。PKA、PKG、PKC分别为cAMP、cGMP、DAG/Ca2+依赖的蛋白激酶。Ca2+-CaM依赖性蛋白激酶由钙调蛋白激活，均为胞内丝/苏氨酸激酶，与胰岛素受体无关"},{"q":"下列属于解偶联剂的是","o":["鱼藤酮","寡霉素","2,4-二硝基苯酚","ADP","AMP"],"a":2,"e":"2,4-二硝基苯酚为脂溶性弱酸，可携带H+穿过线粒体内膜，破坏质子电化学梯度，使氧化与磷酸化脱节，电子传递照常进行而ATP不能生成，能量以热形式散失。鱼藤酮抑制复合体Ⅰ，寡霉素抑制ATP合酶，均属呼吸链或合酶抑制剂。ADP是磷酸化的底物，AMP无解偶联作用"},{"q":"DNA载体的最基本性质是","o":["青霉素抗性","自我转录能力","自我复制能力","卡那霉素抗性","自我表达能力"],"a":2,"e":"载体须能独立复制，才能在受体细胞中随染色体外DNA的复制而稳定传代，这是作为载体的最基本性质。此外还需具备筛选标记、单一限制酶切位点、分子较小且易导入。多个切口会被切成碎片，不能与细菌共存则无法扩增，缺乏遗传标志无法筛选，分子量大则导入效率低，均为载体的禁忌"},{"q":"肝细胞内合成胆固醇需参与的酶是","o":["磷脂酰胆碱-胆固醇酰基转移酶","HMG-CoA氧化酶","HMG-CoA还原酶","HMG-CoA裂解酶","脂酰COA-胆固醇酰基转移酶"],"a":2,"e":"胆固醇合成以HMG-CoA为关键中间物，HMG-CoA还原酶催化其生成甲羟戊酸，是该途径的限速酶，也是他汀类药物的作用靶点。HMG-CoA裂解酶作用于酮体生成，裂解HMG-CoA为乙酰乙酸和乙酰CoA。HMG-CoA氧化酶并非体内存在的酶；磷脂酰胆碱-胆固醇酰基转移酶催化血浆胆固醇酯化，与合成无关"},{"q":"下列关于P/O比值，叙述错误的是","o":["每消耗1个氧原子所消耗的无机磷的原子数","每消耗1个氧原子所消耗的ADP的分子数","每消耗1/2摩尔O2能生成的ATP的摩尔数","测定底物的P/O比值，可以推测其呼吸链中的偶联部位","琥珀酸通过Cyt c进入呼吸链，其P/O比值为2"],"a":4,"e":"P/O比值指每消耗1个氧原子所消耗的无机磷原子数，即生成ATP的分子数，也可表述为每消耗1/2摩尔O2所生成的ATP摩尔数，据此可推断呼吸链的偶联部位。琥珀酸经复合体Ⅱ进链、绕过复合体Ⅰ，P/O比值约为1.5而非2"},{"q":"酶促反应速率v达到最大反应速率Vmax的80%时，底物浓度[S]为","o":["1Km","2Km","3Km","4Km","5Km"],"a":3,"e":"按米氏方程v=Vmax[S]/(Km+[S])，v=0.8Vmax时0.8Km+0.8[S]=[S]，解得[S]=4Km。1Km对应50%Vmax，2Km约67%，3Km为75%，5Km约83%，均低于80%"},{"q":"关于肝细胞性黄疸，下列说法错误的是","o":["常见于肝实质性疾病，如肝炎，肝肿瘤等","肝脏处理胆红素能量下降","也称肝源性黄疸","尿胆红是阴性","血清结合和未结合胆红素都升高"],"a":3,"e":"肝细胞性黄疸时肝细胞摄取、结合与排泄胆红素均障碍，血中结合胆红素升高且为水溶性，可经肾小球滤过，故尿胆红素呈阳性而非阴性。血中未结合胆红素亦升高，尿胆素原可高可低。溶血性黄疸尿胆红素阴性、尿胆素原显著增多，与本题所述相反"},{"q":"乙酰CoA不能参与的反应是","o":["氧化分解","合成糖原","生成酮体","合成脂酸","合成胆固醇"],"a":1,"e":"乙酰CoA经三羧酸循环氧化分解，也可羧化为丙二酸单酰CoA合成脂肪酸，或合成胆固醇、生成酮体，但丙酮酸脱氢酶反应不可逆，乙酰CoA不能转变为丙酮酸，故不能净合成糖原。糖原合成只能由葡萄糖经UDPG途径完成"},{"q":"关于核酸结构，叙述错误的是","o":["DNA双螺旋表面有一条大沟和一条小沟","DNA双螺旋结构中相邻碱基之间存在碱基堆积力","碱基位于DNA双螺旋内侧，碱基对形成一种近似平面的环形结构","与DNA相比，RNA种类繁多，分子量相对较大","RNA可形成局部双螺旋结构"],"a":3,"e":"与DNA相比，RNA种类虽多，但分子量通常远小于DNA，故分子量相对较大的说法错误。DNA双螺旋表面有一条大沟和一条小沟；相邻碱基间存在碱基堆积力；碱基位于内侧、碱基对形成近似平面的环形结构；RNA可形成局部双螺旋，这些均正确"},{"q":"反式作用因子指的是","o":["具有激活功能的调节蛋白","具有抑制功能的调节蛋白","能激活自身基因表达的调节蛋白","能抑制自身基因表达的调节蛋白","能调节另一基因表达的调节蛋白"],"a":4,"e":"反式作用因子由某一基因编码，经扩散后与另一基因的顺式作用元件结合，反式激活或抑制该基因表达。具有激活或抑制功能、作用于自身基因的调节蛋白属顺式作用蛋白，A、B、C、D四项均未点明作用于另一基因"},{"q":"正常染色体内可能存在某些抑制肿瘤发生的基因，它们的丢失、突变或失去功能，使激活的癌基因发挥作用而致癌。与人类肿瘤相关性最高的抑癌基因","o":["RB","P53","PTEN","P16","APC"],"a":1,"e":"p53基因是与人类肿瘤相关性最高的抑癌基因，超过半数肿瘤存在其突变，被称为基因组守护神，可阻滞细胞周期或启动细胞凋亡。RB、PTEN、P16、APC也是抑癌基因，但突变频率或相关肿瘤谱不及p53广泛"},{"q":"作为目的基因载体的根本条件是","o":["可以独立复制","有多个切口","不能与细菌共存","不应该有基因标志","分子量大"],"a":0,"e":"载体是携带目的基因进入受体细胞并使其扩增或表达的DNA分子，必须能独立复制，才能随宿主繁殖而稳定传代，这是根本条件。此外还需筛选标记与单一酶切位点。有多个切口会被切碎，不能与细菌共存无从扩增，无基因标志无法筛选，分子量大则导入效率低"},{"q":"有关RNA转录叙述错误的一项是","o":["是以DNA作为模板","遵从碱基配对的规律","新链的延伸方向都是5'→3'方向","核苷酸之间是通过磷酸二酯键相连","底物是NMP"],"a":4,"e":"转录底物为NTP，即ATP、GTP、CTP、UTP，聚合时释放焦磷酸，NMP只是产物链中的组成单位，故E项错误。转录以DNA为模板，遵守碱基配对，新链沿5'→3'延伸，核苷酸之间以3',5'-磷酸二酯键相连"},{"q":"关于同工酶的描述，错误的是","o":["是一组催化相同化学反应的酶","同工酶免疫学性质相同","酶分子活性中心结构相同","同工酶在体内各组织器官的分布不同","同工酶各成员Km值不同"],"a":1,"e":"同工酶催化相同的化学反应，但酶蛋白分子结构不同，因而理化性质与免疫学特性各异，故“免疫学性质相同”错误，可用免疫法区分各型同工酶。各成员活性中心结构相同或相似，Km常有差异以适应不同组织代谢，且在体内各器官分布不同，如LDH1以心肌为主、LDH5以肝为主"},{"q":"以下哪一项不属于基因工程中的常用酶","o":["限制性核酸内切酶","DNA聚合酶","DNA连接酶","反转录酶","拓扑异构酶"],"a":4,"e":"基因工程常用工具酶包括限制性核酸内切酶（切割）、DNA聚合酶（合成、补平）、DNA连接酶（连接）和反转录酶（由mRNA合成cDNA）。拓扑异构酶主要参与DNA复制时解超螺旋，属复制相关酶，不是基因工程常规使用的工具酶"},{"q":"氰化钾抑制的是","o":["细胞色素c","细胞色素c氧化酶","超氧化物歧化酶","ATP酶","铜离子"],"a":1,"e":"氰化物与细胞色素c氧化酶即复合体Ⅳ中的Fe3+结合，阻断电子传给氧，使呼吸链中断、细胞不能利用氧。细胞色素c只是电子载体，超氧化物歧化酶清除氧自由基，ATP合酶位于磷酸化末端，铜离子是复合体Ⅳ的组分而非靶点"},{"q":"关于谷胱甘肽的叙述，正确的是","o":["是体内重要的氧化剂","含有胱氨酸","其中的谷氨酸α-羧基是游离的","C端羧基是主要的功能基团","所含的肽键均为α-肽键"],"a":2,"e":"谷胱甘肽由谷氨酸、半胱氨酸和甘氨酸组成，谷氨酸以γ-羧基与半胱氨酸的氨基成肽键，其α-羧基保持游离，故该说正确。活性基团是半胱氨酸的巯基，可抗氧化并保护酶蛋白；分子中不含丝氨酸，γ-谷氨酰基循环参与氨基酸转运而非其结构特点"},{"q":"阿糖胞苷抗癌的机制是","o":["类似谷氨酰胺，抑制CTP合成","干扰叶酸代谢","抑制CDP还原成dCDP","使dUMP不能利用一碳单位甲基化生成dTMP","干扰叶酸对一碳单位的运输"],"a":2,"e":"阿糖胞苷在体内磷酸化为三磷酸衍生物，抑制核糖核苷酸还原酶，阻断CDP还原为dCDP，使dCTP减少，DNA合成受阻。氮杂丝氨酸才是谷氨酰胺类似物，抑制CTP生成。甲氨蝶呤干扰叶酸代谢，使dUMP不能利用一碳单位甲基化生成dTMP；干扰一碳单位运输亦非其机制"},{"q":"氧化磷酸化的化学渗透假说提出关于ATP形成的原因是","o":["线粒体内膜对ADP渗透性的变化造成的","ADP泵出基质进入膜间隙所致","线粒体蛋白质中形成高能键所","H+被泵出形成线粒体内膜内外质子电化学梯度所致","H+被泵出形成线粒体外膜内外质子电化学梯度所致"],"a":3,"e":"化学渗透假说认为呼吸链的电子传递将H+从基质泵至膜间隙，形成跨线粒体内膜的质子电化学梯度，储藏的势能驱动H+经ATP合酶回流，使ADP与Pi合成ATP。底物水平磷酸化由高能磷酸基直接转移，不依赖膜两侧梯度；H+电化学梯度也不是由ATP水解形成，方向相反"},{"q":"蛋白质分子的结构单元是","o":["氢键","肽键平面","肽键","氨基酸残基","二硫键"],"a":1,"e":"肽键中6个原子Cα1、C、O、N、H、Cα2共处一平面，构成肽单元即肽键平面，是肽链主链的重复结构单位。肽键是连接氨基酸残基的酰胺键，氨基酸残基是肽链的组成残基，氢键与二硫键属维持空间结构的次级键，均不是结构单元"},{"q":"甘油氧化分解和糖分解代谢的共同中间产物是","o":["3-磷酸甘油","β-羟丁酸","磷酸二羟丙酮","乳酸","乙酰乙酸"],"a":2,"e":"甘油经甘油激酶催化生成3-磷酸甘油，再脱氢生成磷酸二羟丙酮，后者异构为甘油醛-3-磷酸进入糖酵解，故磷酸二羟丙酮是二者的共同中间产物。β-羟丁酸与乙酰乙酸属酮体，乳酸是糖无氧氧化产物，3-磷酸甘油位于共同点之前"},{"q":"人类基因组比大肠杆菌基因组大700倍左右，然而，人类基因组复制的时间仅比大肠杆菌基因组复制长6～8倍。这是因为","o":["组蛋白的存在提高了人染色体DNA的复制速率","人类基因组的GC含量低，两条链更容易解链","人基因组的许多序列在复制中直接跳过去，因为只有3%～5%的序列编码蛋白质","人染色体DNA上具有多个复制起始区，大肠杆菌只有一个","人DNA复制经过整个细胞周期，而大肠杆菌的DNA复制每小时启动一次"],"a":3,"e":"真核染色体DNA有多个复制起始点，可形成多个复制眼同时复制，故基因组大700倍而复制时间仅延长数倍；大肠杆菌只有一个oriC。GC含量低并不加快解链，跳过非编码序列之说不能成立，复制仅限S期也不是时间未成比例延长的原因"},{"q":"大鼠饲以去脂膳食一段时间后，其体内主要缺乏的是","o":["磷脂酰胆碱","磷脂酰乙醇胺","前列腺素","胆固醇","1,25-(OH)2D3"],"a":2,"e":"去脂膳食缺乏必需脂肪酸，亚油酸、亚麻酸不足使花生四烯酸合成减少，前列腺素等廿碳多不饱和脂肪酸衍生物生成受限。磷脂酰胆碱、磷脂酰乙醇胺、胆固醇可由糖代谢中间产物合成，1,25-(OH)2D3由胆固醇衍生，均不受明显影响"},{"q":"与G蛋白偶联的受体是","o":["环状受体","7个跨膜螺旋受体","催化性受体","细胞核内受体","细胞质内受体"],"a":1,"e":"G蛋白偶联受体为单体蛋白，肽链七次跨膜，N端在膜外、C端在膜内，胞内部分与异源三聚体G蛋白结合，故称七次跨膜受体。离子通道受体（环状受体）由寡聚体围成孔道，跨膜4次；催化性受体跨膜1次；核内与胞质内受体属细胞内受体"},{"q":"1965年澳大利亚科学家发现，结扎鼠门静脉后，电镜观察到肝实质组织中有一些散在的死亡细胞，这些细胞的溶酶体并未被破坏，显然不同于细胞坏死。这些细胞体积收缩、染色质凝集，从其周围的组织中脱落并被吞噬，机体无炎症反应。1972年Kerr等三位科学家首次提出了细胞凋亡的概念。关于细胞凋亡的叙述中，错误的是","o":["某种信号触发的过程","细胞按一定程序缓慢死亡","可诱导肿瘤发生","某些癌基因具有抑制凋亡的作用","生理病理条件下均可发生"],"a":2,"e":"凋亡是受基因调控的程序性死亡，多种信号可触发，生理与病理条件下均可发生，其本身是清除损伤细胞、防止肿瘤发生的机制，并不诱导肿瘤。凋亡受抑才与肿瘤发生相关，某些癌基因如BCL-2抑制凋亡，抑癌基因过度表达则可诱导凋亡"},{"q":"下列维生素中哪种分子中无环状结构","o":["烟酸","叶酸","胆钙化醇","泛酸","生物素"],"a":3,"e":"泛酸由泛解酸与β-丙氨酸以酰胺键相连组成，为开链结构，不含环状骨架，故无环状结构。烟酸为吡啶环，叶酸含蝶酸环与对氨基苯甲酸，胆钙化醇为甾体稠环结构，生物素含咪唑酮并四氢噻吩双环，这些维生素分子内均带环状结构"},{"q":"竞争性抑制剂对酶促反应速率的影响是","o":["Km升高，Vmax不变","Km下降，Vmax下降","Km不变，Vmax下降","Km下降，Vmax升高","Km下降，Vmax不变"],"a":0,"e":"竞争性抑制剂与底物结构相似，与底物竞争酶的活性中心，增大底物浓度可解除抑制，故表观Km升高而Vmax不变。非竞争性抑制不影响底物结合，Km不变而Vmax降低；反竞争性抑制使Km与Vmax同时降低；不可逆抑制共价修饰酶分子，酶量减少，不属可逆的动力学改变"},{"q":"DNA水解的最终产物中，不包括","o":["磷酸","嘌呤碱","脱氧核糖","嘧啶碱","腺苷"],"a":4,"e":"DNA彻底水解的最终产物为磷酸、脱氧核糖、嘌呤碱（腺嘌呤、鸟嘌呤）和嘧啶碱（胞嘧啶、胸腺嘧啶）。腺苷是腺嘌呤与核糖组成的核苷，含核糖且未彻底水解，不是DNA水解产物，故不包括腺苷"},{"q":"真核生物转录发生的部位是","o":["线粒体","细胞质","细胞核","内质网","微粒体"],"a":2,"e":"真核生物的转录主要在细胞核内进行，由RNA聚合酶以DNA为模板合成RNA，产物经加工后运至细胞质翻译。线粒体虽也有转录，但所占比重很小；细胞质是翻译场所；内质网、微粒体参与蛋白质合成与脂质代谢，均非转录的主要部位"},{"q":"关于痛风症，描述错误的是","o":["分为原发性和继发性两种","原发性痛风多有遗传性","继发性痛风是继发于其他疾病过程中的一种临床表现，也可由于药物导致","女性发病多见于中年","最重要的生化基础是高尿素血症"],"a":4,"e":"痛风最重要的生化基础是高尿酸血症，尿酸盐结晶沉积于关节及软组织，而非高尿素血症，E项名称有误。痛风分原发性和继发性，原发性多有遗传倾向，继发性见于血液病、肾病及使用利尿剂等药物；女性多在绝经后发病"},{"q":"下列关于由核糖核苷酸还原成脱氧核糖核苷酸的叙述，错误的是","o":["4种核苷酸都涉及相同的还原酶体系","多发生在二磷酸核苷水平上","还原酶系包括氧化还原蛋白和硫氧化还原蛋白还原酶","GSSG/GSH参与","以上都对"],"a":3,"e":"四种核苷酸在二磷酸核苷水平由统一的核糖核苷酸还原酶体系催化，需氧化还原蛋白与硫氧化还原蛋白还原酶参与，供氢体为NADPH，通过硫氧化还原蛋白的巯基传递氢，并非GSSG/GSH直接参与，故该项错误"},{"q":"下列直接抑制转肽酶的抗生素是","o":["放线菌酮","四环素","土霉素","链霉素和卡那霉素","利福平"],"a":0,"e":"放线菌酮特异抑制真核核糖体的肽酰转移酶，阻断肽链延长。四环素与土霉素抑制原核小亚基、阻止氨酰tRNA进入A位，链霉素与卡那霉素作用于原核小亚基致读码错误，利福平抑制原核RNA聚合酶"},{"q":"脂肪酸合成时所需的氢来自","o":["NADH","NADPH","FADH2","FMNH2","UQH2"],"a":1,"e":"脂肪酸合成中的还原反应由NADPH供氢，其来源为磷酸戊糖途径及苹果酸酶催化的反应，每合成1分子软脂酸消耗14分子NADPH。NADH主要在氧化分解中供氢，经呼吸链产能；FADH2、FMNH2、UQH2为呼吸链递氢体，方向相反"},{"q":"能直接进行氧化脱氨基作用的氨基酸是","o":["甘氨酸","天冬氨酸","谷氨酸","丝氨酸","丙氨酸"],"a":2,"e":"谷氨酸是唯一能以L-谷氨酸脱氢酶直接氧化脱氨基的氨基酸，脱下的氨由NAD(P)+接受，反应可逆。其余氨基酸须先经转氨基把氨基交给α-酮戊二酸生成谷氨酸，再脱氨，即联合脱氨基。甘氨酸、丝氨酸、丙氨酸、天冬氨酸均无直接氧化脱氨途径"},{"q":"Alu高度重复序列","o":["在人的基因组中广泛存在","具有组织特异性","在原核生物基因组中存在","包含限制性内切核酸酶EcoRⅠ的切点","与转录调控有关"],"a":0,"e":"Alu序列是人类基因组中拷贝数极高的短散在重复序列，广泛分布于全基因组，属中度重复序列。其分布无组织特异性，为真核生物特有，序列中不含EcoRⅠ切点，也不直接参与转录调控；Alu自身不编码转座酶，借LINE编码的逆转录酶转座"},{"q":"构成需氧脱氢酶辅酶的维生素是","o":["生物素","硫胺素","谷胺素","磷酸吡哆醛","核黄素"],"a":4,"e":"需氧脱氢酶以FMN或FAD为辅基，其辅酶即维生素B2的活性形式，如琥珀酸脱氢酶、黄嘌呤氧化酶，接受底物脱下的氢后直接交给氧。生物素是羧化酶辅酶，硫胺素焦磷酸是脱羧酶与转酮醇酶辅因子，磷酸吡哆醛来自维生素B6，参与转氨基与脱羧，均不构成需氧脱氢酶辅酶"},{"q":"线粒体外脂肪酸合成的限速酶是","o":["脂酰CoA合成酶","乙酰CoA羧化酶","肉碱脂酰转移酶Ⅰ","肉碱脂酰转移酶Ⅱ","β-酮脂酰还原酶"],"a":1,"e":"脂肪酸合成在胞质溶胶进行，乙酰CoA羧化酶催化乙酰CoA生成丙二酸单酰CoA，是整条途径的限速步骤，受柠檬酸别构激活、长链脂酰CoA抑制。肉碱脂酰转移酶Ⅰ为脂肪酸β-氧化的限速酶，方向相反。β-酮脂酰还原酶只是脂肪酸合酶复合体中的一步还原酶，不具限速作用"},{"q":"关于真核生物的TATA盒叙述，正确的是","o":["RNA聚合酶与DNA模板稳定结合处","转录起始点","RNA聚合酶的活性中心","转录终止位点","DNA合成的起始位点"],"a":0,"e":"TATA盒位于转录起始点上游约-25～-30bp，是TFⅡD中TBP识别并结合的核心序列，由此稳定RNA聚合酶Ⅱ与模板的结合并确定起始位点。转录起始点由起始子元件决定，并非TATA盒本身；它不构成酶的活性中心，也不负责终止。CAAT盒、GC盒属上游调控元件"},{"q":"关于天冬氨酸氨基甲酰基转移酶的下列说法，错误的是","o":["CTP是其反馈抑制剂","是嘧啶核苷酸从头合成的调节酶","由多个亚基组成","是变构酶","服从米-曼氏方程"],"a":4,"e":"天冬氨酸氨基甲酰转移酶是嘧啶核苷酸从头合成的调节酶，由多个亚基组成，属别构酶，CTP为其反馈抑制物，动力学呈S形曲线而不服从米-曼氏方程。服从米-曼氏方程者为典型的非别构酶，其反应速率与底物浓度呈双曲线关系"},{"q":"下列哪种物质是甘油磷脂合成必须参加的物质","o":["CTP","UTP","UMP","GMP","TDP"],"a":0,"e":"甘油磷脂合成需ATP供能，CTP参与胆碱、乙醇胺及甘油二酯的活化，生成CDP-胆碱、CDP-乙醇胺与CDP-甘油二酯。UTP参与糖原合成，UMP与GMP为核苷酸降解物，TDP不参与磷脂合成"},{"q":"糖酵解中，下列哪一个酶催化的反应是限速反应","o":["丙酮酸激酶","6-磷酸果糖激酶-1","己糖激酶","磷酸丙糖异构酶","醛缩酶"],"a":1,"e":"糖酵解的三个关键酶为己糖激酶、磷酸果糖激酶-1和丙酮酸激酶，其中磷酸果糖激酶-1催化的反应最慢，是首要调控点。丙酮酸激酶催化底物水平磷酸化，己糖激酶催化第一步磷酸化，磷酸丙糖异构酶与醛缩酶催化的反应可逆且无调节作用"},{"q":"可经脱氨基作用直接生成α-酮戊二酸的氨基酸是","o":["丙氨酸","谷氨酸","丝氨酸","色氨酸","甘氨酸"],"a":1,"e":"L-谷氨酸经L-谷氨酸脱氢酶催化氧化脱氨，直接生成α-酮戊二酸和氨，该酶在肝、肾、脑活性高，是联合脱氨基的核心环节。丙氨酸与丝氨酸脱氨生成丙酮酸，甘氨酸经丝氨酸途径代谢，色氨酸碳骨架复杂，均不直接生成α-酮戊二酸"},{"q":"原核基因表达调控涉及衰减子的是","o":["乳糖操纵子的阻遏蛋白","阿拉伯糖操纵子的阻遏蛋白","色氨酸操纵子的阻遏蛋白","大肠杆菌的Lex阻遏蛋白","沙门氏菌鞭毛素基因阻遏蛋白"],"a":2,"e":"色氨酸操纵子前导序列中，色氨酸浓度升高时转录提前终止，该序列称衰减子，对阻遏蛋白的粗调起精调作用。乳糖操纵子、阿拉伯糖操纵子经阻遏蛋白与诱导物调节，无衰减子结构。Lex阻遏蛋白参与SOS修复的诱导表达，与衰减无关"},{"q":"关于限制性内切酶的叙述，错误的是","o":["能识别DN特定的碱基顺序并在特定的位点切开DNA","能专一降解经甲基化修饰的DNA","主要从细菌中获得","重组DNA的重要工具酶","切割点附近的碱基顺序一般呈回文结构"],"a":1,"e":"限制性内切酶识别未甲基化的特定回文序列并切割外源DNA，宿主自身DNA经甲基化修饰后不被切割，故B项所述恰好相反。该酶主要从细菌中提取，是重组DNA技术最重要的工具酶，切割位点附近的序列多呈回文结构"}];
